#[inline]
fn control_transfer_method(major: u64, code: u64) -> Option<u32> {
    if major == IRP_MJ_FILE_SYSTEM_CONTROL
        || major == IRP_MJ_DEVICE_CONTROL
        || major == IRP_MJ_INTERNAL_DEVICE_CONTROL
    {
        Some(ioctl::method(code as u32))
    } else {
        None
    }
}

fn pending_irp_returns_read_bytes(major: u64, minor: u64, fsctl: u64, output_len: u64) -> bool {
    major == IRP_MJ_READ
        || major == IRP_MJ_QUERY_INFORMATION
        || major == major::IRP_MJ_QUERY_EA as u64
        || major == major::IRP_MJ_QUERY_QUOTA as u64
        || major == major::IRP_MJ_QUERY_VOLUME_INFORMATION as u64
        || major == major::IRP_MJ_DIRECTORY_CONTROL as u64
        || major == IRP_MJ_FILE_SYSTEM_CONTROL && fsctl == FSCTL_PIPE_TRANSCEIVE
        || control_transfer_method(major, fsctl).is_some() && output_len != 0
        || major == IRP_MJ_PNP
            && minor == nt_pnp_abi::IRP_MN_QUERY_CAPABILITIES as u64
            && output_len == nt_pnp_abi::DEVICE_CAPABILITIES_X64_SIZE as u64
}

fn pending_irp_completion_output_len(
    major: u64,
    minor: u64,
    output_len: u64,
    information: u64,
) -> u64 {
    if major == IRP_MJ_PNP
        && minor == nt_pnp_abi::IRP_MN_QUERY_CAPABILITIES as u64
        && output_len == nt_pnp_abi::DEVICE_CAPABILITIES_X64_SIZE as u64
    {
        output_len
    } else {
        information.min(output_len)
    }
}

unsafe fn pool_alloc_zeroed(size: u64) -> u64 {
    let capacity = (size.max(1) + 7) & !7;
    let ptr = pool_alloc(capacity);
    if ptr != 0 {
        zero(ptr, capacity);
    }
    ptr
}

unsafe fn alloc_driver_frame_run(instance: usize, name: &[u8], count: u64) -> Option<u64> {
    let Some(base) = try_alloc_slot_run(count) else {
        print_str(b"[driver-launch] frame run slot allocation failed inst=");
        print_u64(instance as u64);
        print_str(b" name=");
        print_str(name);
        print_str(b" count=");
        print_u64(count);
        print_str(b"\n");
        return None;
    };
    let mut done = 0u64;
    while done < count {
        let remaining = count - done;
        let batch = remaining.min(SEL4_RETYPE_FAN_OUT_LIMIT);
        let slot = base + done;
        let error = untyped_retype_r(
            CAP_INIT_UNTYPED,
            OBJ_X86_4K_PAGE,
            PAGING_BITS,
            batch as u32,
            slot,
        );
        if error != 0 {
            print_str(b"[driver-launch] frame run retype failed inst=");
            print_u64(instance as u64);
            print_str(b" name=");
            print_str(name);
            print_str(b" index=");
            print_u64(done);
            print_str(b" batch=");
            print_u64(batch);
            print_str(b" label=");
            print_u64(error);
            print_str(b"\n");
            let mut j = 0u64;
            while j < done {
                let _ = cnode_delete_recycle_r(base + j);
                j += 1;
            }
            while j < count {
                recycle_deleted_root_slot(base + j);
                j += 1;
            }
            return None;
        }
        done += batch;
    }
    Some(base)
}

unsafe fn copy_driver_cap(instance: usize, name: &[u8], source: u64) -> Option<u64> {
    let (cap, error) = copy_cap_r(source);
    if error == 0 {
        return Some(cap);
    }
    print_str(b"[driver-launch] cap copy failed inst=");
    print_u64(instance as u64);
    print_str(b" name=");
    print_str(name);
    print_str(b" source=0x");
    print_hex64(source);
    print_str(b" label=");
    print_u64(error);
    print_str(b"\n");
    None
}

unsafe fn trace_hosted_resource_grant(stage: &[u8], device_id: u64, index: u64, total: u64) {
    if HOSTED_RESOURCE_GRANT_TRACE_COUNT.fetch_add(1, Ordering::Relaxed)
        >= HOSTED_RESOURCE_GRANT_TRACE_CAP
    {
        return;
    }
    print_str(b"[driver-launch] resource grant ");
    print_str(stage);
    print_str(b" device_id=");
    print_u64(device_id);
    if total != 0 {
        print_str(b" index=");
        print_u64(index);
        print_str(b"/");
        print_u64(total);
    }
    print_str(b"\n");
}

unsafe fn trace_hosted_resource_grant_detail(
    device_id: u64,
    mmio_phys: u64,
    mmio_len: u64,
    mmio_frame_base: u64,
    mmio_map_pages: u64,
    mmio_va: u64,
    dma_frame_base: u64,
    dma_pages: u64,
) {
    if HOSTED_RESOURCE_GRANT_DETAIL_TRACE_COUNT.fetch_add(1, Ordering::Relaxed)
        >= HOSTED_RESOURCE_GRANT_DETAIL_TRACE_CAP
    {
        return;
    }
    print_str(b"[driver-launch] resource grant detail device_id=");
    print_u64(device_id);
    print_str(b" mmio=0x");
    print_hex64(mmio_phys);
    print_str(b" len=");
    print_u64(mmio_len);
    print_str(b" frame-cap=");
    print_u64(mmio_frame_base);
    print_str(b" map-pages=");
    print_u64(mmio_map_pages);
    print_str(b" va=0x");
    print_hex64(mmio_va);
    if dma_pages != 0 {
        print_str(b" dma-frame-cap=");
        print_u64(dma_frame_base);
        print_str(b" dma-pages=");
        print_u64(dma_pages);
    }
    print_str(b"\n");
}

#[allow(clippy::too_many_arguments)]
unsafe fn trace_hosted_hal_translate_bus_address(
    stage: &[u8],
    interface_type: u32,
    bus_number: u32,
    expected_interface_type: u32,
    expected_bus_number: u32,
    bus_address: u64,
    requested_space: u32,
    translated_space: u32,
    translated_address: u64,
    mmio_base: u64,
    mmio_len: u64,
    port_base: u64,
    port_len: u64,
) {
    if HOSTED_HAL_TRANSLATE_TRACE_COUNT.fetch_add(1, Ordering::Relaxed)
        >= HOSTED_HAL_TRANSLATE_TRACE_CAP
    {
        return;
    }
    print_str(b"[driver-launch] HalTranslateBusAddress ");
    print_str(stage);
    print_str(b" if=");
    print_u64(interface_type as u64);
    print_str(b"/");
    print_u64(expected_interface_type as u64);
    print_str(b" bus=");
    print_u64(bus_number as u64);
    print_str(b"/");
    print_u64(expected_bus_number as u64);
    print_str(b" addr=0x");
    print_hex64(bus_address);
    print_str(b" space=");
    print_u64(requested_space as u64);
    print_str(b"->");
    print_u64(translated_space as u64);
    print_str(b" translated=0x");
    print_hex64(translated_address);
    print_str(b" mmio=0x");
    print_hex64(mmio_base);
    print_str(b"/");
    print_u64(mmio_len);
    print_str(b" port=0x");
    print_hex64(port_base);
    print_str(b"/");
    print_u64(port_len);
    print_str(b"\n");
}

unsafe fn pool_pull_request_bytes(
    service_label: u64,
    transfer_id: u64,
    dst: u64,
    len: u64,
) -> bool {
    let mut offset = 0u64;
    while offset < len {
        let chunk = (len - offset).min(FSD_ARG_BYTES);
        let (_, status, _, _, _) =
            call_on4((service_label << 12) | 3, transfer_id, offset, chunk, 0);
        if status as u32 as i32 != STATUS_SUCCESS {
            return false;
        }
        let mut index = 0u64;
        while index < chunk {
            let byte = read_volatile((FSD_ARG_VADDR + index) as *const u8);
            write_volatile((dst + offset + index) as *mut u8, byte);
            index += 1;
        }
        offset += chunk;
    }
    true
}

unsafe fn pool_push_request_bytes(
    transfer_id: u64,
    src: u64,
    source_offset: u64,
    destination_offset: u64,
    len: u64,
) -> bool {
    let mut copied = 0u64;
    while copied < len {
        let chunk = (len - copied).min(FSD_ARG_BYTES);
        let mut index = 0u64;
        while index < chunk {
            let byte = read_volatile((src + source_offset + copied + index) as *const u8);
            write_volatile((FSD_ARG_VADDR + index) as *mut u8, byte);
            index += 1;
        }
        let (_, status, _, _, _) = call_on4(
            (FSD_SERVICE_PUSH_IRP_OUTPUT_LABEL << 12) | 3,
            transfer_id,
            destination_offset + copied,
            chunk,
            0,
        );
        if status as u32 as i32 != STATUS_SUCCESS {
            return false;
        }
        copied += chunk;
    }
    true
}

unsafe fn pool_free_request_buffers(data: u64, aux_data: u64, mdl: u64) {
    if mdl != 0 {
        pool_free(mdl);
    }
    if aux_data != 0 && aux_data != data {
        pool_free(aux_data);
    }
    if data != 0 {
        pool_free(data);
    }
}

unsafe fn pool_free_irp_auxiliary_graph(
    pnp_resource_list: u64,
    create_security_context: u64,
    create_access_state: u64,
    create_parameters: u64,
) {
    for pointer in [
        create_parameters,
        create_access_state,
        create_security_context,
        pnp_resource_list,
    ] {
        if pointer != 0 {
            pool_free(pointer);
        }
    }
}

unsafe fn allocate_nonpaged_mdl(virtual_address: u64, length: u64) -> u64 {
    if virtual_address == 0 || length == 0 || length > u32::MAX as u64 {
        return 0;
    }
    let mdl = pool_alloc_zeroed(nt_mdl::MDL_SIZE as u64);
    if mdl == 0 {
        return 0;
    }
    write_unaligned(
        (mdl + nt_mdl::MDL_OFF_SIZE) as *mut i16,
        nt_mdl::MDL_SIZE as i16,
    );
    write_unaligned(
        (mdl + nt_mdl::MDL_OFF_FLAGS) as *mut i16,
        nt_mdl::MDL_MAPPED_TO_SYSTEM_VA
            | nt_mdl::MDL_PAGES_LOCKED
            | nt_mdl::MDL_SOURCE_IS_NONPAGED_POOL,
    );
    write_unaligned(
        (mdl + nt_mdl::MDL_OFF_MAPPED_SYSTEM_VA) as *mut u64,
        virtual_address,
    );
    write_unaligned(
        (mdl + nt_mdl::MDL_OFF_START_VA) as *mut u64,
        virtual_address & !0xFFF,
    );
    write_unaligned(
        (mdl + nt_mdl::MDL_OFF_BYTE_COUNT) as *mut u32,
        length as u32,
    );
    write_unaligned(
        (mdl + nt_mdl::MDL_OFF_BYTE_OFFSET) as *mut u32,
        (virtual_address & 0xFFF) as u32,
    );
    mdl
}

// Retained pending-IRP completion. When a pipe READ goes STATUS_PENDING, npfs retains the
// read IRP in its inbound queue (QueueState=ReadEntries) and the EXECUTIVE parks the caller. The
// peer's later WRITE is serviced by npfs's OWN NpWriteDataQueue fast path, which copies the write
// payload DIRECTLY into that pending read IRP's buffer and completes it via IoCompleteRequest —
// synchronously, during the write call. So by the time control returns to the executive the read data
// is in the retained read IRP and the inbound queue is drained; a fresh read would find nothing.
// Completion is therefore recorded in the canonical pending-IRP owner node. Its buffers are
// reclaimed only after the executive consumes the result through the mirrored component pool.
#[repr(C)]
#[derive(Clone, Copy)]
struct PendingIrpNode {
    next: u64,
    /// Generation-tagged lifecycle word. It is accessed only through `AtomicU64`; keeping it out
    /// of `PendingIrp` makes payload snapshots disjoint from concurrent state transitions.
    owner_state: u64,
    /// Canonical lookup identity, accessed atomically and cleared before TOMBSTONE publication.
    canonical_irp_id: u64,
    /// Raw WDM identity used by `IoCompleteRequest`. This remains separate from the mutable request
    /// payload so lookup never races post-dispatch FILE_OBJECT bookkeeping.
    raw_irp: u64,
    entry: PendingIrp,
}
const FSD_RUNTIME_TABLES_OFF: u64 = 0x3000;
const FSD_COMPLETION_SEQ_OFF: u64 = FSD_RUNTIME_TABLES_OFF;
const FSD_PENDING_IRP_CAP: usize = 256;
const FSD_PENDING_IRP_HEAD_OFF: u64 = FSD_RUNTIME_TABLES_OFF + 0x08;
const FSD_PENDING_IRPS_OFF: u64 = align_up_u64(FSD_RUNTIME_TABLES_OFF + 0x10, 8);
const _: () = assert!(
    FSD_PENDING_IRPS_OFF
        + core::mem::size_of::<PendingIrpNode>() as u64 * FSD_PENDING_IRP_CAP as u64
        <= FSD_DATA_PHYSICAL_MAP_OFF
);

const fn align_up_u64(value: u64, align: u64) -> u64 {
    (value + align - 1) & !(align - 1)
}

unsafe fn next_completion_seq(data_base: u64) -> u64 {
    let sequence = &*((data_base + FSD_COMPLETION_SEQ_OFF) as *const AtomicU64);
    sequence
        .fetch_update(Ordering::AcqRel, Ordering::Acquire, |current| {
            let next = current.wrapping_add(1);
            Some(if next == 0 { 1 } else { next })
        })
        .unwrap_or(0)
        .wrapping_add(1)
        .max(1)
}

#[inline]
unsafe fn pending_irp_head(data_base: u64) -> *mut u64 {
    (data_base + FSD_PENDING_IRP_HEAD_OFF) as *mut u64
}

#[inline]
unsafe fn pending_irp_owner_state(node: u64) -> &'static AtomicU64 {
    &*((node + core::mem::offset_of!(PendingIrpNode, owner_state) as u64) as *const AtomicU64)
}

#[inline]
unsafe fn pending_irp_canonical_id(node: u64) -> &'static AtomicU64 {
    &*((node + core::mem::offset_of!(PendingIrpNode, canonical_irp_id) as u64) as *const AtomicU64)
}

#[inline]
unsafe fn pending_irp_raw_irp(node: u64) -> &'static AtomicU64 {
    &*((node + core::mem::offset_of!(PendingIrpNode, raw_irp) as u64) as *const AtomicU64)
}

#[inline]
const fn pending_irp_entry_address(node: u64) -> u64 {
    node + core::mem::offset_of!(PendingIrpNode, entry) as u64
}

#[inline]
fn hosted_irp_state_kind(state: u64) -> u64 {
    state & HOSTED_IRP_STATE_MASK
}

#[inline]
fn hosted_irp_state_with_kind(state: u64, kind: u64) -> u64 {
    (state & !HOSTED_IRP_STATE_MASK) | kind
}

fn completion_owner_phase(kind: u64) -> Option<nt_io_manager::CompletionOwnerPhase> {
    use nt_io_manager::CompletionOwnerPhase;
    match kind {
        HOSTED_IRP_DISPATCHING => Some(CompletionOwnerPhase::Dispatching),
        HOSTED_IRP_STOPPED_DISPATCH => Some(CompletionOwnerPhase::StoppedDispatch),
        HOSTED_IRP_PENDING => Some(CompletionOwnerPhase::Pending),
        HOSTED_IRP_CANCEL_ROUTINE => Some(CompletionOwnerPhase::CancelRoutine),
        HOSTED_IRP_COMPLETING_DISPATCH => Some(CompletionOwnerPhase::CompletingDispatch),
        HOSTED_IRP_COMPLETING_PENDING => Some(CompletionOwnerPhase::CompletingPending),
        HOSTED_IRP_COMPLETING_CANCEL => Some(CompletionOwnerPhase::CompletingCancel),
        HOSTED_IRP_COMPLETED_DISPATCH => Some(CompletionOwnerPhase::CompletedDispatch),
        HOSTED_IRP_READY => Some(CompletionOwnerPhase::Ready),
        HOSTED_IRP_COMPLETED_CANCEL => Some(CompletionOwnerPhase::CompletedCancel),
        HOSTED_IRP_COMPLETING_DEFERRED => Some(CompletionOwnerPhase::CompletingDeferred),
        _ => None,
    }
}

fn completion_owner_kind(phase: nt_io_manager::CompletionOwnerPhase) -> u64 {
    use nt_io_manager::CompletionOwnerPhase;
    match phase {
        CompletionOwnerPhase::Dispatching => HOSTED_IRP_DISPATCHING,
        CompletionOwnerPhase::StoppedDispatch => HOSTED_IRP_STOPPED_DISPATCH,
        CompletionOwnerPhase::Pending => HOSTED_IRP_PENDING,
        CompletionOwnerPhase::CancelRoutine => HOSTED_IRP_CANCEL_ROUTINE,
        CompletionOwnerPhase::CompletingDispatch => HOSTED_IRP_COMPLETING_DISPATCH,
        CompletionOwnerPhase::CompletingPending => HOSTED_IRP_COMPLETING_PENDING,
        CompletionOwnerPhase::CompletingCancel => HOSTED_IRP_COMPLETING_CANCEL,
        CompletionOwnerPhase::CompletedDispatch => HOSTED_IRP_COMPLETED_DISPATCH,
        CompletionOwnerPhase::Ready => HOSTED_IRP_READY,
        CompletionOwnerPhase::CompletedCancel => HOSTED_IRP_COMPLETED_CANCEL,
        CompletionOwnerPhase::CompletingDeferred => HOSTED_IRP_COMPLETING_DEFERRED,
    }
}

fn next_hosted_irp_generation(state: u64) -> u64 {
    let mut generation = (state & !HOSTED_IRP_STATE_MASK).wrapping_add(HOSTED_IRP_GENERATION_STEP);
    if generation == 0 {
        generation = HOSTED_IRP_GENERATION_STEP;
    }
    generation
}

#[inline]
unsafe fn pending_irp_slot(data_base: u64, index: usize) -> *mut PendingIrpNode {
    (data_base
        + FSD_PENDING_IRPS_OFF
        + (index as u64) * core::mem::size_of::<PendingIrpNode>() as u64) as *mut PendingIrpNode
}

#[inline]
unsafe fn pending_irp_node_valid(node: u64) -> bool {
    let pool_start = FSD_POOL_VADDR + POOL_DATA_OFF;
    let pool_end = FSD_POOL_VADDR + FSD_POOL_FRAMES * 0x1000;
    let in_pool = node >= pool_start
        && node & 7 == 0
        && node
            .checked_add(core::mem::size_of::<PendingIrpNode>() as u64)
            .is_some_and(|end| end <= pool_end);
    let table_start = FSD_DATA_VADDR + FSD_PENDING_IRPS_OFF;
    let table_end =
        table_start + core::mem::size_of::<PendingIrpNode>() as u64 * FSD_PENDING_IRP_CAP as u64;
    let in_table = node >= table_start
        && node & 7 == 0
        && node
            .checked_add(core::mem::size_of::<PendingIrpNode>() as u64)
            .is_some_and(|end| end <= table_end)
        && (node - table_start) % core::mem::size_of::<PendingIrpNode>() as u64 == 0;
    in_pool || in_table
}

#[derive(Clone, Copy)]
struct PendingIrpCompletionTarget {
    data: u64,
    output_capacity: u64,
    completion_source_kind: u8,
    major: u8,
    minor: u8,
}

#[derive(Clone, Copy)]
struct PendingIrpCompletionClaim {
    node: u64,
    completing_state: u64,
    owner_claim: nt_io_manager::CompletionOwnerClaim,
    target: PendingIrpCompletionTarget,
}

unsafe fn claim_pending_irp_completion(irp: u64) -> Option<PendingIrpCompletionClaim> {
    let mut node = (&*pending_irp_head(FSD_DATA_VADDR).cast::<AtomicU64>()).load(Ordering::Acquire);
    let mut steps = 0u64;
    while node != 0 && steps < POOL_FREE_LIST_MAX {
        if !pending_irp_node_valid(node) {
            return None;
        }
        let state = pending_irp_owner_state(node).load(Ordering::Acquire);
        let kind = hosted_irp_state_kind(state);
        if let Some(owner_claim) =
            completion_owner_phase(kind).and_then(nt_io_manager::CompletionOwnerClaim::begin)
        {
            // The raw IRP identity and completion projection remain immutable while the owner is
            // active. Match the raw IRP before claiming the lifecycle word; the generation-bearing
            // CAS below proves that the inspected projection was not recycled before the claim.
            let candidate_irp = pending_irp_raw_irp(node).load(Ordering::Relaxed);
            if candidate_irp != irp {
                node = read_volatile(node as *const u64);
                steps += 1;
                continue;
            }
            let completing =
                hosted_irp_state_with_kind(state, completion_owner_kind(owner_claim.claimed()));
            if pending_irp_owner_state(node)
                .compare_exchange(state, completing, Ordering::AcqRel, Ordering::Acquire)
                .is_ok()
            {
                let entry = pending_irp_entry_address(node);
                return Some(PendingIrpCompletionClaim {
                    node,
                    completing_state: completing,
                    owner_claim,
                    target: PendingIrpCompletionTarget {
                        data: read_volatile(
                            (entry + core::mem::offset_of!(PendingIrp, data) as u64) as *const u64,
                        ),
                        output_capacity: read_volatile(
                            (entry + core::mem::offset_of!(PendingIrp, output_capacity) as u64)
                                as *const u64,
                        ),
                        completion_source_kind: read_volatile(
                            (entry
                                + core::mem::offset_of!(PendingIrp, completion_source_kind) as u64)
                                as *const u8,
                        ),
                        major: read_volatile(
                            (entry + core::mem::offset_of!(PendingIrp, major) as u64) as *const u8,
                        ),
                        minor: read_volatile(
                            (entry + core::mem::offset_of!(PendingIrp, minor) as u64) as *const u8,
                        ),
                    },
                });
            }
            continue;
        }
        node = read_volatile(node as *const u64);
        steps += 1;
    }
    None
}

unsafe fn pending_irp_raw_identity_exists(irp: u64) -> bool {
    let mut node = (&*pending_irp_head(FSD_DATA_VADDR).cast::<AtomicU64>()).load(Ordering::Acquire);
    let mut steps = 0u64;
    while node != 0 && steps < POOL_FREE_LIST_MAX {
        if !pending_irp_node_valid(node) {
            return false;
        }
        let kind = hosted_irp_state_kind(pending_irp_owner_state(node).load(Ordering::Acquire));
        if kind != HOSTED_IRP_TOMBSTONE && pending_irp_raw_irp(node).load(Ordering::Relaxed) == irp
        {
            return true;
        }
        node = read_volatile(node as *const u64);
        steps += 1;
    }
    false
}

unsafe fn release_pending_irp_completion_claim(
    claim: PendingIrpCompletionClaim,
    release: nt_io_manager::CompletionClaimRelease,
) {
    let active = hosted_irp_state_with_kind(
        claim.completing_state,
        completion_owner_kind(claim.owner_claim.release(release, false)),
    );
    if pending_irp_owner_state(claim.node)
        .compare_exchange(
            claim.completing_state,
            active,
            Ordering::Release,
            Ordering::Acquire,
        )
        .is_ok()
    {
        return;
    }

    // A dispatch or cancel caller may transfer ownership while this worker is unwinding. Once it
    // publishes DEFERRED that caller has returned, so both a stopped unwind and a failed attempt
    // must leave the graph with the ordinary asynchronous owner.
    let deferred =
        hosted_irp_state_with_kind(claim.completing_state, HOSTED_IRP_COMPLETING_DEFERRED);
    let handed_off = hosted_irp_state_with_kind(
        claim.completing_state,
        completion_owner_kind(claim.owner_claim.release(release, true)),
    );
    pending_irp_owner_state(claim.node)
        .compare_exchange(deferred, handed_off, Ordering::Release, Ordering::Acquire)
        .expect("hosted IRP completion claim lost its caller handoff");
}

unsafe fn restore_pending_irp_completion_claim(claim: PendingIrpCompletionClaim) {
    release_pending_irp_completion_claim(claim, nt_io_manager::CompletionClaimRelease::Restore);
}

unsafe fn park_pending_irp_completion_claim(claim: PendingIrpCompletionClaim) {
    release_pending_irp_completion_claim(claim, nt_io_manager::CompletionClaimRelease::Stop);
}

unsafe fn tombstone_pending_irp_owner(node: u64, consuming_state: u64) {
    // `consuming_state` is exclusive. Clear the old identity before publishing TOMBSTONE; after
    // that release a dispatcher may immediately reuse the node for a new generation.
    pending_irp_canonical_id(node).store(0, Ordering::Relaxed);
    pending_irp_raw_irp(node).store(0, Ordering::Relaxed);
    write_volatile(pending_irp_entry_address(node) as *mut u64, 0);
    let tombstone = hosted_irp_state_with_kind(consuming_state, HOSTED_IRP_TOMBSTONE);
    if pending_irp_owner_state(node)
        .compare_exchange(
            consuming_state,
            tombstone,
            Ordering::Release,
            Ordering::Acquire,
        )
        .is_err()
    {
        panic!("hosted IRP owner changed while being retired");
    }
}

unsafe fn release_pending_irp_graph_component(entry: PendingIrp) {
    let reclaim = entry
        .completion
        .completed()
        .map(|completion| completion.reclaim)
        .unwrap_or(0);
    let candidates = [
        reclaim,
        entry.mdl,
        if entry.aux_data != entry.data {
            entry.aux_data
        } else {
            0
        },
        entry.data,
        entry.create_parameters,
        entry.create_access_state,
        entry.create_security_context,
        entry.pnp_resource_list,
        entry.irp,
        if entry.owns_fo { entry.file_object } else { 0 },
    ];
    for (index, pointer) in candidates.iter().copied().enumerate() {
        if pointer != 0 && !candidates[..index].contains(&pointer) {
            pool_free(pointer);
        }
    }
}

unsafe fn insert_pending_irp(canonical_irp_id: u64, entry: PendingIrp) -> Option<u64> {
    let head = pending_irp_head(FSD_DATA_VADDR).cast::<AtomicU64>();
    let mut node = (&*head).load(Ordering::Acquire);
    let mut steps = 0u64;
    while node != 0 && steps < POOL_FREE_LIST_MAX {
        if !pending_irp_node_valid(node) {
            return None;
        }
        let state = pending_irp_owner_state(node).load(Ordering::Acquire);
        if hosted_irp_state_kind(state) == HOSTED_IRP_TOMBSTONE {
            let generation = next_hosted_irp_generation(state);
            let initializing = generation | HOSTED_IRP_INITIALIZING;
            if pending_irp_owner_state(node)
                .compare_exchange(state, initializing, Ordering::AcqRel, Ordering::Acquire)
                .is_ok()
            {
                write_volatile(pending_irp_entry_address(node) as *mut PendingIrp, entry);
                pending_irp_canonical_id(node).store(canonical_irp_id, Ordering::Relaxed);
                pending_irp_raw_irp(node).store(entry.irp, Ordering::Relaxed);
                let dispatching = generation | HOSTED_IRP_DISPATCHING;
                pending_irp_owner_state(node).store(dispatching, Ordering::Release);
                return Some(node);
            }
        }
        node = read_volatile(node as *const u64);
        steps += 1;
    }

    node = 0;
    let mut owner_state_initialized = false;
    let initializing = HOSTED_IRP_GENERATION_STEP | HOSTED_IRP_INITIALIZING;
    for index in 0..FSD_PENDING_IRP_CAP {
        let slot = pending_irp_slot(FSD_DATA_VADDR, index);
        if pending_irp_owner_state(slot as u64)
            .compare_exchange(0, initializing, Ordering::AcqRel, Ordering::Acquire)
            .is_ok()
        {
            node = slot as u64;
            owner_state_initialized = true;
            break;
        }
    }
    if node == 0 {
        node = pool_alloc(core::mem::size_of::<PendingIrpNode>() as u64);
        if node == 0 {
            return None;
        }
    }
    let generation = HOSTED_IRP_GENERATION_STEP;
    write_volatile(node as *mut u64, 0);
    pending_irp_canonical_id(node).store(canonical_irp_id, Ordering::Relaxed);
    pending_irp_raw_irp(node).store(entry.irp, Ordering::Relaxed);
    write_volatile(pending_irp_entry_address(node) as *mut PendingIrp, entry);
    if !owner_state_initialized {
        pending_irp_owner_state(node).store(initializing, Ordering::Relaxed);
    }
    loop {
        let old = (&*head).load(Ordering::Acquire);
        write_volatile(node as *mut u64, old);
        if (&*head)
            .compare_exchange(old, node, Ordering::Release, Ordering::Acquire)
            .is_ok()
        {
            break;
        }
    }
    pending_irp_owner_state(node).store(generation | HOSTED_IRP_DISPATCHING, Ordering::Release);
    Some(node)
}

#[derive(Clone, Copy)]
struct PendingIrpCancelTarget {
    node: u64,
    irp: u64,
    cancel_routine: u64,
}

unsafe fn claim_pending_irp_cancel_target(canonical_irp_id: u64) -> Option<PendingIrpCancelTarget> {
    if canonical_irp_id == 0 {
        return None;
    }
    let mut node = (&*pending_irp_head(FSD_DATA_VADDR).cast::<AtomicU64>()).load(Ordering::Acquire);
    let mut steps = 0u64;
    while node != 0 && steps < POOL_FREE_LIST_MAX {
        if !pending_irp_node_valid(node) {
            return None;
        }
        let state = pending_irp_owner_state(node).load(Ordering::Acquire);
        if hosted_irp_state_kind(state) == HOSTED_IRP_PENDING
            && pending_irp_canonical_id(node).load(Ordering::Relaxed) == canonical_irp_id
        {
            let cancel_state = hosted_irp_state_with_kind(state, HOSTED_IRP_CANCEL_ROUTINE);
            if pending_irp_owner_state(node)
                .compare_exchange(state, cancel_state, Ordering::AcqRel, Ordering::Acquire)
                .is_err()
            {
                continue;
            }
            let entry = read_volatile(pending_irp_entry_address(node) as *const PendingIrp);
            if pending_irp_canonical_id(node).load(Ordering::Relaxed) != canonical_irp_id
                || entry.irp == 0
                || pending_irp_raw_irp(node).load(Ordering::Relaxed) != entry.irp
            {
                panic!("claimed hosted IRP cancel identity changed");
            }
            let cancel_routine =
                read_unaligned((entry.irp + WDM_X64_IRP_CANCEL_ROUTINE_OFFSET) as *const u64);
            return Some(PendingIrpCancelTarget {
                node,
                irp: entry.irp,
                cancel_routine,
            });
        }
        node = read_volatile(node as *const u64);
        steps += 1;
    }
    None
}

unsafe fn cancel_pending_irp(canonical_irp_id: u64) -> bool {
    let Some(target) = claim_pending_irp_cancel_target(canonical_irp_id) else {
        return false;
    };
    let invoked = s_io_cancel_irp(target.irp);
    loop {
        let state = pending_irp_owner_state(target.node).load(Ordering::Acquire);
        match hosted_irp_state_kind(state) {
            HOSTED_IRP_CANCEL_ROUTINE => {
                let pending = hosted_irp_state_with_kind(state, HOSTED_IRP_PENDING);
                if pending_irp_owner_state(target.node)
                    .compare_exchange(state, pending, Ordering::AcqRel, Ordering::Acquire)
                    .is_err()
                {
                    continue;
                }
                break;
            }
            // Another worker owns completion and will publish READY. Cancellation must not spin on
            // a preempted worker, especially on a single-core seL4 schedule.
            HOSTED_IRP_COMPLETED_CANCEL => {
                let ready = hosted_irp_state_with_kind(state, HOSTED_IRP_READY);
                if pending_irp_owner_state(target.node)
                    .compare_exchange(state, ready, Ordering::AcqRel, Ordering::Acquire)
                    .is_err()
                {
                    continue;
                }
                break;
            }
            HOSTED_IRP_COMPLETING_CANCEL => {
                let deferred = hosted_irp_state_with_kind(state, HOSTED_IRP_COMPLETING_DEFERRED);
                if pending_irp_owner_state(target.node)
                    .compare_exchange(state, deferred, Ordering::AcqRel, Ordering::Acquire)
                    .is_err()
                {
                    continue;
                }
                break;
            }
            HOSTED_IRP_READY => break,
            other => panic!("invalid hosted IRP post-cancel owner state {other}"),
        }
    }
    let trace = FSD_CANCEL_TRACE_COUNT.fetch_add(1, Ordering::Relaxed);
    if trace < 32 {
        print_str(b"[fsd-cancel] canonical-irp=0x");
        print_hex64(canonical_irp_id);
        print_str(b" raw-irp=0x");
        print_hex64(target.irp);
        print_str(b" routine=0x");
        print_hex64(target.cancel_routine);
        print_str(b" invoked=");
        print_u64(invoked as u64);
        print_str(b"\n");
    }
    true
}

unsafe fn copy_pending_irp_completion(
    canonical_irp_id: u64,
    offset: u64,
    capacity: u64,
) -> (i32, u64) {
    if canonical_irp_id == 0 {
        return (0xC000_000Du32 as i32, 0); // STATUS_INVALID_PARAMETER
    }
    let mut node = (&*pending_irp_head(FSD_DATA_VADDR).cast::<AtomicU64>()).load(Ordering::Acquire);
    let mut steps = 0u64;
    while node != 0 && steps < POOL_FREE_LIST_MAX {
        if !pending_irp_node_valid(node) {
            return (0xC000_0001u32 as i32, 0); // STATUS_UNSUCCESSFUL
        }
        let next = read_volatile(node as *const u64);
        let state = pending_irp_owner_state(node).load(Ordering::Acquire);
        if hosted_irp_state_kind(state) == HOSTED_IRP_PUBLISHED
            && pending_irp_canonical_id(node).load(Ordering::Relaxed) == canonical_irp_id
        {
            let copying = hosted_irp_state_with_kind(state, HOSTED_IRP_COPYING);
            if pending_irp_owner_state(node)
                .compare_exchange(state, copying, Ordering::AcqRel, Ordering::Acquire)
                .is_err()
            {
                continue;
            }
            let entry = read_volatile(pending_irp_entry_address(node) as *const PendingIrp);
            let Some(completion) = entry.completion.completed() else {
                pending_irp_owner_state(node).store(state, Ordering::Release);
                return (0xC000_0001u32 as i32, 0);
            };
            let valid_range = offset
                .checked_add(capacity)
                .is_some_and(|end| end <= completion.length as u64);
            let source = completion.source.checked_add(offset);
            let source_valid = capacity == 0
                || component_pool_allocation_capacity(completion.source).is_some_and(|available| {
                    offset
                        .checked_add(capacity)
                        .is_some_and(|end| end <= available)
                });
            if !valid_range || !source_valid {
                pending_irp_owner_state(node).store(state, Ordering::Release);
                return (0xC000_000Du32 as i32, 0);
            }
            if let Some(source) = source {
                if !pool_push_request_bytes(canonical_irp_id, source, 0, 0, capacity) {
                    pending_irp_owner_state(node).store(state, Ordering::Release);
                    return (0xC000_0001u32 as i32, 0); // STATUS_UNSUCCESSFUL
                }
            }
            pending_irp_owner_state(node).store(state, Ordering::Release);
            return (0, capacity);
        }
        node = next;
        steps += 1;
    }
    (0xC000_000Du32 as i32, 0)
}

unsafe fn acknowledge_pending_irp_completion(canonical_irp_id: u64) -> bool {
    if canonical_irp_id == 0 {
        return false;
    }
    let mut node = (&*pending_irp_head(FSD_DATA_VADDR).cast::<AtomicU64>()).load(Ordering::Acquire);
    let mut steps = 0u64;
    while node != 0 && steps < POOL_FREE_LIST_MAX {
        if !pending_irp_node_valid(node) {
            return false;
        }
        let next = read_volatile(node as *const u64);
        let state = pending_irp_owner_state(node).load(Ordering::Acquire);
        if hosted_irp_state_kind(state) == HOSTED_IRP_PUBLISHED
            && pending_irp_canonical_id(node).load(Ordering::Relaxed) == canonical_irp_id
        {
            let consuming = hosted_irp_state_with_kind(state, HOSTED_IRP_CONSUMING);
            if pending_irp_owner_state(node)
                .compare_exchange(state, consuming, Ordering::AcqRel, Ordering::Acquire)
                .is_err()
            {
                continue;
            }
            let entry = read_volatile(pending_irp_entry_address(node) as *const PendingIrp);
            let completion = entry
                .completion
                .completed()
                .expect("published hosted IRP owner has no completion payload");
            let create_failed =
                matches!(entry.major as u64, 0 | 1) && (completion.status as i32).is_negative();
            if !entry.owns_fo
                && (entry.major as u64 == IRP_MJ_CLOSE || create_failed)
                && entry.canonical_file_id != 0
            {
                fo_release(entry.canonical_file_id);
            }
            release_pending_irp_graph_component(entry);
            tombstone_pending_irp_owner(node, consuming);
            return true;
        }
        node = next;
        steps += 1;
    }
    false
}

unsafe fn pending_irp_node_exec_va(win: ExecVaWindow, node: u64) -> Option<u64> {
    let table_start = FSD_DATA_VADDR + FSD_PENDING_IRPS_OFF;
    let table_bytes = core::mem::size_of::<PendingIrpNode>() as u64 * FSD_PENDING_IRP_CAP as u64;
    if node >= table_start
        && node.checked_add(core::mem::size_of::<PendingIrpNode>() as u64)?
            <= table_start.checked_add(table_bytes)?
        && (node - table_start) % core::mem::size_of::<PendingIrpNode>() as u64 == 0
    {
        return win.data_va.checked_add(node - FSD_DATA_VADDR);
    }
    hosted_pool_allocation_exec_va(
        win.pool_va,
        node,
        core::mem::size_of::<PendingIrpNode>() as u64,
    )
}

fn hosted_completion_storage_instance(instance: usize) -> usize {
    unsafe {
        hosted_provider_dispatch_route_for_instance(instance)
            .map(|route| route.provider_instance)
            .unwrap_or(instance)
    }
}

unsafe fn poll_hosted_completion(instance_index: usize) -> Option<nt_io_manager::DriverCompletion> {
    let owner_domain = instance_domain_identity(instance(instance_index)?)?;
    let storage_instance = hosted_completion_storage_instance(instance_index);
    let win = ExecVaWindow::try_for_instance(storage_instance)?;
    let head = (win.data_va + FSD_PENDING_IRP_HEAD_OFF) as *const AtomicU64;
    loop {
        let mut node = (&*head).load(Ordering::Acquire);
        let mut best: Option<(u64, u64, u64)> = None;
        let mut steps = 0u64;
        while node != 0 && steps < POOL_FREE_LIST_MAX {
            let node_exec = pending_irp_node_exec_va(win, node)?;
            let next = read_volatile(node_exec as *const u64);
            let ready_state = pending_irp_owner_state(node_exec).load(Ordering::Acquire);
            if hosted_irp_state_kind(ready_state) != HOSTED_IRP_READY {
                node = next;
                steps += 1;
                continue;
            }
            let copying_state = hosted_irp_state_with_kind(ready_state, HOSTED_IRP_COPYING);
            if pending_irp_owner_state(node_exec)
                .compare_exchange(
                    ready_state,
                    copying_state,
                    Ordering::AcqRel,
                    Ordering::Acquire,
                )
                .is_err()
            {
                node = next;
                steps += 1;
                continue;
            }
            let canonical_irp_id = pending_irp_canonical_id(node_exec).load(Ordering::Relaxed);
            let entry = read_volatile(pending_irp_entry_address(node_exec) as *const PendingIrp);
            let completion = entry.completion.completed();
            pending_irp_owner_state(node_exec).store(ready_state, Ordering::Release);
            if canonical_irp_id != 0 && entry.owner_domain == owner_domain {
                if let Some(completion) = completion {
                    if best
                        .as_ref()
                        .is_none_or(|(_, _, sequence)| completion.sequence < *sequence)
                    {
                        best = Some((node_exec, ready_state, completion.sequence));
                    }
                }
            }
            node = next;
            steps += 1;
        }
        let (node_exec, ready_state, _) = best?;
        let published_state = hosted_irp_state_with_kind(ready_state, HOSTED_IRP_PUBLISHED);
        if pending_irp_owner_state(node_exec)
            .compare_exchange(
                ready_state,
                published_state,
                Ordering::AcqRel,
                Ordering::Acquire,
            )
            .is_err()
        {
            continue;
        }
        let canonical_irp_id = pending_irp_canonical_id(node_exec).load(Ordering::Relaxed);
        let entry = read_volatile(pending_irp_entry_address(node_exec) as *const PendingIrp);
        let completion = entry
            .completion
            .completed()
            .expect("published hosted IRP owner has no completion payload");
        return Some(nt_io_manager::DriverCompletion {
            irp_id: IrpId(canonical_irp_id),
            status: nt_status::NtStatus(completion.status as i32),
            information: completion.information,
            file_context: if matches!(
                entry.major,
                major::IRP_MJ_CREATE
                    | major::IRP_MJ_CREATE_NAMED_PIPE
                    | major::IRP_MJ_CREATE_MAILSLOT
            ) {
                Some(entry.fid)
            } else {
                None
            },
        });
    }
}

// --- host-side pool allocator (the trampolines run in the component) --------------------------

/// Hard bound on a free-list traversal. The pool has a 16-byte header, so a well-formed
/// list can never be longer than this; anything past it means the list is CORRUPT (a cycle), and a
/// cycle must degrade to the bump path rather than spin the whole executive.
const POOL_FREE_LIST_MAX: u64 = (FSD_POOL_FRAMES * 0x1000) / 16;
const COMPONENT_POOL_LOCK_OFF: u64 = 0x10;
const COMPONENT_DEVICE_REPLY_LOCK_OFF: u64 = 0x18;
/// Double `pool_free` calls the guard below rejected, and free-list cycles `pool_alloc` broke out of.
/// Both are counter-backed so a regression is a gate failure rather than a silent 555-second hang.
pub(crate) static FSD_POOL_DOUBLE_FREES: AtomicU64 = AtomicU64::new(0);
pub(crate) static FSD_POOL_LIST_CYCLES: AtomicU64 = AtomicU64::new(0);
pub(crate) static FSD_POOL_INVALID_FREES: AtomicU64 = AtomicU64::new(0);

struct ComponentPoolLockGuard;

impl Drop for ComponentPoolLockGuard {
    fn drop(&mut self) {
        unsafe {
            (&*((FSD_POOL_VADDR + COMPONENT_POOL_LOCK_OFF) as *const AtomicU64))
                .store(0, Ordering::Release);
        }
    }
}

unsafe fn component_pool_lock() -> ComponentPoolLockGuard {
    let lock = &*((FSD_POOL_VADDR + COMPONENT_POOL_LOCK_OFF) as *const AtomicU64);
    while lock
        .compare_exchange_weak(0, 1, Ordering::Acquire, Ordering::Relaxed)
        .is_err()
    {
        // Hosted driver threads share one physical CPU. A contended raw spin would prevent the
        // owner from ever being scheduled, especially when it is parked across an executive
        // callback. Yielding preserves real mutual exclusion while giving the owner a chance to
        // finish the bounded allocator mutation and release the lock.
        crate::yield_now();
    }
    ComponentPoolLockGuard
}

struct ComponentDeviceReplyLockGuard;

impl Drop for ComponentDeviceReplyLockGuard {
    fn drop(&mut self) {
        unsafe {
            (&*((FSD_POOL_VADDR + COMPONENT_DEVICE_REPLY_LOCK_OFF) as *const AtomicU64))
                .store(0, Ordering::Release);
        }
    }
}

unsafe fn component_device_reply_lock() -> ComponentDeviceReplyLockGuard {
    let lock = &*((FSD_POOL_VADDR + COMPONENT_DEVICE_REPLY_LOCK_OFF) as *const AtomicU64);
    while lock
        .compare_exchange_weak(0, 1, Ordering::Acquire, Ordering::Relaxed)
        .is_err()
    {
        crate::yield_now();
    }
    ComponentDeviceReplyLockGuard
}

/// A simple free-list allocator: an FSD alloc/frees file objects; a leak-forever bump would exhaust
/// under FSCTL churn. Header = 16 B ([+0]=capacity, [+8]=next-free). `pool_free` pushes onto the
/// single free list (head @ [POOL+8]); `pool_alloc` first-fits it before bumping. Counter @ [POOL+0].
///
/// The first-fit walk is cycle-bounded so allocator metadata damage cannot spin the executive.
pub(crate) unsafe fn pool_alloc(size: u64) -> u64 {
    let _guard = component_pool_lock();
    POOL_CALLS += 1;
    if POOL_CALLS % 16384 == 0 {
        print_str(b"[fsd-pool-heartbeat] calls=");
        print_u64(POOL_CALLS);
        print_str(b" size=");
        print_u64(size);
        print_str(b"\n");
    }
    // first-fit the free list
    let head_slot = (FSD_POOL_VADDR + 8) as *mut u64;
    let mut prev = head_slot;
    let mut cur = read_volatile(head_slot);
    let mut steps = 0u64;
    while cur != 0 {
        if steps >= POOL_FREE_LIST_MAX {
            if FSD_POOL_LIST_CYCLES.fetch_add(1, Ordering::Relaxed) == 0 {
                print_str(b"[fsd-host] POOL FREE-LIST CYCLE -> bump path\n");
            }
            break;
        }
        steps += 1;
        let cap = read_volatile((cur - 16) as *const u64);
        if cap >= size {
            let next = read_volatile((cur - 8) as *const u64);
            write_volatile(prev, next);
            return cur;
        }
        prev = (cur - 8) as *mut u64;
        cur = read_volatile((cur - 8) as *const u64);
    }
    // bump
    let ctr = FSD_POOL_VADDR as *mut u64;
    let mut off = read_volatile(ctr);
    if off < POOL_DATA_OFF {
        off = POOL_DATA_OFF;
    }
    // 16-byte header + 16-align the returned block
    let hdr = (FSD_POOL_VADDR + off + 15) & !15;
    let block = hdr + 16;
    let cap = FSD_POOL_VADDR + FSD_POOL_FRAMES * 0x1000;
    if size == 0 || block + size > cap {
        print_str(b"[fsd-host] POOL EXHAUSTED size=0x");
        print_hex(size as u32);
        print_str(b"\n");
        return 0;
    }
    write_volatile(ctr, (block + size) - FSD_POOL_VADDR);
    write_volatile((block - 16) as *mut u64, size); // capacity header
    write_volatile((block - 8) as *mut u64, 0);
    block
}

/// Push one exact allocation base back onto the free list, rejecting invalid and duplicate frees.
unsafe fn pool_free(p: u64) {
    let _guard = component_pool_lock();
    POOL_CALLS += 1;
    if POOL_CALLS % 16384 == 0 {
        print_str(b"[fsd-pool-heartbeat] calls=");
        print_u64(POOL_CALLS);
        print_str(b" free p=");
        print_hex(p as u32);
        print_str(b"\n");
    }
    if component_pool_allocation_capacity(p).is_none() {
        if FSD_POOL_INVALID_FREES.fetch_add(1, Ordering::Relaxed) == 0 {
            print_str(b"[fsd-pool-invalid] component free pointer=");
            print_hex64(p);
            print_str(b"\n");
        }
        return;
    }
    let head_slot = (FSD_POOL_VADDR + 8) as *mut u64;
    let mut cur = read_volatile(head_slot);
    let mut steps = 0u64;
    while cur != 0 && steps < POOL_FREE_LIST_MAX {
        if steps == 4096 && POOL_LONG_WALKS < 8 {
            POOL_LONG_WALKS += 1;
            print_str(b"[fsd-pool] LONG free-list walk p=");
            print_hex(p as u32);
            print_str(b" cur=");
            print_hex(cur as u32);
            print_str(b"\n");
        }
        if cur == p {
            if FSD_POOL_DOUBLE_FREES.fetch_add(1, Ordering::Relaxed) == 0 {
                print_str(b"[fsd-host] rejected DOUBLE pool_free p=0x");
                print_hex(p as u32);
                print_str(b" (would cycle the free list)\n");
            }
            return;
        }
        cur = read_volatile((cur - 8) as *const u64);
        steps += 1;
    }
    if cur != 0 {
        // Already corrupt (a cycle from before this guard existed) — do not extend it.
        if FSD_POOL_LIST_CYCLES.fetch_add(1, Ordering::Relaxed) == 0 {
            print_str(b"[fsd-host] POOL FREE-LIST CYCLE on free -> drop\n");
        }
        return;
    }
    let head = read_volatile(head_slot);
    write_volatile((p - 8) as *mut u64, head);
    write_volatile(head_slot, p);
}

// --- FILE_OBJECT LIFETIME: one FILE_OBJECT per OPEN, not per IRP -------------------------------
//
// ★ THE BUG THIS FIXES (the root cause of the LSA-self-RPC npfs hang). `run_irp` used to build a
// FRESH `FILE_OBJECT` for every dispatched IRP and free it the moment that IRP completed. But an
// FSD keeps the FILE_OBJECT pointer well past the IRP that introduced it:
//
//   * `NpSetFileObject(FileObject, Ccb, NonPagedCcb, End)` (`fileobsup.c:64`) stores our pointer,
//     and `NpCreateClientEnd`/`NpCreateExistingNamedPipe`/`NpSetConnectedPipeState` record it in
//     **`Ccb->FileObject[NamedPipeEnd]`** (`create.c:645/772`, `strucsup.c:334`, `statesup.c:51`).
//   * on disconnect/close npfs WRITES THROUGH that stored pointer —
//     `NpSetFileObject(Ccb->FileObject[end], NULL, NULL, …)` (`statesup.c:163/289/292/310/…`) zeroes
//     `FsContext`(+0x18) / `FsContext2`(+0x20) and sets `PrivateCacheMap`(+0x30) = 1.
//
// With the per-IRP lifetime those stores landed on a block the pool had already RECYCLED. The FSD
// pool hands 0x100-byte blocks straight back out, and the very next consumer of that size class is
// npfs' own `NP_DATA_QUEUE_ENTRY`/`NP_CCB`, so npfs silently corrupted its OWN data-queue
// bookkeeping: +0x10 of an `NP_DATA_QUEUE_ENTRY` is `DataEntryType`, +0x18 is `Irp`, +0x30 is
// `DataSize`; +0x10 of an `NP_DATA_QUEUE` is `QueueState`. A `DataEntryType` outside
// {Buffered, Unbuffered} with `QueueState == Empty` is precisely the state in which
// `NpGetNextRealDataQueueEntry` (`datasup.c:183`) loops forever: it re-reads `Queue.Flink`, calls
// `NpRemoveDataQueueEntry`, and that function returns WITHOUT removing anything when
// `QueueState == Empty` — a call-free infinite spin inside npfs (zero faults, zero imports), which
// is exactly what was observed.
//
// The fix is the NT lifetime: ONE FILE_OBJECT per OPEN, reused by every IRP on that open (which is
// also what makes two concurrent IRPs on one handle — a pending read plus a write, the ordinary
// rpcrt4 server shape — structurally correct rather than merely lucky), freed on CLEANUP/CLOSE.

#[derive(Clone, Copy)]
struct FileObjectSlot {
    /// Generation-protected I/O Manager identity for this open.
    canonical_file_id: u64,
    /// The FILE_OBJECT block in the FSD pool.
    fo: u64,
}

static mut FILE_OBJECTS: Option<Vec<FileObjectSlot>> = None;

/// FILE_OBJECTs created for an open (one per open, not per IRP).
pub(crate) static FSD_FO_OPENS: AtomicU64 = AtomicU64::new(0);
/// IRPs that REUSED the open's existing FILE_OBJECT (the concurrent-IRP proof).
pub(crate) static FSD_FO_REUSED: AtomicU64 = AtomicU64::new(0);
/// Times a `Ccb->FileObject[end]` pointer npfs still holds was checked for liveness.
pub(crate) static FSD_FO_LIVE_CHECKS: AtomicU64 = AtomicU64::new(0);
/// …and was NOT one of our live per-open FILE_OBJECTs (a dangling FSD-held pointer).
pub(crate) static FSD_FO_DANGLING: AtomicU64 = AtomicU64::new(0);
/// …and no longer even CONTAINS a FILE_OBJECT (`Type != IO_TYPE_FILE` / wrong `Size`) — the hard,
/// non-circular evidence of a use-after-free: the pool recycled the block under npfs' feet.
pub(crate) static FSD_FO_CORRUPTED: AtomicU64 = AtomicU64::new(0);
/// Opens rejected because the per-open FILE_OBJECT registry could not grow.
pub(crate) static FSD_FO_TABLE_EXHAUSTED: AtomicU64 = AtomicU64::new(0);

unsafe fn file_objects_mut() -> &'static mut Vec<FileObjectSlot> {
    let slot = &mut *core::ptr::addr_of_mut!(FILE_OBJECTS);
    if slot.is_none() {
        *slot = Some(Vec::new());
    }
    slot.as_mut().unwrap()
}

unsafe fn file_objects() -> Option<&'static Vec<FileObjectSlot>> {
    (*core::ptr::addr_of!(FILE_OBJECTS)).as_ref()
}

/// The per-open FILE_OBJECT for one canonical FileId, or 0.
unsafe fn fo_lookup(canonical_file_id: u64) -> u64 {
    if canonical_file_id == 0 {
        return 0;
    }
    let Some(table) = file_objects() else {
        return 0;
    };
    for slot in table.iter() {
        if slot.canonical_file_id == canonical_file_id {
            return slot.fo;
        }
    }
    0
}

unsafe fn fo_reserve_new_slot() -> bool {
    let table = file_objects_mut();
    if table.iter().any(|slot| slot.canonical_file_id == 0) || table.len() < table.capacity() {
        return true;
    }
    if table.try_reserve(1).is_ok() {
        true
    } else {
        FSD_FO_TABLE_EXHAUSTED.fetch_add(1, Ordering::Relaxed);
        false
    }
}

/// Is `fo` one of the live per-open FILE_OBJECTs?
unsafe fn fo_is_registered(fo: u64) -> bool {
    let Some(table) = file_objects() else {
        return false;
    };
    table
        .iter()
        .any(|slot| slot.canonical_file_id != 0 && slot.fo == fo)
}

/// Register `fo` as the per-open FILE_OBJECT for a canonical FileId. A live
/// generation can name only one component-local object.
unsafe fn fo_register(canonical_file_id: u64, fo: u64) -> bool {
    if canonical_file_id == 0 || fo == 0 {
        return false;
    }
    let table = file_objects_mut();
    for slot in table.iter_mut() {
        if slot.canonical_file_id == canonical_file_id {
            return slot.fo == fo;
        }
    }
    for slot in table.iter_mut() {
        if slot.canonical_file_id == 0 {
            *slot = FileObjectSlot {
                canonical_file_id,
                fo,
            };
            FSD_FO_OPENS.fetch_add(1, Ordering::Relaxed);
            return true;
        }
    }
    if table.len() == table.capacity() && table.try_reserve(1).is_err() {
        FSD_FO_TABLE_EXHAUSTED.fetch_add(1, Ordering::Relaxed);
        return false;
    }
    table.push(FileObjectSlot {
        canonical_file_id,
        fo,
    });
    FSD_FO_OPENS.fetch_add(1, Ordering::Relaxed);
    true
}

/// Release the per-open FILE_OBJECT for one canonical FileId. CLOSE is the only
/// normal place this component-local object dies.
unsafe fn fo_release(canonical_file_id: u64) {
    if canonical_file_id == 0 {
        return;
    }
    let table = file_objects_mut();
    for slot in table.iter_mut() {
        if slot.canonical_file_id == canonical_file_id {
            pool_free(slot.fo);
            *slot = FileObjectSlot {
                canonical_file_id: 0,
                fo: 0,
            };
            return;
        }
    }
}

// --- npfs DATA-QUEUE CONSISTENCY AUDIT (the hang guard + the lifetime proof) -------------------
//
// npfs' own `ASSERT`s over these invariants are compiled out of the release `npfs.sys` we host, so
// an inconsistency is not caught — it becomes the call-free `NpGetNextRealDataQueueEntry` spin
// described above, which freezes the WHOLE boot (the executive blocks in `component_pump`'s recv,
// RUNEXIT=124). Auditing the queues from the host BEFORE we dispatch into npfs turns that class of
// failure into a bounded, counter-backed report — and, because the audit also validates the
// FILE_OBJECT pointers npfs is holding, it is the direct proof that the lifetime fix above works.
//
// x64 offsets (`npfs.h`): NP_CCB { NodeType@0, NamedPipeState@2, ClientQos@8, CcbEntry@0x18,
// Fcb@0x28, FileObject[2]@0x30, Process@0x40, ClientSession@0x48, NonPagedCcb@0x50,
// DataQueue[2]@0x58 (0x28 each), ClientContext@0xA8, IrpList@0xB0 }.
// NP_DATA_QUEUE { Queue(LIST_ENTRY)@0, QueueState@0x10, BytesInQueue@0x14, EntriesInQueue@0x18,
// QuotaUsed@0x1c, ByteOffset@0x20, Quota@0x24 }.
// NP_DATA_QUEUE_ENTRY { QueueEntry(LIST_ENTRY)@0, DataEntryType@0x10, Irp@0x18, QuotaInEntry@0x20,
// ClientSecurityContext@0x28, DataSize@0x30 }.
const NPFS_NTC_CCB: u16 = 6;
const NP_CCB_FILE_OBJECT: u64 = 0x30;
const NP_CCB_DATA_QUEUE: u64 = 0x58;
const NP_DATA_QUEUE_SIZE: u64 = 0x28;
/// `NP_DATA_QUEUE_STATE::Empty`.
const NP_QUEUE_EMPTY: u32 = 2;
/// Largest legal `NP_DATA_QUEUE_ENTRY::DataEntryType` (Buffered=0, Unbuffered=1, plus npfs'
/// internal 2 = flush-buffers marker and 3).
const NP_ENTRY_TYPE_MAX: u32 = 3;
/// Hard bound on a data-queue walk (npfs' quotas keep real queues tiny).
const NP_QUEUE_WALK_MAX: u32 = 64;

/// Data queues audited before dispatch.
pub(crate) static FSD_QUEUE_AUDITS: AtomicU64 = AtomicU64::new(0);
/// Data queues found INCONSISTENT and re-initialised to a consistent empty state (the hang guard).
/// MUST be 0 on a healthy boot — a non-zero value is a gate failure, not a silent 555-second hang.
pub(crate) static FSD_QUEUE_REPAIRS: AtomicU64 = AtomicU64::new(0);
static mut QUEUE_DUMP_COUNT: u32 = 0;

/// Print one data-queue dump line (bounded).
unsafe fn queue_dump(tag: &[u8], dq: u64, state: u32, entries: u32, walked: u32, types: u32) {
    print_str(tag);
    print_str(b" dq=0x");
    print_hex(dq as u32);
    print_str(b" state=");
    print_u64(state as u64);
    print_str(b" entries=");
    print_u64(entries as u64);
    print_str(b" walked=");
    print_u64(walked as u64);
    print_str(b" types=0x");
    print_hex(types);
    unsafe {
        print_str(b" bytes=");
        print_u64(read_volatile((dq + 0x14) as *const u32) as u64);
        print_str(b" quotaused=");
        print_u64(read_volatile((dq + 0x1c) as *const u32) as u64);
        print_str(b" byteoff=");
        print_u64(read_volatile((dq + 0x20) as *const u32) as u64);
        print_str(b" quota=");
        print_u64(read_volatile((dq + 0x24) as *const u32) as u64);
    }
    print_str(b"\n");
}

#[derive(Clone, Copy)]
struct PipeQueueView {
    state: u32,
    bytes: u32,
    entries: u32,
    quota_used: u32,
    byte_offset: u32,
}

#[derive(Clone, Copy)]
struct PipeCcbView {
    q: [PipeQueueView; 2],
}

#[derive(Clone, Copy)]
pub(crate) struct DceRpcContextHandleView {
    offset: u16,
    attributes: u32,
    uuid: [u8; 16],
}

const DCERPC_CONTEXT_HANDLE_TRACE_CAP: usize = 4;

#[derive(Clone, Copy)]
pub(crate) struct DceRpcPduView {
    ptype: u8,
    flags: u8,
    frag_len: u16,
    call_id: u32,
    assoc_gid: Option<u32>,
    alloc_hint: Option<u32>,
    opnum: Option<u16>,
    fault_status: Option<u32>,
    context_handles: [Option<DceRpcContextHandleView>; DCERPC_CONTEXT_HANDLE_TRACE_CAP],
}

#[derive(Clone, Copy)]
struct DceRpcReadAssembly {
    fid: u64,
    frag_len: u16,
    len: u16,
    buf: [u8; DCERPC_READ_REASSEMBLY_BYTES],
}

#[derive(Clone, Copy)]
struct DceRpcContextFlow {
    uuid: [u8; 16],
    first_response_fid: u64,
    last_response_fid: u64,
    first_request_fid: u64,
    last_request_fid: u64,
    first_response_call: u32,
    first_request_call: u32,
    first_request_op: u16,
    response_count: u16,
    request_count: u16,
}

const EMPTY_DCERPC_READ_ASSEMBLY: DceRpcReadAssembly = DceRpcReadAssembly {
    fid: 0,
    frag_len: 0,
    len: 0,
    buf: [0; DCERPC_READ_REASSEMBLY_BYTES],
};

const EMPTY_DCERPC_CONTEXT_FLOW: DceRpcContextFlow = DceRpcContextFlow {
    uuid: [0; 16],
    first_response_fid: 0,
    last_response_fid: 0,
    first_request_fid: 0,
    last_request_fid: 0,
    first_response_call: 0,
    first_request_call: 0,
    first_request_op: 0,
    response_count: 0,
    request_count: 0,
};

static mut DCERPC_READ_REASSEMBLY: Option<Vec<DceRpcReadAssembly>> = None;
static mut DCERPC_READ_REASSEMBLY_TRACE_COUNT: u32 = 0;
static mut DCERPC_READ_REASSEMBLY_CONTEXT_TRACE_COUNT: u32 = 0;
static mut DCERPC_CONTEXT_FLOW: Option<Vec<DceRpcContextFlow>> = None;
static mut DCERPC_CONTEXT_FLOW_CREATE_TRACE_COUNT: u32 = 0;
static mut DCERPC_CONTEXT_FLOW_USE_TRACE_COUNT: u32 = 0;
static mut DCERPC_CONTEXT_FLOW_MISS_TRACE_COUNT: u32 = 0;

unsafe fn dcerpc_read_reassembly_table_mut() -> &'static mut Vec<DceRpcReadAssembly> {
    let slot = &mut *core::ptr::addr_of_mut!(DCERPC_READ_REASSEMBLY);
    if slot.is_none() {
        *slot = Some(Vec::new());
    }
    slot.as_mut().unwrap()
}

unsafe fn dcerpc_context_flow_table_mut() -> &'static mut Vec<DceRpcContextFlow> {
    let slot = &mut *core::ptr::addr_of_mut!(DCERPC_CONTEXT_FLOW);
    if slot.is_none() {
        *slot = Some(Vec::new());
    }
    slot.as_mut().unwrap()
}

unsafe fn dcerpc_context_flow_table() -> Option<&'static Vec<DceRpcContextFlow>> {
    (&*core::ptr::addr_of!(DCERPC_CONTEXT_FLOW)).as_ref()
}

impl PipeCcbView {
    fn has_queued_state(&self) -> bool {
        self.q.iter().any(|q| {
            q.state != NP_QUEUE_EMPTY
                || q.bytes != 0
                || q.entries != 0
                || q.quota_used != 0
                || q.byte_offset != 0
        })
    }
}

unsafe fn dcerpc_pdu_view(payload: u64, len: u64) -> Option<DceRpcPduView> {
    if payload == 0 || len < 16 {
        return None;
    }
    let version = read_volatile(payload as *const u8);
    if version != 5 {
        return None;
    }
    let ptype = read_volatile((payload + 2) as *const u8);
    if ptype > 19 {
        return None;
    }
    let flags = read_volatile((payload + 3) as *const u8);
    let frag_len = u16::from_le_bytes([
        read_volatile((payload + 8) as *const u8),
        read_volatile((payload + 9) as *const u8),
    ]);
    let call_id = u32::from_le_bytes([
        read_volatile((payload + 12) as *const u8),
        read_volatile((payload + 13) as *const u8),
        read_volatile((payload + 14) as *const u8),
        read_volatile((payload + 15) as *const u8),
    ]);
    let alloc_hint = if (ptype == 0 || ptype == 2 || ptype == 3) && len >= 20 {
        Some(u32::from_le_bytes([
            read_volatile((payload + 16) as *const u8),
            read_volatile((payload + 17) as *const u8),
            read_volatile((payload + 18) as *const u8),
            read_volatile((payload + 19) as *const u8),
        ]))
    } else {
        None
    };
    let assoc_gid = if (ptype == 11 || ptype == 12) && len >= 24 {
        Some(u32::from_le_bytes([
            read_volatile((payload + 20) as *const u8),
            read_volatile((payload + 21) as *const u8),
            read_volatile((payload + 22) as *const u8),
            read_volatile((payload + 23) as *const u8),
        ]))
    } else {
        None
    };
    let opnum = if ptype == 0 && len >= 24 {
        Some(u16::from_le_bytes([
            read_volatile((payload + 22) as *const u8),
            read_volatile((payload + 23) as *const u8),
        ]))
    } else {
        None
    };
    let fault_status = if ptype == 3 && len >= 28 {
        Some(u32::from_le_bytes([
            read_volatile((payload + 24) as *const u8),
            read_volatile((payload + 25) as *const u8),
            read_volatile((payload + 26) as *const u8),
            read_volatile((payload + 27) as *const u8),
        ]))
    } else {
        None
    };
    let context_handles = dcerpc_context_handles(payload, len, ptype, frag_len);
    Some(DceRpcPduView {
        ptype,
        flags,
        frag_len,
        call_id,
        assoc_gid,
        alloc_hint,
        opnum,
        fault_status,
        context_handles,
    })
}

pub(crate) unsafe fn dcerpc_pdu_view_from_slice(payload: &[u8]) -> Option<DceRpcPduView> {
    dcerpc_pdu_view(payload.as_ptr() as u64, payload.len() as u64)
}

pub(crate) unsafe fn trace_dcerpc_read_reassembly_from_slice(
    file_id: u64,
    status: u32,
    info: u64,
    payload: &[u8],
) {
    trace_dcerpc_read_reassembly(
        file_id,
        status,
        info,
        payload.as_ptr() as u64,
        payload.len() as u64,
    );
}

unsafe fn trace_dcerpc_read_reassembly(
    file_id: u64,
    status: u32,
    info: u64,
    payload: u64,
    len: u64,
) {
    if file_id == 0 || payload == 0 || info == 0 || len == 0 {
        return;
    }
    if status != 0 && status != STATUS_BUFFER_OVERFLOW {
        return;
    }

    let chunk_len = core::cmp::min(info, len);
    if chunk_len == 0 {
        return;
    }

    if let Some(index) = dcerpc_read_reassembly_active_slot(file_id) {
        let complete = dcerpc_read_reassembly_append(index, payload, chunk_len);
        if complete {
            dcerpc_read_reassembly_emit(index, status, info);
            dcerpc_read_reassembly_clear(index);
        }
        return;
    }

    if chunk_len < 16 || read_volatile(payload as *const u8) != 5 {
        return;
    }

    let frag_len = u16::from_le_bytes([
        read_volatile((payload + 8) as *const u8),
        read_volatile((payload + 9) as *const u8),
    ]);
    if frag_len < 16 {
        return;
    }

    let index = dcerpc_read_reassembly_new_slot(file_id);
    dcerpc_read_reassembly_start(index, file_id, frag_len);
    let complete = dcerpc_read_reassembly_append(index, payload, chunk_len);
    if complete {
        dcerpc_read_reassembly_emit(index, status, info);
        dcerpc_read_reassembly_clear(index);
    }
}

unsafe fn dcerpc_read_reassembly_active_slot(fid: u64) -> Option<usize> {
    let table = dcerpc_read_reassembly_table_mut();
    for (index, entry) in table.iter().enumerate() {
        if entry.fid == fid && entry.frag_len >= 16 && entry.len < entry.frag_len {
            return Some(index);
        }
    }
    None
}

unsafe fn dcerpc_read_reassembly_new_slot(fid: u64) -> usize {
    let table = dcerpc_read_reassembly_table_mut();
    for (index, entry) in table.iter().enumerate() {
        if entry.fid == 0 || entry.fid == fid {
            return index;
        }
    }
    let index = table.len();
    table.push(EMPTY_DCERPC_READ_ASSEMBLY);
    index
}

unsafe fn dcerpc_read_reassembly_start(index: usize, fid: u64, frag_len: u16) {
    let table = dcerpc_read_reassembly_table_mut();
    table[index] = DceRpcReadAssembly {
        fid,
        frag_len,
        len: 0,
        buf: [0; DCERPC_READ_REASSEMBLY_BYTES],
    };
}

unsafe fn dcerpc_read_reassembly_append(index: usize, payload: u64, chunk_len: u64) -> bool {
    let table = dcerpc_read_reassembly_table_mut();
    let entry = &mut table[index];
    let target_len = core::cmp::min(entry.frag_len as usize, DCERPC_READ_REASSEMBLY_BYTES);
    let have = entry.len as usize;
    if have >= target_len {
        return true;
    }
    let copy_len = core::cmp::min(target_len - have, chunk_len as usize);
    for offset in 0..copy_len {
        entry.buf[have + offset] = read_volatile((payload + offset as u64) as *const u8);
    }
    entry.len = (have + copy_len) as u16;
    entry.len as usize >= target_len
}

unsafe fn dcerpc_read_reassembly_emit(index: usize, status: u32, info: u64) {
    let table = dcerpc_read_reassembly_table_mut();
    let entry = table[index];
    let view = dcerpc_pdu_view(entry.buf.as_ptr() as u64, entry.len as u64);
    let Some(view) = view else {
        return;
    };
    dcerpc_trace_context_flow(entry.fid, view);
    let force_late = dcerpc_pdu_has_context(view) || view.ptype == 3;
    if DCERPC_READ_REASSEMBLY_TRACE_COUNT >= DCERPC_READ_REASSEMBLY_TRACE_CAP {
        if !force_late
            || DCERPC_READ_REASSEMBLY_CONTEXT_TRACE_COUNT
                >= DCERPC_READ_REASSEMBLY_CONTEXT_TRACE_CAP
        {
            return;
        }
        DCERPC_READ_REASSEMBLY_CONTEXT_TRACE_COUNT += 1;
    } else {
        DCERPC_READ_REASSEMBLY_TRACE_COUNT += 1;
    }
    print_str(b"[fsd-pipe-rpc-read] fid=0x");
    print_hex(entry.fid as u32);
    print_str(b" captured=");
    print_u64(entry.len as u64);
    print_str(b" frag=");
    print_u64(entry.frag_len as u64);
    print_str(b" status=0x");
    print_hex(status);
    print_str(b" info=");
    print_u64(info);
    print_dcerpc_pdu_view(Some(view));
    print_str(b"\n");
}

fn dcerpc_pdu_has_context(pdu: DceRpcPduView) -> bool {
    pdu.context_handles.iter().any(Option::is_some)
}

unsafe fn dcerpc_trace_context_flow(fid: u64, pdu: DceRpcPduView) {
    if !matches!(pdu.ptype, 0 | 2 | 3) {
        return;
    }
    for context in pdu.context_handles.iter().flatten() {
        let existing_index = dcerpc_context_flow_find(context.uuid);
        let seen_response = existing_index
            .and_then(|index| {
                dcerpc_context_flow_table()
                    .and_then(|table| table.get(index))
                    .map(|entry| entry.response_count != 0)
            })
            .unwrap_or(false);
        let Some(index) = existing_index.or_else(|| dcerpc_context_flow_alloc(context.uuid)) else {
            if pdu.ptype == 0
                && DCERPC_CONTEXT_FLOW_MISS_TRACE_COUNT < DCERPC_CONTEXT_FLOW_MISS_TRACE_CAP
            {
                DCERPC_CONTEXT_FLOW_MISS_TRACE_COUNT += 1;
                dcerpc_print_context_flow(b"drop", fid, pdu, *context, None, false);
            }
            continue;
        };

        let table = dcerpc_context_flow_table_mut();
        let entry = &mut table[index];
        match pdu.ptype {
            0 => {
                if entry.first_request_fid == 0 {
                    entry.first_request_fid = fid;
                    entry.first_request_call = pdu.call_id;
                    entry.first_request_op = pdu.opnum.unwrap_or(0);
                }
                entry.last_request_fid = fid;
                entry.request_count = entry.request_count.saturating_add(1);
                if seen_response {
                    let first_use = entry.request_count == 1;
                    if first_use
                        && DCERPC_CONTEXT_FLOW_USE_TRACE_COUNT < DCERPC_CONTEXT_FLOW_USE_TRACE_CAP
                    {
                        DCERPC_CONTEXT_FLOW_USE_TRACE_COUNT += 1;
                        dcerpc_print_context_flow(b"use", fid, pdu, *context, Some(*entry), true);
                    }
                } else if DCERPC_CONTEXT_FLOW_MISS_TRACE_COUNT < DCERPC_CONTEXT_FLOW_MISS_TRACE_CAP
                {
                    DCERPC_CONTEXT_FLOW_MISS_TRACE_COUNT += 1;
                    dcerpc_print_context_flow(b"miss", fid, pdu, *context, Some(*entry), false);
                }
            }
            2 => {
                let first_response = entry.response_count == 0;
                if first_response {
                    entry.first_response_fid = fid;
                    entry.first_response_call = pdu.call_id;
                }
                entry.last_response_fid = fid;
                entry.response_count = entry.response_count.saturating_add(1);
                if first_response
                    && DCERPC_CONTEXT_FLOW_CREATE_TRACE_COUNT < DCERPC_CONTEXT_FLOW_CREATE_TRACE_CAP
                {
                    DCERPC_CONTEXT_FLOW_CREATE_TRACE_COUNT += 1;
                    dcerpc_print_context_flow(b"create", fid, pdu, *context, Some(*entry), true);
                }
            }
            3 => {
                if !seen_response
                    && DCERPC_CONTEXT_FLOW_MISS_TRACE_COUNT < DCERPC_CONTEXT_FLOW_MISS_TRACE_CAP
                {
                    DCERPC_CONTEXT_FLOW_MISS_TRACE_COUNT += 1;
                    dcerpc_print_context_flow(
                        b"fault-miss",
                        fid,
                        pdu,
                        *context,
                        Some(*entry),
                        false,
                    );
                }
            }
            _ => {}
        }
    }
}

unsafe fn dcerpc_context_flow_find(uuid: [u8; 16]) -> Option<usize> {
    let table = dcerpc_context_flow_table()?;
    for (index, entry) in table.iter().enumerate() {
        if (entry.response_count != 0 || entry.request_count != 0) && entry.uuid == uuid {
            return Some(index);
        }
    }
    None
}

unsafe fn dcerpc_context_flow_alloc(uuid: [u8; 16]) -> Option<usize> {
    let table = dcerpc_context_flow_table_mut();
    for (index, entry) in table.iter_mut().enumerate() {
        if entry.response_count == 0 && entry.request_count == 0 {
            *entry = DceRpcContextFlow {
                uuid,
                ..EMPTY_DCERPC_CONTEXT_FLOW
            };
            return Some(index);
        }
    }
    let index = table.len();
    table.push(DceRpcContextFlow {
        uuid,
        ..EMPTY_DCERPC_CONTEXT_FLOW
    });
    Some(index)
}

unsafe fn dcerpc_print_context_flow(
    kind: &[u8],
    fid: u64,
    pdu: DceRpcPduView,
    context: DceRpcContextHandleView,
    entry: Option<DceRpcContextFlow>,
    seen_response: bool,
) {
    print_str(b"[fsd-pipe-rpc-ctx] ");
    print_str(kind);
    print_str(b" fid=0x");
    print_hex(fid as u32);
    print_str(b" rpc=");
    print_str(dcerpc_ptype_name(pdu.ptype));
    print_str(b" call=");
    print_u64(pdu.call_id as u64);
    if let Some(opnum) = pdu.opnum {
        print_str(b" op=");
        print_u64(opnum as u64);
    }
    if let Some(status) = pdu.fault_status {
        print_str(b" fault=0x");
        print_hex(status);
    }
    print_str(b" ctx@");
    print_u64(context.offset as u64);
    print_str(b" attr=");
    print_u64(context.attributes as u64);
    print_str(b" uuid=");
    print_uuid(context.uuid);
    print_str(b" seen_rsp=");
    print_u64(seen_response as u64);
    if let Some(entry) = entry {
        print_str(b" rsp_fid=0x");
        print_hex(entry.first_response_fid as u32);
        print_str(b" last_rsp=0x");
        print_hex(entry.last_response_fid as u32);
        print_str(b" req_fid=0x");
        print_hex(entry.first_request_fid as u32);
        print_str(b" last_req=0x");
        print_hex(entry.last_request_fid as u32);
        print_str(b" rsp_n=");
        print_u64(entry.response_count as u64);
        print_str(b" req_n=");
        print_u64(entry.request_count as u64);
        if entry.first_request_call != 0 {
            print_str(b" first_req_call=");
            print_u64(entry.first_request_call as u64);
            print_str(b" first_req_op=");
            print_u64(entry.first_request_op as u64);
        }
    }
    print_str(b"\n");
}

unsafe fn dcerpc_read_reassembly_clear(index: usize) {
    if let Some(entry) = dcerpc_read_reassembly_table_mut().get_mut(index) {
        *entry = EMPTY_DCERPC_READ_ASSEMBLY;
    }
}

unsafe fn dcerpc_context_handles(
    payload: u64,
    len: u64,
    ptype: u8,
    frag_len: u16,
) -> [Option<DceRpcContextHandleView>; DCERPC_CONTEXT_HANDLE_TRACE_CAP] {
    let mut handles = [None; DCERPC_CONTEXT_HANDLE_TRACE_CAP];
    if !matches!(ptype, 0 | 2 | 3) {
        return handles;
    }
    let wire_len = core::cmp::min(len, frag_len as u64);
    if wire_len < 44 {
        return handles;
    }

    // Request/response/fault bodies begin after the 24-byte PDU-specific header. Many stubs place a
    // context handle there, but later arguments can carry the same NDR wire shape too.
    if let Some(context) = dcerpc_context_handle_at(payload, wire_len, 24) {
        dcerpc_push_context_handle(&mut handles, context);
    }

    let mut offset = 28u64;
    while offset + 20 <= wire_len && offset <= u16::MAX as u64 {
        if let Some(context) = dcerpc_context_handle_at(payload, wire_len, offset as u16) {
            dcerpc_push_context_handle(&mut handles, context);
        }
        if handles.last().copied().flatten().is_some() {
            break;
        }
        offset += 4;
    }
    handles
}

fn dcerpc_push_context_handle(
    handles: &mut [Option<DceRpcContextHandleView>; DCERPC_CONTEXT_HANDLE_TRACE_CAP],
    context: DceRpcContextHandleView,
) {
    if handles.iter().flatten().any(|existing| {
        existing.offset == context.offset
            || (existing.attributes == context.attributes && existing.uuid == context.uuid)
    }) {
        return;
    }
    if let Some(slot) = handles.iter_mut().find(|slot| slot.is_none()) {
        *slot = Some(context);
    }
}

unsafe fn dcerpc_context_handle_at(
    payload: u64,
    len: u64,
    offset: u16,
) -> Option<DceRpcContextHandleView> {
    let offset_u64 = offset as u64;
    if len < offset_u64 + 20 {
        return None;
    }
    let attributes = u32::from_le_bytes([
        read_volatile((payload + offset_u64) as *const u8),
        read_volatile((payload + offset_u64 + 1) as *const u8),
        read_volatile((payload + offset_u64 + 2) as *const u8),
        read_volatile((payload + offset_u64 + 3) as *const u8),
    ]);
    if attributes > 2 {
        return None;
    }
    let mut uuid = [0u8; 16];
    let mut any = false;
    for (i, byte) in uuid.iter_mut().enumerate() {
        *byte = read_volatile((payload + offset_u64 + 4 + i as u64) as *const u8);
        any |= *byte != 0;
    }
    if !any || !dcerpc_uuid_looks_generated(&uuid) {
        return None;
    }
    Some(DceRpcContextHandleView {
        offset,
        attributes,
        uuid,
    })
}

fn dcerpc_uuid_looks_generated(uuid: &[u8; 16]) -> bool {
    // RPC context handles are assigned with UuidCreate before being marshalled. Filtering to normal
    // UUID version/variant bits keeps counted strings and small pointer fields out of the trace.
    let version = uuid[7] >> 4;
    let variant = uuid[8] & 0xc0;
    (1..=5).contains(&version) && variant == 0x80
}

fn dcerpc_ptype_name(ptype: u8) -> &'static [u8] {
    match ptype {
        0 => b"request",
        2 => b"response",
        3 => b"fault",
        11 => b"bind",
        12 => b"bind_ack",
        13 => b"bind_nak",
        14 => b"alter",
        15 => b"alter_ack",
        _ => b"pdu",
    }
}

pub(crate) fn print_dcerpc_pdu_view(view: Option<DceRpcPduView>) {
    let Some(pdu) = view else {
        return;
    };
    print_str(b" rpc=");
    print_str(dcerpc_ptype_name(pdu.ptype));
    print_str(b" call=");
    print_u64(pdu.call_id as u64);
    print_str(b" frag=");
    print_u64(pdu.frag_len as u64);
    print_str(b" flags=0x");
    print_hex(pdu.flags as u32);
    if let Some(assoc_gid) = pdu.assoc_gid {
        print_str(b" assoc=");
        print_u64(assoc_gid as u64);
    }
    if let Some(alloc_hint) = pdu.alloc_hint {
        print_str(b" hint=");
        print_u64(alloc_hint as u64);
    }
    if let Some(opnum) = pdu.opnum {
        print_str(b" op=");
        print_u64(opnum as u64);
    }
    if let Some(status) = pdu.fault_status {
        print_str(b" fault=0x");
        print_hex(status);
    }
    for context in pdu.context_handles.iter().flatten() {
        print_str(b" ctx@");
        print_u64(context.offset as u64);
        print_str(b" attr=");
        print_u64(context.attributes as u64);
        print_str(b" uuid=");
        print_uuid(context.uuid);
    }
}

fn print_hex_byte(byte: u8) {
    const HEX: &[u8; 16] = b"0123456789abcdef";
    debug_put_char(HEX[(byte >> 4) as usize]);
    debug_put_char(HEX[(byte & 0xf) as usize]);
}

fn print_uuid(uuid: [u8; 16]) {
    debug_put_char(b'{');
    print_hex_byte(uuid[3]);
    print_hex_byte(uuid[2]);
    print_hex_byte(uuid[1]);
    print_hex_byte(uuid[0]);
    debug_put_char(b'-');
    print_hex_byte(uuid[5]);
    print_hex_byte(uuid[4]);
    debug_put_char(b'-');
    print_hex_byte(uuid[7]);
    print_hex_byte(uuid[6]);
    debug_put_char(b'-');
    print_hex_byte(uuid[8]);
    print_hex_byte(uuid[9]);
    debug_put_char(b'-');
    for byte in &uuid[10..16] {
        print_hex_byte(*byte);
    }
    debug_put_char(b'}');
}

unsafe fn pipe_queue_view(dq: u64) -> PipeQueueView {
    PipeQueueView {
        state: read_volatile((dq + 0x10) as *const u32),
        bytes: read_volatile((dq + 0x14) as *const u32),
        entries: read_volatile((dq + 0x18) as *const u32),
        quota_used: read_volatile((dq + 0x1c) as *const u32),
        byte_offset: read_volatile((dq + 0x20) as *const u32),
    }
}

unsafe fn pipe_ccb_view_in_pool(fid: u64, exec_pool_va: u64) -> Option<PipeCcbView> {
    if fid == 0 || fid == 1 {
        return None;
    }
    let component_ccb = fid & !1;
    let component_pool_end = FSD_POOL_VADDR + FSD_POOL_FRAMES * 0x1000;
    if component_ccb < FSD_POOL_VADDR + POOL_DATA_OFF
        || component_ccb + 0xC0 > component_pool_end
        || component_ccb & 7 != 0
    {
        return None;
    }
    let ccb = exec_pool_va + (component_ccb - FSD_POOL_VADDR);
    if read_volatile(ccb as *const u16) != NPFS_NTC_CCB {
        return None;
    }
    Some(PipeCcbView {
        q: [
            pipe_queue_view(ccb + NP_CCB_DATA_QUEUE),
            pipe_queue_view(ccb + NP_CCB_DATA_QUEUE + NP_DATA_QUEUE_SIZE),
        ],
    })
}

unsafe fn pipe_ccb_view(fid: u64) -> Option<PipeCcbView> {
    pipe_ccb_view_in_pool(fid, FSD_POOL_VADDR)
}

fn component_pool_end() -> u64 {
    FSD_POOL_VADDR + FSD_POOL_FRAMES * 0x1000
}

unsafe fn component_pool_allocation_capacity(component_va: u64) -> Option<u64> {
    if component_va < FSD_POOL_VADDR + POOL_DATA_OFF + 16
        || component_va & 15 != 0
        || component_va >= component_pool_end()
    {
        return None;
    }
    let bump = read_volatile(FSD_POOL_VADDR as *const u64);
    let used_end = FSD_POOL_VADDR.checked_add(bump.min(FSD_POOL_FRAMES * 0x1000))?;
    let capacity = read_volatile((component_va - 16) as *const u64);
    if capacity == 0 || component_va.checked_add(capacity)? > used_end {
        return None;
    }
    Some(capacity)
}

unsafe fn hosted_pool_allocation_exec_range(
    exec_pool_va: u64,
    component_va: u64,
) -> Option<(u64, u64)> {
    if exec_pool_va == 0
        || component_va < FSD_POOL_VADDR + POOL_DATA_OFF + 16
        || component_va & 15 != 0
        || component_va >= component_pool_end()
    {
        return None;
    }
    let exec_va = exec_pool_va.checked_add(component_va - FSD_POOL_VADDR)?;
    let bump = read_volatile(exec_pool_va as *const u64);
    let used_end = exec_pool_va.checked_add(bump.min(FSD_POOL_FRAMES * 0x1000))?;
    let capacity = read_volatile((exec_va - 16) as *const u64);
    if capacity == 0 || exec_va.checked_add(capacity)? > used_end {
        return None;
    }
    Some((exec_va, capacity))
}

unsafe fn hosted_pool_allocation_exec_va(
    exec_pool_va: u64,
    component_va: u64,
    bytes: u64,
) -> Option<u64> {
    let (exec_va, capacity) = hosted_pool_allocation_exec_range(exec_pool_va, component_va)?;
    (bytes <= capacity).then_some(exec_va)
}

fn component_pool_to_exec_va(exec_pool_va: u64, component_va: u64, bytes: u64) -> Option<u64> {
    if component_va < FSD_POOL_VADDR + POOL_DATA_OFF
        || component_va >= component_pool_end()
        || bytes > component_pool_end().saturating_sub(component_va)
    {
        return None;
    }
    exec_pool_va.checked_add(component_va - FSD_POOL_VADDR)
}

fn translate_component_range(
    component_va: u64,
    bytes: u64,
    component_base: u64,
    component_len: u64,
    exec_base: u64,
) -> Option<u64> {
    if exec_base == 0 || component_va < component_base {
        return None;
    }
    let end = component_va.checked_add(bytes)?;
    if end > component_base.checked_add(component_len)? {
        return None;
    }
    exec_base.checked_add(component_va - component_base)
}

fn component_to_exec_va_for_instance(
    instance: usize,
    inst: DriverInstance,
    component_va: u64,
    bytes: u64,
) -> Option<u64> {
    let win = ExecVaWindow::try_for_instance(instance)?;
    let image_frames = if inst.image_frames == 0 {
        FSD_IMAGE_FRAMES
    } else {
        inst.image_frames
    };
    translate_component_range(
        component_va,
        bytes,
        FSD_CODE_VA,
        image_frames * 0x1000,
        win.code_va,
    )
    .or_else(|| {
        translate_component_range(
            component_va,
            bytes,
            FSD_POOL_VADDR,
            FSD_POOL_FRAMES * 0x1000,
            inst.exec_pool_va,
        )
    })
    .or_else(|| {
        translate_component_range(
            component_va,
            bytes,
            FSD_STACK_VADDR,
            FSD_STACK_BYTES,
            inst.exec_stack_va,
        )
    })
    .or_else(|| {
        translate_component_range(
            component_va,
            bytes,
            FSD_DATA_VADDR,
            FSD_DATA_FRAMES * 0x1000,
            win.data_va,
        )
    })
    .or_else(|| {
        translate_component_range(
            component_va,
            bytes,
            FSD_SHARED_VADDR,
            FSD_SHARED_FRAMES * 0x1000,
            inst.exec_shared_va,
        )
    })
    .or_else(|| {
        translate_component_range(
            component_va,
            bytes,
            FSD_ARG_VADDR,
            FSD_ARG_FRAMES * 0x1000,
            inst.exec_arg_va,
        )
    })
}

pub(crate) unsafe fn hosted_component_stack_qword(
    shared_va: u64,
    component_rsp: u64,
    qword_index: u64,
) -> Option<u64> {
    let byte_offset = qword_index.checked_mul(8)?;
    let component_va = component_rsp.checked_add(byte_offset)?;
    if component_va < FSD_STACK_VADDR
        || component_va.checked_add(8)? > FSD_STACK_VADDR + FSD_STACK_BYTES
    {
        return None;
    }
    let (_, inst) = instance_by_shared_va(shared_va)?;
    if inst.exec_stack_va == 0 {
        return None;
    }
    let exec_va = inst
        .exec_stack_va
        .checked_add(component_va - FSD_STACK_VADDR)?;
    Some(core::ptr::read_volatile(exec_va as *const u64))
}

fn exec_pool_to_component_va(exec_pool_va: u64, exec_va: u64) -> Option<u64> {
    if exec_va < exec_pool_va {
        return None;
    }
    let off = exec_va - exec_pool_va;
    if off >= FSD_POOL_FRAMES * 0x1000 {
        return None;
    }
    Some(FSD_POOL_VADDR + off)
}

struct ExecutivePoolLockGuard(*const AtomicU64);

impl Drop for ExecutivePoolLockGuard {
    fn drop(&mut self) {
        unsafe { (&*self.0).store(0, Ordering::Release) }
    }
}

unsafe fn hosted_instance_pool_lock(exec_pool_va: u64) -> Option<ExecutivePoolLockGuard> {
    let lock_address = exec_pool_va.checked_add(COMPONENT_POOL_LOCK_OFF)?;
    let lock = &*(lock_address as *const AtomicU64);
    while lock
        .compare_exchange_weak(0, 1, Ordering::Acquire, Ordering::Relaxed)
        .is_err()
    {
        // The lock is shared with hosted component threads. The executive must not monopolize the
        // only CPU while waiting for a component owner to run and release it.
        crate::yield_now();
    }
    Some(ExecutivePoolLockGuard(lock as *const AtomicU64))
}

unsafe fn hosted_instance_pool_alloc(inst: DriverInstance, size: u64) -> Option<u64> {
    if inst.exec_pool_va == 0 || size == 0 {
        return None;
    }
    let _guard = hosted_instance_pool_lock(inst.exec_pool_va)?;
    let pool_bytes = FSD_POOL_FRAMES.checked_mul(0x1000)?;
    let exec_pool_end = inst.exec_pool_va.checked_add(pool_bytes)?;
    let component_pool_end = component_pool_end();
    let head_slot_exec = inst.exec_pool_va.checked_add(8)?;
    let mut prev_next_slot_exec = head_slot_exec;
    let mut cur = read_volatile(head_slot_exec as *const u64);
    let mut steps = 0u64;
    while cur != 0 {
        if steps >= POOL_FREE_LIST_MAX {
            FSD_POOL_LIST_CYCLES.fetch_add(1, Ordering::Relaxed);
            break;
        }
        steps += 1;
        if cur < FSD_POOL_VADDR + POOL_DATA_OFF || cur >= component_pool_end {
            break;
        }
        let Some(cur_exec) = inst.exec_pool_va.checked_add(cur - FSD_POOL_VADDR) else {
            break;
        };
        if cur_exec < inst.exec_pool_va + 16 || cur_exec >= exec_pool_end {
            break;
        }
        let cap = read_volatile((cur_exec - 16) as *const u64);
        let next = read_volatile((cur_exec - 8) as *const u64);
        if cap >= size {
            write_volatile(prev_next_slot_exec as *mut u64, next);
            return Some(cur);
        }
        prev_next_slot_exec = cur_exec - 8;
        cur = next;
    }

    let ctr_exec = inst.exec_pool_va;
    let mut off = read_volatile(ctr_exec as *const u64);
    if off < POOL_DATA_OFF {
        off = POOL_DATA_OFF;
    }
    let hdr = FSD_POOL_VADDR.checked_add(off)?.checked_add(15)? & !15;
    let block = hdr.checked_add(16)?;
    let end = block.checked_add(size)?;
    if end > component_pool_end {
        return None;
    }
    let block_exec = inst.exec_pool_va.checked_add(block - FSD_POOL_VADDR)?;
    if block_exec < inst.exec_pool_va + 16 || block_exec >= exec_pool_end {
        return None;
    }
    write_volatile(ctr_exec as *mut u64, end - FSD_POOL_VADDR);
    write_volatile((block_exec - 16) as *mut u64, size);
    write_volatile((block_exec - 8) as *mut u64, 0);
    Some(block)
}

unsafe fn hosted_instance_pool_free_unlocked(inst: DriverInstance, p: u64) -> bool {
    let Some(p_exec) = hosted_pool_allocation_exec_va(inst.exec_pool_va, p, 1) else {
        if FSD_POOL_INVALID_FREES.fetch_add(1, Ordering::Relaxed) == 0 {
            print_str(b"[fsd-pool-invalid] executive free pointer=");
            print_hex64(p);
            print_str(b" driver=");
            print_hex64(inst.driver_id);
            print_str(b"\n");
        }
        return false;
    };
    let Some(head_slot_exec) = inst.exec_pool_va.checked_add(8) else {
        return false;
    };
    let mut cur = read_volatile(head_slot_exec as *const u64);
    let mut steps = 0u64;
    while cur != 0 && steps < POOL_FREE_LIST_MAX {
        if cur == p {
            FSD_POOL_DOUBLE_FREES.fetch_add(1, Ordering::Relaxed);
            return false;
        }
        if cur < FSD_POOL_VADDR + POOL_DATA_OFF || cur >= component_pool_end() {
            break;
        }
        let Some(cur_exec) = inst.exec_pool_va.checked_add(cur - FSD_POOL_VADDR) else {
            break;
        };
        if cur_exec < inst.exec_pool_va + 16 {
            break;
        }
        cur = read_volatile((cur_exec - 8) as *const u64);
        steps += 1;
    }
    write_volatile(
        (p_exec - 8) as *mut u64,
        read_volatile(head_slot_exec as *const u64),
    );
    write_volatile(head_slot_exec as *mut u64, p);
    true
}

unsafe fn hosted_instance_pool_free(inst: DriverInstance, p: u64) -> bool {
    let Some(_guard) = hosted_instance_pool_lock(inst.exec_pool_va) else {
        return false;
    };
    hosted_instance_pool_free_unlocked(inst, p)
}

unsafe fn hosted_instance_pool_allocation_is_free_unlocked(
    inst: DriverInstance,
    p: u64,
) -> Option<bool> {
    hosted_pool_allocation_exec_va(inst.exec_pool_va, p, 1)?;
    let head_slot_exec = inst.exec_pool_va.checked_add(8)?;
    let exec_pool_end = inst
        .exec_pool_va
        .checked_add(FSD_POOL_FRAMES.checked_mul(0x1000)?)?;
    let mut current = read_volatile(head_slot_exec as *const u64);
    let mut steps = 0u64;
    while current != 0 {
        if steps >= POOL_FREE_LIST_MAX
            || current < FSD_POOL_VADDR + POOL_DATA_OFF + 16
            || current >= component_pool_end()
        {
            return None;
        }
        if current == p {
            return Some(true);
        }
        let current_exec = inst
            .exec_pool_va
            .checked_add(current.checked_sub(FSD_POOL_VADDR)?)?;
        if current_exec < inst.exec_pool_va + POOL_DATA_OFF + 16 || current_exec >= exec_pool_end {
            return None;
        }
        current = read_volatile((current_exec - 8) as *const u64);
        steps += 1;
    }
    Some(false)
}

unsafe fn release_hosted_instance_pool_allocation_if_live(inst: DriverInstance, p: u64) -> bool {
    if p == 0 {
        return true;
    }
    let Some(_guard) = hosted_instance_pool_lock(inst.exec_pool_va) else {
        return false;
    };
    match hosted_instance_pool_allocation_is_free_unlocked(inst, p) {
        Some(true) => true,
        Some(false) => hosted_instance_pool_free_unlocked(inst, p),
        None => false,
    }
}

unsafe fn print_active_irp_graph_for_deadman(inst: &DriverInstance) {
    let sh = inst.exec_shared_va;
    let irp_c = read_volatile((sh + SH_ACTIVE_IRP) as *const u64);
    let iosl_c = read_volatile((sh + SH_ACTIVE_IOSL) as *const u64);
    let data_c = read_volatile((sh + SH_ACTIVE_DATA) as *const u64);
    let data_cap = read_volatile((sh + SH_ACTIVE_DATA_CAP) as *const u64);
    let fo_c = read_volatile((sh + SH_ACTIVE_FILE_OBJECT) as *const u64);
    if irp_c == 0 && iosl_c == 0 {
        return;
    }
    print_str(b"[deadman] active-driver-irp irp=");
    print_hex64(irp_c);
    print_str(b" iosl=");
    print_hex64(iosl_c);
    print_str(b" data=");
    print_hex64(data_c);
    print_str(b" data-cap=");
    print_u64(data_cap);
    print_str(b" fo=");
    print_hex64(fo_c);
    if let Some(irp) = component_pool_to_exec_va(inst.exec_pool_va, irp_c, WDM_X64_IRP_SIZE as u64)
    {
        let system_buffer = read_unaligned((irp + 0x18) as *const u64);
        let status = read_unaligned((irp + 0x30) as *const u32);
        let info = read_unaligned((irp + 0x38) as *const u64);
        let current_location = read_unaligned((irp + 0x42) as *const u8);
        let stack_count = read_unaligned((irp + 0x43) as *const u8);
        let user_buffer = read_unaligned((irp + 0x70) as *const u64);
        let current_stack = read_unaligned((irp + 0xb8) as *const u64);
        print_str(b" irp.sys=");
        print_hex64(system_buffer);
        print_str(b" irp.user=");
        print_hex64(user_buffer);
        print_str(b" irp.curstack=");
        print_hex64(current_stack);
        print_str(b" irp.loc=");
        print_u64(current_location as u64);
        print_str(b"/");
        print_u64(stack_count as u64);
        print_str(b" ios=");
        print_hex(status);
        print_str(b"/");
        print_u64(info);
    }
    if let Some(iosl) = component_pool_to_exec_va(
        inst.exec_pool_va,
        iosl_c,
        WDM_X64_IO_STACK_LOCATION_SIZE as u64,
    ) {
        let mj = read_unaligned(iosl as *const u8);
        let mn = read_unaligned((iosl + WDM_X64_IO_STACK_MINOR_OFFSET) as *const u8);
        let length = read_unaligned((iosl + 0x08) as *const u32);
        let io_control = read_unaligned((iosl + 0x18) as *const u32);
        let type3 = read_unaligned((iosl + 0x20) as *const u64);
        let device = read_unaligned((iosl + 0x28) as *const u64);
        let file_object = read_unaligned((iosl + 0x30) as *const u64);
        print_str(b" stack.mj=");
        print_u64(mj as u64);
        print_str(b".");
        print_u64(mn as u64);
        print_str(b" len=");
        print_u64(length as u64);
        print_str(b" ctl=0x");
        print_hex(io_control);
        print_str(b" type3=");
        print_hex64(type3);
        print_str(b" dev=");
        print_hex64(device);
        print_str(b" stack.fo=");
        print_hex64(file_object);
        if let Some(fo) = component_pool_to_exec_va(
            inst.exec_pool_va,
            file_object,
            WDM_X64_FILE_OBJECT_SIZE as u64,
        ) {
            let fsctx = read_unaligned((fo + 0x18) as *const u64);
            let fsctx2 = read_unaligned((fo + 0x20) as *const u64);
            print_str(b" fsctx=");
            print_hex64(fsctx);
            print_str(b" fsctx2=");
            print_hex64(fsctx2);
        }
    }
    print_str(b"\n");
}

unsafe fn print_pipe_queue_heads_for_deadman(fid: u64, inst: &DriverInstance, active_out: u64) {
    if fid == 0 || fid == 1 {
        return;
    }
    let component_ccb = fid & !1;
    if component_ccb < FSD_POOL_VADDR + POOL_DATA_OFF
        || component_ccb + 0xC0 > component_pool_end()
        || component_ccb & 7 != 0
    {
        return;
    }
    let Some(ccb) = component_pool_to_exec_va(inst.exec_pool_va, component_ccb, 0xC0) else {
        return;
    };
    if read_volatile(ccb as *const u16) != NPFS_NTC_CCB {
        return;
    }
    for end in 0..2u64 {
        let dq = ccb + NP_CCB_DATA_QUEUE + end * NP_DATA_QUEUE_SIZE;
        let Some(component_dq) = exec_pool_to_component_va(inst.exec_pool_va, dq) else {
            continue;
        };
        let head_c = read_volatile(dq as *const u64);
        let state = read_volatile((dq + 0x10) as *const u32);
        let bytes = read_volatile((dq + 0x14) as *const u32);
        let entries = read_volatile((dq + 0x18) as *const u32);
        let quota = read_volatile((dq + 0x1c) as *const u32);
        let byte_offset = read_volatile((dq + 0x20) as *const u32);
        print_str(b"[deadman] active-driver-q");
        print_u64(end);
        print_str(b" dq=");
        print_hex64(component_dq);
        print_str(b" state=");
        print_u64(state as u64);
        print_str(b" bytes=");
        print_u64(bytes as u64);
        print_str(b" entries=");
        print_u64(entries as u64);
        print_str(b" quota=");
        print_u64(quota as u64);
        print_str(b" offset=");
        print_u64(byte_offset as u64);
        print_str(b" head=");
        print_hex64(head_c);
        if head_c != component_dq && head_c & 7 == 0 {
            if let Some(head) = component_pool_to_exec_va(inst.exec_pool_va, head_c, 0x38) {
                let ty = read_volatile((head + 0x10) as *const u32);
                let irp = read_volatile((head + 0x18) as *const u64);
                let quota_in_entry = read_volatile((head + 0x20) as *const u32);
                let client_ctx = read_volatile((head + 0x28) as *const u64);
                let data_size = read_volatile((head + 0x30) as *const u32);
                let remaining = data_size.saturating_sub(byte_offset);
                let expected_copy = (remaining as u64).min(active_out);
                let src_c = head_c + 0x38 + byte_offset as u64;
                print_str(b" entry.type=");
                print_u64(ty as u64);
                print_str(b" entry.irp=");
                print_hex64(irp);
                print_str(b" entry.quota=");
                print_u64(quota_in_entry as u64);
                print_str(b" entry.ctx=");
                print_hex64(client_ctx);
                print_str(b" entry.size=");
                print_u64(data_size as u64);
                print_str(b" expected=");
                print_u64(remaining as u64);
                print_str(b"/");
                print_u64(expected_copy);
                print_str(b" src=");
                print_hex64(src_c);
                if let Some(src) = component_pool_to_exec_va(inst.exec_pool_va, src_c, 1) {
                    print_str(b" bytes=");
                    let preview = expected_copy.min(8);
                    for i in 0..preview {
                        print_hex_byte(read_volatile((src + i) as *const u8));
                    }
                }
            }
        }
        print_str(b"\n");
    }
}

fn print_pipe_ccb_view(tag: &[u8], view: PipeCcbView) {
    print_str(tag);
    for end in 0..2usize {
        let q = view.q[end];
        print_str(b" q");
        print_u64(end as u64);
        print_str(b"=");
        print_u64(q.state as u64);
        print_str(b"/");
        print_u64(q.bytes as u64);
        print_str(b"/");
        print_u64(q.entries as u64);
        print_str(b"/");
        print_u64(q.byte_offset as u64);
        print_str(b"/");
        print_u64(q.quota_used as u64);
    }
}

fn trace_active_write_call_site(phase: &[u8], seq: u64, file_id: u64, handler: u64, irp: u64) {
    print_str(b"[fsd-active-write] ");
    print_str(phase);
    print_str(b" seq=");
    print_u64(seq);
    print_str(b" fid=");
    print_hex64(file_id);
    print_str(b" handler=");
    print_hex64(handler);
    print_str(b" irp=");
    print_hex64(irp);
    unsafe {
        if let Some(view) = pipe_ccb_view(file_id) {
            print_pipe_ccb_view(b"", view);
        }
    }
    print_str(b"\n");
}

fn print_hex64(value: u64) {
    print_str(b"0x");
    for i in (0..16).rev() {
        let nib = ((value >> (i * 4)) & 0xf) as u8;
        debug_put_char(if nib < 10 {
            b'0' + nib
        } else {
            b'a' + (nib - 10)
        });
    }
}

