static mut KE_NUMBER_PROCESSORS_VALUE: u8 = 1;

unsafe fn initialize_hosted_loader_block(exec_data_va: u64) {
    let cell = exec_data_va + FSD_DATA_KE_LOADER_BLOCK_CELL_OFF;
    let Some(root_paddr) = crate::loader_acpi_root_paddr() else {
        write_volatile(cell as *mut u64, 0);
        return;
    };
    let block = exec_data_va + FSD_DATA_LOADER_BLOCK_OFF;
    let root = exec_data_va + FSD_DATA_LOADER_CONFIG_ROOT_OFF;
    let acpi = exec_data_va + FSD_DATA_LOADER_ACPI_NODE_OFF;
    let identifier = exec_data_va + FSD_DATA_LOADER_ACPI_IDENTIFIER_OFF;
    let config = exec_data_va + FSD_DATA_LOADER_ACPI_CONFIG_OFF;
    core::ptr::write_bytes(block as *mut u8, 0, 0x100);
    core::ptr::write_bytes(root as *mut u8, 0, 0x48);
    core::ptr::write_bytes(acpi as *mut u8, 0, 0x48);
    core::ptr::write_bytes(config as *mut u8, 0, FSD_DATA_LOADER_CONFIG_CAPACITY);

    // NT 5.2 LOADER_PARAMETER_BLOCK: initialize the three list heads and publish the real ARC
    // configuration root at offset 0x60.
    for list_off in [0u64, 0x10, 0x20] {
        write_unaligned(
            (block + list_off) as *mut u64,
            FSD_DATA_LOADER_BLOCK_VA + list_off,
        );
        write_unaligned(
            (block + list_off + 8) as *mut u64,
            FSD_DATA_LOADER_BLOCK_VA + list_off,
        );
    }
    write_unaligned((block + 0x60) as *mut u64, FSD_DATA_LOADER_CONFIG_ROOT_VA);

    // CONFIGURATION_COMPONENT_DATA root: SystemClass / MaximumType, with the firmware ACPI node as
    // its child. CONFIGURATION_COMPONENT_DATA is 0x48 bytes on NT amd64.
    write_unaligned((root + 0x08) as *mut u64, FSD_DATA_LOADER_ACPI_NODE_VA);
    write_unaligned((root + 0x18) as *mut u32, 0); // SystemClass
    write_unaligned((root + 0x1C) as *mut u32, 40); // MaximumType
    write_unaligned((root + 0x2C) as *mut u32, u32::MAX); // AffinityMask

    // Firmware child: AdapterClass / MultiFunctionAdapter, matching the FreeLdr ACPI BIOS node.
    write_unaligned((acpi + 0x00) as *mut u64, FSD_DATA_LOADER_CONFIG_ROOT_VA);
    write_unaligned((acpi + 0x18) as *mut u32, 3); // AdapterClass
    write_unaligned((acpi + 0x1C) as *mut u32, 12); // MultiFunctionAdapter
    write_unaligned((acpi + 0x2C) as *mut u32, u32::MAX); // AffinityMask
    write_unaligned((acpi + 0x34) as *mut u32, 10);
    write_unaligned(
        (acpi + 0x38) as *mut u64,
        FSD_DATA_LOADER_ACPI_IDENTIFIER_VA,
    );
    write_unaligned((acpi + 0x40) as *mut u64, FSD_DATA_LOADER_ACPI_CONFIG_VA);
    core::ptr::copy_nonoverlapping(b"ACPI BIOS\0".as_ptr(), identifier as *mut u8, 10);

    // BOOTBOOT owns the firmware memory map. Project all of it into the exact variable-length
    // FreeLdr/NT 5.2 resource-list shape; no fabricated empty E820 prefix is accepted here.
    let config_output =
        core::slice::from_raw_parts_mut(config as *mut u8, FSD_DATA_LOADER_CONFIG_CAPACITY);
    let Ok(config_bytes) = nt_compat_exports::configuration::encode_loader_acpi_configuration(
        config_output,
        root_paddr,
        crate::loader_firmware_memory_map(),
    ) else {
        write_volatile(cell as *mut u64, 0);
        return;
    };
    write_unaligned((acpi + 0x30) as *mut u32, config_bytes as u32);
    write_volatile(cell as *mut u64, FSD_DATA_LOADER_BLOCK_VA);
}

unsafe fn initialize_hosted_driver_data_exports(exec_data_va: u64) {
    let mm_system_range_start = exec_data_va + FSD_DATA_MM_SYSTEM_RANGE_START_OFF;
    write_volatile(
        mm_system_range_start as *mut u64,
        FSD_HOSTED_SYSTEM_RANGE_START,
    );

    let io_file_object_type_cell = exec_data_va + FSD_DATA_IO_FILE_OBJECT_TYPE_CELL_OFF;
    let io_file_object_type_body = exec_data_va + FSD_DATA_IO_FILE_OBJECT_TYPE_BODY_OFF;
    write_volatile(
        io_file_object_type_cell as *mut u64,
        FSD_DATA_IO_FILE_OBJECT_TYPE_BODY_VA,
    );
    write_volatile(io_file_object_type_body as *mut u64, 0x4649_4c45_5459_5045); // "FILETYPE"
    let ex_event_object_type_cell = exec_data_va + FSD_DATA_EX_EVENT_OBJECT_TYPE_CELL_OFF;
    let ex_event_object_type_body = exec_data_va + FSD_DATA_EX_EVENT_OBJECT_TYPE_BODY_OFF;
    write_volatile(
        ex_event_object_type_cell as *mut u64,
        FSD_DATA_EX_EVENT_OBJECT_TYPE_BODY_VA,
    );
    write_volatile(ex_event_object_type_body as *mut u64, 0x4556_454e_5459_5045); // "EVENTYPE"

    let se_exports_cell = exec_data_va + FSD_DATA_SE_EXPORTS_CELL_OFF;
    let se_exports_struct = exec_data_va + FSD_DATA_SE_EXPORTS_STRUCT_OFF;
    let se_sid_pool = exec_data_va + FSD_DATA_SE_SID_POOL_OFF;
    write_volatile(se_exports_cell as *mut u64, FSD_DATA_SE_EXPORTS_STRUCT_VA);
    core::ptr::write_bytes(
        se_exports_struct as *mut u8,
        0,
        nt_security::se_exports::se_exports_offset::STRUCT_SIZE,
    );
    core::ptr::write_bytes(
        se_sid_pool as *mut u8,
        0,
        nt_security::se_exports::SID_POOL_SIZE,
    );
    nt_security::se_exports::build_se_exports(
        se_exports_struct as *mut u8,
        se_sid_pool as *mut u8,
        FSD_DATA_SE_SID_POOL_VA,
    );
    initialize_hosted_loader_block(exec_data_va);
}

fn fsd_data_export_addr(name: &str) -> Option<u64> {
    Some(match name {
        "MmSystemRangeStart" => FSD_DATA_MM_SYSTEM_RANGE_START_VA,
        "IoFileObjectType" => FSD_DATA_IO_FILE_OBJECT_TYPE_CELL_VA,
        "ExEventObjectType" => FSD_DATA_EX_EVENT_OBJECT_TYPE_CELL_VA,
        "SeExports" => FSD_DATA_SE_EXPORTS_CELL_VA,
        "KeLoaderBlock" => FSD_DATA_KE_LOADER_BLOCK_CELL_VA,
        _ => return None,
    })
}

unsafe fn hosted_configuration_entry_matches(
    entry: u64,
    class: u32,
    kind: u32,
    component_key: u64,
) -> bool {
    let key = (component_key != 0).then(|| read_unaligned(component_key as *const u32));
    nt_compat_exports::configuration::component_matches(
        read_unaligned((entry + 0x18) as *const u32),
        read_unaligned((entry + 0x1C) as *const u32),
        read_unaligned((entry + 0x28) as *const u32),
        class,
        kind,
        key,
    )
}

unsafe fn find_hosted_configuration_next_entry(
    child: u64,
    class: u32,
    kind: u32,
    component_key: u64,
    next_link: u64,
    depth: usize,
) -> u64 {
    if child == 0 || next_link == 0 || depth >= 64 {
        return 0;
    }
    let mut current = child;
    let mut visited = 0usize;
    while current != 0 && visited < 4096 {
        let resume = read_unaligned(next_link as *const u64);
        if resume != 0 {
            if current == resume {
                write_unaligned(next_link as *mut u64, 0);
            }
        } else if hosted_configuration_entry_matches(current, class, kind, component_key) {
            return current;
        }

        let mut sibling = read_unaligned((current + 0x10) as *const u64);
        let mut sibling_count = 0usize;
        while sibling != 0 && sibling_count < 4096 {
            let resume = read_unaligned(next_link as *const u64);
            if resume != 0 {
                if sibling == resume {
                    write_unaligned(next_link as *mut u64, 0);
                }
            } else if hosted_configuration_entry_matches(sibling, class, kind, component_key) {
                return sibling;
            }
            let sibling_child = read_unaligned((sibling + 0x08) as *const u64);
            if sibling_child != 0 {
                let found = find_hosted_configuration_next_entry(
                    sibling_child,
                    class,
                    kind,
                    component_key,
                    next_link,
                    depth + 1,
                );
                if found != 0 {
                    return found;
                }
            }
            sibling = read_unaligned((sibling + 0x10) as *const u64);
            sibling_count += 1;
        }
        current = read_unaligned((current + 0x08) as *const u64);
        visited += 1;
    }
    0
}

/// `KeFindConfigurationNextEntry` traverses the loader's ARC configuration tree, resuming after
/// `*NextLink` when the caller enumerates repeated class/type matches.
extern "win64" fn s_ke_find_configuration_next_entry(
    child: u64,
    class: u32,
    kind: u32,
    component_key: u64,
    next_link: u64,
) -> u64 {
    unsafe { find_hosted_configuration_next_entry(child, class, kind, component_key, next_link, 0) }
}

extern "win64" fn s_strlen(src: u64) -> u64 {
    if src == 0 {
        return 0;
    }
    let mut n = 0u64;
    unsafe {
        while n < 32768 && read_volatile((src + n) as *const u8) != 0 {
            n += 1;
        }
    }
    n
}

extern "win64" fn s_strcpy(dst: u64, src: u64) -> u64 {
    if dst == 0 {
        return 0;
    }
    unsafe {
        let mut i = 0u64;
        loop {
            let b = if src == 0 {
                0
            } else {
                read_volatile((src + i) as *const u8)
            };
            write_volatile((dst + i) as *mut u8, b);
            i += 1;
            if b == 0 || i >= 32768 {
                break;
            }
        }
    }
    dst
}

extern "win64" fn s_strcmp(left: u64, right: u64) -> i32 {
    s_strncmp(left, right, usize::MAX)
}

extern "win64" fn s_strncmp(left: u64, right: u64, count: usize) -> i32 {
    if left == 0 || right == 0 {
        return i32::from(left != 0) - i32::from(right != 0);
    }
    unsafe {
        let mut index = 0usize;
        while index < count {
            let left_byte = read_volatile((left + index as u64) as *const u8);
            let right_byte = read_volatile((right + index as u64) as *const u8);
            if left_byte != right_byte {
                return left_byte as i32 - right_byte as i32;
            }
            if left_byte == 0 {
                break;
            }
            index += 1;
        }
    }
    0
}

extern "win64" fn s_strncpy(dst: u64, src: u64, count: usize) -> u64 {
    if dst == 0 {
        return 0;
    }
    unsafe {
        let mut index = 0usize;
        let mut terminated = src == 0;
        while index < count {
            let byte = if terminated {
                0
            } else {
                read_volatile((src + index as u64) as *const u8)
            };
            write_volatile((dst + index as u64) as *mut u8, byte);
            terminated |= byte == 0;
            index += 1;
        }
    }
    dst
}

extern "win64" fn s_strcat(dst: u64, src: u64) -> u64 {
    if dst == 0 {
        return 0;
    }
    let offset = s_strlen(dst);
    s_strcpy(dst.saturating_add(offset), src);
    dst
}

extern "win64" fn s_strstr(haystack: u64, needle: u64) -> u64 {
    if haystack == 0 || needle == 0 {
        return 0;
    }
    let needle_len = s_strlen(needle);
    if needle_len == 0 {
        return haystack;
    }
    let haystack_len = s_strlen(haystack);
    if needle_len > haystack_len {
        return 0;
    }
    let mut offset = 0u64;
    while offset <= haystack_len - needle_len {
        if s_strncmp(haystack + offset, needle, needle_len as usize) == 0 {
            return haystack + offset;
        }
        offset += 1;
    }
    0
}

extern "win64" fn s_wcsstr(haystack: u64, needle: u64) -> u64 {
    if haystack == 0 || needle == 0 {
        return 0;
    }
    let needle_len = s_wcslen(needle);
    if needle_len == 0 {
        return haystack;
    }
    let haystack_len = s_wcslen(haystack);
    if needle_len > haystack_len {
        return 0;
    }
    unsafe {
        let mut offset = 0u64;
        while offset <= haystack_len - needle_len {
            let mut matched = true;
            let mut index = 0u64;
            while index < needle_len {
                let left = read_volatile((haystack + (offset + index) * 2) as *const u16);
                let right = read_volatile((needle + index * 2) as *const u16);
                if left != right {
                    matched = false;
                    break;
                }
                index += 1;
            }
            if matched {
                return haystack + offset * 2;
            }
            offset += 1;
        }
    }
    0
}

extern "win64" fn s_tolower(value: i32) -> i32 {
    if (b'A' as i32..=b'Z' as i32).contains(&value) {
        value + (b'a' - b'A') as i32
    } else {
        value
    }
}

struct Win64PrintfArguments {
    registers: [u64; 3],
    register_count: usize,
    index: usize,
    stack_cursor: u64,
}

impl nt_printf::Arguments for Win64PrintfArguments {
    unsafe fn next(&mut self, _kind: nt_printf::ArgumentKind) -> u64 {
        let value = if self.index < self.register_count {
            self.registers[self.index]
        } else if self.stack_cursor != 0 {
            let value = read_unaligned(self.stack_cursor as *const u64);
            self.stack_cursor = self.stack_cursor.saturating_add(8);
            value
        } else {
            0
        };
        self.index = self.index.saturating_add(1);
        value
    }
}

impl Win64PrintfArguments {
    fn new(registers: [u64; 3], register_count: usize, caller_rsp: u64) -> Self {
        Self {
            registers,
            register_count,
            index: 0,
            // Win64 reserves 32 bytes of caller shadow space. The first variadic stack argument is
            // therefore five pointer-sized slots above the return address.
            stack_cursor: caller_rsp.checked_add(0x28).unwrap_or(0),
        }
    }
}

struct VaListPrintfArguments {
    cursor: u64,
}

impl nt_printf::Arguments for VaListPrintfArguments {
    unsafe fn next(&mut self, _kind: nt_printf::ArgumentKind) -> u64 {
        if self.cursor == 0 {
            return 0;
        }
        let value = read_unaligned(self.cursor as *const u64);
        self.cursor = self.cursor.saturating_add(8);
        value
    }
}

struct NarrowPrintfOutput {
    buffer: u64,
    capacity: usize,
    position: usize,
}

impl nt_printf::Output for NarrowPrintfOutput {
    fn write(&mut self, unit: u16) -> bool {
        if self.position >= self.capacity {
            return false;
        }
        unsafe {
            write_unaligned((self.buffer + self.position as u64) as *mut u8, unit as u8);
        }
        self.position += 1;
        true
    }
}

struct WidePrintfOutput {
    buffer: u64,
    capacity: usize,
    position: usize,
}

impl nt_printf::Output for WidePrintfOutput {
    fn write(&mut self, unit: u16) -> bool {
        if self.position >= self.capacity {
            return false;
        }
        unsafe {
            write_unaligned((self.buffer + self.position as u64 * 2) as *mut u16, unit);
        }
        self.position += 1;
        true
    }
}

unsafe fn format_narrow_driver<A: nt_printf::Arguments>(
    dst: u64,
    capacity: usize,
    fmt: u64,
    args: &mut A,
) -> i32 {
    if dst == 0 || fmt == 0 {
        return -1;
    }
    let mut output = NarrowPrintfOutput {
        buffer: dst,
        capacity,
        position: 0,
    };
    match nt_printf::format_narrow(fmt as *const u8, args, &mut output) {
        Ok(length) => {
            if length < capacity {
                write_unaligned((dst + length as u64) as *mut u8, 0);
            }
            i32::try_from(length).unwrap_or(-1)
        }
        Err(()) => -1,
    }
}

unsafe fn format_wide_driver<A: nt_printf::Arguments>(
    dst: u64,
    capacity: usize,
    fmt: u64,
    args: &mut A,
) -> i32 {
    if dst == 0 || fmt == 0 {
        return -1;
    }
    let mut output = WidePrintfOutput {
        buffer: dst,
        capacity,
        position: 0,
    };
    match nt_printf::format_wide(fmt as *const u16, args, &mut output) {
        Ok(length) => {
            if length < capacity {
                write_unaligned((dst + length as u64 * 2) as *mut u16, 0);
            }
            i32::try_from(length).unwrap_or(-1)
        }
        Err(()) => -1,
    }
}

#[no_mangle]
extern "win64" fn s_sprintf_body(dst: u64, fmt: u64, a0: u64, a1: u64, caller_rsp: u64) -> i32 {
    let mut args = Win64PrintfArguments::new([a0, a1, 0], 2, caller_rsp);
    unsafe { format_narrow_driver(dst, usize::MAX, fmt, &mut args) }
}

#[no_mangle]
extern "win64" fn s_snprintf_body(
    dst: u64,
    count: usize,
    fmt: u64,
    a0: u64,
    caller_rsp: u64,
) -> i32 {
    let mut args = Win64PrintfArguments::new([a0, 0, 0], 1, caller_rsp);
    unsafe { format_narrow_driver(dst, count, fmt, &mut args) }
}

#[no_mangle]
extern "win64" fn s_swprintf_body(dst: u64, fmt: u64, a0: u64, a1: u64, caller_rsp: u64) -> i32 {
    let mut args = Win64PrintfArguments::new([a0, a1, 0], 2, caller_rsp);
    unsafe { format_wide_driver(dst, usize::MAX, fmt, &mut args) }
}

core::arch::global_asm!(
    ".text",
    ".globl hosted_sprintf_gate",
    "hosted_sprintf_gate:",
    "mov r11, rsp",
    "sub rsp, 0x38",
    "mov [rsp + 0x20], r11",
    "call s_sprintf_body",
    "add rsp, 0x38",
    "ret",
    ".globl hosted_snprintf_gate",
    "hosted_snprintf_gate:",
    "mov r11, rsp",
    "sub rsp, 0x38",
    "mov [rsp + 0x20], r11",
    "call s_snprintf_body",
    "add rsp, 0x38",
    "ret",
    ".globl hosted_swprintf_gate",
    "hosted_swprintf_gate:",
    "mov r11, rsp",
    "sub rsp, 0x38",
    "mov [rsp + 0x20], r11",
    "call s_swprintf_body",
    "add rsp, 0x38",
    "ret",
);

extern "win64" {
    fn hosted_sprintf_gate();
    fn hosted_snprintf_gate();
    fn hosted_swprintf_gate();
}

extern "win64" fn s_vsnwprintf(dst: u64, count: usize, fmt: u64, va_list: u64) -> i32 {
    let mut args = VaListPrintfArguments { cursor: va_list };
    unsafe { format_wide_driver(dst, count, fmt, &mut args) }
}

