#[derive(Clone, Copy)]
struct HostedAscii<const N: usize> {
    bytes: [u8; N],
    len: usize,
}

impl<const N: usize> HostedAscii<N> {
    const fn empty() -> Self {
        Self {
            bytes: [0; N],
            len: 0,
        }
    }

    fn clear(&mut self) {
        self.len = 0;
    }

    fn push_byte(&mut self, b: u8) -> bool {
        if self.len >= N || b > 0x7f || b == 0 {
            return false;
        }
        self.bytes[self.len] = b;
        self.len += 1;
        true
    }

    fn push_str(&mut self, src: &str) -> bool {
        let bytes = src.as_bytes();
        if self.len + bytes.len() > N {
            return false;
        }
        let mut i = 0usize;
        while i < bytes.len() {
            let b = bytes[i];
            if b > 0x7f || b == 0 {
                return false;
            }
            self.bytes[self.len + i] = b;
            i += 1;
        }
        self.len += bytes.len();
        true
    }

    fn push_ascii<const M: usize>(&mut self, src: &HostedAscii<M>) -> bool {
        if self.len + src.len > N {
            return false;
        }
        let mut i = 0usize;
        while i < src.len {
            let b = src.bytes[i];
            if b > 0x7f || b == 0 {
                return false;
            }
            self.bytes[self.len + i] = b;
            i += 1;
        }
        self.len += src.len;
        true
    }

    fn set_str(&mut self, src: &str) -> bool {
        self.clear();
        self.push_str(src)
    }

    fn is_empty(&self) -> bool {
        self.len == 0
    }

    fn as_bytes(&self) -> &[u8] {
        &self.bytes[..self.len]
    }

    fn as_str(&self) -> &str {
        core::str::from_utf8(self.as_bytes()).unwrap_or("")
    }

    fn starts_with_byte(&self, b: u8) -> bool {
        self.len != 0 && self.bytes[0] == b
    }

    fn ends_with_byte(&self, b: u8) -> bool {
        self.len != 0 && self.bytes[self.len - 1] == b
    }
}

