#[inline]
fn ascii_upcase_u16(c: u16) -> u16 {
    if (b'a' as u16..=b'z' as u16).contains(&c) {
        c - 32
    } else {
        c
    }
}

#[inline]
fn ascii_upcase_u8(c: u8) -> u8 {
    if c.is_ascii_lowercase() {
        c - 32
    } else {
        c
    }
}

fn ascii_eq_ignore_case(a: &str, b: &str) -> bool {
    let aa = a.as_bytes();
    let bb = b.as_bytes();
    if aa.len() != bb.len() {
        return false;
    }
    let mut i = 0usize;
    while i < aa.len() {
        if ascii_upcase_u8(aa[i]) != ascii_upcase_u8(bb[i]) {
            return false;
        }
        i += 1;
    }
    true
}

fn ascii_prefix_eq_ignore_case(text: &str, prefix: &str) -> bool {
    let text = text.as_bytes();
    let prefix = prefix.as_bytes();
    if text.len() < prefix.len() {
        return false;
    }
    let mut i = 0usize;
    while i < prefix.len() {
        if ascii_upcase_u8(text[i]) != ascii_upcase_u8(prefix[i]) {
            return false;
        }
        i += 1;
    }
    true
}

fn hosted_ascii_eq_ignore_case<const A: usize, const B: usize>(
    a: &HostedAscii<A>,
    b: &HostedAscii<B>,
) -> bool {
    if a.len != b.len {
        return false;
    }
    let mut i = 0usize;
    while i < a.len {
        if ascii_upcase_u8(a.bytes[i]) != ascii_upcase_u8(b.bytes[i]) {
            return false;
        }
        i += 1;
    }
    true
}

fn hosted_ascii_eq_ignore_case_str<const N: usize>(a: &HostedAscii<N>, b: &str) -> bool {
    let bb = b.as_bytes();
    if a.len != bb.len() {
        return false;
    }
    let mut i = 0usize;
    while i < a.len {
        if ascii_upcase_u8(a.bytes[i]) != ascii_upcase_u8(bb[i]) {
            return false;
        }
        i += 1;
    }
    true
}

fn driver_key_matches_class_guid(driver_key: &str, class_guid: &str) -> bool {
    if class_guid.is_empty() {
        return true;
    }
    let key = if ascii_prefix_eq_ignore_case(driver_key, "Class\\") {
        &driver_key[6..]
    } else {
        driver_key
    };
    if key.len() < class_guid.len() {
        return false;
    }
    if !ascii_prefix_eq_ignore_case(key, class_guid) {
        return false;
    }
    key.len() == class_guid.len() || key.as_bytes()[class_guid.len()] == b'\\'
}

fn build_hosted_registry_identity(
    class_guid: Option<&str>,
    driver_key: Option<&str>,
    linkage_export: Option<&str>,
    instance_path: &str,
) -> Result<HostedDriverRegistryIdentity, nt_status::NtStatus> {
    let mut identity = EMPTY_HOSTED_DRIVER_REGISTRY_IDENTITY;
    if !identity.instance_path.set_str(instance_path) {
        return Err(nt_status::NtStatus::INVALID_PARAMETER);
    }

    if let Some(driver_key) = driver_key.filter(|key| !key.is_empty()) {
        if let Some(class_guid) = class_guid.filter(|guid| !guid.is_empty()) {
            if !driver_key_matches_class_guid(driver_key, class_guid) {
                return Err(nt_status::NtStatus::INVALID_PARAMETER);
            }
        }
        if !identity.driver_key_name.set_str(driver_key) {
            return Err(nt_status::NtStatus::INVALID_PARAMETER);
        }
        if let Some(linkage_export) = linkage_export {
            if linkage_export.is_empty() || !identity.export_name.set_str(linkage_export) {
                return Err(nt_status::NtStatus::INVALID_PARAMETER);
            }
        }
    } else if linkage_export.is_some() {
        return Err(nt_status::NtStatus::INVALID_PARAMETER);
    }

    identity.used = true;
    Ok(identity)
}

unsafe fn write_shared_registry_ascii<const N: usize>(
    sh: u64,
    len_off: u64,
    buf_off: u64,
    value: &HostedAscii<N>,
) -> Result<(), nt_status::NtStatus> {
    let len = u16::try_from(value.len).map_err(|_| nt_status::NtStatus::INVALID_PARAMETER)?;
    write_volatile((sh + len_off) as *mut u16, len);
    let mut i = 0usize;
    while i < value.len {
        write_volatile((sh + buf_off + i as u64) as *mut u8, value.bytes[i]);
        i += 1;
    }
    Ok(())
}

unsafe fn read_shared_registry_ascii_at<const N: usize>(
    sh: u64,
    len_off: u64,
    buf_off: u64,
) -> Option<HostedAscii<N>> {
    let len = read_volatile((sh + len_off) as *const u16) as usize;
    if len > N {
        return None;
    }
    let mut out = HostedAscii::<N>::empty();
    let mut i = 0usize;
    while i < len {
        let b = read_volatile((sh + buf_off + i as u64) as *const u8);
        if b == 0 || b > 0x7f || !out.push_byte(b) {
            return None;
        }
        i += 1;
    }
    Some(out)
}

unsafe fn clear_shared_registry_identity_at(sh: u64) {
    write_volatile((sh + SH_REGISTRY_IDENTITY_FLAGS) as *mut u32, 0);
    write_volatile((sh + SH_REGISTRY_INSTANCE_LEN) as *mut u16, 0);
    write_volatile((sh + SH_REGISTRY_DRIVER_KEY_LEN) as *mut u16, 0);
    write_volatile((sh + SH_REGISTRY_EXPORT_LEN) as *mut u16, 0);
}

unsafe fn publish_shared_registry_identity_at(
    sh: u64,
    identity: &HostedDriverRegistryIdentity,
) -> Result<(), nt_status::NtStatus> {
    clear_shared_registry_identity_at(sh);
    if !identity.used || identity.instance_path.is_empty() {
        return Err(nt_status::NtStatus::INVALID_PARAMETER);
    }
    write_shared_registry_ascii(
        sh,
        SH_REGISTRY_INSTANCE_LEN,
        SH_REGISTRY_INSTANCE_BUF,
        &identity.instance_path,
    )?;
    let mut flags = SH_REGISTRY_IDENTITY_PRESENT;
    if identity.has_driver_key() {
        write_shared_registry_ascii(
            sh,
            SH_REGISTRY_DRIVER_KEY_LEN,
            SH_REGISTRY_DRIVER_KEY_BUF,
            &identity.driver_key_name,
        )?;
        flags |= SH_REGISTRY_IDENTITY_HAS_DRIVER_KEY;
    }
    if identity.has_linkage_export() {
        write_shared_registry_ascii(
            sh,
            SH_REGISTRY_EXPORT_LEN,
            SH_REGISTRY_EXPORT_BUF,
            &identity.export_name,
        )?;
        flags |= SH_REGISTRY_IDENTITY_HAS_EXPORT;
    }
    write_volatile((sh + SH_REGISTRY_IDENTITY_FLAGS) as *mut u32, flags);
    Ok(())
}

unsafe fn shared_registry_identity() -> Option<HostedDriverRegistryIdentity> {
    shared_registry_identity_at(FSD_SHARED_VADDR)
}

unsafe fn shared_registry_identity_at(sh: u64) -> Option<HostedDriverRegistryIdentity> {
    let flags = read_volatile((sh + SH_REGISTRY_IDENTITY_FLAGS) as *const u32);
    if (flags & SH_REGISTRY_IDENTITY_PRESENT) == 0 {
        return None;
    }
    if (flags & SH_REGISTRY_IDENTITY_HAS_EXPORT) != 0
        && (flags & SH_REGISTRY_IDENTITY_HAS_DRIVER_KEY) == 0
    {
        return None;
    }
    let instance_path = read_shared_registry_ascii_at::<HOSTED_INSTANCE_PATH_MAX>(
        sh,
        SH_REGISTRY_INSTANCE_LEN,
        SH_REGISTRY_INSTANCE_BUF,
    )?;
    if instance_path.is_empty() {
        return None;
    }
    let driver_key_name = if (flags & SH_REGISTRY_IDENTITY_HAS_DRIVER_KEY) != 0 {
        let key = read_shared_registry_ascii_at::<HOSTED_DRIVER_KEY_NAME_MAX>(
            sh,
            SH_REGISTRY_DRIVER_KEY_LEN,
            SH_REGISTRY_DRIVER_KEY_BUF,
        )?;
        if key.is_empty() {
            return None;
        }
        key
    } else {
        HostedAscii::empty()
    };
    let export_name = if (flags & SH_REGISTRY_IDENTITY_HAS_EXPORT) != 0 {
        let export = read_shared_registry_ascii_at::<HOSTED_EXPORT_NAME_MAX>(
            sh,
            SH_REGISTRY_EXPORT_LEN,
            SH_REGISTRY_EXPORT_BUF,
        )?;
        if export.is_empty() {
            return None;
        }
        export
    } else {
        HostedAscii::empty()
    };
    Some(HostedDriverRegistryIdentity {
        instance_path,
        driver_key_name,
        export_name,
        used: true,
    })
}

unsafe fn unicode_string_triplet(us: u64) -> Option<(u16, u16, u64)> {
    if us == 0 {
        return None;
    }
    Some((
        read_unaligned((us + UNICODE_STRING_LENGTH_OFFSET) as *const u16),
        read_unaligned((us + UNICODE_STRING_MAXIMUM_LENGTH_OFFSET) as *const u16),
        read_unaligned((us + UNICODE_STRING_BUFFER_OFFSET) as *const u64),
    ))
}

unsafe fn unicode_string_to_hosted_ascii<const N: usize>(
    us: u64,
    allow_empty: bool,
) -> Option<HostedAscii<N>> {
    let (len, _max, buf) = unicode_string_triplet(us)?;
    if (len & 1) != 0 || (len != 0 && buf == 0) {
        return None;
    }
    if len == 0 {
        return if allow_empty {
            Some(HostedAscii::empty())
        } else {
            None
        };
    }
    let chars = (len / 2) as usize;
    if chars > N {
        return None;
    }
    let mut out = HostedAscii::<N>::empty();
    let mut i = 0usize;
    while i < chars {
        let c = read_unaligned((buf + (i as u64) * 2) as *const u16);
        if c == 0 || c > 0x7f {
            return None;
        }
        if !out.push_byte(c as u8) {
            return None;
        }
        i += 1;
    }
    Some(out)
}

unsafe fn wide_cstr_to_hosted_ascii<const N: usize>(ptr: u64) -> Option<HostedAscii<N>> {
    if ptr == 0 {
        return None;
    }
    let mut out = HostedAscii::<N>::empty();
    let mut i = 0usize;
    loop {
        if i >= N {
            return None;
        }
        let c = read_unaligned((ptr + (i as u64) * 2) as *const u16);
        if c == 0 {
            return Some(out);
        }
        if c > 0x7f || !out.push_byte(c as u8) {
            return None;
        }
        i += 1;
    }
}

unsafe fn write_allocated_unicode_string_from_ascii<const N: usize>(
    us: u64,
    value: &HostedAscii<N>,
) -> i32 {
    if us == 0 {
        return STATUS_INVALID_PARAMETER;
    }
    let data_len = value.len.saturating_mul(2);
    if data_len > u16::MAX as usize - 2 {
        return STATUS_INVALID_PARAMETER;
    }
    let alloc_len = data_len + 2;
    let buf = pool_alloc(alloc_len as u64);
    if buf == 0 {
        return STATUS_INSUFFICIENT_RESOURCES;
    }
    let mut i = 0usize;
    while i < value.len {
        write_unaligned((buf + (i as u64) * 2) as *mut u16, value.bytes[i] as u16);
        i += 1;
    }
    write_unaligned((buf + data_len as u64) as *mut u16, 0);
    write_unaligned(
        (us + UNICODE_STRING_LENGTH_OFFSET) as *mut u16,
        data_len as u16,
    );
    write_unaligned(
        (us + UNICODE_STRING_MAXIMUM_LENGTH_OFFSET) as *mut u16,
        alloc_len as u16,
    );
    write_unaligned((us + UNICODE_STRING_BUFFER_OFFSET) as *mut u64, buf);
    STATUS_SUCCESS
}

unsafe fn object_attributes_root_and_name<const N: usize>(
    object_attributes: u64,
) -> Option<(u64, HostedAscii<N>)> {
    if object_attributes == 0 {
        return None;
    }
    let root = read_unaligned((object_attributes + 8) as *const u64);
    let name = read_unaligned((object_attributes + 0x10) as *const u64);
    let name = if name == 0 {
        HostedAscii::empty()
    } else {
        unicode_string_to_hosted_ascii(name, true)?
    };
    Some((root, name))
}

fn hosted_driver_key_cm_path(
    identity: &HostedDriverRegistryIdentity,
) -> Option<HostedAscii<HOSTED_REGISTRY_PATH_MAX>> {
    if !identity.has_driver_key() {
        return None;
    }
    let key = identity.driver_key_name.as_str();
    let mut path = HostedAscii::<HOSTED_REGISTRY_PATH_MAX>::empty();
    if ascii_prefix_eq_ignore_case(key, r"\Registry\") {
        if !path.push_str(key) {
            return None;
        }
    } else {
        if !path.push_str(r"\Registry\Machine\System\CurrentControlSet\Control\") {
            return None;
        }
        if !ascii_prefix_eq_ignore_case(key, r"Class\") && !path.push_str("Class\\") {
            return None;
        }
        if !path.push_ascii(&identity.driver_key_name) {
            return None;
        }
    }
    Some(path)
}

fn cm_registry_path_from_object_attributes(
    root_slot: Option<&DriverRegistryHandleSlot>,
    name: &HostedAscii<HOSTED_REGISTRY_PATH_MAX>,
) -> Option<HostedAscii<HOSTED_REGISTRY_PATH_MAX>> {
    if name.starts_with_byte(b'\\') {
        let mut path = HostedAscii::<HOSTED_REGISTRY_PATH_MAX>::empty();
        return path.push_ascii(name).then_some(path);
    }

    let root = root_slot?;
    if root.kind != DriverRegistryHandleKind::CmKey || root.path.is_empty() {
        return None;
    }
    if name.is_empty() {
        return Some(root.path);
    }

    let mut path = HostedAscii::<HOSTED_REGISTRY_PATH_MAX>::empty();
    if !path.push_ascii(&root.path) {
        return None;
    }
    if !path.ends_with_byte(b'\\') && !path.push_byte(b'\\') {
        return None;
    }
    path.push_ascii(name).then_some(path)
}

fn cm_registry_path_from_rtl_path(
    relative_to: u32,
    path: &HostedAscii<HOSTED_REGISTRY_PATH_MAX>,
) -> Option<HostedAscii<HOSTED_REGISTRY_PATH_MAX>> {
    if path.starts_with_byte(b'\\') {
        let mut out = HostedAscii::<HOSTED_REGISTRY_PATH_MAX>::empty();
        return out.push_ascii(path).then_some(out);
    }

    let mut out = HostedAscii::<HOSTED_REGISTRY_PATH_MAX>::empty();
    match relative_to & 0x0000_ffff {
        0 => {}
        1 => {
            if !out.push_str(r"\Registry\Machine\System\CurrentControlSet\Services") {
                return None;
            }
        }
        2 => {
            if !out.push_str(r"\Registry\Machine\System\CurrentControlSet\Control") {
                return None;
            }
        }
        _ => return None,
    }
    if !path.is_empty() {
        if !out.is_empty() && !out.ends_with_byte(b'\\') && !out.push_byte(b'\\') {
            return None;
        }
        if !out.push_ascii(path) {
            return None;
        }
    }
    (!out.is_empty()).then_some(out)
}

fn hex_digit(value: u8) -> u8 {
    match value & 0xf {
        0..=9 => b'0' + (value & 0xf),
        _ => b'A' + ((value & 0xf) - 10),
    }
}

fn push_hex_u32<const N: usize>(out: &mut HostedAscii<N>, value: u32, nibbles: u8) -> bool {
    let mut shift = (nibbles as i32 - 1) * 4;
    while shift >= 0 {
        if !out.push_byte(hex_digit(((value >> shift) & 0xf) as u8)) {
            return false;
        }
        shift -= 4;
    }
    true
}

fn push_hex_u16<const N: usize>(out: &mut HostedAscii<N>, value: u16, nibbles: u8) -> bool {
    push_hex_u32(out, value as u32, nibbles)
}

fn push_hex_u8<const N: usize>(out: &mut HostedAscii<N>, value: u8) -> bool {
    push_hex_u32(out, value as u32, 2)
}

fn guid_parts_to_hosted_ascii(
    d1: u32,
    d2: u16,
    d3: u16,
    d4: [u8; 8],
) -> Option<HostedAscii<HOSTED_DRIVER_KEY_NAME_MAX>> {
    let mut out = HostedAscii::<HOSTED_DRIVER_KEY_NAME_MAX>::empty();
    if !out.push_byte(b'{')
        || !push_hex_u32(&mut out, d1, 8)
        || !out.push_byte(b'-')
        || !push_hex_u16(&mut out, d2, 4)
        || !out.push_byte(b'-')
        || !push_hex_u16(&mut out, d3, 4)
        || !out.push_byte(b'-')
        || !push_hex_u8(&mut out, d4[0])
        || !push_hex_u8(&mut out, d4[1])
        || !out.push_byte(b'-')
    {
        return None;
    }
    let mut i = 2usize;
    while i < d4.len() {
        if !push_hex_u8(&mut out, d4[i]) {
            return None;
        }
        i += 1;
    }
    if !out.push_byte(b'}') {
        return None;
    }
    Some(out)
}

fn guid_words_to_hosted_ascii(words: [u64; 2]) -> Option<HostedAscii<HOSTED_DRIVER_KEY_NAME_MAX>> {
    let first = words[0].to_le_bytes();
    guid_parts_to_hosted_ascii(
        u32::from_le_bytes(first[..4].try_into().ok()?),
        u16::from_le_bytes(first[4..6].try_into().ok()?),
        u16::from_le_bytes(first[6..8].try_into().ok()?),
        words[1].to_le_bytes(),
    )
}

unsafe fn guid_to_hosted_ascii(guid: u64) -> Option<HostedAscii<HOSTED_DRIVER_KEY_NAME_MAX>> {
    if guid == 0 {
        return None;
    }
    guid_words_to_hosted_ascii([
        read_unaligned(guid as *const u64),
        read_unaligned((guid + 8) as *const u64),
    ])
}

unsafe fn copy_bytes_unchecked(dst: u64, src: u64, len: u64) {
    let mut off = 0u64;
    while off < len {
        write_unaligned(
            (dst + off) as *mut u8,
            read_unaligned((src + off) as *const u8),
        );
        off += 1;
    }
}

unsafe fn write_registry_arg_ascii<const N: usize>(
    len_off: u64,
    buf_off: u64,
    value: &HostedAscii<N>,
) -> bool {
    if value.len > u32::MAX as usize {
        return false;
    }
    write_volatile((FSD_ARG_VADDR + len_off) as *mut u32, value.len as u32);
    let mut i = 0usize;
    while i < value.len {
        write_volatile(
            (FSD_ARG_VADDR + buf_off + i as u64) as *mut u8,
            value.bytes[i],
        );
        i += 1;
    }
    true
}

unsafe fn read_registry_arg_ascii_at<const N: usize>(
    arg: u64,
    len_off: u64,
    buf_off: u64,
    allow_empty: bool,
) -> Option<HostedAscii<N>> {
    let len = read_volatile((arg + len_off) as *const u32) as usize;
    if len == 0 {
        return if allow_empty {
            Some(HostedAscii::empty())
        } else {
            None
        };
    }
    if len > N {
        return None;
    }
    let mut out = HostedAscii::<N>::empty();
    let mut i = 0usize;
    while i < len {
        let b = read_volatile((arg + buf_off + i as u64) as *const u8);
        if b == 0 || b > 0x7f || !out.push_byte(b) {
            return None;
        }
        i += 1;
    }
    Some(out)
}

unsafe fn write_registry_arg_data(data: u64, data_len: u32) -> i32 {
    if data_len as u64 > HOSTED_REGISTRY_ARG_DATA_CAP {
        return STATUS_INVALID_BUFFER_SIZE as i32;
    }
    if data_len != 0 {
        if data == 0 {
            return STATUS_INVALID_PARAMETER;
        }
        copy_bytes_unchecked(
            FSD_ARG_VADDR + HOSTED_REGISTRY_ARG_DATA_OFF,
            data,
            data_len as u64,
        );
    }
    write_volatile(
        (FSD_ARG_VADDR + HOSTED_REGISTRY_ARG_DATA_LEN) as *mut u32,
        data_len,
    );
    STATUS_SUCCESS
}

unsafe fn hosted_registry_broker_call(op: u64, a1: u64, a2: u64, a3: u64) -> (i32, u64, u64) {
    let (_label, status, out1, out2, _) =
        call_on4((FSD_SERVICE_REGISTRY_LABEL << 12) | 4, op, a1, a2, a3);
    (status as u32 as i32, out1, out2)
}

unsafe fn hosted_device_property_begin(
    pdo: u64,
    property: u32,
    buffer_len: u32,
) -> (i32, u64, u64, u64) {
    let (_label, status, required_len, token, chunk_len) = call_on4(
        (FSD_SERVICE_DEVICE_LABEL << 12) | 4,
        HOSTED_DEVICE_OP_QUERY_PROPERTY_BEGIN,
        pdo,
        property as u64,
        buffer_len as u64,
    );
    (status as u32 as i32, required_len, token, chunk_len)
}

unsafe fn hosted_device_property_pull(pdo: u64, token: u64, offset: u64) -> (i32, u64, u64, u64) {
    let (_label, status, required_len, reply_token, chunk_len) = call_on4(
        (FSD_SERVICE_DEVICE_LABEL << 12) | 4,
        HOSTED_DEVICE_OP_QUERY_PROPERTY_PULL,
        pdo,
        token,
        offset,
    );
    (status as u32 as i32, required_len, reply_token, chunk_len)
}

unsafe fn hosted_device_property_abort(pdo: u64, token: u64) {
    if token != 0 {
        let _ = call_on4(
            (FSD_SERVICE_DEVICE_LABEL << 12) | 4,
            HOSTED_DEVICE_OP_QUERY_PROPERTY_ABORT,
            pdo,
            token,
            0,
        );
    }
}

unsafe fn hosted_device_claim_port_range(pdo: u64, start: u64, length: u64) -> i32 {
    let (_label, status, _, _, _) = call_on4(
        (FSD_SERVICE_DEVICE_LABEL << 12) | 4,
        HOSTED_DEVICE_OP_CLAIM_PORT_RANGE,
        pdo,
        start,
        length,
    );
    status as u32 as i32
}

unsafe fn hosted_device_invalidate_relations(pdo: u64, relation_type: u32) {
    let _ = call_on4(
        (FSD_SERVICE_DEVICE_LABEL << 12) | 4,
        HOSTED_DEVICE_OP_INVALIDATE_RELATIONS,
        pdo,
        relation_type as u64,
        0,
    );
}

unsafe fn hosted_device_create(device: u64, driver: u64, extension_size: u64) -> (i32, u64) {
    let (_label, status, canonical_device_id, _, _) = call_on4(
        (FSD_SERVICE_DEVICE_LABEL << 12) | 4,
        HOSTED_DEVICE_OP_CREATE,
        device,
        driver,
        extension_size,
    );
    (status as u32 as i32, canonical_device_id)
}

unsafe fn hosted_device_attach(source: u64, target: u64, lower: u64) -> i32 {
    let (_label, status, _, _, _) = call_on4(
        (FSD_SERVICE_DEVICE_LABEL << 12) | 4,
        HOSTED_DEVICE_OP_ATTACH,
        source,
        target,
        lower,
    );
    status as u32 as i32
}

unsafe fn hosted_device_detach(lower: u64, upper: u64) -> i32 {
    let (_label, status, _, _, _) = call_on4(
        (FSD_SERVICE_DEVICE_LABEL << 12) | 4,
        HOSTED_DEVICE_OP_DETACH,
        lower,
        upper,
        0,
    );
    status as u32 as i32
}

unsafe fn hosted_device_delete(device: u64) -> i32 {
    let (_label, status, _, _, _) = call_on4(
        (FSD_SERVICE_DEVICE_LABEL << 12) | 4,
        HOSTED_DEVICE_OP_DELETE,
        device,
        0,
        0,
    );
    status as u32 as i32
}

unsafe fn hosted_symbolic_link_operation(op: u64) -> i32 {
    let (_label, status, _, _, _) = call_on4((FSD_SERVICE_DEVICE_LABEL << 12) | 4, op, 0, 0, 0);
    status as u32 as i32
}

unsafe fn hosted_device_interface_operation(op: u64, pdo: u64, arg2: u64, arg3: u64) -> i32 {
    let (_label, status, _, _, _) =
        call_on4((FSD_SERVICE_DEVICE_LABEL << 12) | 4, op, pdo, arg2, arg3);
    status as u32 as i32
}

unsafe fn broker_query_registry_path_value(
    key_path: &HostedAscii<HOSTED_REGISTRY_PATH_MAX>,
    value_name: &HostedAscii<HOSTED_REGISTRY_PATH_MAX>,
) -> (i32, u32, u32) {
    if key_path.is_empty()
        || !write_registry_arg_ascii(
            HOSTED_REGISTRY_ARG_KEY_LEN,
            HOSTED_REGISTRY_ARG_KEY_OFF,
            key_path,
        )
        || !write_registry_arg_ascii(
            HOSTED_REGISTRY_ARG_VALUE_LEN,
            HOSTED_REGISTRY_ARG_VALUE_OFF,
            value_name,
        )
    {
        return (STATUS_INVALID_PARAMETER, 0, 0);
    }
    let (status, value_type, data_len) =
        hosted_registry_broker_call(HOSTED_REGISTRY_OP_QUERY_PATH_VALUE, 0, 0, 0);
    (status, value_type as u32, data_len as u32)
}

unsafe fn registry_arg_data_slice(len: u32) -> &'static [u8] {
    core::slice::from_raw_parts(
        (FSD_ARG_VADDR + HOSTED_REGISTRY_ARG_DATA_OFF) as *const u8,
        len as usize,
    )
}

/// `PVOID ExAllocatePoolWithTag(POOL_TYPE, SIZE_T NumberOfBytes, ULONG Tag)`.
extern "win64" fn s_ex_alloc_pool_tag(_pool: u64, size: u64, _tag: u64) -> u64 {
    unsafe { pool_alloc(size) }
}
/// `PVOID ExAllocatePoolWithQuotaTag(POOL_TYPE, SIZE_T, ULONG)`.
extern "win64" fn s_ex_alloc_pool_quota_tag(_pool: u64, size: u64, _tag: u64) -> u64 {
    unsafe { pool_alloc(size) }
}
/// `PVOID ExAllocatePool(POOL_TYPE, SIZE_T)`.
extern "win64" fn s_ex_alloc_pool(_pool: u64, size: u64) -> u64 {
    unsafe { pool_alloc(size) }
}
/// `void ExFreePoolWithTag(PVOID, ULONG)` / `void ExFreePool(PVOID)`.
extern "win64" fn s_ex_free_pool_tag(p: u64, _tag: u64) {
    unsafe { pool_free(p) }
}
extern "win64" fn s_ex_free_pool(p: u64) {
    unsafe { pool_free(p) }
}

/// `void RtlInitUnicodeString(PUNICODE_STRING Dest, PCWSTR Source)`.
extern "win64" fn s_rtl_init_unicode_string(dst: u64, src: u64) {
    if dst == 0 {
        return;
    }
    unsafe {
        let mut len = 0u16;
        if src != 0 {
            let mut n = 0u64;
            while read_unaligned((src + n * 2) as *const u16) != 0 {
                n += 1;
            }
            len = (n * 2) as u16;
        }
        write_unaligned(dst as *mut u16, len); // Length
        write_unaligned((dst + 2) as *mut u16, if src != 0 { len + 2 } else { 0 }); // MaximumLength
        write_unaligned((dst + 8) as *mut u64, src); // Buffer
    }
}

/// `void RtlInitEmptyUnicodeString(PUNICODE_STRING, PWSTR Buffer, USHORT MaxLen)`.
extern "win64" fn s_rtl_init_empty_unicode_string(dst: u64, buf: u64, maxlen: u64) {
    if dst == 0 {
        return;
    }
    unsafe {
        write_unaligned(dst as *mut u16, 0);
        write_unaligned((dst + 2) as *mut u16, maxlen as u16);
        write_unaligned((dst + 8) as *mut u64, buf);
    }
}

/// `VOID RtlFreeUnicodeString(PUNICODE_STRING)`.
extern "win64" fn s_rtl_free_unicode_string(us: u64) {
    unsafe {
        if let Some((_len, _max, buf)) = unicode_string_triplet(us) {
            if buf != 0 {
                pool_free(buf);
            }
            write_unaligned((us + UNICODE_STRING_LENGTH_OFFSET) as *mut u16, 0);
            write_unaligned((us + UNICODE_STRING_MAXIMUM_LENGTH_OFFSET) as *mut u16, 0);
            write_unaligned((us + UNICODE_STRING_BUFFER_OFFSET) as *mut u64, 0);
        }
    }
}

/// `VOID RtlCopyUnicodeString(PUNICODE_STRING Destination, PCUNICODE_STRING Source)`.
extern "win64" fn s_rtl_copy_unicode_string(dst: u64, src: u64) {
    if dst == 0 {
        return;
    }
    unsafe {
        let dst_max =
            read_unaligned((dst + UNICODE_STRING_MAXIMUM_LENGTH_OFFSET) as *const u16) & !1;
        let dst_buf = read_unaligned((dst + UNICODE_STRING_BUFFER_OFFSET) as *const u64);
        if src == 0 || dst_buf == 0 || dst_max == 0 {
            write_unaligned((dst + UNICODE_STRING_LENGTH_OFFSET) as *mut u16, 0);
            return;
        }
        let (src_len, _src_max, src_buf) = unicode_string_triplet(src).unwrap_or((0, 0, 0));
        let copy_len = (src_len & !1).min(dst_max);
        if src_buf != 0 && copy_len != 0 {
            copy_bytes_unchecked(dst_buf, src_buf, copy_len as u64);
        }
        write_unaligned((dst + UNICODE_STRING_LENGTH_OFFSET) as *mut u16, copy_len);
    }
}

/// `LONG RtlCompareUnicodeString(PCUNICODE_STRING, PCUNICODE_STRING, BOOLEAN CaseInsensitive)`.
extern "win64" fn s_rtl_compare_unicode_string(left: u64, right: u64, case_insensitive: u8) -> i32 {
    unsafe {
        let (left_len, _left_max, left_buf) = unicode_string_triplet(left).unwrap_or((0, 0, 0));
        let (right_len, _right_max, right_buf) = unicode_string_triplet(right).unwrap_or((0, 0, 0));
        let left_chars = (left_len / 2) as u64;
        let right_chars = (right_len / 2) as u64;
        let common = left_chars.min(right_chars);
        let mut i = 0u64;
        while i < common {
            let mut a = if left_buf == 0 {
                0
            } else {
                read_unaligned((left_buf + i * 2) as *const u16)
            };
            let mut b = if right_buf == 0 {
                0
            } else {
                read_unaligned((right_buf + i * 2) as *const u16)
            };
            if case_insensitive != 0 {
                a = ascii_upcase_u16(a);
                b = ascii_upcase_u16(b);
            }
            if a != b {
                return a as i32 - b as i32;
            }
            i += 1;
        }
        left_chars as i32 - right_chars as i32
    }
}

/// `NTSTATUS RtlUpcaseUnicodeString(PUNICODE_STRING Dest, PCUNICODE_STRING Src, BOOLEAN Allocate)`.
extern "win64" fn s_rtl_upcase_unicode_string(dst: u64, src: u64, allocate: u8) -> i32 {
    if dst == 0 || src == 0 {
        return STATUS_INVALID_PARAMETER;
    }
    unsafe {
        let (src_len, _src_max, src_buf) = unicode_string_triplet(src).unwrap_or((0, 0, 0));
        if src_len != 0 && src_buf == 0 {
            return STATUS_INVALID_PARAMETER;
        }
        let dst_buf = if allocate != 0 {
            let alloc_len = (src_len as u64).max(2);
            let p = pool_alloc(alloc_len);
            if p == 0 {
                return STATUS_INSUFFICIENT_RESOURCES;
            }
            write_unaligned(
                (dst + UNICODE_STRING_MAXIMUM_LENGTH_OFFSET) as *mut u16,
                alloc_len as u16,
            );
            write_unaligned((dst + UNICODE_STRING_BUFFER_OFFSET) as *mut u64, p);
            p
        } else {
            let max_len =
                read_unaligned((dst + UNICODE_STRING_MAXIMUM_LENGTH_OFFSET) as *const u16) & !1;
            let p = read_unaligned((dst + UNICODE_STRING_BUFFER_OFFSET) as *const u64);
            if src_len > max_len || (src_len != 0 && p == 0) {
                write_unaligned((dst + UNICODE_STRING_LENGTH_OFFSET) as *mut u16, 0);
                return STATUS_BUFFER_TOO_SMALL;
            }
            p
        };
        let mut off = 0u64;
        while off < src_len as u64 {
            let c = read_unaligned((src_buf + off) as *const u16);
            write_unaligned((dst_buf + off) as *mut u16, ascii_upcase_u16(c));
            off += 2;
        }
        write_unaligned((dst + UNICODE_STRING_LENGTH_OFFSET) as *mut u16, src_len);
    }
    STATUS_SUCCESS
}

/// `NTSTATUS RtlAppendUnicodeStringToString(PUNICODE_STRING Dest, PCUNICODE_STRING Src)`.
extern "win64" fn s_rtl_append_unicode_string_to_string(dst: u64, src: u64) -> i32 {
    if dst == 0 || src == 0 {
        return STATUS_INVALID_PARAMETER;
    }
    unsafe {
        let dst_len = read_unaligned((dst + UNICODE_STRING_LENGTH_OFFSET) as *const u16) & !1;
        let dst_max =
            read_unaligned((dst + UNICODE_STRING_MAXIMUM_LENGTH_OFFSET) as *const u16) & !1;
        let dst_buf = read_unaligned((dst + UNICODE_STRING_BUFFER_OFFSET) as *const u64);
        let (src_len, _src_max, src_buf) = unicode_string_triplet(src).unwrap_or((0, 0, 0));
        if dst_buf == 0 || (src_len != 0 && src_buf == 0) {
            return STATUS_INVALID_PARAMETER;
        }
        if src_len > dst_max.saturating_sub(dst_len) {
            return STATUS_BUFFER_TOO_SMALL;
        }
        copy_bytes_unchecked(dst_buf + dst_len as u64, src_buf, src_len as u64);
        let new_len = dst_len + src_len;
        write_unaligned((dst + UNICODE_STRING_LENGTH_OFFSET) as *mut u16, new_len);
        if new_len <= dst_max.saturating_sub(2) {
            write_unaligned((dst_buf + new_len as u64) as *mut u16, 0);
        }
    }
    STATUS_SUCCESS
}

/// `NTSTATUS RtlAppendUnicodeToString(PUNICODE_STRING Dest, PCWSTR Src)`.
extern "win64" fn s_rtl_append_unicode_to_string(dst: u64, src: u64) -> i32 {
    if dst == 0 {
        return STATUS_INVALID_PARAMETER;
    }
    if src == 0 {
        return STATUS_SUCCESS;
    }
    unsafe {
        let dst_len = read_unaligned((dst + UNICODE_STRING_LENGTH_OFFSET) as *const u16) & !1;
        let dst_max =
            read_unaligned((dst + UNICODE_STRING_MAXIMUM_LENGTH_OFFSET) as *const u16) & !1;
        let dst_buf = read_unaligned((dst + UNICODE_STRING_BUFFER_OFFSET) as *const u64);
        if dst_buf == 0 {
            return STATUS_INVALID_PARAMETER;
        }
        let src_chars = s_wcslen(src) as u16;
        let src_len = src_chars.saturating_mul(2);
        if src_len > dst_max.saturating_sub(dst_len) {
            return STATUS_BUFFER_TOO_SMALL;
        }
        copy_bytes_unchecked(dst_buf + dst_len as u64, src, src_len as u64);
        let new_len = dst_len + src_len;
        write_unaligned((dst + UNICODE_STRING_LENGTH_OFFSET) as *mut u16, new_len);
        if new_len <= dst_max.saturating_sub(2) {
            write_unaligned((dst_buf + new_len as u64) as *mut u16, 0);
        }
    }
    STATUS_SUCCESS
}

/// `BOOLEAN RtlEqualUnicodeString(PCUNICODE_STRING, PCUNICODE_STRING, BOOLEAN)`.
extern "win64" fn s_rtl_equal_unicode_string(left: u64, right: u64, case_insensitive: u8) -> u8 {
    (s_rtl_compare_unicode_string(left, right, case_insensitive) == 0) as u8
}

unsafe fn ansi_string_triplet(s: u64) -> Option<(u16, u16, u64)> {
    if s == 0 {
        return None;
    }
    Some((
        read_unaligned((s + ANSI_STRING_LENGTH_OFFSET) as *const u16),
        read_unaligned((s + ANSI_STRING_MAXIMUM_LENGTH_OFFSET) as *const u16),
        read_unaligned((s + ANSI_STRING_BUFFER_OFFSET) as *const u64),
    ))
}

unsafe fn strlen8(src: u64) -> u16 {
    if src == 0 {
        return 0;
    }
    let mut n = 0u64;
    while n < u16::MAX as u64 && read_unaligned((src + n) as *const u8) != 0 {
        n += 1;
    }
    n as u16
}

/// `VOID RtlInitAnsiString(PANSI_STRING Dest, PCSZ Source)` / `RtlInitString`.
extern "win64" fn s_rtl_init_ansi_string(dst: u64, src: u64) {
    if dst == 0 {
        return;
    }
    unsafe {
        let len = strlen8(src);
        write_unaligned((dst + ANSI_STRING_LENGTH_OFFSET) as *mut u16, len);
        write_unaligned(
            (dst + ANSI_STRING_MAXIMUM_LENGTH_OFFSET) as *mut u16,
            if src == 0 { 0 } else { len.saturating_add(1) },
        );
        write_unaligned((dst + ANSI_STRING_BUFFER_OFFSET) as *mut u64, src);
    }
}

/// `NTSTATUS RtlAnsiStringToUnicodeString(PUNICODE_STRING, PCANSI_STRING, BOOLEAN Allocate)`.
extern "win64" fn s_rtl_ansi_string_to_unicode_string(dst: u64, src: u64, allocate: u8) -> i32 {
    if dst == 0 || src == 0 {
        return STATUS_INVALID_PARAMETER;
    }
    unsafe {
        let (src_len, _src_max, src_buf) = ansi_string_triplet(src).unwrap_or((0, 0, 0));
        if src_len != 0 && src_buf == 0 {
            return STATUS_INVALID_PARAMETER;
        }
        let out_len = src_len.saturating_mul(2);
        let dst_buf = if allocate != 0 {
            let alloc_len = (out_len as u64).saturating_add(2);
            let p = pool_alloc(alloc_len);
            if p == 0 {
                return STATUS_INSUFFICIENT_RESOURCES;
            }
            write_unaligned(
                (dst + UNICODE_STRING_MAXIMUM_LENGTH_OFFSET) as *mut u16,
                alloc_len as u16,
            );
            write_unaligned((dst + UNICODE_STRING_BUFFER_OFFSET) as *mut u64, p);
            p
        } else {
            let max_len =
                read_unaligned((dst + UNICODE_STRING_MAXIMUM_LENGTH_OFFSET) as *const u16);
            let p = read_unaligned((dst + UNICODE_STRING_BUFFER_OFFSET) as *const u64);
            if out_len > max_len || (out_len != 0 && p == 0) {
                return STATUS_BUFFER_TOO_SMALL;
            }
            p
        };
        let mut i = 0u64;
        while i < src_len as u64 {
            let b = read_unaligned((src_buf + i) as *const u8);
            write_unaligned((dst_buf + i * 2) as *mut u16, b as u16);
            i += 1;
        }
        write_unaligned((dst + UNICODE_STRING_LENGTH_OFFSET) as *mut u16, out_len);
        if out_len
            <= read_unaligned((dst + UNICODE_STRING_MAXIMUM_LENGTH_OFFSET) as *const u16)
                .saturating_sub(2)
        {
            write_unaligned((dst_buf + out_len as u64) as *mut u16, 0);
        }
    }
    STATUS_SUCCESS
}

/// `NTSTATUS RtlUnicodeStringToAnsiString(PANSI_STRING, PCUNICODE_STRING, BOOLEAN Allocate)`.
extern "win64" fn s_rtl_unicode_string_to_ansi_string(dst: u64, src: u64, allocate: u8) -> i32 {
    if dst == 0 || src == 0 {
        return STATUS_INVALID_PARAMETER;
    }
    unsafe {
        let (src_len, _src_max, src_buf) = unicode_string_triplet(src).unwrap_or((0, 0, 0));
        if src_len != 0 && src_buf == 0 {
            return STATUS_INVALID_PARAMETER;
        }
        let out_len = src_len / 2;
        let dst_buf = if allocate != 0 {
            let alloc_len = (out_len as u64).saturating_add(1);
            let p = pool_alloc(alloc_len);
            if p == 0 {
                return STATUS_INSUFFICIENT_RESOURCES;
            }
            write_unaligned(
                (dst + ANSI_STRING_MAXIMUM_LENGTH_OFFSET) as *mut u16,
                alloc_len as u16,
            );
            write_unaligned((dst + ANSI_STRING_BUFFER_OFFSET) as *mut u64, p);
            p
        } else {
            let max_len = read_unaligned((dst + ANSI_STRING_MAXIMUM_LENGTH_OFFSET) as *const u16);
            let p = read_unaligned((dst + ANSI_STRING_BUFFER_OFFSET) as *const u64);
            if out_len > max_len || (out_len != 0 && p == 0) {
                return STATUS_BUFFER_TOO_SMALL;
            }
            p
        };
        let mut i = 0u64;
        while i < out_len as u64 {
            let w = read_unaligned((src_buf + i * 2) as *const u16);
            write_unaligned(
                (dst_buf + i) as *mut u8,
                if w <= 0x7f { w as u8 } else { b'?' },
            );
            i += 1;
        }
        write_unaligned((dst + ANSI_STRING_LENGTH_OFFSET) as *mut u16, out_len);
        if out_len
            <= read_unaligned((dst + ANSI_STRING_MAXIMUM_LENGTH_OFFSET) as *const u16)
                .saturating_sub(1)
        {
            write_unaligned((dst_buf + out_len as u64) as *mut u8, 0);
        }
    }
    STATUS_SUCCESS
}

/// `VOID RtlFreeAnsiString(PANSI_STRING)`.
extern "win64" fn s_rtl_free_ansi_string(s: u64) {
    unsafe {
        if let Some((_len, _max, buf)) = ansi_string_triplet(s) {
            if buf != 0 {
                pool_free(buf);
            }
            write_unaligned((s + ANSI_STRING_LENGTH_OFFSET) as *mut u16, 0);
            write_unaligned((s + ANSI_STRING_MAXIMUM_LENGTH_OFFSET) as *mut u16, 0);
            write_unaligned((s + ANSI_STRING_BUFFER_OFFSET) as *mut u64, 0);
        }
    }
}

/// `BOOLEAN RtlCreateUnicodeString(PUNICODE_STRING, PCWSTR)`.
extern "win64" fn s_rtl_create_unicode_string(dst: u64, src: u64) -> u8 {
    if dst == 0 || src == 0 {
        return 0;
    }
    unsafe {
        let chars = s_wcslen(src);
        let Some(bytes) = chars.checked_mul(2) else {
            return 0;
        };
        let Some(alloc_len) = bytes.checked_add(2) else {
            return 0;
        };
        if alloc_len > u16::MAX as u64 {
            return 0;
        }
        let buf = pool_alloc(alloc_len);
        if buf == 0 {
            return 0;
        }
        copy_bytes_unchecked(buf, src, bytes);
        write_unaligned((buf + bytes) as *mut u16, 0);
        write_unaligned(
            (dst + UNICODE_STRING_LENGTH_OFFSET) as *mut u16,
            bytes as u16,
        );
        write_unaligned(
            (dst + UNICODE_STRING_MAXIMUM_LENGTH_OFFSET) as *mut u16,
            alloc_len as u16,
        );
        write_unaligned((dst + UNICODE_STRING_BUFFER_OFFSET) as *mut u64, buf);
    }
    1
}

/// `NTSTATUS RtlUnicodeToMultiByteN(PCHAR, ULONG, PULONG, PCWCH, ULONG)`.
extern "win64" fn s_rtl_unicode_to_multibyte_n(
    dst: u64,
    dst_max: u32,
    bytes_out: u64,
    src: u64,
    src_bytes: u32,
) -> i32 {
    if src_bytes != 0 && src == 0 {
        return STATUS_INVALID_PARAMETER;
    }
    let chars = src_bytes / 2;
    let copy_chars = chars.min(dst_max);
    unsafe {
        if bytes_out != 0 {
            write_unaligned(bytes_out as *mut u32, copy_chars);
        }
        if copy_chars != 0 && dst == 0 {
            return STATUS_ACCESS_VIOLATION;
        }
        let mut i = 0u32;
        while i < copy_chars {
            let w = read_unaligned((src + i as u64 * 2) as *const u16);
            write_unaligned(
                (dst + i as u64) as *mut u8,
                if w <= 0x7f { w as u8 } else { b'?' },
            );
            i += 1;
        }
    }
    STATUS_SUCCESS
}

/// `LONG RtlCompareString(PCANSI_STRING, PCANSI_STRING, BOOLEAN)`.
extern "win64" fn s_rtl_compare_string(left: u64, right: u64, case_insensitive: u8) -> i32 {
    unsafe {
        let (left_len, _left_max, left_buf) = ansi_string_triplet(left).unwrap_or((0, 0, 0));
        let (right_len, _right_max, right_buf) = ansi_string_triplet(right).unwrap_or((0, 0, 0));
        let common = (left_len as u64).min(right_len as u64);
        let mut i = 0u64;
        while i < common {
            let mut a = if left_buf == 0 {
                0
            } else {
                read_unaligned((left_buf + i) as *const u8)
            };
            let mut b = if right_buf == 0 {
                0
            } else {
                read_unaligned((right_buf + i) as *const u8)
            };
            if case_insensitive != 0 {
                a = ascii_upcase_u8(a);
                b = ascii_upcase_u8(b);
            }
            if a != b {
                return a as i32 - b as i32;
            }
            i += 1;
        }
        left_len as i32 - right_len as i32
    }
}

/// `wcsncmp`.
extern "win64" fn s_wcsncmp(left: u64, right: u64, count: u64) -> i32 {
    unsafe {
        let mut i = 0u64;
        while i < count {
            let a = if left == 0 {
                0
            } else {
                read_unaligned((left + i * 2) as *const u16)
            };
            let b = if right == 0 {
                0
            } else {
                read_unaligned((right + i * 2) as *const u16)
            };
            if a != b || a == 0 || b == 0 {
                return a as i32 - b as i32;
            }
            i += 1;
        }
    }
    0
}

extern "win64" fn s_wcscpy(dst: u64, src: u64) -> u64 {
    unsafe {
        let mut i = 0u64;
        loop {
            let c = if src == 0 {
                0
            } else {
                read_unaligned((src + i * 2) as *const u16)
            };
            write_unaligned((dst + i * 2) as *mut u16, c);
            i += 1;
            if c == 0 {
                break;
            }
        }
    }
    dst
}

extern "win64" fn s_wcsncpy(dst: u64, src: u64, count: u64) -> u64 {
    unsafe {
        let mut i = 0u64;
        let mut padding = false;
        while i < count {
            let c = if padding || src == 0 {
                0
            } else {
                read_unaligned((src + i * 2) as *const u16)
            };
            write_unaligned((dst + i * 2) as *mut u16, c);
            if c == 0 {
                padding = true;
            }
            i += 1;
        }
    }
    dst
}

unsafe fn wcs_end(mut s: u64) -> u64 {
    while read_unaligned(s as *const u16) != 0 {
        s += 2;
    }
    s
}

extern "win64" fn s_wcscat(dst: u64, src: u64) -> u64 {
    unsafe {
        let end = wcs_end(dst);
        let _ = s_wcscpy(end, src);
    }
    dst
}

extern "win64" fn s_wcsncat(dst: u64, src: u64, count: u64) -> u64 {
    unsafe {
        let mut out = wcs_end(dst);
        let mut i = 0u64;
        while i < count {
            let c = if src == 0 {
                0
            } else {
                read_unaligned((src + i * 2) as *const u16)
            };
            if c == 0 {
                break;
            }
            write_unaligned(out as *mut u16, c);
            out += 2;
            i += 1;
        }
        write_unaligned(out as *mut u16, 0);
    }
    dst
}

unsafe fn unicode_string_parts(us: u64) -> Option<(u64, u16)> {
    if us == 0 {
        return None;
    }
    let len = read_unaligned(us as *const u16);
    let buf = read_unaligned((us + 8) as *const u64);
    if len == 0 || len as usize > SH_CAPTURED_PATH_BYTES || (len & 1) != 0 || buf == 0 {
        return None;
    }
    Some((buf, len))
}

unsafe fn clear_shared_path_len(len_off: u64) {
    clear_shared_path_len_at(FSD_SHARED_VADDR, len_off);
}

unsafe fn clear_shared_path_len_at(sh: u64, len_off: u64) {
    write_volatile((sh + len_off) as *mut u16, 0);
}

unsafe fn copy_wstr_to_shared(src: u64, len: u16, len_off: u64, buf_off: u64) {
    let mut off = 0u64;
    while off < len as u64 {
        let b = read_volatile((src + off) as *const u8);
        write_volatile((FSD_SHARED_VADDR + buf_off + off) as *mut u8, b);
        off += 1;
    }
    write_volatile((FSD_SHARED_VADDR + len_off) as *mut u16, len);
}

unsafe fn clear_hosted_device_interface_arg() {
    write_volatile(
        (FSD_ARG_VADDR + HOSTED_DEVICE_INTERFACE_ARG_LINK_LEN) as *mut u16,
        0,
    );
}

unsafe fn copy_ascii_to_hosted_device_interface_arg<const N: usize>(value: &HostedAscii<N>) -> i32 {
    let len = value.len.saturating_mul(2);
    if value.is_empty()
        || len > HOSTED_INTERFACE_LINK_MAX.saturating_mul(2)
        || len > u16::MAX as usize
    {
        return STATUS_INVALID_PARAMETER;
    }
    let mut i = 0usize;
    while i < value.len {
        write_volatile(
            (FSD_ARG_VADDR + HOSTED_DEVICE_INTERFACE_ARG_LINK_BUF + (i as u64) * 2) as *mut u16,
            value.bytes[i] as u16,
        );
        i += 1;
    }
    write_volatile(
        (FSD_ARG_VADDR + HOSTED_DEVICE_INTERFACE_ARG_LINK_LEN) as *mut u16,
        len as u16,
    );
    STATUS_SUCCESS
}

unsafe fn copy_unicode_to_hosted_device_interface_arg(unicode_string: u64) -> i32 {
    let Some((len, _max, buffer)) = unicode_string_triplet(unicode_string) else {
        return STATUS_INVALID_PARAMETER;
    };
    if len == 0
        || (len & 1) != 0
        || len as usize > HOSTED_INTERFACE_LINK_MAX.saturating_mul(2)
        || buffer == 0
    {
        return STATUS_INVALID_PARAMETER;
    }
    let mut offset = 0u64;
    while offset < len as u64 {
        write_volatile(
            (FSD_ARG_VADDR + HOSTED_DEVICE_INTERFACE_ARG_LINK_BUF + offset) as *mut u8,
            read_unaligned((buffer + offset) as *const u8),
        );
        offset += 1;
    }
    write_volatile(
        (FSD_ARG_VADDR + HOSTED_DEVICE_INTERFACE_ARG_LINK_LEN) as *mut u16,
        len,
    );
    STATUS_SUCCESS
}

/// `NTSTATUS IoCreateDevice(PDRIVER_OBJECT, ULONG DeviceExtensionSize, PUNICODE_STRING DeviceName,
/// DEVICE_TYPE, ULONG Characteristics, BOOLEAN Exclusive, PDEVICE_OBJECT *DeviceObject)`.
/// Allocate a DEVICE_OBJECT (with the requested extension) from the pool, minimally initialize it,
/// link it onto DriverObject->DeviceObject, and return it via the out-param. Records the device in
/// the shared page (the executive resolves the FSD's control device to it).
extern "win64" fn s_io_create_device(
    drv: u64,
    ext_size: u32,
    name: u64,
    dev_type: u32,
    chars: u32,
    excl: u8,
    dev_out: u64,
) -> i32 {
    unsafe {
        if drv == 0 || dev_out == 0 {
            return STATUS_INVALID_PARAMETER;
        }
        write_unaligned(dev_out as *mut u64, 0);
        clear_shared_path_len(SH_DEVICE_NAME_LEN);
        let named_device = if name != 0 {
            match unicode_string_parts(name) {
                Some(parts) => Some(parts),
                None => return 0xC000_000Du32 as i32, // STATUS_INVALID_PARAMETER
            }
        } else {
            None
        };
        if let Some((name_buf, name_len)) = named_device {
            copy_wstr_to_shared(name_buf, name_len, SH_DEVICE_NAME_LEN, SH_DEVICE_NAME_BUF);
        }
        let flags = DeviceFlags::DEVICE_INITIALIZING.bits()
            | if excl != 0 {
                DeviceFlags::EXCLUSIVE.bits()
            } else {
                0
            }
            | if named_device.is_some() {
                DeviceFlags::DEVICE_HAS_NAME.bits()
            } else {
                0
            };
        let projection = match crate::hosted_driver_projection::create_hosted_device_projection(
            drv, ext_size, dev_type, flags, chars, pool_alloc, pool_free,
        ) {
            Ok(projection) => projection,
            Err(status) => {
                clear_shared_path_len(SH_DEVICE_NAME_LEN);
                return status;
            }
        };
        let dev = projection.device_object();
        let (status, canonical_device_id) = hosted_device_create(dev, drv, ext_size as u64);
        if status < 0 || canonical_device_id == 0 {
            crate::hosted_driver_projection::delete_hosted_device_projection(dev, pool_free);
            clear_shared_path_len(SH_DEVICE_NAME_LEN);
            return if status < 0 {
                status
            } else {
                STATUS_INVALID_DEVICE_REQUEST
            };
        }
        write_unaligned(dev_out as *mut u64, dev);
        let mut v = read_volatile((FSD_SHARED_VADDR + SH_VERDICT) as *const u32) | V_DEVICE;
        if named_device.is_some() {
            v |= V_NAMED_DEVICE;
        }
        write_volatile((FSD_SHARED_VADDR + SH_VERDICT) as *mut u32, v);
        clear_shared_path_len(SH_DEVICE_NAME_LEN);
    }
    0 // STATUS_SUCCESS
}

/// `void IoDeleteDevice(PDEVICE_OBJECT)`.
extern "win64" fn s_io_delete_device(dev: u64) {
    if dev == 0 {
        panic!("IoDeleteDevice received a null DEVICE_OBJECT");
    }
    unsafe {
        let status = hosted_device_delete(dev);
        assert_eq!(status, STATUS_SUCCESS, "hosted IoDeleteDevice failed");
    }
}

/// `NTSTATUS IoAllocateDriverObjectExtension(PDRIVER_OBJECT, PVOID ClientId, ULONG Size, PVOID *Out)`.
extern "win64" fn s_io_allocate_driver_object_extension(
    driver_object: u64,
    client_id: u64,
    size: u32,
    extension_out: u64,
) -> i32 {
    if driver_object == 0 || extension_out == 0 || size == 0 {
        return STATUS_INVALID_PARAMETER;
    }
    unsafe {
        let table = driver_object_extensions_mut();
        if table.iter().any(|slot| {
            slot.used && slot.driver_object == driver_object && slot.client_id == client_id
        }) {
            write_unaligned(extension_out as *mut u64, 0);
            return STATUS_OBJECT_NAME_COLLISION;
        }
        let reusable = table.iter().position(|slot| !slot.used);
        let extension = pool_alloc(size as u64);
        if extension == 0 {
            write_unaligned(extension_out as *mut u64, 0);
            return STATUS_INSUFFICIENT_RESOURCES;
        }
        core::ptr::write_bytes(extension as *mut u8, 0, size as usize);
        let slot = DriverObjectExtensionSlot {
            driver_object,
            client_id,
            extension,
            used: true,
        };
        if let Some(idx) = reusable {
            table[idx] = slot;
        } else {
            table.push(slot);
        }
        write_unaligned(extension_out as *mut u64, extension);
    }
    STATUS_SUCCESS
}

/// `PVOID IoGetDriverObjectExtension(PDRIVER_OBJECT, PVOID ClientId)`.
extern "win64" fn s_io_get_driver_object_extension(driver_object: u64, client_id: u64) -> u64 {
    unsafe {
        let Some(table) = driver_object_extensions() else {
            return 0;
        };
        table
            .iter()
            .find(|slot| {
                slot.used && slot.driver_object == driver_object && slot.client_id == client_id
            })
            .map(|slot| slot.extension)
            .unwrap_or(0)
    }
}

unsafe fn driver_object_extensions_mut() -> &'static mut Vec<DriverObjectExtensionSlot> {
    let slot = &mut *core::ptr::addr_of_mut!(DRIVER_OBJECT_EXTENSIONS);
    if slot.is_none() {
        *slot = Some(Vec::new());
    }
    slot.as_mut().unwrap()
}

unsafe fn driver_object_extensions() -> Option<&'static Vec<DriverObjectExtensionSlot>> {
    (*core::ptr::addr_of!(DRIVER_OBJECT_EXTENSIONS)).as_ref()
}

unsafe fn clear_driver_object_extensions_for_driver_object(driver_object: u64) {
    if driver_object == 0 {
        return;
    }
    let Some(table) = (*core::ptr::addr_of_mut!(DRIVER_OBJECT_EXTENSIONS)).as_mut() else {
        return;
    };
    for slot in table.iter_mut() {
        if slot.used && slot.driver_object == driver_object {
            slot.driver_object = 0;
            slot.client_id = 0;
            slot.extension = 0;
            slot.used = false;
        }
    }
}

unsafe fn driver_registry_handles_mut() -> &'static mut Vec<DriverRegistryHandleSlot> {
    let slot = &mut *core::ptr::addr_of_mut!(DRIVER_REGISTRY_HANDLES);
    if slot.is_none() {
        *slot = Some(Vec::new());
    }
    slot.as_mut().unwrap()
}

unsafe fn hosted_registry_identities_mut() -> &'static mut Vec<HostedRegistryIdentitySlot> {
    let slot = &mut *core::ptr::addr_of_mut!(HOSTED_REGISTRY_IDENTITIES);
    if slot.is_none() {
        *slot = Some(Vec::new());
    }
    slot.as_mut().unwrap()
}

unsafe fn hosted_registry_identities() -> Option<&'static Vec<HostedRegistryIdentitySlot>> {
    (*core::ptr::addr_of!(HOSTED_REGISTRY_IDENTITIES)).as_ref()
}

unsafe fn allocate_hosted_registry_identity(
    identity: HostedDriverRegistryIdentity,
) -> Result<HostedRegistryIdentityId, nt_status::NtStatus> {
    let table = hosted_registry_identities_mut();
    for (idx, slot) in table.iter_mut().enumerate() {
        if !slot.used {
            *slot = HostedRegistryIdentitySlot {
                identity,
                ref_count: 1,
                used: true,
            };
            return Ok(idx);
        }
    }
    let idx = table.len();
    table.push(HostedRegistryIdentitySlot {
        identity,
        ref_count: 1,
        used: true,
    });
    Ok(idx)
}

unsafe fn hosted_registry_identity(
    identity_id: HostedRegistryIdentityId,
) -> Option<HostedDriverRegistryIdentity> {
    if identity_id == INVALID_HOSTED_REGISTRY_IDENTITY_ID {
        return None;
    }
    let table = hosted_registry_identities()?;
    if identity_id < table.len() && table[identity_id].used {
        Some(table[identity_id].identity)
    } else {
        None
    }
}

unsafe fn release_hosted_registry_identity(identity_id: HostedRegistryIdentityId) {
    if identity_id == INVALID_HOSTED_REGISTRY_IDENTITY_ID {
        return;
    }
    let Some(table) = (*core::ptr::addr_of_mut!(HOSTED_REGISTRY_IDENTITIES)).as_mut() else {
        return;
    };
    if identity_id >= table.len() || !table[identity_id].used || table[identity_id].ref_count == 0 {
        return;
    }
    table[identity_id].ref_count -= 1;
    if table[identity_id].ref_count == 0 {
        table[identity_id] = EMPTY_HOSTED_REGISTRY_IDENTITY_SLOT;
    }
}

unsafe fn allocate_cm_registry_handle(path: HostedAscii<HOSTED_REGISTRY_PATH_MAX>) -> Option<u64> {
    if path.is_empty() {
        return None;
    }
    let table = driver_registry_handles_mut();
    for (idx, slot) in table.iter_mut().enumerate() {
        if !slot.used {
            if idx as u64 > DRIVER_REGISTRY_HANDLE_INDEX_MASK {
                return None;
            }
            let handle = DRIVER_REGISTRY_HANDLE_BASE | idx as u64;
            *slot = DriverRegistryHandleSlot {
                handle,
                kind: DriverRegistryHandleKind::CmKey,
                path,
                used: true,
            };
            return Some(handle);
        }
    }
    if table.len() as u64 > DRIVER_REGISTRY_HANDLE_INDEX_MASK {
        return None;
    }
    let idx = table.len();
    let handle = DRIVER_REGISTRY_HANDLE_BASE | idx as u64;
    table.push(DriverRegistryHandleSlot {
        handle,
        kind: DriverRegistryHandleKind::CmKey,
        path,
        used: true,
    });
    Some(handle)
}

unsafe fn close_driver_registry_handle(handle: u64) -> bool {
    if (handle & !DRIVER_REGISTRY_HANDLE_INDEX_MASK) != DRIVER_REGISTRY_HANDLE_BASE {
        return false;
    }
    let idx = (handle & DRIVER_REGISTRY_HANDLE_INDEX_MASK) as usize;
    let Some(table) = (*core::ptr::addr_of_mut!(DRIVER_REGISTRY_HANDLES)).as_mut() else {
        return false;
    };
    if idx >= table.len() || !table[idx].used || table[idx].handle != handle {
        return false;
    }
    table[idx] = EMPTY_DRIVER_REGISTRY_HANDLE_SLOT;
    true
}

unsafe fn driver_registry_handle_slot(handle: u64) -> Option<DriverRegistryHandleSlot> {
    if (handle & !DRIVER_REGISTRY_HANDLE_INDEX_MASK) != DRIVER_REGISTRY_HANDLE_BASE {
        return None;
    }
    let idx = (handle & DRIVER_REGISTRY_HANDLE_INDEX_MASK) as usize;
    let table = (*core::ptr::addr_of!(DRIVER_REGISTRY_HANDLES)).as_ref()?;
    if idx < table.len() && table[idx].used && table[idx].handle == handle {
        Some(table[idx])
    } else {
        None
    }
}

/// `NTSTATUS IoOpenDeviceRegistryKey(PDEVICE_OBJECT, ULONG, ACCESS_MASK, PHANDLE)`.
extern "win64" fn s_io_open_device_registry_key(
    pdo: u64,
    _dev_inst_key_type: u32,
    _desired_access: u32,
    handle_out: u64,
) -> i32 {
    if handle_out == 0 {
        return STATUS_INVALID_PARAMETER;
    }
    unsafe {
        let (status, handle, _) =
            hosted_registry_broker_call(HOSTED_REGISTRY_OP_OPEN_DEVICE_KEY, pdo, 0, 0);
        write_unaligned(
            handle_out as *mut u64,
            if status == STATUS_SUCCESS { handle } else { 0 },
        );
        status
    }
}

pub(crate) const HOSTED_INTERFACE_TYPE_INTERNAL: u32 = 0;
pub(crate) const HOSTED_INTERFACE_TYPE_PCIBUS: u32 = 5;
pub(crate) const HOSTED_INTERFACE_TYPE_PNPBUS: u32 = 15;
const BUS_DATA_TYPE_PCI_CONFIGURATION: u32 = 4;

#[derive(Clone, Copy)]
pub(crate) struct HostedBusIdentity {
    pub interface_type: u32,
    pub bus_number: u32,
    pub address: u32,
    pub pci_vendor_id: u16,
    pub pci_device_id: u16,
    pub pci_class: u32,
    pub pci_config_irq_line: u8,
    pub pci_irq_pin: u8,
}

impl HostedBusIdentity {
    pub(crate) const fn root_bus() -> Self {
        Self {
            interface_type: HOSTED_INTERFACE_TYPE_PNPBUS,
            bus_number: 0,
            address: u32::MAX,
            pci_vendor_id: 0,
            pci_device_id: 0,
            pci_class: 0,
            pci_config_irq_line: 0,
            pci_irq_pin: 0,
        }
    }

    pub(crate) const fn pci(
        bus: u8,
        dev: u8,
        func: u8,
        vendor: u16,
        device: u16,
        class: u32,
        irq_line: u8,
        irq_pin: u8,
    ) -> Self {
        Self {
            interface_type: HOSTED_INTERFACE_TYPE_PCIBUS,
            bus_number: bus as u32,
            address: ((dev as u32) << 16) | func as u32,
            pci_vendor_id: vendor,
            pci_device_id: device,
            pci_class: class,
            pci_config_irq_line: irq_line,
            pci_irq_pin: irq_pin,
        }
    }
}

unsafe fn hosted_resource_identity_active() -> bool {
    read_volatile((FSD_SHARED_VADDR + SH_RESOURCE_PDO_OBJECT) as *const u64) != 0
        || shared_address_resource_count(FSD_SHARED_VADDR).is_some_and(|count| count != 0)
        || read_volatile((FSD_SHARED_VADDR + SH_RESOURCE_INTERRUPT_VECTOR) as *const u32) != 0
        || read_volatile((FSD_SHARED_VADDR + SH_DMA_COMMON_LEN) as *const u64) != 0
}

unsafe fn hosted_pdo_known(pdo: u64) -> bool {
    pdo != 0
        && (hosted_device_binding_by_pdo_object(pdo).is_some()
            || read_volatile((FSD_SHARED_VADDR + SH_REQ_FILEID) as *const u64) == pdo)
}

unsafe fn hosted_registry_identity_by_pdo_object(pdo: u64) -> Option<HostedDriverRegistryIdentity> {
    if let Some(identity_id) = hosted_registry_identity_id_by_pdo_object(pdo) {
        if let Some(identity) = hosted_registry_identity(identity_id) {
            return Some(identity);
        }
    }
    let inflight_pdo = read_volatile((FSD_SHARED_VADDR + SH_REQ_FILEID) as *const u64);
    if inflight_pdo == pdo {
        shared_registry_identity()
    } else {
        None
    }
}

unsafe fn hosted_registry_identity_id_by_pdo_object(pdo: u64) -> Option<HostedRegistryIdentityId> {
    if pdo == 0 {
        return None;
    }
    if let Some(binding) = hosted_device_binding_by_pdo_object(pdo) {
        if hosted_registry_identity(binding.registry_identity_id).is_some() {
            return Some(binding.registry_identity_id);
        }
    }
    let inflight_pdo = read_volatile((FSD_SHARED_VADDR + SH_REQ_FILEID) as *const u64);
    let identity_id = read_volatile(core::ptr::addr_of!(HOSTED_ADD_DEVICE_REGISTRY_IDENTITY_ID));
    if inflight_pdo == pdo && hosted_registry_identity(identity_id).is_some() {
        Some(identity_id)
    } else {
        None
    }
}

unsafe fn hosted_device_object_known(device_object: u64) -> bool {
    device_object != 0
        && (hosted_device_binding_by_device_object(device_object).is_some()
            || read_volatile((FSD_SHARED_VADDR + SH_ACTIVE_DEVICE_OBJECT) as *const u64)
                == device_object)
}

unsafe fn trace_io_get_device_property(
    pdo: u64,
    property: u32,
    buffer_len: u32,
    status: i32,
    value: u32,
) {
    if HOSTED_IO_DEVICE_PROPERTY_TRACE_COUNT.fetch_add(1, Ordering::Relaxed)
        >= HOSTED_IO_DEVICE_PROPERTY_TRACE_CAP
    {
        return;
    }
    print_str(b"[driver-launch] IoGetDeviceProperty pdo=0x");
    print_hex64(pdo);
    print_str(b" prop=");
    print_u64(property as u64);
    print_str(b" len=");
    print_u64(buffer_len as u64);
    print_str(b" status=0x");
    print_hex(status as u32);
    print_str(b" value=0x");
    print_hex(value);
    print_str(b"\n");
}

/// `NTSTATUS IoGetDeviceProperty(PDEVICE_OBJECT, DEVICE_REGISTRY_PROPERTY, ULONG, PVOID, PULONG)`.
extern "win64" fn s_io_get_device_property(
    pdo: u64,
    property: u32,
    buffer_len: u32,
    buffer: u64,
    result_len: u64,
) -> i32 {
    unsafe {
        if result_len == 0 {
            trace_io_get_device_property(pdo, property, buffer_len, STATUS_INVALID_PARAMETER, 0);
            return STATUS_INVALID_PARAMETER;
        }
        write_unaligned(result_len as *mut u32, 0);
        if buffer_len != 0 && buffer == 0 {
            trace_io_get_device_property(pdo, property, buffer_len, STATUS_INVALID_PARAMETER, 0);
            return STATUS_INVALID_PARAMETER;
        }
        let _reply_guard = component_device_reply_lock();
        let (mut status, required_len_wire, token, first_chunk_wire) =
            hosted_device_property_begin(pdo, property, buffer_len);
        let (required_len, first_chunk) = match (
            u32::try_from(required_len_wire),
            u32::try_from(first_chunk_wire),
        ) {
            (Ok(required_len), Ok(first_chunk)) => (required_len, first_chunk),
            _ => {
                hosted_device_property_abort(pdo, token);
                status = STATUS_INVALID_PARAMETER;
                (0, 0)
            }
        };
        write_unaligned(result_len as *mut u32, required_len);
        if status != STATUS_SUCCESS {
            trace_io_get_device_property(pdo, property, buffer_len, status, 0);
            return status;
        }
        if required_len > buffer_len
            || first_chunk > required_len
            || first_chunk as u64 > HOSTED_DEVICE_ARG_DATA_CAP
            || (first_chunk < required_len && token == 0)
            || (first_chunk == required_len && token != 0)
        {
            hosted_device_property_abort(pdo, token);
            status = if required_len > buffer_len {
                STATUS_BUFFER_TOO_SMALL
            } else {
                STATUS_INVALID_PARAMETER
            };
            trace_io_get_device_property(pdo, property, buffer_len, status, 0);
            return status;
        }

        let scratch = if required_len == 0 {
            0
        } else {
            pool_alloc(required_len as u64)
        };
        if required_len != 0 && scratch == 0 {
            hosted_device_property_abort(pdo, token);
            trace_io_get_device_property(
                pdo,
                property,
                buffer_len,
                STATUS_INSUFFICIENT_RESOURCES,
                0,
            );
            return STATUS_INSUFFICIENT_RESOURCES;
        }
        if first_chunk != 0 {
            copy_bytes_unchecked(
                scratch,
                FSD_ARG_VADDR + HOSTED_DEVICE_ARG_DATA_OFF,
                first_chunk as u64,
            );
        }
        let mut offset = first_chunk;
        while offset < required_len {
            let (pull_status, pull_total, pull_token, chunk_wire) =
                hosted_device_property_pull(pdo, token, offset as u64);
            let chunk = u32::try_from(chunk_wire).unwrap_or(0);
            if pull_status != STATUS_SUCCESS
                || pull_total != required_len as u64
                || pull_token != token
                || chunk == 0
                || chunk > required_len - offset
                || chunk as u64 > HOSTED_DEVICE_ARG_DATA_CAP
            {
                hosted_device_property_abort(pdo, token);
                if scratch != 0 {
                    pool_free(scratch);
                }
                status = if pull_status == STATUS_SUCCESS {
                    STATUS_INVALID_PARAMETER
                } else {
                    pull_status
                };
                trace_io_get_device_property(pdo, property, buffer_len, status, 0);
                return status;
            }
            copy_bytes_unchecked(
                scratch + offset as u64,
                FSD_ARG_VADDR + HOSTED_DEVICE_ARG_DATA_OFF,
                chunk as u64,
            );
            offset += chunk;
        }
        if required_len != 0 {
            copy_bytes_unchecked(buffer, scratch, required_len as u64);
            pool_free(scratch);
        }
        let value = if status == STATUS_SUCCESS && required_len == 4 {
            read_unaligned(buffer as *const u32)
        } else {
            0
        };
        trace_io_get_device_property(pdo, property, buffer_len, status, value);
        status
    }
}

/// `void IoInvalidateDeviceRelations(PDEVICE_OBJECT PhysicalDeviceObject,
/// DEVICE_RELATION_TYPE Type)`.
extern "win64" fn s_io_invalidate_device_relations(pdo: u64, relation_type: u32) {
    unsafe {
        hosted_device_invalidate_relations(pdo, relation_type);
    }
}

fn build_hosted_interface_link(
    guid: &HostedAscii<HOSTED_DRIVER_KEY_NAME_MAX>,
    instance_path: &HostedAscii<HOSTED_INSTANCE_PATH_MAX>,
    reference: &HostedAscii<HOSTED_DRIVER_KEY_NAME_MAX>,
) -> Option<HostedAscii<HOSTED_INTERFACE_LINK_MAX>> {
    if guid.is_empty() || instance_path.is_empty() {
        return None;
    }
    let mut out = HostedAscii::<HOSTED_INTERFACE_LINK_MAX>::empty();
    if !out.push_str("\\??\\") {
        return None;
    }
    let mut i = 0usize;
    while i < instance_path.len {
        let b = if instance_path.bytes[i] == b'\\' {
            b'#'
        } else {
            instance_path.bytes[i]
        };
        if !out.push_byte(b) {
            return None;
        }
        i += 1;
    }
    if !out.push_byte(b'#') || !out.push_ascii(guid) {
        return None;
    }
    if !reference.is_empty() && (!out.push_byte(b'\\') || !out.push_ascii(reference)) {
        return None;
    }
    Some(out)
}

fn parse_hosted_interface_reference(
    symbolic_link: &HostedAscii<HOSTED_INTERFACE_LINK_MAX>,
    guid: &HostedAscii<HOSTED_DRIVER_KEY_NAME_MAX>,
    instance_path: &HostedAscii<HOSTED_INSTANCE_PATH_MAX>,
) -> Option<HostedAscii<HOSTED_DRIVER_KEY_NAME_MAX>> {
    let base = build_hosted_interface_link(
        guid,
        instance_path,
        &HostedAscii::<HOSTED_DRIVER_KEY_NAME_MAX>::empty(),
    )?;
    if symbolic_link.len < base.len {
        return None;
    }
    let mut i = 0usize;
    while i < base.len {
        if ascii_upcase_u8(symbolic_link.bytes[i]) != ascii_upcase_u8(base.bytes[i]) {
            return None;
        }
        i += 1;
    }
    if symbolic_link.len == base.len {
        return Some(HostedAscii::empty());
    }
    if symbolic_link.bytes[base.len] != b'\\' {
        return None;
    }
    let mut reference = HostedAscii::<HOSTED_DRIVER_KEY_NAME_MAX>::empty();
    i = base.len + 1;
    while i < symbolic_link.len {
        let byte = symbolic_link.bytes[i];
        if byte == b'\\' || byte == b'/' || !reference.push_byte(byte) {
            return None;
        }
        i += 1;
    }
    (!reference.is_empty()).then_some(reference)
}

unsafe fn hosted_device_interface_registrations_mut(
) -> &'static mut Vec<HostedDeviceInterfaceRegistration> {
    let slot = &mut *core::ptr::addr_of_mut!(HOSTED_DEVICE_INTERFACE_REGISTRATIONS);
    if slot.is_none() {
        *slot = Some(Vec::new());
    }
    slot.as_mut().unwrap()
}

unsafe fn hosted_interface_instance_path(
    owner_domain: HostedDomainIdentity,
    pdo_device_id: u64,
    pdo_object: u64,
    sh: u64,
) -> Option<HostedAscii<HOSTED_INSTANCE_PATH_MAX>> {
    if let Some(binding) = hosted_device_bindings().and_then(|bindings| {
        bindings.iter().copied().find(|binding| {
            binding.used
                && binding.projection_domain == owner_domain
                && binding.pdo_device_id == pdo_device_id
                && binding.pdo_object == pdo_object
        })
    }) {
        return hosted_registry_identity(binding.registry_identity_id)
            .map(|identity| identity.instance_path);
    }
    let inflight_pdo = read_volatile((sh + SH_REQ_FILEID) as *const u64);
    if inflight_pdo == pdo_object {
        shared_registry_identity_at(sh).map(|identity| identity.instance_path)
    } else {
        None
    }
}

unsafe fn register_hosted_device_interface(
    owner_domain: HostedDomainIdentity,
    pdo_device_id: u64,
    class_guid: [u64; 2],
    reference: HostedAscii<HOSTED_DRIVER_KEY_NAME_MAX>,
    symbolic_link: HostedAscii<HOSTED_INTERFACE_LINK_MAX>,
) -> Result<(), nt_status::NtStatus> {
    if owner_domain.domain_id.raw() == 0 || owner_domain.cookie == 0 || pdo_device_id == 0 {
        return Err(nt_status::NtStatus::INVALID_PARAMETER);
    }
    let table = hosted_device_interface_registrations_mut();
    for slot in table.iter_mut() {
        if !slot.used {
            continue;
        }
        let exact_key = slot.owner_domain == owner_domain
            && slot.pdo_device_id == pdo_device_id
            && slot.class_guid == class_guid
            && hosted_ascii_eq_ignore_case(&slot.reference, &reference);
        let exact_link = hosted_ascii_eq_ignore_case(&slot.symbolic_link, &symbolic_link);
        if exact_key || exact_link {
            return if exact_key && exact_link {
                Ok(())
            } else {
                Err(nt_status::NtStatus::OBJECT_NAME_COLLISION)
            };
        }
    }
    for slot in table.iter_mut() {
        if !slot.used {
            *slot = HostedDeviceInterfaceRegistration {
                owner_domain,
                pdo_device_id,
                class_guid,
                reference,
                symbolic_link,
                enabled: false,
                used: true,
            };
            return Ok(());
        }
    }
    table
        .try_reserve(1)
        .map_err(|_| nt_status::NtStatus::INSUFFICIENT_RESOURCES)?;
    table.push(HostedDeviceInterfaceRegistration {
        owner_domain,
        pdo_device_id,
        class_guid,
        reference,
        symbolic_link,
        enabled: false,
        used: true,
    });
    Ok(())
}

/// `NTSTATUS IoRegisterDeviceInterface(...)`.
extern "win64" fn s_io_register_device_interface(
    pdo: u64,
    class_guid: u64,
    reference_string: u64,
    symbolic_link_name: u64,
) -> i32 {
    if symbolic_link_name == 0 || class_guid == 0 {
        return STATUS_INVALID_PARAMETER;
    }
    unsafe {
        write_unaligned(
            (symbolic_link_name + UNICODE_STRING_LENGTH_OFFSET) as *mut u16,
            0,
        );
        write_unaligned(
            (symbolic_link_name + UNICODE_STRING_MAXIMUM_LENGTH_OFFSET) as *mut u16,
            0,
        );
        write_unaligned(
            (symbolic_link_name + UNICODE_STRING_BUFFER_OFFSET) as *mut u64,
            0,
        );

        if !hosted_pdo_known(pdo) {
            return STATUS_INVALID_PARAMETER;
        }
        let Some(identity) = hosted_registry_identity_by_pdo_object(pdo) else {
            return STATUS_OBJECT_NAME_NOT_FOUND;
        };
        let Some(guid) = guid_to_hosted_ascii(class_guid) else {
            return STATUS_INVALID_PARAMETER;
        };
        let reference = if reference_string == 0 {
            HostedAscii::<HOSTED_DRIVER_KEY_NAME_MAX>::empty()
        } else {
            let Some(reference) = unicode_string_to_hosted_ascii::<HOSTED_DRIVER_KEY_NAME_MAX>(
                reference_string,
                true,
            ) else {
                return STATUS_INVALID_PARAMETER;
            };
            reference
        };
        if reference
            .as_bytes()
            .iter()
            .any(|byte| *byte == b'\\' || *byte == b'/')
        {
            return STATUS_INVALID_DEVICE_REQUEST;
        }
        let Some(symbolic_link) =
            build_hosted_interface_link(&guid, &identity.instance_path, &reference)
        else {
            return STATUS_INVALID_PARAMETER;
        };
        let status = write_allocated_unicode_string_from_ascii(symbolic_link_name, &symbolic_link);
        if status < 0 {
            return status;
        }
        let _reply_guard = component_device_reply_lock();
        clear_hosted_device_interface_arg();
        let capture_status = copy_ascii_to_hosted_device_interface_arg(&symbolic_link);
        if capture_status < 0 {
            s_rtl_free_unicode_string(symbolic_link_name);
            return capture_status;
        }
        let broker_status = hosted_device_interface_operation(
            HOSTED_DEVICE_OP_REGISTER_INTERFACE,
            pdo,
            read_unaligned(class_guid as *const u64),
            read_unaligned((class_guid + 8) as *const u64),
        );
        clear_hosted_device_interface_arg();
        if broker_status < 0 {
            s_rtl_free_unicode_string(symbolic_link_name);
        }
        broker_status
    }
}

extern "win64" fn s_io_set_device_interface_state(symbolic_link_name: u64, enable: u8) -> i32 {
    unsafe {
        let _reply_guard = component_device_reply_lock();
        clear_hosted_device_interface_arg();
        let capture_status = copy_unicode_to_hosted_device_interface_arg(symbolic_link_name);
        if capture_status < 0 {
            return capture_status;
        }
        let status = hosted_device_interface_operation(
            HOSTED_DEVICE_OP_SET_INTERFACE_STATE,
            0,
            (enable != 0) as u64,
            0,
        );
        clear_hosted_device_interface_arg();
        status
    }
}

extern "win64" fn s_io_register_shutdown_notification(device: u64) -> i32 {
    unsafe {
        if hosted_device_object_known(device) {
            STATUS_SUCCESS
        } else {
            STATUS_INVALID_PARAMETER
        }
    }
}

extern "win64" fn s_io_unregister_shutdown_notification(_device: u64) {}

fn nt_path_ascii_string(path: &NtPath) -> Option<String> {
    let mut out = String::new();
    for unit in path.to_units() {
        if !(0x20..=0x7e).contains(&unit) {
            return None;
        }
        out.push(char::from_u32(unit as u32)?);
    }
    Some(out)
}

/// `PDEVICE_OBJECT IoAttachDeviceToDeviceStack(PDEVICE_OBJECT SourceDevice, PDEVICE_OBJECT TargetDevice)`.
extern "win64" fn s_io_attach_device_to_device_stack(source: u64, target: u64) -> u64 {
    unsafe {
        let lower = match crate::hosted_driver_projection::attach_hosted_device_projection(
            source, target,
        ) {
            Some(lower) => lower,
            None => return 0,
        };
        if hosted_device_attach(source, target, lower) != STATUS_SUCCESS {
            crate::hosted_driver_projection::detach_hosted_device_projection(lower);
            return 0;
        }
        lower
    }
}

/// `void IoDetachDevice(PDEVICE_OBJECT TargetDevice)`.
extern "win64" fn s_io_detach_device(lower: u64) {
    if lower == 0 {
        return;
    }
    unsafe {
        let upper = crate::hosted_driver_projection::hosted_attached_device(lower);
        if upper == 0 {
            panic!("IoDetachDevice target has no upper attachment");
        }
        let status = hosted_device_detach(lower, upper);
        assert_eq!(status, STATUS_SUCCESS, "hosted IoDetachDevice failed");
        crate::hosted_driver_projection::detach_hosted_device_projection(lower);
    }
}

unsafe fn irp_current_stack_location(irp: u64) -> u64 {
    if irp == 0 {
        0
    } else {
        read_unaligned((irp + 0xb8) as *const u64)
    }
}

unsafe fn irp_next_stack_location(irp: u64) -> u64 {
    irp_current_stack_location(irp).saturating_sub(WDM_X64_IO_STACK_LOCATION_SIZE as u64)
}

const WDM_X64_IRP_CURRENT_LOCATION_OFFSET: u64 = 0x43;
const WDM_X64_IRP_STACK_COUNT_OFFSET: u64 = 0x42;
const WDM_X64_IRP_IO_STATUS_STATUS_OFFSET: u64 = 0x30;
const WDM_X64_IRP_IO_STATUS_INFORMATION_OFFSET: u64 = 0x38;
const WDM_X64_IRP_PENDING_RETURNED_OFFSET: u64 = 0x41;
const WDM_X64_IRP_CANCEL_OFFSET: u64 = 0x44;
const WDM_X64_IRP_CANCEL_IRQL_OFFSET: u64 = 0x45;
const WDM_X64_IRP_CANCEL_ROUTINE_OFFSET: u64 = 0x68;
const WDM_X64_IRP_DRIVER_CONTEXT3_OFFSET: u64 = 0x90;
const WDM_X64_IO_STACK_MINOR_OFFSET: u64 = 0x01;
const WDM_X64_IO_STACK_CONTROL_OFFSET: u64 = 0x03;
const WDM_X64_IO_STACK_DEVICE_OBJECT_OFFSET: u64 = 0x28;
const WDM_X64_IO_STACK_COMPLETION_ROUTINE_OFFSET: u64 = 0x38;
const WDM_X64_IO_STACK_CONTEXT_OFFSET: u64 = 0x40;
const WDM_X64_IO_STACK_COPY_TO_NEXT_BYTES: u64 = WDM_X64_IO_STACK_COMPLETION_ROUTINE_OFFSET;
const WDM_X64_SL_PENDING_RETURNED: u8 = 0x01;
const WDM_X64_SL_ERROR_RETURNED: u8 = 0x02;

const WDM_X64_IO_TYPE_IRP: u16 = 6;
const IO_TYPE_CSQ_IRP_CONTEXT: u32 = 1;
const IO_TYPE_CSQ: u32 = 2;
const IO_CSQ_SIZE: u64 = 64;
const IO_CSQ_INSERT_IRP_OFFSET: u64 = 0x08;
const IO_CSQ_REMOVE_IRP_OFFSET: u64 = 0x10;
const IO_CSQ_PEEK_NEXT_IRP_OFFSET: u64 = 0x18;
const IO_CSQ_ACQUIRE_LOCK_OFFSET: u64 = 0x20;
const IO_CSQ_RELEASE_LOCK_OFFSET: u64 = 0x28;
const IO_CSQ_COMPLETE_CANCELED_IRP_OFFSET: u64 = 0x30;
const IO_CSQ_RESERVE_POINTER_OFFSET: u64 = 0x38;
const IO_CSQ_IRP_CONTEXT_TYPE_OFFSET: u64 = 0x00;
const IO_CSQ_IRP_CONTEXT_IRP_OFFSET: u64 = 0x08;
const IO_CSQ_IRP_CONTEXT_CSQ_OFFSET: u64 = 0x10;

/// `PIO_STACK_LOCATION IoGetCurrentIrpStackLocation(PIRP)`.
extern "win64" fn s_io_get_current_irp_stack_location(irp: u64) -> u64 {
    unsafe { irp_current_stack_location(irp) }
}

/// `PIO_STACK_LOCATION IoGetNextIrpStackLocation(PIRP)`.
extern "win64" fn s_io_get_next_irp_stack_location(irp: u64) -> u64 {
    unsafe { irp_next_stack_location(irp) }
}

/// `void IoCopyCurrentIrpStackLocationToNext(PIRP)`.
extern "win64" fn s_io_copy_current_irp_stack_location_to_next(irp: u64) {
    unsafe {
        let current = irp_current_stack_location(irp);
        let next = irp_next_stack_location(irp);
        if current == 0 || next == 0 {
            return;
        }
        let mut off = 0u64;
        while off < WDM_X64_IO_STACK_COPY_TO_NEXT_BYTES {
            let byte = read_unaligned((current + off) as *const u8);
            write_unaligned((next + off) as *mut u8, byte);
            off += 1;
        }
        write_unaligned((next + WDM_X64_IO_STACK_CONTROL_OFFSET) as *mut u8, 0);
    }
}

/// `void IoSkipCurrentIrpStackLocation(PIRP)`.
extern "win64" fn s_io_skip_current_irp_stack_location(irp: u64) {
    unsafe {
        if irp == 0 {
            return;
        }
        let current_location =
            read_unaligned((irp + WDM_X64_IRP_CURRENT_LOCATION_OFFSET) as *const u8);
        write_unaligned(
            (irp + WDM_X64_IRP_CURRENT_LOCATION_OFFSET) as *mut u8,
            current_location.wrapping_add(1),
        );
        let current_stack = irp_current_stack_location(irp);
        if current_stack != 0 {
            write_unaligned(
                (irp + 0xb8) as *mut u64,
                current_stack + WDM_X64_IO_STACK_LOCATION_SIZE as u64,
            );
        }
    }
}

/// `PDRIVER_CANCEL IoSetCancelRoutine(PIRP, PDRIVER_CANCEL)`.
extern "win64" fn s_io_set_cancel_routine(irp: u64, cancel_routine: u64) -> u64 {
    if irp == 0 {
        return 0;
    }
    unsafe {
        (&*((irp + WDM_X64_IRP_CANCEL_ROUTINE_OFFSET) as *const AtomicU64))
            .swap(cancel_routine, Ordering::AcqRel)
    }
}

/// `PIRP IoAllocateIrp(CCHAR StackSize, BOOLEAN ChargeQuota)`.
extern "win64" fn s_io_allocate_irp(stack_size: u8, _charge_quota: u8) -> u64 {
    let stack_count = stack_size as u64;
    if stack_count == 0 || stack_count > 32 {
        return 0;
    }
    let total = WDM_X64_IRP_SIZE as u64 + stack_count * WDM_X64_IO_STACK_LOCATION_SIZE as u64;
    unsafe {
        let irp = pool_alloc(total);
        if irp == 0 {
            return 0;
        }
        core::ptr::write_bytes(irp as *mut u8, 0, total as usize);
        let stack_base = irp + WDM_X64_IRP_SIZE as u64;
        write_unaligned(irp as *mut u16, WDM_X64_IO_TYPE_IRP);
        write_unaligned((irp + 2) as *mut u16, total as u16);
        write_unaligned(
            (irp + WDM_X64_IRP_STACK_COUNT_OFFSET) as *mut u8,
            stack_size,
        );
        write_unaligned(
            (irp + WDM_X64_IRP_CURRENT_LOCATION_OFFSET) as *mut u8,
            stack_size.saturating_add(1),
        );
        write_unaligned(
            (irp + 0xb8) as *mut u64,
            stack_base + stack_count * WDM_X64_IO_STACK_LOCATION_SIZE as u64,
        );
        irp
    }
}

/// `VOID IoFreeIrp(PIRP)`.
extern "win64" fn s_io_free_irp(irp: u64) {
    unsafe {
        pool_free(irp);
    }
}

/// `PIRP IoBuildDeviceIoControlRequest(...)`.
extern "win64" fn s_io_build_device_io_control_request(
    io_control_code: u32,
    device_object: u64,
    input_buffer: u64,
    input_buffer_length: u32,
    output_buffer: u64,
    output_buffer_length: u32,
    internal_device_io_control: u8,
    event: u64,
    io_status_block: u64,
) -> u64 {
    if device_object == 0 {
        return 0;
    }
    let stack_size = unsafe {
        component_pool_allocation_capacity(device_object)
            .filter(|capacity| *capacity >= 0x50)
            .map(|_| read_unaligned((device_object + 0x4c) as *const u8).max(1))
            .unwrap_or(1)
    };
    let irp = s_io_allocate_irp(stack_size, 0);
    if irp == 0 {
        return 0;
    }
    unsafe {
        let method = io_control_code & 3;
        let mut system_buffer = 0u64;
        let mut user_buffer = 0u64;
        let mut mdl = 0u64;
        let mut flags = 0u32;
        let type3_input_buffer;
        match method {
            ioctl::METHOD_BUFFERED => {
                let length = input_buffer_length.max(output_buffer_length) as u64;
                if length != 0 {
                    system_buffer = pool_alloc_zeroed(length);
                    if system_buffer == 0 {
                        pool_free(irp);
                        return 0;
                    }
                    if input_buffer != 0 && input_buffer_length != 0 {
                        core::ptr::copy_nonoverlapping(
                            input_buffer as *const u8,
                            system_buffer as *mut u8,
                            input_buffer_length as usize,
                        );
                    }
                    flags = IRP_BUFFERED_IO | IRP_DEALLOCATE_BUFFER;
                    if output_buffer != 0 {
                        flags |= IRP_INPUT_OPERATION;
                    }
                    user_buffer = output_buffer;
                }
                type3_input_buffer = 0;
            }
            ioctl::METHOD_IN_DIRECT | ioctl::METHOD_OUT_DIRECT => {
                if input_buffer != 0 && input_buffer_length != 0 {
                    system_buffer = pool_alloc(input_buffer_length as u64);
                    if system_buffer == 0 {
                        pool_free(irp);
                        return 0;
                    }
                    core::ptr::copy_nonoverlapping(
                        input_buffer as *const u8,
                        system_buffer as *mut u8,
                        input_buffer_length as usize,
                    );
                    flags = IRP_BUFFERED_IO | IRP_DEALLOCATE_BUFFER;
                }
                if output_buffer != 0 && output_buffer_length != 0 {
                    mdl = s_io_allocate_mdl(output_buffer, output_buffer_length, 0, 0, irp);
                    if mdl == 0 {
                        if system_buffer != 0 {
                            pool_free(system_buffer);
                        }
                        pool_free(irp);
                        return 0;
                    }
                }
                type3_input_buffer = 0;
            }
            ioctl::METHOD_NEITHER => {
                user_buffer = output_buffer;
                type3_input_buffer = input_buffer;
            }
            _ => unreachable!(),
        }

        let stack = irp_next_stack_location(irp);
        if stack == 0 {
            if mdl != 0 {
                s_io_free_mdl(mdl);
            }
            if system_buffer != 0 {
                pool_free(system_buffer);
            }
            pool_free(irp);
            return 0;
        }
        let major = if internal_device_io_control != 0 {
            major::IRP_MJ_INTERNAL_DEVICE_CONTROL
        } else {
            major::IRP_MJ_DEVICE_CONTROL
        };
        let stack_bytes =
            core::slice::from_raw_parts_mut(stack as *mut u8, WDM_X64_IO_STACK_LOCATION_SIZE);
        if write_wdm_io_stack_location(
            stack_bytes,
            WdmIoStackLocationInit {
                major,
                minor: 0,
                flags: 0,
                control: 0,
                device_object,
                file_object: 0,
                parameters: WdmIoStackParameters::DeviceControl {
                    output_buffer_length,
                    input_buffer_length,
                    io_control_code,
                    type3_input_buffer,
                },
            },
        )
        .is_err()
        {
            if mdl != 0 {
                s_io_free_mdl(mdl);
            }
            if system_buffer != 0 {
                pool_free(system_buffer);
            }
            pool_free(irp);
            return 0;
        }
        write_unaligned((irp + 0x08) as *mut u64, mdl);
        write_unaligned((irp + 0x10) as *mut u32, flags);
        write_unaligned((irp + 0x18) as *mut u64, system_buffer);
        write_unaligned((irp + 0x48) as *mut u64, io_status_block);
        write_unaligned((irp + 0x50) as *mut u64, event);
        write_unaligned((irp + 0x70) as *mut u64, user_buffer);
        write_unaligned((irp + 0xa8) as *mut u64, s_current_process());
    }
    irp
}

/// `BOOLEAN IoCancelIrp(PIRP)`.
extern "win64" fn s_io_cancel_irp(irp: u64) -> u8 {
    if irp == 0 {
        return 0;
    }
    unsafe {
        let old = hosted_raise_irql(DISPATCH_LEVEL);
        while IO_CANCEL_SPIN_LOCK
            .compare_exchange_weak(0, 1, Ordering::Acquire, Ordering::Relaxed)
            .is_err()
        {
            core::hint::spin_loop();
        }
        write_unaligned((irp + WDM_X64_IRP_CANCEL_OFFSET) as *mut u8, 1);
        write_unaligned((irp + WDM_X64_IRP_CANCEL_IRQL_OFFSET) as *mut u8, old);
        let routine = (&*((irp + WDM_X64_IRP_CANCEL_ROUTINE_OFFSET) as *const AtomicU64))
            .swap(0, Ordering::AcqRel);
        if routine != 0 {
            let stack = irp_current_stack_location(irp);
            let device = if stack != 0 {
                read_unaligned((stack + WDM_X64_IO_STACK_DEVICE_OBJECT_OFFSET) as *const u64)
            } else {
                0
            };
            let f: extern "win64" fn(u64, u64) = core::mem::transmute(routine as *const ());
            f(device, irp);
            return 1;
        }
        IO_CANCEL_SPIN_LOCK.store(0, Ordering::Release);
        hosted_lower_irql(old);
    }
    0
}

/// `PIO_WORKITEM IoAllocateWorkItem(PDEVICE_OBJECT)`.
extern "win64" fn s_io_allocate_work_item(device_object: u64) -> u64 {
    unsafe {
        let work_item = pool_alloc(0x40);
        if work_item == 0 {
            return 0;
        }
        core::ptr::write_bytes(work_item as *mut u8, 0, 0x40);
        write_unaligned((work_item + 0x20) as *mut u64, device_object);
        work_item
    }
}

#[inline]
unsafe fn hosted_work_queue_slot(shared_va: u64, index: u64) -> u64 {
    shared_va + SH_WORK_QUEUE_ENTRIES + (index % SH_WORK_QUEUE_CAPACITY) * SH_WORK_QUEUE_ENTRY_SIZE
}

unsafe fn enqueue_hosted_work_item(
    kind: u64,
    work_item: u64,
    routine: u64,
    arg0: u64,
    arg1: u64,
) -> bool {
    if routine == 0 {
        return false;
    }
    let head = read_volatile((FSD_SHARED_VADDR + SH_WORK_QUEUE_HEAD) as *const u64);
    let tail = read_volatile((FSD_SHARED_VADDR + SH_WORK_QUEUE_TAIL) as *const u64);
    if tail.wrapping_sub(head) >= SH_WORK_QUEUE_CAPACITY {
        let drops = read_volatile((FSD_SHARED_VADDR + SH_WORK_QUEUE_DROPS) as *const u64);
        write_volatile(
            (FSD_SHARED_VADDR + SH_WORK_QUEUE_DROPS) as *mut u64,
            drops.saturating_add(1),
        );
        return false;
    }
    let slot = hosted_work_queue_slot(FSD_SHARED_VADDR, tail);
    write_volatile((slot + SH_WORK_QUEUE_ENTRY_KIND) as *mut u64, kind);
    write_volatile(
        (slot + SH_WORK_QUEUE_ENTRY_WORK_ITEM) as *mut u64,
        work_item,
    );
    write_volatile((slot + SH_WORK_QUEUE_ENTRY_ROUTINE) as *mut u64, routine);
    write_volatile((slot + SH_WORK_QUEUE_ENTRY_ARG0) as *mut u64, arg0);
    write_volatile((slot + SH_WORK_QUEUE_ENTRY_ARG1) as *mut u64, arg1);
    write_volatile(
        (FSD_SHARED_VADDR + SH_WORK_QUEUE_TAIL) as *mut u64,
        tail.wrapping_add(1),
    );
    true
}

/// `VOID IoQueueWorkItem(PIO_WORKITEM, PIO_WORKITEM_ROUTINE, WORK_QUEUE_TYPE, PVOID)`.
extern "win64" fn s_io_queue_work_item(
    work_item: u64,
    worker_routine: u64,
    _queue_type: u32,
    context: u64,
) {
    if work_item == 0 || worker_routine == 0 {
        return;
    }
    unsafe {
        let device_object = read_unaligned((work_item + 0x20) as *const u64);
        write_unaligned((work_item + 0x28) as *mut u64, worker_routine);
        write_unaligned((work_item + 0x30) as *mut u64, context);
        let _ = enqueue_hosted_work_item(
            HOSTED_WORK_QUEUE_KIND_IO,
            work_item,
            worker_routine,
            device_object,
            context,
        );
    }
}

/// `VOID IoFreeWorkItem(PIO_WORKITEM)`.
extern "win64" fn s_io_free_work_item(work_item: u64) {
    unsafe {
        pool_free(work_item);
    }
}

/// `VOID IoAcquireCancelSpinLock(PKIRQL)`.
extern "win64" fn s_io_acquire_cancel_spin_lock(old_irql_out: u64) {
    unsafe {
        let old = hosted_raise_irql(DISPATCH_LEVEL);
        while IO_CANCEL_SPIN_LOCK
            .compare_exchange_weak(0, 1, Ordering::Acquire, Ordering::Relaxed)
            .is_err()
        {
            core::hint::spin_loop();
        }
        if old_irql_out != 0 {
            write_unaligned(old_irql_out as *mut u8, old);
        }
    }
}

/// `VOID IoReleaseCancelSpinLock(KIRQL)`.
extern "win64" fn s_io_release_cancel_spin_lock(old_irql: u8) {
    unsafe {
        IO_CANCEL_SPIN_LOCK.store(0, Ordering::Release);
        hosted_lower_irql(old_irql);
    }
}

/// `PDEVICE_OBJECT IoGetRelatedDeviceObject(PFILE_OBJECT)`.
extern "win64" fn s_io_get_related_device_object(file_object: u64) -> u64 {
    if file_object == 0 {
        return 0;
    }
    unsafe { read_unaligned((file_object + 0x08) as *const u64) }
}

unsafe fn csq_acquire(csq: u64) -> u8 {
    let acquire = read_unaligned((csq + IO_CSQ_ACQUIRE_LOCK_OFFSET) as *const u64);
    let mut irql = 0u8;
    if acquire != 0 {
        let f: extern "win64" fn(u64, u64) = core::mem::transmute(acquire as *const ());
        f(csq, (&mut irql as *mut u8) as u64);
    }
    irql
}

unsafe fn csq_release(csq: u64, irql: u8) {
    let release = read_unaligned((csq + IO_CSQ_RELEASE_LOCK_OFFSET) as *const u64);
    if release != 0 {
        let f: extern "win64" fn(u64, u8) = core::mem::transmute(release as *const ());
        f(csq, irql);
    }
}

unsafe fn csq_clear_irp_context(irp: u64) {
    if irp == 0 {
        return;
    }
    let context = read_unaligned((irp + WDM_X64_IRP_DRIVER_CONTEXT3_OFFSET) as *const u64);
    if context != 0
        && read_unaligned((context + IO_CSQ_IRP_CONTEXT_TYPE_OFFSET) as *const u32)
            == IO_TYPE_CSQ_IRP_CONTEXT
    {
        write_unaligned((context + IO_CSQ_IRP_CONTEXT_IRP_OFFSET) as *mut u64, 0);
    }
    write_unaligned((irp + WDM_X64_IRP_DRIVER_CONTEXT3_OFFSET) as *mut u64, 0);
}

/// `NTSTATUS IoCsqInitialize(PIO_CSQ, callbacks...)`.
extern "win64" fn s_io_csq_initialize(
    csq: u64,
    insert: u64,
    remove: u64,
    peek: u64,
    acquire: u64,
    release: u64,
    complete_canceled: u64,
) -> i32 {
    if csq == 0 || insert == 0 || remove == 0 || peek == 0 || acquire == 0 || release == 0 {
        return STATUS_INVALID_PARAMETER;
    }
    unsafe {
        core::ptr::write_bytes(csq as *mut u8, 0, IO_CSQ_SIZE as usize);
        write_unaligned(csq as *mut u32, IO_TYPE_CSQ);
        write_unaligned((csq + IO_CSQ_INSERT_IRP_OFFSET) as *mut u64, insert);
        write_unaligned((csq + IO_CSQ_REMOVE_IRP_OFFSET) as *mut u64, remove);
        write_unaligned((csq + IO_CSQ_PEEK_NEXT_IRP_OFFSET) as *mut u64, peek);
        write_unaligned((csq + IO_CSQ_ACQUIRE_LOCK_OFFSET) as *mut u64, acquire);
        write_unaligned((csq + IO_CSQ_RELEASE_LOCK_OFFSET) as *mut u64, release);
        write_unaligned(
            (csq + IO_CSQ_COMPLETE_CANCELED_IRP_OFFSET) as *mut u64,
            complete_canceled,
        );
        write_unaligned((csq + IO_CSQ_RESERVE_POINTER_OFFSET) as *mut u64, 0);
    }
    STATUS_SUCCESS
}

/// `VOID IoCsqInsertIrp(PIO_CSQ, PIRP, PIO_CSQ_IRP_CONTEXT)`.
extern "win64" fn s_io_csq_insert_irp(csq: u64, irp: u64, context: u64) {
    if csq == 0 || irp == 0 {
        return;
    }
    unsafe {
        if context != 0 {
            write_unaligned(
                (context + IO_CSQ_IRP_CONTEXT_TYPE_OFFSET) as *mut u32,
                IO_TYPE_CSQ_IRP_CONTEXT,
            );
            write_unaligned((context + IO_CSQ_IRP_CONTEXT_IRP_OFFSET) as *mut u64, irp);
            write_unaligned((context + IO_CSQ_IRP_CONTEXT_CSQ_OFFSET) as *mut u64, csq);
            write_unaligned(
                (irp + WDM_X64_IRP_DRIVER_CONTEXT3_OFFSET) as *mut u64,
                context,
            );
        } else {
            write_unaligned((irp + WDM_X64_IRP_DRIVER_CONTEXT3_OFFSET) as *mut u64, csq);
        }
        write_unaligned((irp + WDM_X64_IRP_PENDING_RETURNED_OFFSET) as *mut u8, 1);
        let insert = read_unaligned((csq + IO_CSQ_INSERT_IRP_OFFSET) as *const u64);
        if insert == 0 {
            return;
        }
        let irql = csq_acquire(csq);
        let f: extern "win64" fn(u64, u64) = core::mem::transmute(insert as *const ());
        f(csq, irp);
        csq_release(csq, irql);
    }
}

/// `PIRP IoCsqRemoveIrp(PIO_CSQ, PIO_CSQ_IRP_CONTEXT)`.
extern "win64" fn s_io_csq_remove_irp(csq: u64, context: u64) -> u64 {
    if csq == 0 || context == 0 {
        return 0;
    }
    unsafe {
        let irp = read_unaligned((context + IO_CSQ_IRP_CONTEXT_IRP_OFFSET) as *const u64);
        if irp == 0 {
            return 0;
        }
        let remove = read_unaligned((csq + IO_CSQ_REMOVE_IRP_OFFSET) as *const u64);
        if remove == 0 {
            return 0;
        }
        let irql = csq_acquire(csq);
        let f: extern "win64" fn(u64, u64) = core::mem::transmute(remove as *const ());
        f(csq, irp);
        csq_clear_irp_context(irp);
        csq_release(csq, irql);
        irp
    }
}

/// `PIRP IoCsqRemoveNextIrp(PIO_CSQ, PVOID PeekContext)`.
extern "win64" fn s_io_csq_remove_next_irp(csq: u64, peek_context: u64) -> u64 {
    if csq == 0 {
        return 0;
    }
    unsafe {
        let peek = read_unaligned((csq + IO_CSQ_PEEK_NEXT_IRP_OFFSET) as *const u64);
        let remove = read_unaligned((csq + IO_CSQ_REMOVE_IRP_OFFSET) as *const u64);
        if peek == 0 || remove == 0 {
            return 0;
        }
        let irql = csq_acquire(csq);
        let peek_fn: extern "win64" fn(u64, u64, u64) -> u64 =
            core::mem::transmute(peek as *const ());
        let irp = peek_fn(csq, 0, peek_context);
        if irp != 0 {
            let remove_fn: extern "win64" fn(u64, u64) = core::mem::transmute(remove as *const ());
            remove_fn(csq, irp);
            csq_clear_irp_context(irp);
        }
        csq_release(csq, irql);
        irp
    }
}

/// `NTSTATUS IofCallDriver(PDEVICE_OBJECT, PIRP)`.
extern "win64" fn s_iof_call_driver(device: u64, irp: u64) -> i32 {
    unsafe {
        let Some((_, previous_location, _)) = validate_hosted_irp_packet(irp) else {
            return 0xC000_0010u32 as i32; // STATUS_INVALID_DEVICE_REQUEST
        };
        if previous_location <= 1 || device == 0 {
            return 0xC000_0010u32 as i32;
        }
        let current_location_after_forward = previous_location - 1;
        let next = irp_next_stack_location(irp);
        write_unaligned(
            (irp + WDM_X64_IRP_CURRENT_LOCATION_OFFSET) as *mut u8,
            current_location_after_forward,
        );
        write_unaligned((irp + 0xb8) as *mut u64, next);
        write_unaligned(
            (next + WDM_X64_IO_STACK_DEVICE_OBJECT_OFFSET) as *mut u64,
            device,
        );
        let forwarded_minor =
            read_unaligned((next + WDM_X64_IO_STACK_MINOR_OFFSET) as *const u8) as u64;
        let major = read_unaligned(next as *const u8) as u64;

        let driver_object = component_pool_allocation_capacity(device)
            .filter(|capacity| *capacity >= 0x50)
            .map(|_| read_unaligned((device + 0x08) as *const u64))
            .unwrap_or(0);
        if driver_object != 0 {
            if !major::is_valid_major(major as u8)
                || component_pool_allocation_capacity(driver_object)
                    .is_none_or(|capacity| capacity < WDM_X64_DRIVER_OBJECT_SIZE as u64)
            {
                return 0xC000_0010u32 as i32;
            }
            let handler = read_unaligned(
                (driver_object + WDM_X64_DRIVER_MAJOR_FUNCTION_OFFSET as u64 + major * 8)
                    as *const u64,
            );
            if handler == 0 {
                return 0xC000_0010u32 as i32;
            }
            trace_wdm_forward_call(
                device,
                irp,
                previous_location,
                current_location_after_forward,
                next,
                forwarded_minor,
                STATUS_PENDING as i32,
            );
            let dispatch: extern "win64" fn(u64, u64) -> i32 =
                core::mem::transmute(handler as *const ());
            return dispatch(device, irp);
        }

        let status = if major == IRP_MJ_PNP {
            let (_, result, _, _, _) = call_on4(
                (FSD_SERVICE_ROOT_PDO_PNP_LABEL << 12) | 2,
                device,
                forwarded_minor,
                0,
                0,
            );
            result as u32 as i32
        } else {
            nt_status::NtStatus::INVALID_DEVICE_REQUEST.raw()
        };
        trace_wdm_forward_call(
            device,
            irp,
            previous_location,
            current_location_after_forward,
            next,
            forwarded_minor,
            status,
        );
        write_unaligned(
            (irp + WDM_X64_IRP_IO_STATUS_STATUS_OFFSET) as *mut i32,
            status,
        );
        write_unaligned(
            (irp + WDM_X64_IRP_IO_STATUS_INFORMATION_OFFSET) as *mut u64,
            0,
        );
        s_io_complete_request(irp, 0);
        status
    }
}

unsafe fn trace_wdm_forward_call(
    device: u64,
    irp: u64,
    previous_location: u8,
    current_location: u8,
    stack: u64,
    minor: u64,
    status: i32,
) {
    if WDM_FORWARD_CALL_TRACE_COUNT.fetch_add(1, Ordering::Relaxed) >= WDM_FORWARD_TRACE_CAP {
        return;
    }
    let completion = if stack == 0 {
        0
    } else {
        read_unaligned((stack + WDM_X64_IO_STACK_COMPLETION_ROUTINE_OFFSET) as *const u64)
    };
    let context = if stack == 0 {
        0
    } else {
        read_unaligned((stack + WDM_X64_IO_STACK_CONTEXT_OFFSET) as *const u64)
    };
    let control = if stack == 0 {
        0
    } else {
        read_unaligned((stack + WDM_X64_IO_STACK_CONTROL_OFFSET) as *const u8)
    };
    print_str(b"[wdm-forward] dev=");
    print_hex64(device);
    print_str(b" irp=");
    print_hex64(irp);
    print_str(b" loc=");
    print_u64(previous_location as u64);
    print_str(b"->");
    print_u64(current_location as u64);
    print_str(b" stack=");
    print_hex64(stack);
    print_str(b" minor=");
    print_u64(minor);
    print_str(b" status=0x");
    print_hex(status as u32);
    print_str(b" completion=");
    print_hex64(completion);
    print_str(b" control=0x");
    print_hex(control as u32);
    print_str(b" context=");
    print_hex64(context);
    print_str(b"\n");
}

#[derive(Copy, Clone, Eq, PartialEq)]
enum HostedIrpUnwindOutcome {
    Terminal,
    MoreProcessingRequired,
}

unsafe fn validate_hosted_irp_packet(irp: u64) -> Option<(u8, u8, u64)> {
    let capacity = component_pool_allocation_capacity(irp)?;
    if capacity < WDM_X64_IRP_SIZE as u64
        || read_unaligned(irp as *const u16) != WDM_X64_IO_TYPE_IRP
    {
        return None;
    }
    let packet_size = read_unaligned((irp + 2) as *const u16) as u64;
    let stack_count = read_unaligned((irp + WDM_X64_IRP_STACK_COUNT_OFFSET) as *const u8);
    let current_location = read_unaligned((irp + WDM_X64_IRP_CURRENT_LOCATION_OFFSET) as *const u8);
    let required = (WDM_X64_IRP_SIZE as u64)
        .checked_add((stack_count as u64).checked_mul(WDM_X64_IO_STACK_LOCATION_SIZE as u64)?)?;
    let terminal_location = stack_count.checked_add(1)?;
    if stack_count == 0
        || current_location == 0
        || current_location > terminal_location
        || packet_size < required
        || packet_size > capacity
    {
        return None;
    }
    let expected_stack = (irp + WDM_X64_IRP_SIZE as u64).checked_add(
        (current_location as u64 - 1).checked_mul(WDM_X64_IO_STACK_LOCATION_SIZE as u64)?,
    )?;
    (irp_current_stack_location(irp) == expected_stack).then_some((
        stack_count,
        current_location,
        expected_stack,
    ))
}

unsafe fn clear_completed_stack_location(stack: u64) {
    write_unaligned((stack + 0x01) as *mut u8, 0);
    write_unaligned((stack + 0x02) as *mut u8, 0);
    let control = read_unaligned((stack + WDM_X64_IO_STACK_CONTROL_OFFSET) as *const u8);
    write_unaligned(
        (stack + WDM_X64_IO_STACK_CONTROL_OFFSET) as *mut u8,
        control & WDM_X64_SL_ERROR_RETURNED,
    );
    write_unaligned((stack + 0x08) as *mut u64, 0);
    write_unaligned((stack + 0x10) as *mut u64, 0);
    write_unaligned((stack + 0x18) as *mut u64, 0);
    write_unaligned((stack + 0x30) as *mut u64, 0);
}

/// Run the native bottom-to-top completion walk. The raw cursor is advanced before every callback,
/// and no IRP field is touched after a routine returns `STATUS_MORE_PROCESSING_REQUIRED`.
unsafe fn unwind_hosted_irp(irp: u64) -> Result<HostedIrpUnwindOutcome, ()> {
    let (stack_count, current_location, mut stack) = validate_hosted_irp_packet(irp).ok_or(())?;
    let mut cursor = nt_io_manager::CompletionUnwindCursor::new(stack_count, current_location)
        .map_err(|_| ())?;
    let last_stack = irp + WDM_X64_IRP_SIZE as u64;
    let mut error_code =
        if read_unaligned((last_stack + WDM_X64_IO_STACK_CONTROL_OFFSET) as *const u8)
            & WDM_X64_SL_ERROR_RETURNED
            != 0
        {
            read_unaligned((last_stack + 0x20) as *const i32)
        } else {
            STATUS_SUCCESS
        };

    while !cursor.is_terminal() {
        let status = read_unaligned((irp + WDM_X64_IRP_IO_STATUS_STATUS_OFFSET) as *const i32);
        if status < 0 && status != error_code {
            error_code = status;
            let current_control =
                read_unaligned((stack + WDM_X64_IO_STACK_CONTROL_OFFSET) as *const u8);
            write_unaligned(
                (stack + WDM_X64_IO_STACK_CONTROL_OFFSET) as *mut u8,
                current_control | WDM_X64_SL_ERROR_RETURNED,
            );
            write_unaligned((last_stack + 0x20) as *mut i32, error_code);
            let last_control =
                read_unaligned((last_stack + WDM_X64_IO_STACK_CONTROL_OFFSET) as *const u8);
            write_unaligned(
                (last_stack + WDM_X64_IO_STACK_CONTROL_OFFSET) as *mut u8,
                last_control | WDM_X64_SL_ERROR_RETURNED,
            );
        }

        let control = read_unaligned((stack + WDM_X64_IO_STACK_CONTROL_OFFSET) as *const u8);
        let completion =
            read_unaligned((stack + WDM_X64_IO_STACK_COMPLETION_ROUTINE_OFFSET) as *const u64);
        let context = read_unaligned((stack + WDM_X64_IO_STACK_CONTEXT_OFFSET) as *const u64);
        let cancelled = read_unaligned((irp + WDM_X64_IRP_CANCEL_OFFSET) as *const u8) != 0;
        let frame = cursor
            .next_frame(
                nt_io_manager::StackControl::from_bits_retain(control),
                completion != 0,
                nt_status::NtStatus(status),
                cancelled,
            )
            .map_err(|_| ())?
            .ok_or(())?;

        write_unaligned(
            (irp + WDM_X64_IRP_PENDING_RETURNED_OFFSET) as *mut u8,
            frame.pending_returned as u8,
        );
        let next_stack = stack + WDM_X64_IO_STACK_LOCATION_SIZE as u64;
        write_unaligned(
            (irp + WDM_X64_IRP_CURRENT_LOCATION_OFFSET) as *mut u8,
            frame.next_location,
        );
        write_unaligned((irp + 0xb8) as *mut u64, next_stack);

        let device_object = if frame.completion_device_location.is_some() {
            read_unaligned((next_stack + WDM_X64_IO_STACK_DEVICE_OBJECT_OFFSET) as *const u64)
        } else {
            0
        };
        clear_completed_stack_location(stack);
        if frame.propagate_pending {
            let upper_control =
                read_unaligned((next_stack + WDM_X64_IO_STACK_CONTROL_OFFSET) as *const u8);
            write_unaligned(
                (next_stack + WDM_X64_IO_STACK_CONTROL_OFFSET) as *mut u8,
                upper_control | WDM_X64_SL_PENDING_RETURNED,
            );
        }
        trace_wdm_completion(
            irp,
            stack,
            status,
            completion,
            control,
            frame.invoke_routine,
            next_stack,
            device_object,
            context,
        );
        if frame.invoke_routine {
            let routine: extern "win64" fn(u64, u64, u64) -> i32 =
                core::mem::transmute(completion as *const ());
            let disposition = nt_io_manager::CompletionRoutineDisposition::from_status(
                nt_status::NtStatus(routine(device_object, irp, context)),
            );
            if disposition == nt_io_manager::CompletionRoutineDisposition::Stop {
                return Ok(HostedIrpUnwindOutcome::MoreProcessingRequired);
            }
        }
        stack = next_stack;
    }
    Ok(HostedIrpUnwindOutcome::Terminal)
}

unsafe fn trace_wdm_completion(
    irp: u64,
    stack: u64,
    status: i32,
    completion: u64,
    control: u8,
    invoke: bool,
    next_stack: u64,
    device_object: u64,
    context: u64,
) {
    if WDM_FORWARD_COMPLETION_TRACE_COUNT.fetch_add(1, Ordering::Relaxed) >= WDM_FORWARD_TRACE_CAP {
        return;
    }
    print_str(b"[wdm-complete] irp=");
    print_hex64(irp);
    print_str(b" stack=");
    print_hex64(stack);
    print_str(b" status=0x");
    print_hex(status as u32);
    print_str(b" completion=");
    print_hex64(completion);
    print_str(b" control=0x");
    print_hex(control as u32);
    print_str(b" invoke=");
    print_u64(if invoke { 1 } else { 0 });
    print_str(b" next=");
    print_hex64(next_stack);
    print_str(b" devobj=");
    print_hex64(device_object);
    print_str(b" context=");
    print_hex64(context);
    print_str(b"\n");
}

/// `NTSTATUS PoCallDriver(PDEVICE_OBJECT, PIRP)`.
extern "win64" fn s_po_call_driver(device: u64, irp: u64) -> i32 {
    s_iof_call_driver(device, irp)
}

/// `void PoStartNextPowerIrp(PIRP)`.
extern "win64" fn s_po_start_next_power_irp(_irp: u64) {}

/// `POWER_STATE PoSetPowerState(PDEVICE_OBJECT, POWER_STATE_TYPE, POWER_STATE)` — update the
/// authoritative record for this exact device stack and return that record's previous state.
extern "win64" fn s_po_set_power_state(device: u64, power_type: u32, state: u32) -> u32 {
    unsafe {
        let Some(devnode_id) = hosted_power_devnode_by_device_object(device) else {
            return nt_power_manager::DevicePowerState::Unspecified as u32;
        };
        match power_type {
            nt_power_types::POWER_STATE_TYPE_DEVICE => {
                let Some(state) = nt_power_manager::DevicePowerState::from_u32(state) else {
                    return nt_power_manager::DevicePowerState::Unspecified as u32;
                };
                crate::power_manager::report_device_state(devnode_id, state)
                    .map(|previous| previous as u32)
                    .unwrap_or(nt_power_manager::DevicePowerState::Unspecified as u32)
            }
            nt_power_types::POWER_STATE_TYPE_SYSTEM => {
                let Some(state) = nt_power_manager::SystemPowerState::from_u32(state) else {
                    return nt_power_manager::SystemPowerState::Unspecified as u32;
                };
                crate::power_manager::report_system_state(devnode_id, state)
                    .map(|previous| previous as u32)
                    .unwrap_or(nt_power_manager::SystemPowerState::Unspecified as u32)
            }
            _ => nt_power_manager::DevicePowerState::Unspecified as u32,
        }
    }
}

/// `PMDL IoAllocateMdl(PVOID, ULONG, BOOLEAN, BOOLEAN, PIRP)` — project a single-buffer MDL
/// while recording the canonical MDL id in the driver-visible `Next` field.
extern "win64" fn s_io_allocate_mdl(
    virtual_address: u64,
    length: u32,
    _secondary_buffer: u8,
    _charge_quota: u8,
    _irp: u64,
) -> u64 {
    unsafe {
        if virtual_address == 0 || length == 0 {
            return 0;
        }
        let mdl = pool_alloc(nt_mdl::MDL_SIZE as u64);
        if mdl == 0 {
            return 0;
        }
        let id = hosted_mdl_registry_mut().allocate(virtual_address, length);
        write_unaligned((mdl + nt_mdl::MDL_OFF_NEXT) as *mut u64, id);
        write_unaligned(
            (mdl + nt_mdl::MDL_OFF_SIZE) as *mut i16,
            nt_mdl::MDL_SIZE as i16,
        );
        write_unaligned(
            (mdl + nt_mdl::MDL_OFF_START_VA) as *mut u64,
            virtual_address & !0xFFF,
        );
        write_unaligned((mdl + nt_mdl::MDL_OFF_BYTE_COUNT) as *mut u32, length);
        write_unaligned(
            (mdl + nt_mdl::MDL_OFF_BYTE_OFFSET) as *mut u32,
            (virtual_address & 0xFFF) as u32,
        );
        mdl
    }
}

/// `VOID IoFreeMdl(PMDL)`.
extern "win64" fn s_io_free_mdl(mdl: u64) {
    unsafe {
        if mdl == 0 {
            return;
        }
        let id = read_unaligned((mdl + nt_mdl::MDL_OFF_NEXT) as *const u64);
        let _ = hosted_mdl_registry_mut().free(id);
        pool_free(mdl);
    }
}

/// `VOID IoBuildPartialMdl(PMDL SourceMdl, PMDL TargetMdl, PVOID VirtualAddress, ULONG Length)`.
extern "win64" fn s_io_build_partial_mdl(
    source_mdl: u64,
    target_mdl: u64,
    virtual_address: u64,
    length: u32,
) {
    if source_mdl == 0 || target_mdl == 0 {
        return;
    }
    unsafe {
        let source_start = read_unaligned((source_mdl + nt_mdl::MDL_OFF_START_VA) as *const u64);
        let source_offset =
            read_unaligned((source_mdl + nt_mdl::MDL_OFF_BYTE_OFFSET) as *const u32);
        let source_len = read_unaligned((source_mdl + nt_mdl::MDL_OFF_BYTE_COUNT) as *const u32);
        let va = if virtual_address != 0 {
            virtual_address
        } else {
            source_start + source_offset as u64
        };
        let len = if length != 0 { length } else { source_len };
        write_unaligned((target_mdl + nt_mdl::MDL_OFF_NEXT) as *mut u64, 0);
        write_unaligned(
            (target_mdl + nt_mdl::MDL_OFF_SIZE) as *mut i16,
            nt_mdl::MDL_SIZE as i16,
        );
        write_unaligned(
            (target_mdl + nt_mdl::MDL_OFF_FLAGS) as *mut i16,
            nt_mdl::MDL_MAPPED_TO_SYSTEM_VA,
        );
        write_unaligned(
            (target_mdl + nt_mdl::MDL_OFF_START_VA) as *mut u64,
            va & !0xFFF,
        );
        write_unaligned((target_mdl + nt_mdl::MDL_OFF_BYTE_COUNT) as *mut u32, len);
        write_unaligned(
            (target_mdl + nt_mdl::MDL_OFF_BYTE_OFFSET) as *mut u32,
            (va & 0xFFF) as u32,
        );
        write_unaligned(
            (target_mdl + nt_mdl::MDL_OFF_MAPPED_SYSTEM_VA) as *mut u64,
            va,
        );
    }
}

/// `VOID MmBuildMdlForNonPagedPool(PMDL)` — mark the MDL nonpaged and set `MappedSystemVa`.
extern "win64" fn s_mm_build_mdl_for_nonpaged_pool(mdl: u64) {
    unsafe {
        if mdl == 0 {
            return;
        }
        let id = read_unaligned((mdl + nt_mdl::MDL_OFF_NEXT) as *const u64);
        let _ = hosted_mdl_registry_mut().build_for_nonpaged(id);
        let flags = read_unaligned((mdl + nt_mdl::MDL_OFF_FLAGS) as *const i16);
        write_unaligned(
            (mdl + nt_mdl::MDL_OFF_FLAGS) as *mut i16,
            flags | nt_mdl::MDL_SOURCE_IS_NONPAGED_POOL | nt_mdl::MDL_MAPPED_TO_SYSTEM_VA,
        );
        let start = read_unaligned((mdl + nt_mdl::MDL_OFF_START_VA) as *const u64);
        let offset = read_unaligned((mdl + nt_mdl::MDL_OFF_BYTE_OFFSET) as *const u32);
        write_unaligned(
            (mdl + nt_mdl::MDL_OFF_MAPPED_SYSTEM_VA) as *mut u64,
            start + offset as u64,
        );
    }
}

/// `VOID MmProbeAndLockPages(PMDL, KPROCESSOR_MODE, LOCK_OPERATION)`.
extern "win64" fn s_mm_probe_and_lock_pages(mdl: u64, _access_mode: u8, _operation: u32) {
    unsafe {
        if mdl == 0 {
            return;
        }
        let id = read_unaligned((mdl + nt_mdl::MDL_OFF_NEXT) as *const u64);
        let _ = hosted_mdl_registry_mut().build_for_nonpaged(id);
        let flags = read_unaligned((mdl + nt_mdl::MDL_OFF_FLAGS) as *const i16);
        write_unaligned(
            (mdl + nt_mdl::MDL_OFF_FLAGS) as *mut i16,
            flags | nt_mdl::MDL_PAGES_LOCKED | nt_mdl::MDL_MAPPED_TO_SYSTEM_VA,
        );
        let start = read_unaligned((mdl + nt_mdl::MDL_OFF_START_VA) as *const u64);
        let offset = read_unaligned((mdl + nt_mdl::MDL_OFF_BYTE_OFFSET) as *const u32);
        write_unaligned(
            (mdl + nt_mdl::MDL_OFF_MAPPED_SYSTEM_VA) as *mut u64,
            start + offset as u64,
        );
    }
}

/// `VOID MmUnlockPages(PMDL)`.
extern "win64" fn s_mm_unlock_pages(mdl: u64) {
    unsafe {
        if mdl == 0 {
            return;
        }
        let flags = read_unaligned((mdl + nt_mdl::MDL_OFF_FLAGS) as *const i16);
        write_unaligned(
            (mdl + nt_mdl::MDL_OFF_FLAGS) as *mut i16,
            flags & !nt_mdl::MDL_PAGES_LOCKED,
        );
    }
}

/// `PVOID MmMapLockedPagesSpecifyCache(...)` — return the MDL's existing nonpaged mapping.
extern "win64" fn s_mm_map_locked_pages_specify_cache(
    mdl: u64,
    _access_mode: u8,
    _cache_type: u32,
    _requested_address: u64,
    _bug_check_on_failure: u32,
    _priority: u32,
) -> u64 {
    unsafe {
        if mdl == 0 {
            return 0;
        }
        let mapped = read_unaligned((mdl + nt_mdl::MDL_OFF_MAPPED_SYSTEM_VA) as *const u64);
        if mapped != 0 {
            return mapped;
        }
        let start = read_unaligned((mdl + nt_mdl::MDL_OFF_START_VA) as *const u64);
        let offset = read_unaligned((mdl + nt_mdl::MDL_OFF_BYTE_OFFSET) as *const u32);
        start + offset as u64
    }
}

/// `PVOID MmMapLockedPages(PMDL, KPROCESSOR_MODE)`.
extern "win64" fn s_mm_map_locked_pages(mdl: u64, access_mode: u8) -> u64 {
    s_mm_map_locked_pages_specify_cache(mdl, access_mode, 0, 0, 0, 0)
}

/// `VOID MmUnmapLockedPages(PVOID, PMDL)`.
extern "win64" fn s_mm_unmap_locked_pages(_base: u64, mdl: u64) {
    unsafe {
        if mdl == 0 {
            return;
        }
        let flags = read_unaligned((mdl + nt_mdl::MDL_OFF_FLAGS) as *const i16);
        write_unaligned(
            (mdl + nt_mdl::MDL_OFF_FLAGS) as *mut i16,
            flags & !nt_mdl::MDL_MAPPED_TO_SYSTEM_VA,
        );
    }
}

/// `PVOID MmAllocateContiguousMemorySpecifyCache(...)`.
extern "win64" fn s_mm_allocate_contiguous_memory_specify_cache(
    number_of_bytes: u64,
    _lowest: u64,
    _highest: u64,
    _boundary: u64,
    _cache_type: u32,
) -> u64 {
    unsafe { pool_alloc(number_of_bytes) }
}

extern "win64" fn s_mm_free_contiguous_memory_specify_cache(
    base: u64,
    _number_of_bytes: u64,
    _cache_type: u32,
) {
    unsafe {
        pool_free(base);
    }
}

extern "win64" fn s_mm_allocate_non_cached_memory(number_of_bytes: u64) -> u64 {
    unsafe { pool_alloc(number_of_bytes) }
}

extern "win64" fn s_mm_free_non_cached_memory(base: u64, _number_of_bytes: u64) {
    unsafe {
        pool_free(base);
    }
}

unsafe fn hosted_physical_mapping_slice_mut(
    exec_data_va: u64,
) -> &'static mut [nt_compat_exports::memory::PhysicalMapping] {
    core::slice::from_raw_parts_mut(
        (exec_data_va + FSD_DATA_PHYSICAL_MAP_OFF + FSD_DATA_PHYSICAL_MAP_HEADER_BYTES)
            as *mut nt_compat_exports::memory::PhysicalMapping,
        FSD_DATA_PHYSICAL_MAP_CAPACITY,
    )
}

unsafe fn append_hosted_physical_frame(
    exec_data_va: u64,
    count: usize,
    virtual_address: u64,
    frame_cap: u64,
) -> Option<usize> {
    let physical_address = get_frame_paddr(frame_cap);
    nt_compat_exports::memory::append_physical_page(
        hosted_physical_mapping_slice_mut(exec_data_va),
        count,
        virtual_address,
        physical_address,
        0x1000,
    )
}

unsafe fn append_hosted_physical_cap_run(
    exec_data_va: u64,
    mut count: usize,
    virtual_base: u64,
    frame_base: u64,
    frames: u64,
) -> Option<usize> {
    let mut frame = 0u64;
    while frame < frames {
        count = append_hosted_physical_frame(
            exec_data_va,
            count,
            virtual_base.checked_add(frame.checked_mul(0x1000)?)?,
            frame_base.checked_add(frame)?,
        )?;
        frame += 1;
    }
    Some(count)
}

unsafe fn initialize_hosted_physical_map(
    exec_data_va: u64,
    image_frames: &[u64],
    pool_frame_base: u64,
    data_frame_base: u64,
    shared_frame_base: u64,
    arg_frame_base: u64,
    stack_frame_base: u64,
    stack_frame_count: u64,
    ipc_buffer_frame: u64,
) -> bool {
    let header = exec_data_va + FSD_DATA_PHYSICAL_MAP_OFF;
    write_volatile(header as *mut u64, 0);
    let count_cell = &*((header + 8) as *const AtomicU32);
    count_cell.store(0, Ordering::Relaxed);
    write_volatile(
        (header + 12) as *mut u32,
        FSD_DATA_PHYSICAL_MAP_CAPACITY as u32,
    );
    let mappings = hosted_physical_mapping_slice_mut(exec_data_va);
    mappings.fill(nt_compat_exports::memory::PhysicalMapping::default());

    let mut count = 0usize;
    for (index, frame_cap) in image_frames.iter().copied().enumerate() {
        let Some(next) = append_hosted_physical_frame(
            exec_data_va,
            count,
            FSD_CODE_VA + index as u64 * 0x1000,
            frame_cap,
        ) else {
            return false;
        };
        count = next;
    }
    for (virtual_base, frame_base, frames) in [
        (FSD_POOL_VADDR, pool_frame_base, FSD_POOL_FRAMES),
        (FSD_DATA_VADDR, data_frame_base, FSD_DATA_FRAMES),
        (FSD_SHARED_VADDR, shared_frame_base, FSD_SHARED_FRAMES),
        (FSD_ARG_VADDR, arg_frame_base, FSD_ARG_FRAMES),
        (FSD_STACK_VADDR, stack_frame_base, stack_frame_count),
        (IPCBUF_VADDR, ipc_buffer_frame, 1),
    ] {
        let Some(next) =
            append_hosted_physical_cap_run(exec_data_va, count, virtual_base, frame_base, frames)
        else {
            return false;
        };
        count = next;
    }
    count_cell.store(count as u32, Ordering::Release);
    write_volatile(header as *mut u64, FSD_DATA_PHYSICAL_MAP_MAGIC);
    true
}

unsafe fn hosted_component_physical_mappings(
) -> Option<&'static [nt_compat_exports::memory::PhysicalMapping]> {
    let header = FSD_DATA_VADDR + FSD_DATA_PHYSICAL_MAP_OFF;
    if read_volatile(header as *const u64) != FSD_DATA_PHYSICAL_MAP_MAGIC {
        return None;
    }
    let count = (&*((header + 8) as *const AtomicU32))
        .load(Ordering::Acquire)
        .min(FSD_DATA_PHYSICAL_MAP_CAPACITY as u32) as usize;
    Some(core::slice::from_raw_parts(
        (header + FSD_DATA_PHYSICAL_MAP_HEADER_BYTES)
            as *const nt_compat_exports::memory::PhysicalMapping,
        count,
    ))
}

unsafe fn hosted_component_physical_address(virtual_address: u64) -> Option<u64> {
    if let Some(resource) = find_shared_address_resource_by_va(FSD_SHARED_VADDR, virtual_address, 1)
    {
        return resource
            .translated_start
            .checked_add(virtual_address.checked_sub(resource.va)?);
    }
    nt_compat_exports::memory::physical_address(
        hosted_component_physical_mappings()?,
        virtual_address,
    )
}

unsafe fn hosted_component_virtual_address(physical_address: u64, length: u64) -> Option<u64> {
    nt_compat_exports::memory::virtual_address(
        hosted_component_physical_mappings()?,
        physical_address,
        length,
    )
}

/// `PHYSICAL_ADDRESS MmGetPhysicalAddress(PVOID)` — translate only live mappings published for
/// this isolated driver VSpace. Unknown or unmapped addresses return zero, as NT does on failure.
extern "win64" fn s_mm_get_physical_address(virtual_address: u64) -> u64 {
    unsafe { hosted_component_physical_address(virtual_address).unwrap_or(0) }
}

/// `PVOID MmMapIoSpace(PHYSICAL_ADDRESS, SIZE_T, MEMORY_CACHING_TYPE)` — return the component VA
/// for a BAR range the executive already granted to this hosted driver. Requests outside the active
/// grant fail with NULL; there is no success fallback.
extern "win64" fn s_mm_map_io_space(phys: u64, length: u64, _cache: u32) -> u64 {
    unsafe {
        if let Some(existing) = hosted_component_virtual_address(phys, length) {
            return existing;
        }
        let Some(resource) = find_shared_address_resource_by_range(
            FSD_SHARED_VADDR,
            SH_RESOURCE_ADDRESS_KIND_MEMORY,
            phys,
            length,
            true,
        ) else {
            return 0;
        };
        if resource.va == 0 || resource.map_len > resource.len {
            return 0;
        }
        let offset = phys - resource.translated_start;
        write_volatile(
            (FSD_SHARED_VADDR + SH_RESOURCE_MMIO_MAPPED_PHYS) as *mut u64,
            phys,
        );
        write_volatile(
            (FSD_SHARED_VADDR + SH_RESOURCE_MMIO_MAPPED_LEN) as *mut u64,
            length,
        );
        resource.va + offset
    }
}

/// `void MmUnmapIoSpace(PVOID, SIZE_T)` — revoke the recorded projection. The VSpace mapping is
/// owned by the executive grant and is torn down with the component.
extern "win64" fn s_mm_unmap_io_space(base: u64, _length: u64) {
    unsafe {
        if find_shared_address_resource_by_va(FSD_SHARED_VADDR, base, 1).is_some() {
            write_volatile(
                (FSD_SHARED_VADDR + SH_RESOURCE_MMIO_MAPPED_PHYS) as *mut u64,
                0,
            );
            write_volatile(
                (FSD_SHARED_VADDR + SH_RESOURCE_MMIO_MAPPED_LEN) as *mut u64,
                0,
            );
        }
    }
}

/// `NTSTATUS IoConnectInterrupt(...)` — validate the requested vector against the active PnP grant
/// and hand back a component-local interrupt projection.
#[allow(clippy::too_many_arguments)]
extern "win64" fn s_io_connect_interrupt(
    interrupt_obj_out: *mut u64,
    service_routine: u64,
    service_context: u64,
    _spin_lock: u64,
    vector: u32,
    _irql: u8,
    _sync_irql: u8,
    _mode: u32,
    _share: u8,
    affinity: u64,
    _floating: u8,
) -> i32 {
    unsafe {
        let granted_vector =
            read_volatile((FSD_SHARED_VADDR + SH_RESOURCE_INTERRUPT_VECTOR) as *const u32);
        let granted_affinity =
            read_volatile((FSD_SHARED_VADDR + SH_RESOURCE_INTERRUPT_AFFINITY) as *const u64);
        if granted_vector == 0
            || vector != granted_vector
            || (affinity != 0 && granted_affinity != 0 && affinity != granted_affinity)
        {
            let status = 0xC000_000Du32 as i32; // STATUS_INVALID_PARAMETER
            trace_hosted_io_connect_interrupt(
                interrupt_obj_out as u64,
                service_routine,
                service_context,
                vector,
                granted_vector,
                affinity,
                granted_affinity,
                0,
                status,
            );
            return status;
        }
        let projection = pool_alloc(0x20);
        if projection == 0 {
            let status = 0xC000_009Au32 as i32; // STATUS_INSUFFICIENT_RESOURCES
            trace_hosted_io_connect_interrupt(
                interrupt_obj_out as u64,
                service_routine,
                service_context,
                vector,
                granted_vector,
                affinity,
                granted_affinity,
                0,
                status,
            );
            return status;
        }
        write_unaligned(projection as *mut u32, vector);
        write_unaligned((projection + 8) as *mut u64, service_routine);
        write_unaligned((projection + 16) as *mut u64, service_context);
        if !interrupt_obj_out.is_null() {
            write_unaligned(interrupt_obj_out, projection);
        }
        write_volatile(
            (FSD_SHARED_VADDR + SH_RESOURCE_INTERRUPT_OBJECT) as *mut u64,
            projection,
        );
        write_volatile(
            (FSD_SHARED_VADDR + SH_RESOURCE_INTERRUPT_ROUTINE) as *mut u64,
            service_routine,
        );
        write_volatile(
            (FSD_SHARED_VADDR + SH_RESOURCE_INTERRUPT_CONTEXT) as *mut u64,
            service_context,
        );
        let (_label, broker_status, interrupt_id, _, _) = call_on4(
            (FSD_SERVICE_INTERRUPT_LABEL << 12) | 2,
            HOSTED_INTERRUPT_OP_CONNECT,
            projection,
            0,
            0,
        );
        let broker_status = broker_status as u32 as i32;
        if broker_status != STATUS_SUCCESS || interrupt_id == 0 {
            if !interrupt_obj_out.is_null() {
                write_unaligned(interrupt_obj_out, 0);
            }
            write_volatile(
                (FSD_SHARED_VADDR + SH_RESOURCE_INTERRUPT_OBJECT) as *mut u64,
                0,
            );
            write_volatile(
                (FSD_SHARED_VADDR + SH_RESOURCE_INTERRUPT_ROUTINE) as *mut u64,
                0,
            );
            write_volatile(
                (FSD_SHARED_VADDR + SH_RESOURCE_INTERRUPT_CONTEXT) as *mut u64,
                0,
            );
            pool_free(projection);
            trace_hosted_io_connect_interrupt(
                interrupt_obj_out as u64,
                service_routine,
                service_context,
                vector,
                granted_vector,
                affinity,
                granted_affinity,
                0,
                broker_status,
            );
            return if broker_status == STATUS_SUCCESS {
                STATUS_INVALID_DEVICE_REQUEST
            } else {
                broker_status
            };
        }
        write_volatile(
            (FSD_SHARED_VADDR + SH_RESOURCE_INTERRUPT_ID) as *mut u64,
            interrupt_id,
        );
        trace_hosted_io_connect_interrupt(
            interrupt_obj_out as u64,
            service_routine,
            service_context,
            vector,
            granted_vector,
            affinity,
            granted_affinity,
            projection,
            0,
        );
        0
    }
}

/// `void IoDisconnectInterrupt(PKINTERRUPT)` — clear the connected projection if it is the active
/// one for this hosted driver.
extern "win64" fn s_io_disconnect_interrupt(pkinterrupt: u64) {
    unsafe {
        let active = read_volatile((FSD_SHARED_VADDR + SH_RESOURCE_INTERRUPT_OBJECT) as *const u64);
        if pkinterrupt != 0 && pkinterrupt == active {
            let (_label, status, _, _, _) = call_on4(
                (FSD_SERVICE_INTERRUPT_LABEL << 12) | 2,
                HOSTED_INTERRUPT_OP_DISCONNECT,
                pkinterrupt,
                0,
                0,
            );
            if status as u32 as i32 != STATUS_SUCCESS {
                return;
            }
            write_volatile(
                (FSD_SHARED_VADDR + SH_RESOURCE_INTERRUPT_OBJECT) as *mut u64,
                0,
            );
            write_volatile(
                (FSD_SHARED_VADDR + SH_RESOURCE_INTERRUPT_ROUTINE) as *mut u64,
                0,
            );
            write_volatile(
                (FSD_SHARED_VADDR + SH_RESOURCE_INTERRUPT_CONTEXT) as *mut u64,
                0,
            );
            write_volatile((FSD_SHARED_VADDR + SH_RESOURCE_INTERRUPT_ID) as *mut u64, 0);
            write_volatile(
                (FSD_SHARED_VADDR + SH_RESOURCE_INTERRUPT_DELIVERED_VECTOR) as *mut u64,
                0,
            );
            write_volatile(
                (FSD_SHARED_VADDR + SH_RESOURCE_INTERRUPT_ISR_CLAIMED) as *mut u64,
                0,
            );
            write_volatile(
                (FSD_SHARED_VADDR + SH_RESOURCE_INTERRUPT_DELIVERIES) as *mut u64,
                0,
            );
            clear_dpc_queue_projection(FSD_SHARED_VADDR);
            pool_free(pkinterrupt);
        }
    }
}

/// `PDMA_ADAPTER IoGetDmaAdapter(PDEVICE_OBJECT, PDEVICE_DESCRIPTION, PULONG)` — build a
/// driver-local DMA adapter projection only when PnP granted this devnode a DMA common buffer.
extern "win64" fn s_io_get_dma_adapter(
    _pdo: u64,
    _device_description: u64,
    number_of_map_registers: *mut u32,
) -> u64 {
    unsafe {
        let adapter_id = read_volatile((FSD_SHARED_VADDR + SH_DMA_ADAPTER_ID) as *const u64);
        let grant_va = read_volatile((FSD_SHARED_VADDR + SH_DMA_COMMON_VA) as *const u64);
        let grant_len = read_volatile((FSD_SHARED_VADDR + SH_DMA_COMMON_LEN) as *const u64);
        let grant_logical = read_volatile((FSD_SHARED_VADDR + SH_DMA_COMMON_LOGICAL) as *const u64);
        if adapter_id == 0 || grant_va == 0 || grant_len == 0 || grant_logical == 0 {
            return 0;
        }
        let active_adapter = read_volatile((FSD_SHARED_VADDR + SH_DMA_ADAPTER_BLOB) as *const u64);
        if dma_adapter_blob_matches(active_adapter, adapter_id) {
            if !number_of_map_registers.is_null() {
                write_unaligned(number_of_map_registers, 64);
            }
            return active_adapter;
        }

        let ops = pool_alloc(0x100);
        if ops == 0 {
            return 0;
        }
        let adapter = pool_alloc(HOSTED_DMA_ADAPTER_SIZE);
        if adapter == 0 {
            pool_free(ops);
            return 0;
        }

        // DMA_OPERATIONS: publish the NT5 WDM operations needed by NDIS bus-master DMA. Later
        // post-NT5 extended entries stay NULL and therefore fail closed if a driver requires them.
        write_unaligned(ops as *mut u32, 0x100);
        write_unaligned(
            (ops + 8) as *mut u64,
            s_dma_put_adapter as *const () as usize as u64,
        );
        write_unaligned(
            (ops + 16) as *mut u64,
            s_dma_allocate_common_buffer as *const () as usize as u64,
        );
        write_unaligned(
            (ops + 24) as *mut u64,
            s_dma_free_common_buffer as *const () as usize as u64,
        );
        write_unaligned(
            (ops + 32) as *mut u64,
            s_dma_allocate_adapter_channel as *const () as usize as u64,
        );
        write_unaligned(
            (ops + 40) as *mut u64,
            s_dma_flush_adapter_buffers as *const () as usize as u64,
        );
        write_unaligned(
            (ops + 48) as *mut u64,
            s_dma_free_adapter_channel as *const () as usize as u64,
        );
        write_unaligned(
            (ops + 56) as *mut u64,
            s_dma_free_map_registers as *const () as usize as u64,
        );
        write_unaligned(
            (ops + 64) as *mut u64,
            s_dma_map_transfer as *const () as usize as u64,
        );
        write_unaligned(
            (ops + 72) as *mut u64,
            s_dma_get_dma_alignment as *const () as usize as u64,
        );
        write_unaligned(
            (ops + 80) as *mut u64,
            s_dma_read_dma_counter as *const () as usize as u64,
        );
        write_unaligned(
            (ops + 88) as *mut u64,
            s_dma_get_scatter_gather_list as *const () as usize as u64,
        );
        write_unaligned(
            (ops + 96) as *mut u64,
            s_dma_put_scatter_gather_list as *const () as usize as u64,
        );
        write_unaligned(
            (ops + 104) as *mut u64,
            s_dma_calculate_scatter_gather_list as *const () as usize as u64,
        );
        write_unaligned(
            (ops + 112) as *mut u64,
            s_dma_build_scatter_gather_list as *const () as usize as u64,
        );
        write_unaligned(
            (ops + 120) as *mut u64,
            s_dma_build_mdl_from_scatter_gather_list as *const () as usize as u64,
        );

        // DMA_ADAPTER: Version@0, Size@2, DmaOperations@8, followed by hosted bridge metadata.
        write_unaligned(adapter as *mut u16, 1);
        write_unaligned((adapter + 2) as *mut u16, HOSTED_DMA_ADAPTER_SIZE as u16);
        write_unaligned((adapter + HOSTED_DMA_ADAPTER_OPS_OFFSET) as *mut u64, ops);
        write_unaligned(
            (adapter + HOSTED_DMA_ADAPTER_SIGNATURE_OFFSET) as *mut u64,
            HOSTED_DMA_ADAPTER_SIGNATURE,
        );
        write_unaligned(
            (adapter + HOSTED_DMA_ADAPTER_ID_OFFSET) as *mut u64,
            adapter_id,
        );
        write_unaligned(
            (adapter + HOSTED_DMA_ADAPTER_GRANT_VA_OFFSET) as *mut u64,
            grant_va,
        );
        write_unaligned(
            (adapter + HOSTED_DMA_ADAPTER_GRANT_LEN_OFFSET) as *mut u64,
            grant_len,
        );
        write_unaligned(
            (adapter + HOSTED_DMA_ADAPTER_GRANT_LOGICAL_OFFSET) as *mut u64,
            grant_logical,
        );
        write_volatile(
            (FSD_SHARED_VADDR + SH_DMA_ADAPTER_BLOB) as *mut u64,
            adapter,
        );
        write_volatile((FSD_SHARED_VADDR + SH_DMA_OPS_BLOB) as *mut u64, ops);
        if !number_of_map_registers.is_null() {
            write_unaligned(number_of_map_registers, 64);
        }
        adapter
    }
}

/// `PutDmaAdapter` — release the component-local adapter projection.
extern "win64" fn s_dma_put_adapter(adapter: u64) {
    unsafe {
        if dma_adapter_blob_id(adapter).is_none() {
            return;
        }
        let active = read_volatile((FSD_SHARED_VADDR + SH_DMA_ADAPTER_BLOB) as *const u64);
        let ops = read_unaligned((adapter + HOSTED_DMA_ADAPTER_OPS_OFFSET) as *const u64);
        write_unaligned(
            (adapter + HOSTED_DMA_ADAPTER_SIGNATURE_OFFSET) as *mut u64,
            0,
        );
        pool_free(adapter);
        if ops != 0 {
            pool_free(ops);
        }
        if adapter == active {
            write_volatile((FSD_SHARED_VADDR + SH_DMA_ADAPTER_BLOB) as *mut u64, 0);
            write_volatile((FSD_SHARED_VADDR + SH_DMA_OPS_BLOB) as *mut u64, 0);
        }
    }
}

const HOSTED_DMA_COMMON_ALIGNMENT: u64 = 0x1000;
const HOSTED_DMA_RECORD_KIND_COMMON: u64 = 1;
const HOSTED_DMA_RECORD_KIND_MAP_TRANSFER: u64 = 2;
const HOSTED_DMA_RECORD_FLAG_WRITE_TO_DEVICE: u64 = 1;
const HOSTED_DMA_MAP_REGISTER_SIGNATURE: u64 = 0x4D41_5052_4547_3031; // "MAPREG01"
const HOSTED_DMA_ADAPTER_SIGNATURE: u64 = 0x444D_4144_4150_3031; // "DMADAP01"
const HOSTED_DMA_ADAPTER_SIZE: u64 = 0x40;
const HOSTED_DMA_ADAPTER_OPS_OFFSET: u64 = 0x08;
const HOSTED_DMA_ADAPTER_SIGNATURE_OFFSET: u64 = 0x10;
const HOSTED_DMA_ADAPTER_ID_OFFSET: u64 = 0x18;
const HOSTED_DMA_ADAPTER_GRANT_VA_OFFSET: u64 = 0x20;
const HOSTED_DMA_ADAPTER_GRANT_LEN_OFFSET: u64 = 0x28;
const HOSTED_DMA_ADAPTER_GRANT_LOGICAL_OFFSET: u64 = 0x30;

#[derive(Clone, Copy)]
struct HostedDmaAdapterMetadata {
    adapter_id: u64,
    grant_va: u64,
    grant_len: u64,
    grant_logical: u64,
}

fn align_up(value: u64, alignment: u64) -> Option<u64> {
    if alignment == 0 || !alignment.is_power_of_two() {
        return None;
    }
    value
        .checked_add(alignment - 1)
        .map(|aligned| aligned & !(alignment - 1))
}

unsafe fn dma_allocation_record(sh: u64, index: u64) -> Option<u64> {
    if index >= dma_allocation_record_capacity(sh) {
        return None;
    }
    let offset = SH_DMA_ALLOC_RECORDS.checked_add(index.checked_mul(SH_DMA_ALLOC_RECORD_SIZE)?)?;
    if offset.checked_add(SH_DMA_ALLOC_RECORD_SIZE)? > SH_DMA_ALLOC_RECORD_LIMIT {
        return None;
    }
    Some(sh + offset)
}

const fn dma_allocation_record_arena_capacity() -> u64 {
    (SH_DMA_ALLOC_RECORD_LIMIT - SH_DMA_ALLOC_RECORDS) / SH_DMA_ALLOC_RECORD_SIZE
}

unsafe fn dma_allocation_record_capacity(sh: u64) -> u64 {
    let capacity = read_volatile((sh + SH_DMA_ALLOC_RECORD_CAPACITY) as *const u64);
    if capacity == dma_allocation_record_arena_capacity() {
        capacity
    } else {
        0
    }
}

unsafe fn clear_dma_allocation_records(sh: u64) {
    write_volatile((sh + SH_DMA_ALLOC_CURSOR) as *mut u64, 0);
    write_volatile((sh + SH_DMA_ALLOC_RECORD_COUNT) as *mut u64, 0);
    write_volatile(
        (sh + SH_DMA_ALLOC_RECORD_CAPACITY) as *mut u64,
        dma_allocation_record_arena_capacity(),
    );
    let mut i = 0u64;
    while i < dma_allocation_record_arena_capacity() {
        if let Some(record) = dma_allocation_record(sh, i) {
            clear_dma_allocation_record(record);
        }
        i += 1;
    }
}

unsafe fn clear_dma_allocation_record(record: u64) {
    write_volatile((record + SH_DMA_ALLOC_RECORD_LOGICAL) as *mut u64, 0);
    write_volatile((record + SH_DMA_ALLOC_RECORD_LEN) as *mut u64, 0);
    write_volatile((record + SH_DMA_ALLOC_RECORD_VA) as *mut u64, 0);
    write_volatile((record + SH_DMA_ALLOC_RECORD_KIND) as *mut u64, 0);
    write_volatile((record + SH_DMA_ALLOC_RECORD_SOURCE_VA) as *mut u64, 0);
    write_volatile((record + SH_DMA_ALLOC_RECORD_FLAGS) as *mut u64, 0);
    write_volatile((record + SH_DMA_ALLOC_RECORD_MAP_REGISTER) as *mut u64, 0);
}

unsafe fn dma_allocation_range_overlaps(
    sh: u64,
    grant_logical: u64,
    offset: u64,
    length: u64,
) -> Option<u64> {
    let end = offset.checked_add(length)?;
    let mut i = 0u64;
    let capacity = dma_allocation_record_capacity(sh);
    while i < capacity {
        let record = dma_allocation_record(sh, i)?;
        let logical = read_volatile((record + SH_DMA_ALLOC_RECORD_LOGICAL) as *const u64);
        let record_len = read_volatile((record + SH_DMA_ALLOC_RECORD_LEN) as *const u64);
        if logical != 0 && record_len != 0 {
            let record_offset = logical.checked_sub(grant_logical)?;
            let record_end = record_offset.checked_add(record_len)?;
            if offset < record_end && record_offset < end {
                return Some(record_end);
            }
        }
        i += 1;
    }
    None
}

unsafe fn first_free_dma_allocation_record(sh: u64) -> Option<u64> {
    let mut i = 0u64;
    let capacity = dma_allocation_record_capacity(sh);
    while i < capacity {
        let record = dma_allocation_record(sh, i)?;
        if read_volatile((record + SH_DMA_ALLOC_RECORD_LEN) as *const u64) == 0 {
            return Some(record);
        }
        i += 1;
    }
    None
}

unsafe fn dma_adapter_blob_id(adapter: u64) -> Option<u64> {
    if adapter == 0
        || read_unaligned((adapter + HOSTED_DMA_ADAPTER_SIGNATURE_OFFSET) as *const u64)
            != HOSTED_DMA_ADAPTER_SIGNATURE
    {
        return None;
    }
    Some(read_unaligned(
        (adapter + HOSTED_DMA_ADAPTER_ID_OFFSET) as *const u64,
    ))
}

unsafe fn dma_adapter_metadata(adapter: u64) -> Option<HostedDmaAdapterMetadata> {
    let adapter_id = dma_adapter_blob_id(adapter)?;
    let ops = read_unaligned((adapter + HOSTED_DMA_ADAPTER_OPS_OFFSET) as *const u64);
    let grant_va = read_unaligned((adapter + HOSTED_DMA_ADAPTER_GRANT_VA_OFFSET) as *const u64);
    let grant_len = read_unaligned((adapter + HOSTED_DMA_ADAPTER_GRANT_LEN_OFFSET) as *const u64);
    let grant_logical =
        read_unaligned((adapter + HOSTED_DMA_ADAPTER_GRANT_LOGICAL_OFFSET) as *const u64);
    if ops == 0 || grant_va == 0 || grant_len == 0 || grant_logical == 0 {
        return None;
    }
    Some(HostedDmaAdapterMetadata {
        adapter_id,
        grant_va,
        grant_len,
        grant_logical,
    })
}

unsafe fn dma_adapter_blob_matches(adapter: u64, adapter_id: u64) -> bool {
    if adapter_id == 0 {
        return false;
    }
    dma_adapter_metadata(adapter)
        .map(|metadata| metadata.adapter_id == adapter_id)
        .unwrap_or(false)
}

/// `AllocateCommonBuffer` — allocate a bounded slice from the PnP-granted DMA common-buffer window.
extern "win64" fn s_dma_allocate_common_buffer(
    adapter: u64,
    length: u32,
    logical_out: *mut i64,
    _cache_enabled: u8,
) -> u64 {
    unsafe {
        let Some(metadata) = dma_adapter_metadata(adapter) else {
            return 0;
        };
        let requested = length as u64;
        if requested == 0 || requested > metadata.grant_len {
            return 0;
        }

        let Some(record) = first_free_dma_allocation_record(FSD_SHARED_VADDR) else {
            return 0;
        };
        let mut offset = 0u64;
        loop {
            let Some(aligned) = align_up(offset, HOSTED_DMA_COMMON_ALIGNMENT) else {
                return 0;
            };
            let Some(end) = aligned.checked_add(requested) else {
                return 0;
            };
            if end > metadata.grant_len {
                return 0;
            }
            if let Some(next_offset) = dma_allocation_range_overlaps(
                FSD_SHARED_VADDR,
                metadata.grant_logical,
                aligned,
                requested,
            ) {
                offset = next_offset;
                continue;
            }
            offset = aligned;
            break;
        }

        let va = metadata.grant_va + offset;
        let logical = metadata.grant_logical + offset;
        // Common-buffer allocation does not promise zeroed memory, and provider-domain NDIS must
        // not dereference a VA that belongs to the dependent miniport VSpace.
        write_volatile((record + SH_DMA_ALLOC_RECORD_LOGICAL) as *mut u64, logical);
        write_volatile((record + SH_DMA_ALLOC_RECORD_LEN) as *mut u64, requested);
        write_volatile((record + SH_DMA_ALLOC_RECORD_VA) as *mut u64, va);
        write_volatile(
            (record + SH_DMA_ALLOC_RECORD_KIND) as *mut u64,
            HOSTED_DMA_RECORD_KIND_COMMON,
        );
        write_volatile((record + SH_DMA_ALLOC_RECORD_SOURCE_VA) as *mut u64, 0);
        write_volatile((record + SH_DMA_ALLOC_RECORD_FLAGS) as *mut u64, 0);
        write_volatile((record + SH_DMA_ALLOC_RECORD_MAP_REGISTER) as *mut u64, 0);
        write_volatile(
            (FSD_SHARED_VADDR + SH_DMA_REQUESTED_LEN) as *mut u64,
            requested,
        );
        write_volatile((FSD_SHARED_VADDR + SH_DMA_ALLOCATED_VA) as *mut u64, va);
        write_volatile(
            (FSD_SHARED_VADDR + SH_DMA_ALLOCATED_LOGICAL) as *mut u64,
            logical,
        );
        let count = read_volatile((FSD_SHARED_VADDR + SH_DMA_ALLOC_RECORD_COUNT) as *const u64);
        let used = ((record - FSD_SHARED_VADDR - SH_DMA_ALLOC_RECORDS) / SH_DMA_ALLOC_RECORD_SIZE)
            .saturating_add(1);
        if used > count {
            write_volatile(
                (FSD_SHARED_VADDR + SH_DMA_ALLOC_RECORD_COUNT) as *mut u64,
                used,
            );
        }
        let cursor = read_volatile((FSD_SHARED_VADDR + SH_DMA_ALLOC_CURSOR) as *const u64);
        let end = offset + requested;
        if end > cursor {
            write_volatile((FSD_SHARED_VADDR + SH_DMA_ALLOC_CURSOR) as *mut u64, end);
        }
        if !logical_out.is_null() {
            write_unaligned(logical_out, logical as i64);
        }
        va
    }
}

/// `FreeCommonBuffer` — release the matching common-buffer allocation record.
extern "win64" fn s_dma_free_common_buffer(
    adapter: u64,
    length: u32,
    logical: i64,
    virtual_address: u64,
    _cache_enabled: u8,
) {
    unsafe {
        if dma_active_adapter_and_grant(adapter).is_none() {
            return;
        }
        let logical = logical as u64;
        let mut i = 0u64;
        let capacity = dma_allocation_record_capacity(FSD_SHARED_VADDR);
        while i < capacity {
            if let Some(record) = dma_allocation_record(FSD_SHARED_VADDR, i) {
                let active_logical =
                    read_volatile((record + SH_DMA_ALLOC_RECORD_LOGICAL) as *const u64);
                let active_len = read_volatile((record + SH_DMA_ALLOC_RECORD_LEN) as *const u64);
                let active_va = read_volatile((record + SH_DMA_ALLOC_RECORD_VA) as *const u64);
                let kind = read_volatile((record + SH_DMA_ALLOC_RECORD_KIND) as *const u64);
                if active_logical != 0
                    && kind == HOSTED_DMA_RECORD_KIND_COMMON
                    && logical == active_logical
                    && virtual_address == active_va
                    && length as u64 == active_len
                {
                    write_volatile(
                        (FSD_SHARED_VADDR + SH_DMA_FREED_LOGICAL) as *mut u64,
                        active_logical,
                    );
                    clear_dma_allocation_record(record);
                    if read_volatile((FSD_SHARED_VADDR + SH_DMA_ALLOCATED_LOGICAL) as *const u64)
                        == active_logical
                    {
                        write_volatile(
                            (FSD_SHARED_VADDR + SH_DMA_ALLOCATED_LOGICAL) as *mut u64,
                            0,
                        );
                        write_volatile((FSD_SHARED_VADDR + SH_DMA_ALLOCATED_VA) as *mut u64, 0);
                        write_volatile((FSD_SHARED_VADDR + SH_DMA_REQUESTED_LEN) as *mut u64, 0);
                    }
                    return;
                }
            }
            i += 1;
        }
    }
}

unsafe fn dma_active_adapter_and_grant(adapter: u64) -> Option<(u64, u64, u64)> {
    dma_adapter_metadata(adapter).map(|metadata| {
        (
            metadata.grant_va,
            metadata.grant_len,
            metadata.grant_logical,
        )
    })
}

unsafe fn dma_mdl_transfer_window(mdl: u64, current_va: u64, requested: u64) -> Option<(u64, u64)> {
    if mdl == 0 || requested == 0 || requested > u32::MAX as u64 {
        return None;
    }
    let start = read_unaligned((mdl + nt_mdl::MDL_OFF_START_VA) as *const u64);
    let byte_offset = read_unaligned((mdl + nt_mdl::MDL_OFF_BYTE_OFFSET) as *const u32) as u64;
    let byte_count = read_unaligned((mdl + nt_mdl::MDL_OFF_BYTE_COUNT) as *const u32) as u64;
    if byte_count == 0 {
        return None;
    }
    let base = start.checked_add(byte_offset)?;
    let end = base.checked_add(byte_count)?;
    let va = if current_va == 0 { base } else { current_va };
    if va < base || va >= end {
        return None;
    }
    let length = requested.min(end - va);
    (length != 0).then_some((va, length))
}

unsafe fn trace_hosted_dma_sg(
    phase: &[u8],
    reason: &[u8],
    status: i32,
    adapter: u64,
    mdl: u64,
    current_va: u64,
    length: u32,
    sg_list: u64,
    map_register: u64,
    logical: u64,
) {
    if HOSTED_DMA_SG_TRACE_COUNT.fetch_add(1, Ordering::Relaxed) >= HOSTED_DMA_SG_TRACE_CAP {
        return;
    }
    print_str(b"[hosted-sg] ");
    print_str(phase);
    print_str(b" ");
    print_str(reason);
    print_str(b" status=0x");
    print_hex(status as u32);
    print_str(b" adapter=");
    print_hex64(adapter);
    print_str(b" mdl=");
    print_hex64(mdl);
    print_str(b" cur=");
    print_hex64(current_va);
    print_str(b" len=");
    print_u64(length as u64);
    print_str(b" sg=");
    print_hex64(sg_list);
    print_str(b" map=");
    print_hex64(map_register);
    print_str(b" logical=");
    print_hex64(logical);
    if let Some(metadata) = dma_adapter_metadata(adapter) {
        print_str(b" grant=");
        print_hex64(metadata.grant_va);
        print_str(b"/");
        print_u64(metadata.grant_len);
        print_str(b"/");
        print_hex64(metadata.grant_logical);
        print_str(b" adapter-id=");
        print_u64(metadata.adapter_id);
    } else {
        print_str(b" grant=invalid");
    }
    if mdl != 0 {
        print_str(b" mdl.next/start/map/off/count=");
        print_hex64(read_unaligned((mdl + nt_mdl::MDL_OFF_NEXT) as *const u64));
        print_str(b"/");
        print_hex64(read_unaligned(
            (mdl + nt_mdl::MDL_OFF_START_VA) as *const u64,
        ));
        print_str(b"/");
        print_hex64(read_unaligned(
            (mdl + nt_mdl::MDL_OFF_MAPPED_SYSTEM_VA) as *const u64,
        ));
        print_str(b"/");
        print_u64(read_unaligned((mdl + nt_mdl::MDL_OFF_BYTE_OFFSET) as *const u32) as u64);
        print_str(b"/");
        print_u64(read_unaligned((mdl + nt_mdl::MDL_OFF_BYTE_COUNT) as *const u32) as u64);
    }
    print_str(b" records=");
    print_u64(read_volatile(
        (FSD_SHARED_VADDR + SH_DMA_ALLOC_RECORD_COUNT) as *const u64,
    ));
    print_str(b"/");
    print_u64(dma_allocation_record_capacity(FSD_SHARED_VADDR));
    print_str(b" cursor=");
    print_u64(read_volatile(
        (FSD_SHARED_VADDR + SH_DMA_ALLOC_CURSOR) as *const u64,
    ));
    print_str(b"\n");
}

unsafe fn dma_copy_bytes(dst: u64, src: u64, len: u64) {
    let mut offset = 0u64;
    while offset < len {
        let byte = read_volatile((src + offset) as *const u8);
        write_volatile((dst + offset) as *mut u8, byte);
        offset += 1;
    }
}

extern "win64" fn s_dma_allocate_adapter_channel(
    adapter: u64,
    device_object: u64,
    number_of_map_registers: u32,
    execution_routine: u64,
    context: u64,
) -> i32 {
    unsafe {
        if dma_active_adapter_and_grant(adapter).is_none()
            || number_of_map_registers == 0
            || number_of_map_registers > 64
            || execution_routine == 0
        {
            return 0xC000_000Du32 as i32; // STATUS_INVALID_PARAMETER
        }
        let map_register = dma_allocate_map_register_token(number_of_map_registers);
        if map_register == 0 {
            return 0xC000_009Au32 as i32; // STATUS_INSUFFICIENT_RESOURCES
        }
        let routine: extern "win64" fn(u64, u64, u64, u64) -> u32 =
            core::mem::transmute(execution_routine as *const ());
        let action = routine(device_object, 0, map_register, context);
        if action == 2 {
            // DeallocateObject: the caller did not retain the map-register token.
            pool_free(map_register);
        }
        0
    }
}

extern "win64" fn s_dma_free_adapter_channel(_adapter: u64) {}

extern "win64" fn s_dma_map_transfer(
    adapter: u64,
    mdl: u64,
    map_register_base: u64,
    current_va: u64,
    length: *mut u32,
    write_to_device: u8,
) -> i64 {
    unsafe {
        let Some(metadata) = dma_adapter_metadata(adapter) else {
            trace_hosted_dma_sg(
                b"map",
                b"bad-adapter",
                STATUS_INVALID_PARAMETER,
                adapter,
                mdl,
                current_va,
                0,
                0,
                map_register_base,
                0,
            );
            return 0;
        };
        if map_register_base == 0
            || read_unaligned(map_register_base as *const u64) != HOSTED_DMA_MAP_REGISTER_SIGNATURE
            || length.is_null()
        {
            trace_hosted_dma_sg(
                b"map",
                b"bad-map-or-len",
                STATUS_INVALID_PARAMETER,
                adapter,
                mdl,
                current_va,
                0,
                0,
                map_register_base,
                0,
            );
            return 0;
        }
        let requested = read_unaligned(length) as u64;
        let Some((source_va, mapped_len)) = dma_mdl_transfer_window(mdl, current_va, requested)
        else {
            write_unaligned(length, 0);
            trace_hosted_dma_sg(
                b"map",
                b"mdl-window",
                STATUS_INVALID_PARAMETER,
                adapter,
                mdl,
                current_va,
                requested as u32,
                0,
                map_register_base,
                0,
            );
            return 0;
        };
        let Some(record) = first_free_dma_allocation_record(FSD_SHARED_VADDR) else {
            write_unaligned(length, 0);
            trace_hosted_dma_sg(
                b"map",
                b"no-record",
                STATUS_INSUFFICIENT_RESOURCES,
                adapter,
                mdl,
                current_va,
                requested as u32,
                0,
                map_register_base,
                0,
            );
            return 0;
        };

        let mut offset = 0u64;
        loop {
            let Some(aligned) = align_up(offset, HOSTED_DMA_COMMON_ALIGNMENT) else {
                write_unaligned(length, 0);
                trace_hosted_dma_sg(
                    b"map",
                    b"align-overflow",
                    STATUS_INSUFFICIENT_RESOURCES,
                    adapter,
                    mdl,
                    current_va,
                    mapped_len as u32,
                    0,
                    map_register_base,
                    0,
                );
                return 0;
            };
            let Some(end) = aligned.checked_add(mapped_len) else {
                write_unaligned(length, 0);
                trace_hosted_dma_sg(
                    b"map",
                    b"range-overflow",
                    STATUS_INSUFFICIENT_RESOURCES,
                    adapter,
                    mdl,
                    current_va,
                    mapped_len as u32,
                    0,
                    map_register_base,
                    0,
                );
                return 0;
            };
            if end > metadata.grant_len {
                write_unaligned(length, 0);
                trace_hosted_dma_sg(
                    b"map",
                    b"grant-full",
                    STATUS_INSUFFICIENT_RESOURCES,
                    adapter,
                    mdl,
                    current_va,
                    mapped_len as u32,
                    0,
                    map_register_base,
                    0,
                );
                return 0;
            }
            if let Some(next_offset) = dma_allocation_range_overlaps(
                FSD_SHARED_VADDR,
                metadata.grant_logical,
                aligned,
                mapped_len,
            ) {
                offset = next_offset;
                continue;
            }
            offset = aligned;
            break;
        }

        let bounce_va = metadata.grant_va + offset;
        let logical = metadata.grant_logical + offset;
        if write_to_device != 0 {
            dma_copy_bytes(bounce_va, source_va, mapped_len);
        } else {
            core::ptr::write_bytes(bounce_va as *mut u8, 0, mapped_len as usize);
        }
        write_volatile((record + SH_DMA_ALLOC_RECORD_LOGICAL) as *mut u64, logical);
        write_volatile((record + SH_DMA_ALLOC_RECORD_LEN) as *mut u64, mapped_len);
        write_volatile((record + SH_DMA_ALLOC_RECORD_VA) as *mut u64, bounce_va);
        write_volatile(
            (record + SH_DMA_ALLOC_RECORD_KIND) as *mut u64,
            HOSTED_DMA_RECORD_KIND_MAP_TRANSFER,
        );
        write_volatile(
            (record + SH_DMA_ALLOC_RECORD_SOURCE_VA) as *mut u64,
            source_va,
        );
        write_volatile(
            (record + SH_DMA_ALLOC_RECORD_FLAGS) as *mut u64,
            if write_to_device != 0 {
                HOSTED_DMA_RECORD_FLAG_WRITE_TO_DEVICE
            } else {
                0
            },
        );
        write_volatile(
            (record + SH_DMA_ALLOC_RECORD_MAP_REGISTER) as *mut u64,
            map_register_base,
        );
        let count = read_volatile((FSD_SHARED_VADDR + SH_DMA_ALLOC_RECORD_COUNT) as *const u64);
        let used = ((record - FSD_SHARED_VADDR - SH_DMA_ALLOC_RECORDS) / SH_DMA_ALLOC_RECORD_SIZE)
            .saturating_add(1);
        if used > count {
            write_volatile(
                (FSD_SHARED_VADDR + SH_DMA_ALLOC_RECORD_COUNT) as *mut u64,
                used,
            );
        }
        let cursor = read_volatile((FSD_SHARED_VADDR + SH_DMA_ALLOC_CURSOR) as *const u64);
        let end = offset + mapped_len;
        if end > cursor {
            write_volatile((FSD_SHARED_VADDR + SH_DMA_ALLOC_CURSOR) as *mut u64, end);
        }
        write_unaligned(length, mapped_len as u32);
        trace_hosted_dma_sg(
            b"map",
            b"ok",
            STATUS_SUCCESS,
            adapter,
            mdl,
            current_va,
            mapped_len as u32,
            0,
            map_register_base,
            logical,
        );
        logical as i64
    }
}

unsafe fn dma_find_map_record(map_register_base: u64, source_va: u64) -> Option<u64> {
    let capacity = dma_allocation_record_capacity(FSD_SHARED_VADDR);
    let mut i = 0u64;
    while i < capacity {
        let record = dma_allocation_record(FSD_SHARED_VADDR, i)?;
        let kind = read_volatile((record + SH_DMA_ALLOC_RECORD_KIND) as *const u64);
        let token = read_volatile((record + SH_DMA_ALLOC_RECORD_MAP_REGISTER) as *const u64);
        let active_len = read_volatile((record + SH_DMA_ALLOC_RECORD_LEN) as *const u64);
        let active_source = read_volatile((record + SH_DMA_ALLOC_RECORD_SOURCE_VA) as *const u64);
        if kind == HOSTED_DMA_RECORD_KIND_MAP_TRANSFER
            && token == map_register_base
            && active_len != 0
            && (source_va == 0 || source_va == active_source)
        {
            return Some(record);
        }
        i += 1;
    }
    None
}

extern "win64" fn s_dma_flush_adapter_buffers(
    adapter: u64,
    _mdl: u64,
    map_register_base: u64,
    current_va: u64,
    length: u32,
    write_to_device: u8,
) -> u8 {
    unsafe {
        if dma_active_adapter_and_grant(adapter).is_none() || map_register_base == 0 {
            return 0;
        }
        let Some(record) = dma_find_map_record(map_register_base, current_va) else {
            return 0;
        };
        let mapped_len = read_volatile((record + SH_DMA_ALLOC_RECORD_LEN) as *const u64);
        let bounce_va = read_volatile((record + SH_DMA_ALLOC_RECORD_VA) as *const u64);
        let source_va = read_volatile((record + SH_DMA_ALLOC_RECORD_SOURCE_VA) as *const u64);
        if length as u64 > mapped_len || bounce_va == 0 || source_va == 0 {
            return 0;
        }
        if write_to_device == 0 {
            dma_copy_bytes(source_va, bounce_va, length as u64);
        }
        1
    }
}

extern "win64" fn s_dma_free_map_registers(
    _adapter: u64,
    map_register_base: u64,
    _number_of_map_registers: u32,
) {
    unsafe {
        if map_register_base == 0 {
            return;
        }
        let capacity = dma_allocation_record_capacity(FSD_SHARED_VADDR);
        let mut i = 0u64;
        while i < capacity {
            if let Some(record) = dma_allocation_record(FSD_SHARED_VADDR, i) {
                let kind = read_volatile((record + SH_DMA_ALLOC_RECORD_KIND) as *const u64);
                let token =
                    read_volatile((record + SH_DMA_ALLOC_RECORD_MAP_REGISTER) as *const u64);
                if kind == HOSTED_DMA_RECORD_KIND_MAP_TRANSFER && token == map_register_base {
                    clear_dma_allocation_record(record);
                }
            }
            i += 1;
        }
        if read_unaligned(map_register_base as *const u64) == HOSTED_DMA_MAP_REGISTER_SIGNATURE {
            pool_free(map_register_base);
        }
    }
}

extern "win64" fn s_dma_get_dma_alignment(_adapter: u64) -> u32 {
    4
}

extern "win64" fn s_dma_read_dma_counter(_adapter: u64) -> u32 {
    0
}

const HOSTED_SG_CONTEXT_SIZE: u64 = 0x30;
const HOSTED_SG_CONTEXT_SIGNATURE: u64 = 0x5347_4354_5830_3031; // "SGCTX001"
const HOSTED_SG_CONTEXT_MAP_REGISTER: u64 = 0x08;
const HOSTED_SG_CONTEXT_MDL: u64 = 0x10;
const HOSTED_SG_CONTEXT_CURRENT_VA: u64 = 0x18;
const HOSTED_SG_CONTEXT_LENGTH: u64 = 0x20;
const HOSTED_SG_CONTEXT_WRITE_TO_DEVICE: u64 = 0x28;
const HOSTED_SG_CONTEXT_LIST_OWNED: u64 = 0x29;
const HOSTED_SG_LIST_SIZE_ONE: u64 = 0x28;
const HOSTED_SG_ELEMENT_OFFSET: u64 = 0x10;

unsafe fn dma_allocate_map_register_token(number_of_map_registers: u32) -> u64 {
    if number_of_map_registers == 0 || number_of_map_registers > 64 {
        return 0;
    }
    let map_register = pool_alloc_zeroed(0x20);
    if map_register == 0 {
        return 0;
    }
    write_unaligned(map_register as *mut u64, HOSTED_DMA_MAP_REGISTER_SIGNATURE);
    write_unaligned((map_register + 8) as *mut u32, number_of_map_registers);
    map_register
}

unsafe fn dma_prepare_one_element_sg_list(
    adapter: u64,
    mdl: u64,
    current_va: u64,
    length: u32,
    write_to_device: u8,
    sg_list: u64,
    list_owned: u8,
) -> i32 {
    if length == 0 || sg_list == 0 || dma_active_adapter_and_grant(adapter).is_none() {
        trace_hosted_dma_sg(
            b"prepare",
            b"bad-input",
            STATUS_INVALID_PARAMETER,
            adapter,
            mdl,
            current_va,
            length,
            sg_list,
            0,
            0,
        );
        return STATUS_INVALID_PARAMETER;
    }
    let map_register = dma_allocate_map_register_token(1);
    let sg_context = pool_alloc_zeroed(HOSTED_SG_CONTEXT_SIZE);
    if map_register == 0 || sg_context == 0 {
        if map_register != 0 {
            pool_free(map_register);
        }
        if sg_context != 0 {
            pool_free(sg_context);
        }
        trace_hosted_dma_sg(
            b"prepare",
            b"alloc-failed",
            STATUS_INSUFFICIENT_RESOURCES,
            adapter,
            mdl,
            current_va,
            length,
            sg_list,
            map_register,
            0,
        );
        return STATUS_INSUFFICIENT_RESOURCES;
    }
    let mut mapped_len = length;
    let logical = s_dma_map_transfer(
        adapter,
        mdl,
        map_register,
        current_va,
        &mut mapped_len as *mut u32,
        write_to_device,
    ) as u64;
    if logical == 0 || mapped_len == 0 {
        pool_free(sg_context);
        pool_free(map_register);
        trace_hosted_dma_sg(
            b"prepare",
            b"map-failed",
            STATUS_INSUFFICIENT_RESOURCES,
            adapter,
            mdl,
            current_va,
            length,
            sg_list,
            map_register,
            logical,
        );
        return STATUS_INSUFFICIENT_RESOURCES;
    }

    write_unaligned(sg_context as *mut u64, HOSTED_SG_CONTEXT_SIGNATURE);
    write_unaligned(
        (sg_context + HOSTED_SG_CONTEXT_MAP_REGISTER) as *mut u64,
        map_register,
    );
    write_unaligned((sg_context + HOSTED_SG_CONTEXT_MDL) as *mut u64, mdl);
    write_unaligned(
        (sg_context + HOSTED_SG_CONTEXT_CURRENT_VA) as *mut u64,
        current_va,
    );
    write_unaligned(
        (sg_context + HOSTED_SG_CONTEXT_LENGTH) as *mut u32,
        mapped_len,
    );
    write_unaligned(
        (sg_context + HOSTED_SG_CONTEXT_WRITE_TO_DEVICE) as *mut u8,
        write_to_device,
    );
    write_unaligned(
        (sg_context + HOSTED_SG_CONTEXT_LIST_OWNED) as *mut u8,
        list_owned,
    );

    write_unaligned(sg_list as *mut u32, 1);
    write_unaligned((sg_list + 8) as *mut u64, sg_context);
    write_unaligned((sg_list + HOSTED_SG_ELEMENT_OFFSET) as *mut u64, logical);
    write_unaligned(
        (sg_list + HOSTED_SG_ELEMENT_OFFSET + 8) as *mut u32,
        mapped_len,
    );
    write_unaligned((sg_list + HOSTED_SG_ELEMENT_OFFSET + 16) as *mut u64, 0);
    trace_hosted_dma_sg(
        b"prepare",
        b"ok",
        STATUS_SUCCESS,
        adapter,
        mdl,
        current_va,
        mapped_len,
        sg_list,
        map_register,
        logical,
    );
    STATUS_SUCCESS
}

#[allow(clippy::too_many_arguments)]
extern "win64" fn s_dma_get_scatter_gather_list(
    adapter: u64,
    device_object: u64,
    mdl: u64,
    current_va: u64,
    length: u32,
    execution_routine: u64,
    context: u64,
    write_to_device: u8,
) -> i32 {
    unsafe {
        if execution_routine == 0 || length == 0 || dma_active_adapter_and_grant(adapter).is_none()
        {
            trace_hosted_dma_sg(
                b"get",
                b"bad-input",
                STATUS_INVALID_PARAMETER,
                adapter,
                mdl,
                current_va,
                length,
                0,
                0,
                0,
            );
            return STATUS_INVALID_PARAMETER;
        }
        let sg_list = pool_alloc_zeroed(HOSTED_SG_LIST_SIZE_ONE);
        if sg_list == 0 {
            trace_hosted_dma_sg(
                b"get",
                b"list-alloc-failed",
                STATUS_INSUFFICIENT_RESOURCES,
                adapter,
                mdl,
                current_va,
                length,
                0,
                0,
                0,
            );
            return STATUS_INSUFFICIENT_RESOURCES;
        }
        let status = dma_prepare_one_element_sg_list(
            adapter,
            mdl,
            current_va,
            length,
            write_to_device,
            sg_list,
            1,
        );
        if status != 0 {
            pool_free(sg_list);
            trace_hosted_dma_sg(
                b"get",
                b"prepare-failed",
                status,
                adapter,
                mdl,
                current_va,
                length,
                sg_list,
                0,
                0,
            );
            return status;
        }

        let routine: extern "win64" fn(u64, u64, u64, u64) =
            core::mem::transmute(execution_routine as *const ());
        routine(device_object, 0, sg_list, context);
        trace_hosted_dma_sg(
            b"get",
            b"routine-returned",
            STATUS_SUCCESS,
            adapter,
            mdl,
            current_va,
            length,
            sg_list,
            0,
            0,
        );
        STATUS_SUCCESS
    }
}

extern "win64" fn s_dma_calculate_scatter_gather_list(
    adapter: u64,
    _mdl: u64,
    _current_va: u64,
    length: u32,
    scatter_gather_list_size: *mut u32,
    number_of_map_registers: *mut u32,
) -> i32 {
    unsafe {
        let Some((_grant_va, grant_len, _grant_logical)) = dma_active_adapter_and_grant(adapter)
        else {
            return 0xC000_000Du32 as i32; // STATUS_INVALID_PARAMETER
        };
        if length == 0 || scatter_gather_list_size.is_null() {
            return 0xC000_000Du32 as i32; // STATUS_INVALID_PARAMETER
        }
        if length as u64 > grant_len {
            return 0xC000_009Au32 as i32; // STATUS_INSUFFICIENT_RESOURCES
        }
        write_unaligned(scatter_gather_list_size, HOSTED_SG_LIST_SIZE_ONE as u32);
        if !number_of_map_registers.is_null() {
            write_unaligned(number_of_map_registers, 1);
        }
        0
    }
}

#[allow(clippy::too_many_arguments)]
extern "win64" fn s_dma_build_scatter_gather_list(
    adapter: u64,
    device_object: u64,
    mdl: u64,
    current_va: u64,
    length: u32,
    execution_routine: u64,
    context: u64,
    write_to_device: u8,
    scatter_gather_buffer: u64,
    scatter_gather_length: u32,
) -> i32 {
    unsafe {
        if execution_routine == 0 || scatter_gather_buffer == 0 {
            return 0xC000_000Du32 as i32; // STATUS_INVALID_PARAMETER
        }
        if scatter_gather_length < HOSTED_SG_LIST_SIZE_ONE as u32 {
            return 0xC000_0023u32 as i32; // STATUS_BUFFER_TOO_SMALL
        }
        let status = dma_prepare_one_element_sg_list(
            adapter,
            mdl,
            current_va,
            length,
            write_to_device,
            scatter_gather_buffer,
            0,
        );
        if status != 0 {
            return status;
        }
        let routine: extern "win64" fn(u64, u64, u64, u64) =
            core::mem::transmute(execution_routine as *const ());
        routine(device_object, 0, scatter_gather_buffer, context);
        0
    }
}

extern "win64" fn s_dma_build_mdl_from_scatter_gather_list(
    _adapter: u64,
    _scatter_gather: u64,
    _original_mdl: u64,
    target_mdl: *mut u64,
) -> i32 {
    unsafe {
        if !target_mdl.is_null() {
            write_unaligned(target_mdl, 0);
        }
    }
    0xC000_00BBu32 as i32 // STATUS_NOT_SUPPORTED
}

extern "win64" fn s_dma_put_scatter_gather_list(
    adapter: u64,
    scatter_gather: u64,
    write_to_device: u8,
) {
    unsafe {
        if scatter_gather == 0 {
            return;
        }
        let sg_context = read_unaligned((scatter_gather + 8) as *const u64);
        if sg_context == 0
            || read_unaligned(sg_context as *const u64) != HOSTED_SG_CONTEXT_SIGNATURE
        {
            return;
        }
        let map_register =
            read_unaligned((sg_context + HOSTED_SG_CONTEXT_MAP_REGISTER) as *const u64);
        let mdl = read_unaligned((sg_context + HOSTED_SG_CONTEXT_MDL) as *const u64);
        let current_va = read_unaligned((sg_context + HOSTED_SG_CONTEXT_CURRENT_VA) as *const u64);
        let length = read_unaligned((sg_context + HOSTED_SG_CONTEXT_LENGTH) as *const u32);
        let stored_write_to_device =
            read_unaligned((sg_context + HOSTED_SG_CONTEXT_WRITE_TO_DEVICE) as *const u8);
        let list_owned = read_unaligned((sg_context + HOSTED_SG_CONTEXT_LIST_OWNED) as *const u8);
        let direction = if write_to_device != 0 {
            write_to_device
        } else {
            stored_write_to_device
        };
        let _ =
            s_dma_flush_adapter_buffers(adapter, mdl, map_register, current_va, length, direction);
        s_dma_free_map_registers(adapter, map_register, 1);
        pool_free(sg_context);
        if list_owned != 0 {
            pool_free(scatter_gather);
        }
    }
}

/// `NTSTATUS IoCreateSymbolicLink(PUNICODE_STRING, PUNICODE_STRING)`.
extern "win64" fn s_io_create_symbolic_link(link: u64, target: u64) -> i32 {
    unsafe {
        clear_shared_path_len(SH_SYMLINK_LINK_LEN);
        clear_shared_path_len(SH_SYMLINK_TARGET_LEN);
        let Some((link_buf, link_len)) = unicode_string_parts(link) else {
            return 0xC000_000Du32 as i32; // STATUS_INVALID_PARAMETER
        };
        let Some((target_buf, target_len)) = unicode_string_parts(target) else {
            return 0xC000_000Du32 as i32; // STATUS_INVALID_PARAMETER
        };
        copy_wstr_to_shared(link_buf, link_len, SH_SYMLINK_LINK_LEN, SH_SYMLINK_LINK_BUF);
        copy_wstr_to_shared(
            target_buf,
            target_len,
            SH_SYMLINK_TARGET_LEN,
            SH_SYMLINK_TARGET_BUF,
        );
        let status = hosted_symbolic_link_operation(HOSTED_DEVICE_OP_CREATE_SYMBOLIC_LINK);
        clear_shared_path_len(SH_SYMLINK_LINK_LEN);
        clear_shared_path_len(SH_SYMLINK_TARGET_LEN);
        if status >= 0 {
            let v = read_volatile((FSD_SHARED_VADDR + SH_VERDICT) as *const u32);
            write_volatile((FSD_SHARED_VADDR + SH_VERDICT) as *mut u32, v | V_SYMLINK);
        }
        status
    }
}

/// `NTSTATUS IoDeleteSymbolicLink(PUNICODE_STRING)`.
extern "win64" fn s_io_delete_symbolic_link(link: u64) -> i32 {
    unsafe {
        clear_shared_path_len(SH_SYMLINK_LINK_LEN);
        clear_shared_path_len(SH_SYMLINK_TARGET_LEN);
        let Some((link_buf, link_len)) = unicode_string_parts(link) else {
            return 0xC000_000Du32 as i32; // STATUS_INVALID_PARAMETER
        };
        copy_wstr_to_shared(link_buf, link_len, SH_SYMLINK_LINK_LEN, SH_SYMLINK_LINK_BUF);
        let status = hosted_symbolic_link_operation(HOSTED_DEVICE_OP_DELETE_SYMBOLIC_LINK);
        clear_shared_path_len(SH_SYMLINK_LINK_LEN);
        status
    }
}

/// `void IoRegisterFileSystem(PDEVICE_OBJECT)`. Record that the FSD registered; no queue to maintain
/// (the executive routes named-pipe/file paths to the recorded device directly).
extern "win64" fn s_io_register_file_system(_dev: u64) {
    unsafe {
        let v = read_volatile((FSD_SHARED_VADDR + SH_VERDICT) as *const u32);
        write_volatile((FSD_SHARED_VADDR + SH_VERDICT) as *mut u32, v | V_REGFS);
    }
}

unsafe fn finish_driver_local_irp(irp: u64) {
    let status = read_unaligned((irp + WDM_X64_IRP_IO_STATUS_STATUS_OFFSET) as *const i32);
    let information =
        read_unaligned((irp + WDM_X64_IRP_IO_STATUS_INFORMATION_OFFSET) as *const u64);
    let user_iosb = read_unaligned((irp + 0x48) as *const u64);
    let user_event = read_unaligned((irp + 0x50) as *const u64);
    if user_iosb != 0 {
        write_unaligned(user_iosb as *mut i32, status);
        write_unaligned((user_iosb + 8) as *mut u64, information);
    }
    if user_event != 0 {
        let _ = s_ke_set_event(user_event, 0, 0);
    }

    let flags = read_unaligned((irp + 0x10) as *const u32);
    let system_buffer = read_unaligned((irp + 0x18) as *const u64);
    let user_buffer = read_unaligned((irp + 0x70) as *const u64);
    let mdl = read_unaligned((irp + 0x08) as *const u64);
    if flags & (IRP_BUFFERED_IO | IRP_INPUT_OPERATION)
        == (IRP_BUFFERED_IO | IRP_INPUT_OPERATION)
        && system_buffer != 0
        && user_buffer != 0
        && status as u32 != 0x8000_0016 // STATUS_VERIFY_REQUIRED
        && (status as u32 >> 30) != 3
    {
        let copy_len = component_pool_allocation_capacity(system_buffer)
            .map(|capacity| information.min(capacity))
            .unwrap_or(0);
        if copy_len != 0 {
            core::ptr::copy_nonoverlapping(
                system_buffer as *const u8,
                user_buffer as *mut u8,
                copy_len as usize,
            );
        }
    }
    if flags & IRP_DEALLOCATE_BUFFER != 0
        && system_buffer != 0
        && component_pool_allocation_capacity(system_buffer).is_some()
    {
        pool_free(system_buffer);
    }
    if mdl != 0 && component_pool_allocation_capacity(mdl).is_some() {
        s_io_free_mdl(mdl);
    }
    pool_free(irp);
}

/// `void IoCompleteRequest(PIRP, CCHAR)`. Every raw WDM IRP uses the same native completion-stack
/// walk. Requestor IRPs publish through their exact retained owner only after the walk reaches the
/// top; driver-local IRPs use normal IOSB/event delivery and are then reclaimed.
extern "win64" fn s_io_complete_request(irp: u64, _boost: u64) {
    unsafe {
        let claim = claim_pending_irp_completion(irp);
        if claim.is_none() && pending_irp_raw_identity_exists(irp) {
            panic!("IoCompleteRequest attempted to complete an owned IRP twice");
        }
        let active_seq = FSD_ACTIVE_DISPATCH_SEQ.load(Ordering::Relaxed);
        if active_seq >= 128 && FSD_ACTIVE_COMPLETE_TRACE_COUNT.fetch_add(1, Ordering::Relaxed) < 16
        {
            print_str(b"[fsd-complete-active] seq=");
            print_u64(active_seq);
            print_str(b" irp=");
            print_hex64(irp);
            if irp >= FSD_POOL_VADDR + POOL_DATA_OFF
                && irp + WDM_X64_IRP_SIZE as u64 <= FSD_POOL_VADDR + FSD_POOL_FRAMES * 0x1000
            {
                print_str(b" status=");
                print_hex(read_unaligned(
                    (irp + WDM_X64_IRP_IO_STATUS_STATUS_OFFSET) as *const u32,
                ));
                print_str(b" info=");
                print_u64(read_unaligned((irp + 0x38) as *const u64));
            }
            print_str(b"\n");
        }
        // DIAGNOSTIC heartbeat: `NpCompleteDeferredIrps` walks a driver-built LIST_ENTRY chain, so a
        // corrupted (cyclic) deferred list becomes an unbounded completion loop with no other output.
        {
            let calls = IO_COMPLETE_CALLS.fetch_add(1, Ordering::Relaxed) + 1;
            if calls % 4096 == 0 {
                print_str(b"[fsd-complete-heartbeat] calls=");
                print_u64(calls);
                print_str(b" irp=");
                print_hex(irp as u32);
                print_str(b"\n");
            }
        }
        if validate_hosted_irp_packet(irp).is_none() {
            if let Some(claim) = claim {
                restore_pending_irp_completion_claim(claim);
            }
            panic!("IoCompleteRequest received an invalid hosted IRP stack");
        }
        if read_unaligned((irp + WDM_X64_IRP_IO_STATUS_STATUS_OFFSET) as *const u32)
            == STATUS_PENDING
        {
            if let Some(claim) = claim {
                restore_pending_irp_completion_claim(claim);
            }
            panic!("IoCompleteRequest cannot complete an IRP with STATUS_PENDING");
        }
        if read_unaligned((irp + WDM_X64_IRP_CANCEL_ROUTINE_OFFSET) as *const u64) != 0 {
            if let Some(claim) = claim {
                restore_pending_irp_completion_claim(claim);
            }
            panic!("IoCompleteRequest received an IRP with a live cancel routine");
        }
        match unwind_hosted_irp(irp) {
            Ok(HostedIrpUnwindOutcome::MoreProcessingRequired) => {
                if let Some(claim) = claim {
                    park_pending_irp_completion_claim(claim);
                }
                return;
            }
            Ok(HostedIrpUnwindOutcome::Terminal) => {}
            Err(()) => {
                if let Some(claim) = claim {
                    restore_pending_irp_completion_claim(claim);
                }
                panic!("IoCompleteRequest received an invalid hosted IRP stack");
            }
        }
        if read_unaligned((irp + WDM_X64_IRP_IO_STATUS_STATUS_OFFSET) as *const u32)
            == STATUS_PENDING
        {
            panic!("completion routine left a terminal IRP with STATUS_PENDING");
        }
        let Some(claim) = claim else {
            finish_driver_local_irp(irp);
            return;
        };
        let node = claim.node;
        let target = claim.target;
        let status = read_unaligned((irp + WDM_X64_IRP_IO_STATUS_STATUS_OFFSET) as *const u32);
        let information = read_unaligned((irp + 0x38) as *const u64);
        // A completing pending READ carries the peer's just-written payload in its IRP buffer. Retain
        // those bytes under the canonical IRP id so the executive delivers them to the exact waiter.
        // A fresh read would miss because NPFS already drained the queue into this IRP. NPFS can
        // replace a buffered read's AssociatedIrp.SystemBuffer while completing a queued read, so
        // the current IRP field, rather than the request's original buffer, is authoritative.
        // The buffer the driver actually filled is the live SystemBuffer. NPFS may replace the
        // original buffered-I/O allocation while completing a queued read.
        let sysbuf = read_unaligned((irp + 0x18) as *const u64);
        let irp_flags = read_unaligned((irp + 0x10) as *const u32);
        let length = information.min(target.output_capacity).min(u32::MAX as u64) as usize;
        let source = if length == 0 {
            0
        } else if target.completion_source_kind == COMPLETION_SOURCE_REQUEST_DATA {
            target.data
        } else if sysbuf != 0 {
            sysbuf
        } else {
            target.data
        };
        let source_valid = length == 0
            || component_pool_allocation_capacity(source)
                .is_some_and(|capacity| length as u64 <= capacity);
        let reclaim = if irp_flags & IRP_DEALLOCATE_BUFFER != 0 {
            sysbuf
        } else {
            0
        };
        let reclaim_valid = reclaim == 0 || component_pool_allocation_capacity(reclaim).is_some();
        let information_within_output =
            target.output_capacity == 0 || information <= target.output_capacity;
        let filter_requirements = target.major as u64 == IRP_MJ_PNP
            && target.minor as u64 == IRP_MN_FILTER_RESOURCE_REQUIREMENTS;
        let returned_allocation_valid = !filter_requirements
            || information == 0
            || component_pool_allocation_capacity(information).is_some();
        let completion_valid =
            source_valid && reclaim_valid && information_within_output && returned_allocation_valid;
        if completion_valid && filter_requirements && information == target.data {
            write_volatile(
                (pending_irp_entry_address(node) + core::mem::offset_of!(PendingIrp, data) as u64)
                    as *mut u64,
                0,
            );
        }
        let sequence = next_completion_seq(FSD_DATA_VADDR);
        let mut completion = nt_io_manager::RetainedIrpCompletion::pending();
        if completion
            .complete(
                sequence,
                if completion_valid {
                    status
                } else {
                    0xC000_0005
                },
                if completion_valid { information } else { 0 },
                if completion_valid { source } else { 0 },
                if reclaim_valid { reclaim } else { 0 },
                if completion_valid { length as u32 } else { 0 },
                irp_flags,
            )
            .is_err()
        {
            panic!("hosted driver completed the same retained IRP twice");
        }
        write_volatile(
            (pending_irp_entry_address(node) + core::mem::offset_of!(PendingIrp, completion) as u64)
                as *mut nt_io_manager::RetainedIrpCompletion,
            completion,
        );
        release_pending_irp_completion_claim(
            claim,
            nt_io_manager::CompletionClaimRelease::Terminal,
        );
        if PEER_COMPLETION_TRACE_COUNT.fetch_add(1, Ordering::Relaxed) < 8 {
            print_str(b"[fsd-peer-complete] major=");
            print_u64(target.major as u64);
            print_str(b" status=0x");
            print_hex(status);
            print_str(b" info=");
            print_u64(information);
            print_str(b"\n");
        }
    }
}

/// `PVOID IoAllocateErrorLogEntry(PVOID, UCHAR)`.
extern "win64" fn s_io_allocate_error_log_entry(_io_object: u64, entry_size: u8) -> u64 {
    unsafe {
        let size = (entry_size as u64).max(0x30);
        let entry = pool_alloc(size);
        if entry != 0 {
            core::ptr::write_bytes(entry as *mut u8, 0, size as usize);
            write_unaligned(entry as *mut u8, entry_size);
        }
        entry
    }
}

/// `VOID IoWriteErrorLogEntry(PVOID)`.
extern "win64" fn s_io_write_error_log_entry(entry: u64) {
    unsafe {
        if entry != 0 {
            pool_free(entry);
        }
    }
}

// --- REAL VCB internals: the Unicode prefix table (name -> FCB), generic table, ERESOURCE ---------
//
// An FSD's DriverEntry runs its OWN `NpInitializeVcb`/`NpCreateRootDcb`, and every create/open runs
// its OWN `NpFsdCreate*` → `NpCreateFcb`/`NpCreateCcb`. Those exercise the prefix table + resource for
// REAL (the create path bug-checks on a NULL `RtlFindUnicodePrefix`, and create-then-connect must find
// the FCB by name). So these trampolines carry real host-side logic, backed by a fixed-capacity static
// table (no `alloc` in the isolated component). The prefix-MATCH contract is the host-tested
// [`nt_kernel_exec::np_prefix`] logic (component-prefix, case-insensitive, longest wins).
//
// `RtlInsertUnicodePrefix(Table, &Fcb->FullName, &Fcb->PrefixTableEntry)` records the entry pointer
// the FSD passed (so `RtlFindUnicodePrefix` can return the SAME pointer → `CONTAINING_RECORD` recovers
// the FCB). `RtlFindUnicodePrefix(Table, FullName, _)` returns the recorded entry of the longest name
// that is a component-prefix of `FullName`.

/// A recorded prefix-table entry: (the caller's `PUNICODE_PREFIX_TABLE_ENTRY`, the name VA, len-bytes).
/// The name is a `UNICODE_STRING.Buffer` (UTF-16); we read it live from the FSD's own pool at Find time.
#[derive(Clone, Copy)]
struct PrefixSlot {
    entry: u64, // the PUNICODE_PREFIX_TABLE_ENTRY the FSD passed to Insert (returned by Find)
    name_va: u64, // UNICODE_STRING.Buffer VA
    name_len: u16, // UNICODE_STRING.Length (bytes)
    used: bool,
}

impl PrefixSlot {
    const fn empty() -> Self {
        Self {
            entry: 0,
            name_va: 0,
            name_len: 0,
            used: false,
        }
    }
}

/// The single VCB prefix table (npfs is a singleton driver). Populated by
/// `s_rtl_insert_unicode_prefix`, queried by `s_rtl_find_unicode_prefix`, and reset by
/// `s_rtl_init_unicode_prefix`.
static mut PREFIX_TABLE: Option<Vec<PrefixSlot>> = None;

unsafe fn prefix_table_mut() -> &'static mut Vec<PrefixSlot> {
    let slot = &mut *core::ptr::addr_of_mut!(PREFIX_TABLE);
    if slot.is_none() {
        *slot = Some(Vec::new());
    }
    slot.as_mut().unwrap()
}

unsafe fn prefix_table() -> Option<&'static Vec<PrefixSlot>> {
    (&*core::ptr::addr_of!(PREFIX_TABLE)).as_ref()
}

/// Copy a UNICODE_STRING.Buffer (UTF-16) into a fixed scratch for comparison. Returns the length in
/// u16 units (capped at the scratch size). Pipe names are short (`\ntsvcs` = 7).
unsafe fn read_ustr16(buf_va: u64, len_bytes: u16, out: &mut [u16]) -> usize {
    let n = ((len_bytes as usize) / 2).min(out.len());
    for i in 0..n {
        out[i] = read_unaligned((buf_va + (i as u64) * 2) as *const u16);
    }
    n
}

/// `void RtlInitializeUnicodePrefix(PUNICODE_PREFIX_TABLE)` — zero the control struct AND clear the
/// host-side table (the FSD calls this once at NpInitializeVcb before inserting the root DCB).
extern "win64" fn s_rtl_init_unicode_prefix(tbl: u64) {
    unsafe {
        if tbl != 0 {
            // UNICODE_PREFIX_TABLE (0x14 bytes): zero it (NodeTypeCode/NameLength/NextPrefixTree/…).
            write_unaligned(tbl as *mut u64, 0);
            write_unaligned((tbl + 8) as *mut u64, 0);
            write_unaligned((tbl + 16) as *mut u32, 0);
        }
        if let Some(table) = (*core::ptr::addr_of_mut!(PREFIX_TABLE)).as_mut() {
            table.clear();
        }
    }
}

/// `BOOLEAN RtlInsertUnicodePrefix(PUNICODE_PREFIX_TABLE, PUNICODE_STRING Prefix,
/// PUNICODE_PREFIX_TABLE_ENTRY PrefixTableEntry)`. Record (entry, name) so Find returns this entry for
/// names of which `Prefix` is a component-prefix. Returns TRUE unless a duplicate exact name exists.
extern "win64" fn s_rtl_insert_unicode_prefix(_tbl: u64, prefix: u64, entry: u64) -> u64 {
    if prefix == 0 || entry == 0 {
        return 0;
    }
    unsafe {
        let name_len = read_unaligned(prefix as *const u16); // UNICODE_STRING.Length
        let name_va = read_unaligned((prefix + 8) as *const u64); // UNICODE_STRING.Buffer
        let table = prefix_table_mut();
        // dedup: an identical (case-insensitive) name already present → FALSE (the FSD bug-checks on
        // this, meaning it never re-creates the same pipe; our create arm rejects duplicates first).
        let mut new: [u16; 128] = [0; 128];
        let nn = read_ustr16(name_va, name_len, &mut new);
        for s in table.iter() {
            if !s.used {
                continue;
            }
            let mut ex: [u16; 128] = [0; 128];
            let en = read_ustr16(s.name_va, s.name_len, &mut ex);
            if en == nn
                && nt_kernel_exec::np_prefix::is_component_prefix(&ex[..en], &new[..nn])
                && nn == en
            {
                return 0; // duplicate
            }
        }
        for s in table.iter_mut() {
            if !s.used {
                *s = PrefixSlot {
                    entry,
                    name_va,
                    name_len,
                    used: true,
                };
                return 1;
            }
        }
        table.push(PrefixSlot {
            entry,
            name_va,
            name_len,
            used: true,
        });
        1
    }
}

/// `PUNICODE_PREFIX_TABLE_ENTRY RtlFindUnicodePrefix(PUNICODE_PREFIX_TABLE, PUNICODE_STRING FullName,
/// ULONG CaseInsensitiveIndex)`. Return the recorded entry of the longest inserted name that is a
/// component-prefix of `FullName` (NULL if none — the FSD bug-checks, but the root `\` always matches).
extern "win64" fn s_rtl_find_unicode_prefix(_tbl: u64, full: u64, _ci: u64) -> u64 {
    if full == 0 {
        return 0;
    }
    unsafe {
        let full_len = read_unaligned(full as *const u16);
        let full_va = read_unaligned((full + 8) as *const u64);
        let mut fbuf: [u16; 256] = [0; 256];
        let fn_ = read_ustr16(full_va, full_len, &mut fbuf);
        let Some(table) = prefix_table() else {
            return 0;
        };
        let mut best_entry = 0u64;
        let mut best_len = 0usize; // matched name length in u16 units
                                   // Compare against each used slot; keep the longest component-prefix.
        let mut cbuf: [u16; 128] = [0; 128];
        for s in table.iter() {
            if !s.used {
                continue;
            }
            let cn = read_ustr16(s.name_va, s.name_len, &mut cbuf);
            if nt_kernel_exec::np_prefix::is_component_prefix(&cbuf[..cn], &fbuf[..fn_])
                && cn >= best_len
            {
                best_len = cn;
                best_entry = s.entry;
            }
        }
        let _ = full_len;
        best_entry
    }
}

/// `void RtlInitializeGenericTable(PRTL_GENERIC_TABLE, ...)` — zero the 0x48-byte control struct +
/// stash the callbacks (the FSD's EventTable is only exercised on pipe-state-change notify — no live
/// consumer in bring-up, so a zeroing init suffices for it to be enumerable-empty).
extern "win64" fn s_rtl_init_generic_table(tbl: u64, cmp: u64, alloc: u64, free: u64, ctx: u64) {
    if tbl != 0 {
        unsafe {
            let mut i = 0u64;
            while i < 0x48 {
                write_unaligned((tbl + i) as *mut u64, 0);
                i += 8;
            }
            // RTL_GENERIC_TABLE: CompareRoutine@0x28, AllocateRoutine@0x30, FreeRoutine@0x38, Context@0x40.
            write_unaligned((tbl + 0x28) as *mut u64, cmp);
            write_unaligned((tbl + 0x30) as *mut u64, alloc);
            write_unaligned((tbl + 0x38) as *mut u64, free);
            write_unaligned((tbl + 0x40) as *mut u64, ctx);
        }
    }
}

/// `BOOLEAN RtlDeleteElementGenericTable(PRTL_GENERIC_TABLE, PVOID)`.
extern "win64" fn s_rtl_delete_element_generic_table(_tbl: u64, _buffer: u64) -> u8 {
    0
}

/// `VOID RtlRemoveUnicodePrefix(PUNICODE_PREFIX_TABLE, PUNICODE_PREFIX_TABLE_ENTRY)`.
extern "win64" fn s_rtl_remove_unicode_prefix(_tbl: u64, entry: u64) {
    if entry == 0 {
        return;
    }
    unsafe {
        let table = prefix_table_mut();
        for slot in table.iter_mut() {
            if slot.used && slot.entry == entry {
                *slot = PrefixSlot::empty();
                return;
            }
        }
    }
}

const RTL_QUERY_REGISTRY_TABLE_SIZE: u64 = 56;
const RTL_QUERY_REGISTRY_SUBKEY: u32 = 0x0000_0001;
const RTL_QUERY_REGISTRY_REQUIRED: u32 = 0x0000_0004;
const RTL_QUERY_REGISTRY_NOVALUE: u32 = 0x0000_0008;
const RTL_QUERY_REGISTRY_DIRECT: u32 = 0x0000_0020;
const REG_NONE: u32 = 0;
const REG_SZ: u32 = 1;
const REG_EXPAND_SZ: u32 = 2;
const REG_BINARY: u32 = 3;
const REG_DWORD: u32 = 4;
const REG_MULTI_SZ: u32 = 7;
const KEY_BASIC_INFORMATION_CLASS: u32 = 0;
const KEY_VALUE_PARTIAL_INFORMATION_CLASS: u32 = 2;

/// `NTSTATUS RtlQueryRegistryValues(...)` for hosted FSD service parameters.
///
/// The FSD host does not keep a private registry mirror. Current ReactOS FSD callers use this during
/// initialization for optional service parameters and defaults, so the explicit hosted behavior is:
/// apply caller-provided defaults, report missing required values, and enumerate empty optional keys.
extern "win64" fn s_rtl_query_registry_values(
    relative_to: u32,
    path: u64,
    query_table: u64,
    context: u64,
    _environment: u64,
) -> i32 {
    if query_table == 0 {
        return STATUS_INVALID_PARAMETER;
    }
    unsafe {
        let registry_path = wide_cstr_to_hosted_ascii::<HOSTED_REGISTRY_PATH_MAX>(path);
        let cm_registry_path = registry_path
            .as_ref()
            .and_then(|path| cm_registry_path_from_rtl_path(relative_to, path));
        let mut idx = 0u64;
        while idx < 64 {
            let entry = query_table + idx * RTL_QUERY_REGISTRY_TABLE_SIZE;
            let routine = read_unaligned(entry as *const u64);
            let flags = read_unaligned((entry + 8) as *const u32);
            let name = read_unaligned((entry + 16) as *const u64);
            let entry_context = read_unaligned((entry + 24) as *const u64);
            let default_type = read_unaligned((entry + 32) as *const u32);
            let default_data = read_unaligned((entry + 40) as *const u64);
            let default_length = read_unaligned((entry + 48) as *const u32);

            if routine == 0
                && (flags & (RTL_QUERY_REGISTRY_SUBKEY | RTL_QUERY_REGISTRY_DIRECT)) == 0
            {
                break;
            }

            if (flags & RTL_QUERY_REGISTRY_DIRECT) != 0 {
                if name == 0 || routine != 0 || (flags & RTL_QUERY_REGISTRY_SUBKEY) != 0 {
                    return STATUS_INVALID_PARAMETER;
                }
                let value_name = wide_cstr_to_hosted_ascii::<HOSTED_REGISTRY_PATH_MAX>(name);
                let mut value_found = false;
                if let (Some(key_path), Some(value_name)) = (cm_registry_path.as_ref(), value_name)
                {
                    let (status, value_type, data_len) =
                        broker_query_registry_path_value(key_path, &value_name);
                    match status {
                        STATUS_SUCCESS => {
                            let data = registry_arg_data_slice(data_len);
                            let status =
                                write_rtl_direct_registry_value(value_type, data, entry_context);
                            if status < 0 {
                                return status;
                            }
                            value_found = true;
                        }
                        STATUS_OBJECT_NAME_NOT_FOUND => {}
                        status => return status,
                    }
                }
                if !value_found && entry_context != 0 && default_data != 0 && default_length != 0 {
                    let copy_len = (default_length as u64).min(4096);
                    copy_bytes_unchecked(entry_context, default_data, copy_len);
                } else if !value_found && (flags & RTL_QUERY_REGISTRY_REQUIRED) != 0 {
                    return STATUS_OBJECT_NAME_NOT_FOUND;
                }
                idx += 1;
                continue;
            }

            if (flags & RTL_QUERY_REGISTRY_SUBKEY) != 0 {
                if name == 0 {
                    return STATUS_INVALID_PARAMETER;
                }
                if routine == 0 {
                    idx += 1;
                    continue;
                }
            }

            if (flags & RTL_QUERY_REGISTRY_NOVALUE) != 0 && routine != 0 {
                let f: extern "win64" fn(u64, u32, u64, u32, u64, u64) -> i32 =
                    core::mem::transmute(routine as *const ());
                let status = f(0, REG_NONE, 0, 0, context, entry_context);
                if status < 0 {
                    return status;
                }
                idx += 1;
                continue;
            }

            if routine != 0 && name != 0 {
                let f: extern "win64" fn(u64, u32, u64, u32, u64, u64) -> i32 =
                    core::mem::transmute(routine as *const ());
                let status = if default_data != 0 || default_length != 0 {
                    f(
                        name,
                        default_type,
                        default_data,
                        default_length,
                        context,
                        entry_context,
                    )
                } else {
                    f(name, REG_NONE, 0, 0, context, entry_context)
                };
                if status < 0 {
                    return status;
                }
            } else if routine != 0 && (flags & RTL_QUERY_REGISTRY_REQUIRED) != 0 {
                return STATUS_OBJECT_NAME_NOT_FOUND;
            }
            idx += 1;
        }
    }
    STATUS_SUCCESS
}

unsafe fn list_insert_between(entry: u64, prev: u64, next: u64) {
    write_unaligned(entry as *mut u64, next);
    write_unaligned((entry + 8) as *mut u64, prev);
    write_unaligned((prev) as *mut u64, entry);
    write_unaligned((next + 8) as *mut u64, entry);
}

/// `PLIST_ENTRY ExInterlockedInsertTailList(PLIST_ENTRY Head, PLIST_ENTRY Entry, PKSPIN_LOCK)`.
extern "win64" fn s_ex_interlocked_insert_tail_list(head: u64, entry: u64, _lock: u64) -> u64 {
    if head == 0 || entry == 0 {
        return 0;
    }
    unsafe {
        let old_tail = read_unaligned((head + 8) as *const u64);
        let tail = if old_tail == 0 { head } else { old_tail };
        list_insert_between(entry, tail, head);
        old_tail
    }
}

/// `PLIST_ENTRY ExInterlockedInsertHeadList(PLIST_ENTRY Head, PLIST_ENTRY Entry, PKSPIN_LOCK)`.
extern "win64" fn s_ex_interlocked_insert_head_list(head: u64, entry: u64, _lock: u64) -> u64 {
    if head == 0 || entry == 0 {
        return 0;
    }
    unsafe {
        let old_head = read_unaligned(head as *const u64);
        let first = if old_head == 0 { head } else { old_head };
        list_insert_between(entry, head, first);
        old_head
    }
}

/// `PLIST_ENTRY ExInterlockedRemoveHeadList(PLIST_ENTRY Head, PKSPIN_LOCK)`.
extern "win64" fn s_ex_interlocked_remove_head_list(head: u64, _lock: u64) -> u64 {
    if head == 0 {
        return 0;
    }
    unsafe {
        let first = read_unaligned(head as *const u64);
        if first == 0 || first == head {
            return 0;
        }
        let next = read_unaligned(first as *const u64);
        write_unaligned(head as *mut u64, next);
        write_unaligned((next + 8) as *mut u64, head);
        write_unaligned(first as *mut u64, first);
        write_unaligned((first + 8) as *mut u64, first);
        first
    }
}

/// `LARGE_INTEGER ExInterlockedAddLargeInteger(PLARGE_INTEGER, LARGE_INTEGER, PKSPIN_LOCK)`.
extern "win64" fn s_ex_interlocked_add_large_integer(
    addend: u64,
    increment: i64,
    _lock: u64,
) -> i64 {
    unsafe {
        if addend == 0 {
            return 0;
        }
        let old = read_unaligned(addend as *const i64);
        write_unaligned(addend as *mut i64, old.wrapping_add(increment));
        old
    }
}

/// `ULONG ExInterlockedAddUlong(PULONG, ULONG, PKSPIN_LOCK)`.
extern "win64" fn s_ex_interlocked_add_ulong(addend: u64, increment: u32, _lock: u64) -> u32 {
    unsafe {
        if addend == 0 {
            return 0;
        }
        let old = read_unaligned(addend as *const u32);
        write_unaligned(addend as *mut u32, old.wrapping_add(increment));
        old
    }
}

/// `VOID ExQueueWorkItem(PWORK_QUEUE_ITEM, WORK_QUEUE_TYPE)`.
extern "win64" fn s_ex_queue_work_item(work_item: u64, _queue_type: u32) {
    if work_item == 0 {
        return;
    }
    unsafe {
        let routine = read_unaligned((work_item + 0x10) as *const u64);
        let parameter = read_unaligned((work_item + 0x18) as *const u64);
        if routine != 0 {
            let _ = enqueue_hosted_work_item(
                HOSTED_WORK_QUEUE_KIND_EX,
                work_item,
                routine,
                parameter,
                0,
            );
        }
    }
}

/// `NTSTATUS ExInitializeResourceLite(PERESOURCE)` / `void KeInitializeSpinLock(PKSPIN_LOCK)` /
/// `KeInitializeEvent` / timers / DPCs — zero a small struct + return success. Single-threaded host.
extern "win64" fn s_init_small_struct(p: u64) -> i32 {
    if p != 0 {
        unsafe {
            let mut i = 0u64;
            while i < 0x38 {
                write_unaligned((p + i) as *mut u64, 0);
                i += 8;
            }
        }
    }
    0
}

/// `void KeInitializeSpinLock(PKSPIN_LOCK)` — a KSPIN_LOCK is pointer-sized storage.
extern "win64" fn s_ke_initialize_spin_lock(lock: u64) {
    unsafe {
        if lock != 0 {
            write_unaligned(lock as *mut u64, 0);
        }
    }
}

#[inline]
unsafe fn hosted_current_irql() -> u8 {
    read_volatile((FSD_SHARED_VADDR + SH_HOSTED_CURRENT_IRQL) as *const u8)
}

#[inline]
unsafe fn hosted_set_current_irql(irql: u8) {
    write_volatile((FSD_SHARED_VADDR + SH_HOSTED_CURRENT_IRQL) as *mut u8, irql);
}

#[inline]
unsafe fn hosted_raise_irql(irql: u8) -> u8 {
    let old = hosted_current_irql();
    if irql > old {
        hosted_set_current_irql(irql);
    }
    old
}

#[inline]
unsafe fn hosted_lower_irql(irql: u8) {
    hosted_set_current_irql(irql);
}

fn hosted_fast_mutex_failure(mutex: u64, status: i32) -> ! {
    // A failed kernel wait means ownership cannot be established. Continuing would silently break
    // mutual exclusion, so fail closed through the driver's normal bugcheck boundary.
    s_ke_bug_check_ex(
        0xC4,
        0x4654_4D58,
        mutex,
        status as u32 as u64,
        s_ps_get_current_thread_id(),
    );
    loop {
        crate::yield_now();
    }
}

/// `VOID ExInitializeFastMutex(PFAST_MUTEX)` using the NT5 x64 layout.
extern "win64" fn s_ex_initialize_fast_mutex(mutex: u64) {
    if mutex == 0 {
        return;
    }
    unsafe {
        use nt_kernel_exec::executive_sync::fast_mutex_layout;
        write_unaligned((mutex + fast_mutex_layout::COUNT as u64) as *mut i32, 1);
        write_unaligned((mutex + fast_mutex_layout::OWNER as u64) as *mut u64, 0);
        write_unaligned(
            (mutex + fast_mutex_layout::CONTENTION as u64) as *mut u32,
            0,
        );
        s_ke_initialize_event(mutex + fast_mutex_layout::EVENT as u64, 1, 0);
        write_unaligned(
            (mutex + fast_mutex_layout::OLD_IRQL as u64) as *mut u32,
            PASSIVE_LEVEL as u32,
        );
    }
}

/// `VOID ExAcquireFastMutex(PFAST_MUTEX)`.
extern "win64" fn s_ex_acquire_fast_mutex(mutex: u64) {
    if mutex == 0 {
        hosted_fast_mutex_failure(mutex, STATUS_INVALID_PARAMETER);
    }
    let old_irql = unsafe { hosted_raise_irql(APC_LEVEL) };
    let current_thread = s_ps_get_current_thread_id();
    if current_thread == 0 {
        unsafe { hosted_lower_irql(old_irql) };
        hosted_fast_mutex_failure(mutex, STATUS_INVALID_HANDLE);
    }
    use nt_kernel_exec::executive_sync::fast_mutex_layout;
    let count = unsafe { &*((mutex + fast_mutex_layout::COUNT as u64) as *const AtomicI32) };
    if count.fetch_sub(1, Ordering::SeqCst) != 1 {
        let contention =
            unsafe { &*((mutex + fast_mutex_layout::CONTENTION as u64) as *const AtomicU32) };
        contention.fetch_add(1, Ordering::Relaxed);
        let status =
            s_ke_wait_for_single_object(mutex + fast_mutex_layout::EVENT as u64, 0, 0, 0, 0);
        if status != STATUS_SUCCESS {
            unsafe { hosted_lower_irql(old_irql) };
            hosted_fast_mutex_failure(mutex, status);
        }
    }
    unsafe {
        write_unaligned(
            (mutex + fast_mutex_layout::OWNER as u64) as *mut u64,
            current_thread,
        );
        write_unaligned(
            (mutex + fast_mutex_layout::OLD_IRQL as u64) as *mut u32,
            old_irql as u32,
        );
    }
}

/// `VOID ExReleaseFastMutex(PFAST_MUTEX)`.
extern "win64" fn s_ex_release_fast_mutex(mutex: u64) {
    if mutex == 0 {
        hosted_fast_mutex_failure(mutex, STATUS_INVALID_PARAMETER);
    }
    use nt_kernel_exec::executive_sync::fast_mutex_layout;
    let old_irql = unsafe {
        write_unaligned((mutex + fast_mutex_layout::OWNER as u64) as *mut u64, 0);
        read_unaligned((mutex + fast_mutex_layout::OLD_IRQL as u64) as *const u32) as u8
    };
    let count = unsafe { &*((mutex + fast_mutex_layout::COUNT as u64) as *const AtomicI32) };
    if count.fetch_add(1, Ordering::SeqCst) < 0 {
        let _ = s_ke_set_event(mutex + fast_mutex_layout::EVENT as u64, 0, 0);
    }
    unsafe { hosted_lower_irql(old_irql) };
}

/// `BOOLEAN ExTryToAcquireFastMutex(PFAST_MUTEX)`.
extern "win64" fn s_ex_try_to_acquire_fast_mutex(mutex: u64) -> u8 {
    if mutex == 0 {
        return 0;
    }
    use nt_kernel_exec::executive_sync::fast_mutex_layout;
    let old_irql = unsafe { hosted_raise_irql(APC_LEVEL) };
    let count = unsafe { &*((mutex + fast_mutex_layout::COUNT as u64) as *const AtomicI32) };
    if count
        .compare_exchange(1, 0, Ordering::SeqCst, Ordering::SeqCst)
        .is_err()
    {
        unsafe { hosted_lower_irql(old_irql) };
        return 0;
    }
    let current_thread = s_ps_get_current_thread_id();
    if current_thread == 0 {
        count.store(1, Ordering::SeqCst);
        unsafe { hosted_lower_irql(old_irql) };
        return 0;
    }
    unsafe {
        write_unaligned(
            (mutex + fast_mutex_layout::OWNER as u64) as *mut u64,
            current_thread,
        );
        write_unaligned(
            (mutex + fast_mutex_layout::OLD_IRQL as u64) as *mut u32,
            old_irql as u32,
        );
    }
    1
}

/// `KIRQL KeGetCurrentIrql()`.
extern "win64" fn s_ke_get_current_irql() -> u8 {
    unsafe { hosted_current_irql() }
}

/// `KIRQL KeAcquireSpinLockRaiseToDpc(PKSPIN_LOCK)`.
///
/// The hosted NT ABI exposes one logical processor (`KeNumberProcessors == 1`). NT UP spinlocks
/// therefore provide exclusion by raising IRQL; no inter-processor lock word is acquired. This is
/// also what permits a protocol receive indication to synchronously re-enter NDIS send code while
/// the outer indication is at `DISPATCH_LEVEL`.
extern "win64" fn s_ke_acquire_spin_lock_raise_to_dpc(lock: u64) -> u8 {
    unsafe {
        if lock == 0 {
            return hosted_current_irql();
        }
        let old_irql = hosted_raise_irql(DISPATCH_LEVEL);
        compiler_fence(Ordering::SeqCst);
        old_irql
    }
}

/// `void KeReleaseSpinLock(PKSPIN_LOCK, KIRQL)`.
extern "win64" fn s_ke_release_spin_lock(lock: u64, old_irql: u8) {
    unsafe {
        if lock == 0 {
            return;
        }
        compiler_fence(Ordering::SeqCst);
        hosted_lower_irql(old_irql);
    }
}

/// `VOID KeAcquireSpinLockAtDpcLevel(PKSPIN_LOCK)` -- barrier-only on the hosted UP ABI.
extern "win64" fn s_ke_acquire_spin_lock_at_dpc_level(lock: u64) {
    if lock != 0 {
        compiler_fence(Ordering::SeqCst);
    }
}

/// `VOID KeReleaseSpinLockFromDpcLevel(PKSPIN_LOCK)` -- barrier-only on the hosted UP ABI.
extern "win64" fn s_ke_release_spin_lock_from_dpc_level(lock: u64) {
    if lock != 0 {
        compiler_fence(Ordering::SeqCst);
    }
}

/// `void KeInitializeEvent(PRKEVENT, EVENT_TYPE, BOOLEAN)`.
extern "win64" fn s_ke_initialize_event(event: u64, event_type: u32, state: u8) {
    if event == 0 {
        return;
    }
    let kind = if event_type == 1 {
        EventKind::Synchronization
    } else {
        EventKind::Notification
    };
    unsafe {
        kevent::init_kevent(event as *mut u8, kind, state != 0);
    }
}

/// `LONG KeSetEvent(PRKEVENT, KPRIORITY, BOOLEAN)`.
extern "win64" fn s_ke_set_event(event: u64, increment: i32, wait: u8) -> i32 {
    if event == 0 {
        return 0;
    }
    let packed = (increment as u32 as u64) | ((wait as u64) << 32);
    let (_label, previous, _, _, _) = unsafe {
        call_on4(
            (FSD_SERVICE_KE_SET_EVENT_LABEL << 12) | 3,
            event,
            packed,
            0,
            0,
        )
    };
    previous as u32 as i32
}

/// `void KeClearEvent(PRKEVENT)`.
extern "win64" fn s_ke_clear_event(event: u64) {
    if event != 0 {
        unsafe {
            kevent::kevent_clear(event as *mut u8);
        }
    }
}

/// `LONG KeResetEvent(PRKEVENT)`.
extern "win64" fn s_ke_reset_event(event: u64) -> i32 {
    if event == 0 {
        return 0;
    }
    unsafe { kevent::kevent_reset(event as *mut u8) as i32 }
}

/// `LONG KePulseEvent(PRKEVENT, KPRIORITY, BOOLEAN)`.
extern "win64" fn s_ke_pulse_event(event: u64, increment: i32, wait: u8) -> i32 {
    if event == 0 {
        return 0;
    }
    let packed = (increment as u32 as u64) | ((wait as u64) << 32);
    let (_label, previous, _, _, _) = unsafe {
        call_on4(
            (FSD_SERVICE_KE_PULSE_EVENT_LABEL << 12) | 3,
            event,
            packed,
            0,
            0,
        )
    };
    previous as u32 as i32
}

/// `LONG KeReadStateEvent(PRKEVENT)`.
extern "win64" fn s_ke_read_state_event(event: u64) -> i32 {
    if event == 0 {
        return 0;
    }
    unsafe { kevent::kevent_read_state(event as *const u8) as i32 }
}

/// `void KeInitializeSemaphore(PRKSEMAPHORE, LONG, LONG)`.
extern "win64" fn s_ke_initialize_semaphore(semaphore: u64, count: i32, limit: i32) {
    if semaphore == 0 {
        return;
    }
    let _ = unsafe { init_ksemaphore(semaphore as *mut u8, count, limit) };
}

/// `LONG KeReadStateSemaphore(PRKSEMAPHORE)`.
extern "win64" fn s_ke_read_state_semaphore(semaphore: u64) -> i32 {
    if semaphore == 0 {
        return 0;
    }
    unsafe { ksemaphore_read_state(semaphore as *const u8) }
}

/// `LONG KeReleaseSemaphore(PRKSEMAPHORE, KPRIORITY, LONG, BOOLEAN)`.
extern "win64" fn s_ke_release_semaphore(
    semaphore: u64,
    increment: i32,
    adjustment: i32,
    wait: u8,
) -> i32 {
    if semaphore == 0 {
        return 0;
    }
    let packed = (increment as u32 as u64) | ((wait as u64) << 32);
    let (_label, previous, _, _, _) = unsafe {
        call_on4(
            (FSD_SERVICE_KE_RELEASE_SEMAPHORE_LABEL << 12) | 4,
            semaphore,
            adjustment as u32 as u64,
            packed,
            0,
        )
    };
    previous as u32 as i32
}

unsafe fn hosted_dispatcher_ready(object: u64) -> Result<bool, i32> {
    if object == 0 {
        return Err(STATUS_INVALID_PARAMETER);
    }
    let object_type = read_unaligned(object as *const u8);
    if object_type == kevent::EVENT_NOTIFICATION_OBJECT
        || object_type == kevent::EVENT_SYNCHRONIZATION_OBJECT
    {
        return Ok(kevent::kevent_read_state(object as *const u8));
    }
    if object_type == SEMAPHORE_OBJECT {
        return Ok(ksemaphore_read_state(object as *const u8) > 0);
    }
    if object_type == TIMER_NOTIFICATION_OBJECT || object_type == TIMER_SYNCHRONIZATION_OBJECT {
        return Ok(read_unaligned((object + 4) as *const i32) > 0);
    }
    Err(STATUS_INVALID_PARAMETER)
}

unsafe fn hosted_dispatcher_consume(object: u64) -> bool {
    let object_type = read_unaligned(object as *const u8);
    if object_type == kevent::EVENT_NOTIFICATION_OBJECT {
        return true;
    }
    if object_type == kevent::EVENT_SYNCHRONIZATION_OBJECT {
        kevent::kevent_clear(object as *mut u8);
        return true;
    }
    if object_type == SEMAPHORE_OBJECT {
        return ksemaphore_try_wait(object as *mut u8);
    }
    if object_type == TIMER_NOTIFICATION_OBJECT {
        return true;
    }
    if object_type == TIMER_SYNCHRONIZATION_OBJECT {
        write_unaligned((object + 4) as *mut i32, 0);
        return true;
    }
    false
}

unsafe fn hosted_dispatcher_wait_ready(
    objects: &[u64],
    wait_all: bool,
) -> Result<Option<u32>, i32> {
    if objects.is_empty() || objects.len() > HOSTED_DRIVER_WAIT_OBJECT_MAX as usize {
        return Err(STATUS_INVALID_PARAMETER);
    }
    if wait_all {
        for &object in objects {
            if !hosted_dispatcher_ready(object)? {
                return Ok(None);
            }
        }
        Ok(Some(0))
    } else {
        for (index, &object) in objects.iter().enumerate() {
            if hosted_dispatcher_ready(object)? {
                return Ok(Some(index as u32));
            }
        }
        Ok(None)
    }
}

unsafe fn hosted_dispatcher_wait_consume(
    objects: &[u64],
    wait_all: bool,
    ready_index: u32,
) -> bool {
    if wait_all {
        for &object in objects {
            if !hosted_dispatcher_consume(object) {
                return false;
            }
        }
        true
    } else {
        let Some(&object) = objects.get(ready_index as usize) else {
            return false;
        };
        hosted_dispatcher_consume(object)
    }
}

unsafe fn hosted_wait_timeout_payload(timeout: u64) -> (u64, u64) {
    let timeout_value = if timeout == 0 {
        None
    } else {
        Some(read_unaligned(timeout as *const i64))
    };
    let timeout_code = match classify_dispatcher_wait_timeout(timeout_value) {
        DispatcherWaitTimeout::Infinite => 0,
        DispatcherWaitTimeout::Poll => 1,
        DispatcherWaitTimeout::Blocking => 2,
    };
    (timeout_code, timeout_value.unwrap_or(0) as u64)
}

fn hosted_wait_timeout_from_code(code: u64) -> DispatcherWaitTimeout {
    match code {
        1 => DispatcherWaitTimeout::Poll,
        0 => DispatcherWaitTimeout::Infinite,
        _ => DispatcherWaitTimeout::Blocking,
    }
}

fn hosted_driver_deadline_from_timeout(
    timeout_code: u64,
    timeout_arg: u64,
) -> Result<nt_kernel_exec::Deadline, i32> {
    match hosted_wait_timeout_from_code(timeout_code) {
        DispatcherWaitTimeout::Poll => Err(STATUS_TIMEOUT_I32),
        DispatcherWaitTimeout::Infinite => Ok(nt_kernel_exec::Deadline::Infinite),
        DispatcherWaitTimeout::Blocking => {
            let now = crate::nt_time_snapshot();
            let deadline = nt_kernel_exec::Deadline::from_nt_timeout(Some(timeout_arg as i64), now);
            if deadline.is_due(now) {
                Err(STATUS_TIMEOUT_I32)
            } else {
                Ok(deadline)
            }
        }
    }
}

/// `NTSTATUS KeWaitForSingleObject(...)` for hosted-driver local dispatcher objects.
extern "win64" fn s_ke_wait_for_single_object(
    object: u64,
    wait_reason: u32,
    wait_mode: u32,
    alertable: u8,
    timeout: u64,
) -> i32 {
    let packed_wait =
        (wait_reason as u64) | ((wait_mode as u64) << 32) | ((alertable as u64) << 40);
    let (timeout_code, timeout_arg) = unsafe { hosted_wait_timeout_payload(timeout) };
    let (_label, status, _, _, _) = unsafe {
        call_on4(
            (FSD_SERVICE_KE_WAIT_SINGLE_LABEL << 12) | 4,
            object,
            packed_wait,
            timeout_code,
            timeout_arg,
        )
    };
    status as u32 as i32
}

fn hosted_worker_component_base_for_slot(component_slot: usize) -> Option<u64> {
    FSD_WORKER_VADDR.checked_add((component_slot as u64).checked_mul(FSD_WORKER_STRIDE)?)
}

fn hosted_worker_exec_base_for_alias(exec_alias_slot: u64) -> Option<u64> {
    FSD_WORKER_EXEC_ALIAS_BASE.checked_add(exec_alias_slot.checked_mul(FSD_WORKER_STRIDE)?)
}

fn hosted_worker_component_base_from_rsp(rsp: u64) -> Option<u64> {
    if rsp < FSD_WORKER_VADDR {
        return None;
    }
    let relative = rsp - FSD_WORKER_VADDR;
    let offset = relative % FSD_WORKER_STRIDE;
    if offset >= FSD_WORKER_STACK_FRAMES * 0x1000 {
        return None;
    }
    let slot = relative / FSD_WORKER_STRIDE;
    FSD_WORKER_VADDR.checked_add(slot.checked_mul(FSD_WORKER_STRIDE)?)
}

fn current_hosted_worker_scratch_va() -> Option<u64> {
    let rsp: u64;
    unsafe {
        core::arch::asm!(
            "mov {}, rsp",
            out(reg) rsp,
            options(nostack, nomem, preserves_flags)
        );
    }
    hosted_worker_component_base_from_rsp(rsp)?.checked_add(FSD_WORKER_SCRATCH_OFFSET)
}

fn hosted_worker_component_to_exec_va(
    runtime: HostedDriverThreadRuntime,
    component_va: u64,
    bytes: u64,
) -> Option<u64> {
    let component_base = hosted_worker_component_base_for_slot(runtime.component_slot)?;
    let exec_base = hosted_worker_exec_base_for_alias(runtime.exec_alias_slot)?;
    translate_component_range(
        component_va,
        bytes,
        component_base,
        FSD_WORKER_STACK_FRAMES * 0x1000,
        exec_base,
    )
    .or_else(|| {
        translate_component_range(
            component_va,
            bytes,
            runtime.component_scratch_va,
            0x1000,
            runtime.exec_scratch_va,
        )
    })
}

fn hosted_driver_runtime_for_worker_component_range(
    instance: usize,
    component_va: u64,
    bytes: u64,
) -> Option<HostedDriverThreadRuntime> {
    unsafe {
        (*core::ptr::addr_of!(HOSTED_DRIVER_THREAD_RUNTIMES))
            .as_ref()?
            .iter()
            .copied()
            .find(|rt| {
                rt.instance == instance
                    && hosted_worker_component_to_exec_va(*rt, component_va, bytes).is_some()
            })
    }
}

fn hosted_driver_wait_array_exec_va(
    instance: usize,
    inst: DriverInstance,
    runtime: Option<HostedDriverThreadRuntime>,
    component_array: u64,
    bytes: u64,
) -> Option<u64> {
    component_to_exec_va_for_instance(instance, inst, component_array, bytes)
        .or_else(|| {
            runtime.and_then(|rt| hosted_worker_component_to_exec_va(rt, component_array, bytes))
        })
        .or_else(|| {
            hosted_driver_runtime_for_worker_component_range(instance, component_array, bytes)
                .and_then(|rt| hosted_worker_component_to_exec_va(rt, component_array, bytes))
        })
}

fn hosted_driver_wait_object_exec_va(
    instance: usize,
    inst: DriverInstance,
    runtime: Option<HostedDriverThreadRuntime>,
    component_object: u64,
) -> Option<u64> {
    component_to_exec_va_for_instance(instance, inst, component_object, 0x20)
        .or_else(|| {
            runtime.and_then(|rt| hosted_worker_component_to_exec_va(rt, component_object, 0x20))
        })
        .or_else(|| {
            hosted_driver_runtime_for_worker_component_range(instance, component_object, 0x20)
                .and_then(|rt| hosted_worker_component_to_exec_va(rt, component_object, 0x20))
        })
}

pub(crate) enum HostedDriverWaitServiceResult {
    Reply(i32),
    Parked { fresh_reply_cap: u64 },
}

pub(crate) enum HostedDriverThreadTerminateServiceResult {
    Reply(i32),
    Terminated { fresh_reply_cap: u64 },
}

fn park_hosted_driver_wait(
    instance: usize,
    thread_handle: u64,
    active_reply_cap: u64,
    objects: Vec<u64>,
    wait_all: bool,
    api_multiple: bool,
    deadline: nt_kernel_exec::Deadline,
) -> Option<u64> {
    if objects.is_empty() || objects.len() > HOSTED_DRIVER_WAIT_OBJECT_MAX as usize {
        return None;
    }
    if deadline != nt_kernel_exec::Deadline::Infinite
        && !unsafe { crate::service_sec_image::rearm_registered_delay_timer() }
    {
        return None;
    }
    let waiters = unsafe { hosted_driver_waiters_mut() };
    if waiters.iter().any(|waiter| {
        waiter.instance == instance
            && (waiter.thread_handle == thread_handle || waiter.reply_cap == active_reply_cap)
    }) {
        return None;
    }
    if waiters.len() == waiters.capacity() && waiters.try_reserve(4).is_err() {
        return None;
    }
    let fresh = unsafe { take_hosted_driver_reply_spare(instance)? };
    let set_waiting = unsafe {
        hosted_driver_thread_table_mut(instance)
            .and_then(|table| table.set_waiting(thread_handle).ok())
    };
    if set_waiting.is_none() {
        unsafe {
            return_hosted_driver_reply_spare(instance, fresh);
        }
        return None;
    }
    waiters.push(HostedDriverRawWaiter {
        instance,
        thread_handle,
        reply_cap: active_reply_cap,
        objects,
        wait_all,
        api_multiple,
        deadline,
        sequence: HOSTED_DRIVER_WAIT_SEQUENCE.fetch_add(1, Ordering::Relaxed),
    });
    if !rotate_hosted_driver_active_reply(instance, active_reply_cap, fresh) {
        let _ = waiters.pop();
        unsafe {
            let _ = hosted_driver_thread_table_mut(instance)
                .and_then(|table| table.set_ready(thread_handle).ok());
            return_hosted_driver_reply_spare(instance, fresh);
        }
        return None;
    }
    let waiter = waiters.last().unwrap();
    if waiter.api_multiple {
        HOSTED_DRIVER_WAIT_MULTIPLE_PARKED.fetch_add(1, Ordering::Relaxed);
    } else {
        HOSTED_DRIVER_WAIT_SINGLE_PARKED.fetch_add(1, Ordering::Relaxed);
    }
    if deadline != nt_kernel_exec::Deadline::Infinite {
        let _ = unsafe { crate::service_sec_image::rearm_registered_delay_timer() };
    }
    Some(fresh)
}

unsafe fn reply_hosted_driver_waiter(waiter: HostedDriverRawWaiter, status: i32) -> bool {
    let instance = waiter.instance;
    let replied =
        crate::spawn_hosts::pump_reply_on(waiter.reply_cap, 1, status as u32 as u64, 0, 0, 0);
    let _ = hosted_driver_thread_table_mut(instance)
        .and_then(|table| table.set_ready(waiter.thread_handle).ok());
    if replied {
        return_hosted_driver_reply_spare(instance, waiter.reply_cap);
    } else {
        let _ = cnode_delete_recycle_r(waiter.reply_cap);
    }
    replied
}

fn record_hosted_driver_wait_wake_error(api_multiple: bool) {
    if api_multiple {
        HOSTED_DRIVER_WAIT_MULTIPLE_WAKE_ERRORS.fetch_add(1, Ordering::Relaxed);
    } else {
        HOSTED_DRIVER_WAIT_SINGLE_WAKE_ERRORS.fetch_add(1, Ordering::Relaxed);
    }
}

fn record_hosted_driver_wait_woken(api_multiple: bool) {
    if api_multiple {
        HOSTED_DRIVER_WAIT_MULTIPLE_WOKEN.fetch_add(1, Ordering::Relaxed);
    } else {
        HOSTED_DRIVER_WAIT_SINGLE_WOKEN.fetch_add(1, Ordering::Relaxed);
    }
}

fn record_hosted_driver_wait_timeout(api_multiple: bool) {
    if api_multiple {
        HOSTED_DRIVER_WAIT_MULTIPLE_TIMEOUTS.fetch_add(1, Ordering::Relaxed);
    } else {
        HOSTED_DRIVER_WAIT_SINGLE_TIMEOUTS.fetch_add(1, Ordering::Relaxed);
    }
}

/// Hosted-driver wait census: (single-woken, single-timeouts, multiple-woken, multiple-timeouts,
/// waiters-outstanding). A driver that re-arms a wait the instant it times out shows up here as a
/// timeout count climbing with no matching wake — the signature of an executive/component livelock
/// rather than of real waiting.
pub(crate) fn hosted_driver_wait_census() -> (u64, u64, u64, u64, u64) {
    (
        HOSTED_DRIVER_WAIT_SINGLE_WOKEN.load(Ordering::Relaxed),
        HOSTED_DRIVER_WAIT_SINGLE_TIMEOUTS.load(Ordering::Relaxed),
        HOSTED_DRIVER_WAIT_MULTIPLE_WOKEN.load(Ordering::Relaxed),
        HOSTED_DRIVER_WAIT_MULTIPLE_TIMEOUTS.load(Ordering::Relaxed),
        unsafe {
            (*core::ptr::addr_of!(HOSTED_DRIVER_WAITERS))
                .as_ref()
                .map(|waiters| waiters.len() as u64)
                .unwrap_or(0)
        },
    )
}

pub(crate) fn hosted_driver_wait_next_deadline() -> Option<u64> {
    let now = crate::nt_time_snapshot();
    unsafe {
        (*core::ptr::addr_of!(HOSTED_DRIVER_WAITERS))
            .as_ref()?
            .iter()
            .filter_map(|waiter| waiter.deadline.monotonic_target(now))
            .min()
    }
}

pub(crate) fn hosted_driver_timer_next_deadline() -> Option<u64> {
    let now = crate::nt_time_snapshot();
    unsafe {
        (*core::ptr::addr_of!(HOSTED_DRIVER_TIMERS))
            .as_ref()?
            .iter()
            .filter_map(|queue| queue.next_deadline_at(now))
            .min()
    }
}

pub(crate) unsafe fn hosted_driver_timer_wake_due(now_100ns: u64) -> u64 {
    let now = crate::nt_time_snapshot_at(now_100ns);
    let queue_count = (*core::ptr::addr_of!(HOSTED_DRIVER_TIMERS))
        .as_ref()
        .map(Vec::len)
        .unwrap_or(0);
    let mut delivered = 0u64;
    for instance_index in 0..queue_count {
        let expirations = {
            let queues = (*core::ptr::addr_of_mut!(HOSTED_DRIVER_TIMERS))
                .as_mut()
                .unwrap();
            queues[instance_index].run_due_expirations_at(now)
        };
        if expirations.is_empty() {
            continue;
        }
        let Some(inst) = instance(instance_index) else {
            continue;
        };
        for expiry in expirations {
            let runtime = hosted_driver_runtime_for_worker_component_range(
                instance_index,
                expiry.timer_ptr,
                0x40,
            );
            let exec_timer =
                component_to_exec_va_for_instance(instance_index, inst, expiry.timer_ptr, 0x40)
                    .or_else(|| {
                        runtime.and_then(|worker| {
                            hosted_worker_component_to_exec_va(worker, expiry.timer_ptr, 0x40)
                        })
                    });
            let Some(exec_timer) = exec_timer else {
                continue;
            };
            write_unaligned((exec_timer + 4) as *mut i32, 1);
            delivered = delivered.saturating_add(1);
            delivered =
                delivered.saturating_add(wake_hosted_driver_waiters_for_instance(instance_index));

            if let Some(dpc) = expiry.dpc_ptr {
                let activations = hosted_driver_dpc_activations_mut();
                if !activations
                    .iter()
                    .any(|queued| queued.instance == instance_index && queued.dpc_ptr == dpc)
                {
                    activations.push(HostedDriverDpcActivation {
                        instance: instance_index,
                        timer_ptr: expiry.timer_ptr,
                        dpc_ptr: dpc,
                    });
                }
            }
        }
    }
    if FSD_ACTIVE_DISPATCH_SEQ.load(Ordering::Acquire) == 0 {
        delivered = delivered.saturating_add(drain_hosted_driver_dpc_activations());
    }
    delivered
}

pub(crate) fn hosted_driver_dpc_activation_pending() -> bool {
    unsafe {
        (*core::ptr::addr_of!(HOSTED_DRIVER_DPC_ACTIVATIONS))
            .as_ref()
            .is_some_and(|activations| !activations.is_empty())
    }
}

/// Dispatch timer-DPC activations only after the current component has released
/// its shared request bank. The snapshot budget prevents a periodic timer that
/// re-arms during its own DPC from monopolising the executive; newly queued work
/// runs at the next safe scheduler boundary.
pub(crate) unsafe fn drain_hosted_driver_dpc_activations() -> u64 {
    if FSD_ACTIVE_DISPATCH_SEQ.load(Ordering::Acquire) != 0 {
        return 0;
    }
    let budget = (*core::ptr::addr_of!(HOSTED_DRIVER_DPC_ACTIVATIONS))
        .as_ref()
        .map(Vec::len)
        .unwrap_or(0);
    let mut delivered = 0u64;
    for _ in 0..budget {
        if FSD_ACTIVE_DISPATCH_SEQ.load(Ordering::Acquire) != 0 {
            break;
        }
        let activation = {
            let activations = hosted_driver_dpc_activations_mut();
            if activations.is_empty() {
                break;
            }
            activations.remove(0)
        };
        let mut no_output = [];
        if dispatch_irp_for_instance(
            activation.instance,
            FSD_DISPATCH_TIMER_DPC,
            0,
            0,
            0,
            0,
            activation.dpc_ptr,
            activation.timer_ptr,
            0,
            None,
            &[],
            &mut no_output,
        )
        .is_some_and(|(status, _, _)| status >= 0)
        {
            delivered = delivered.saturating_add(1);
        }
    }
    delivered
}

pub(crate) unsafe fn hosted_driver_wait_wake_due(now_100ns: u64) -> u64 {
    let now = crate::nt_time_snapshot_at(now_100ns);
    let mut woken = 0u64;
    loop {
        let due_index = {
            let Some(waiters) = (*core::ptr::addr_of!(HOSTED_DRIVER_WAITERS)).as_ref() else {
                return woken;
            };
            waiters
                .iter()
                .enumerate()
                .filter(|(_, waiter)| waiter.deadline.is_due(now))
                .min_by_key(|(_, waiter)| (waiter.deadline.ordering_key(now), waiter.sequence))
                .map(|(index, _)| index)
        };
        let Some(index) = due_index else {
            break;
        };
        let waiter = hosted_driver_waiters_mut().remove(index);
        let api_multiple = waiter.api_multiple;
        if reply_hosted_driver_waiter(waiter, STATUS_TIMEOUT_I32) {
            record_hosted_driver_wait_timeout(api_multiple);
            woken += 1;
        } else {
            record_hosted_driver_wait_wake_error(api_multiple);
        }
    }
    woken
}

fn wake_hosted_driver_waiters_for_instance(instance: usize) -> u64 {
    let mut woken = 0u64;
    loop {
        let ready_index = unsafe {
            let Some(waiters) = (*core::ptr::addr_of!(HOSTED_DRIVER_WAITERS)).as_ref() else {
                return woken;
            };
            waiters.iter().position(|waiter| {
                waiter.instance == instance
                    && matches!(
                        hosted_dispatcher_wait_ready(&waiter.objects, waiter.wait_all),
                        Ok(Some(_))
                    )
            })
        };
        let Some(index) = ready_index else {
            break;
        };
        let waiter = unsafe { hosted_driver_waiters_mut().remove(index) };
        let wait_is_multiple = waiter.api_multiple;
        let ready_status =
            match unsafe { hosted_dispatcher_wait_ready(&waiter.objects, waiter.wait_all) } {
                Ok(Some(status)) => status,
                _ => {
                    record_hosted_driver_wait_wake_error(wait_is_multiple);
                    unsafe {
                        let _ = reply_hosted_driver_waiter(waiter, STATUS_INVALID_PARAMETER);
                    }
                    continue;
                }
            };
        let consumed = unsafe {
            hosted_dispatcher_wait_consume(&waiter.objects, waiter.wait_all, ready_status)
        };
        if !consumed {
            record_hosted_driver_wait_wake_error(wait_is_multiple);
            unsafe {
                let _ = reply_hosted_driver_waiter(waiter, STATUS_INVALID_PARAMETER);
            }
            continue;
        }
        let replied = unsafe { reply_hosted_driver_waiter(waiter, ready_status as i32) };
        if replied {
            record_hosted_driver_wait_woken(wait_is_multiple);
            woken += 1;
        } else {
            record_hosted_driver_wait_wake_error(wait_is_multiple);
        }
    }
    if woken != 0 {
        let _ = unsafe { crate::service_sec_image::rearm_registered_delay_timer() };
    }
    woken
}

/// `NTSTATUS KeWaitForMultipleObjects(ULONG Count, PVOID Object[], WAIT_TYPE, ...)`.
extern "win64" fn s_ke_wait_for_multiple_objects(
    count: u32,
    object_array: u64,
    wait_type: u32,
    _wait_reason: u32,
    _wait_mode: u32,
    _alertable: u8,
    timeout: u64,
    _wait_block_array: u64,
) -> i32 {
    if count == 0 || count > HOSTED_DRIVER_WAIT_OBJECT_MAX || object_array == 0 {
        return STATUS_INVALID_PARAMETER;
    }
    let Some(bytes) = (count as u64).checked_mul(8) else {
        return STATUS_INVALID_PARAMETER;
    };
    if object_array.checked_add(bytes).is_none() {
        return STATUS_INVALID_PARAMETER;
    }
    let service_array = if let Some(scratch) = current_hosted_worker_scratch_va() {
        unsafe {
            let mut index = 0u32;
            while index < count {
                let object = read_unaligned((object_array + index as u64 * 8) as *const u64);
                write_unaligned((scratch + index as u64 * 8) as *mut u64, object);
                index += 1;
            }
        }
        scratch
    } else {
        object_array
    };
    let (timeout_code, timeout_arg) = unsafe { hosted_wait_timeout_payload(timeout) };
    let packed_wait = (wait_type as u64) | (timeout_code << 32);
    let (_label, status, _, _, _) = unsafe {
        call_on4(
            (FSD_SERVICE_KE_WAIT_MULTIPLE_LABEL << 12) | 4,
            service_array,
            count as u64,
            packed_wait,
            timeout_arg,
        )
    };
    status as u32 as i32
}

/// `VOID KeInitializeTimerEx(PKTIMER, TIMER_TYPE)`.
extern "win64" fn s_ke_initialize_timer_ex(timer: u64, timer_type: u32) {
    if timer == 0 {
        return;
    }
    let _ = s_ke_cancel_timer(timer);
    unsafe {
        core::ptr::write_bytes(timer as *mut u8, 0, 0x40);
        let type_byte = if timer_type == 0 {
            TIMER_NOTIFICATION_OBJECT
        } else {
            TIMER_SYNCHRONIZATION_OBJECT
        };
        write_unaligned(timer as *mut u8, type_byte);
        write_unaligned((timer + 2) as *mut u8, 0x0A);
    }
}

/// `VOID KeInitializeTimer(PKTIMER)`.
extern "win64" fn s_ke_initialize_timer(timer: u64) {
    s_ke_initialize_timer_ex(timer, 0);
}

/// `NTSTATUS KeDelayExecutionThread(KPROCESSOR_MODE, BOOLEAN, PLARGE_INTEGER)`.
extern "win64" fn s_ke_delay_execution_thread(
    _wait_mode: u32,
    _alertable: u8,
    interval: u64,
) -> i32 {
    unsafe {
        if interval != 0 {
            let ticks = read_unaligned(interval as *const i64);
            if ticks < 0 {
                let micros = ((ticks.wrapping_neg() as u64) / 10).min(1000) as u32;
                s_ke_stall_execution_processor(micros);
            }
        }
    }
    STATUS_SUCCESS
}

/// `VOID KeQuerySystemTime(PLARGE_INTEGER)`.
extern "win64" fn s_ke_query_system_time(out: u64) {
    if out != 0 {
        unsafe {
            write_unaligned(out as *mut u64, nt_system_time_100ns());
        }
    }
}

const KDPC_DEFERRED_ROUTINE_OFFSET: u64 = 0x18;
const KDPC_DEFERRED_CONTEXT_OFFSET: u64 = 0x20;
const KDPC_SYSTEM_ARGUMENT1_OFFSET: u64 = 0x28;
const KDPC_SYSTEM_ARGUMENT2_OFFSET: u64 = 0x30;
const KDPC_QUEUED_OFFSET: u64 = 0x38;
const KDPC_SIZE: u64 = 0x40;

unsafe fn dpc_queue_capacity(sh: u64) -> u64 {
    let capacity = read_volatile((sh + SH_DPC_QUEUE_CAPACITY) as *const u64);
    if capacity == 0 || capacity > SH_DPC_QUEUE_DERIVED_CAPACITY {
        0
    } else {
        capacity
    }
}

#[inline]
fn dpc_queue_slot(sh: u64, index: u64, capacity: u64) -> u64 {
    sh + SH_DPC_QUEUE_BASE + (index % capacity) * SH_DPC_QUEUE_ENTRY_SIZE
}

unsafe fn clear_dpc_queue_projection(sh: u64) {
    write_volatile((sh + SH_DPC_QUEUE_HEAD) as *mut u64, 0);
    write_volatile((sh + SH_DPC_QUEUE_TAIL) as *mut u64, 0);
    write_volatile((sh + SH_DPC_QUEUE_DROPS) as *mut u64, 0);
    write_volatile((sh + SH_DPC_DELIVERIES) as *mut u64, 0);
    write_volatile(
        (sh + SH_DPC_QUEUE_CAPACITY) as *mut u64,
        SH_DPC_QUEUE_DERIVED_CAPACITY,
    );
    let mut slot = 0u64;
    while slot < SH_DPC_QUEUE_DERIVED_CAPACITY {
        write_volatile(
            (sh + SH_DPC_QUEUE_BASE + slot * SH_DPC_QUEUE_ENTRY_SIZE) as *mut u64,
            0,
        );
        slot += 1;
    }
}

unsafe fn ensure_dpc_queue_projection(sh: u64) {
    if dpc_queue_capacity(sh) != 0 {
        return;
    }
    write_volatile((sh + SH_DPC_QUEUE_HEAD) as *mut u64, 0);
    write_volatile((sh + SH_DPC_QUEUE_TAIL) as *mut u64, 0);
    write_volatile(
        (sh + SH_DPC_QUEUE_CAPACITY) as *mut u64,
        SH_DPC_QUEUE_DERIVED_CAPACITY,
    );
    let mut slot = 0u64;
    while slot < SH_DPC_QUEUE_DERIVED_CAPACITY {
        write_volatile(
            (sh + SH_DPC_QUEUE_BASE + slot * SH_DPC_QUEUE_ENTRY_SIZE) as *mut u64,
            0,
        );
        slot += 1;
    }
}

/// `void KeInitializeDpc(PRKDPC, PKDEFERRED_ROUTINE, PVOID)`.
extern "win64" fn s_ke_initialize_dpc(dpc: u64, routine: u64, deferred_context: u64) {
    unsafe {
        if dpc == 0 {
            return;
        }
        // Every hosted component owns a software-DPC queue, including
        // resource-free and legacy drivers that never receive a hardware
        // resource projection. KeInitializeDpc is the authoritative point at
        // which that queue first becomes required.
        ensure_dpc_queue_projection(FSD_SHARED_VADDR);
        core::ptr::write_bytes(dpc as *mut u8, 0, KDPC_SIZE as usize);
        write_unaligned((dpc + KDPC_DEFERRED_ROUTINE_OFFSET) as *mut u64, routine);
        write_unaligned(
            (dpc + KDPC_DEFERRED_CONTEXT_OFFSET) as *mut u64,
            deferred_context,
        );
    }
}

/// `BOOLEAN KeInsertQueueDpc(PRKDPC, PVOID, PVOID)` — queue state is represented in the driver-owned
/// KDPC projection so duplicate inserts are rejected deterministically.
extern "win64" fn s_ke_insert_queue_dpc(dpc: u64, arg1: u64, arg2: u64) -> u8 {
    unsafe {
        if dpc == 0
            || read_unaligned((dpc + KDPC_DEFERRED_ROUTINE_OFFSET) as *const u64) == 0
            || read_unaligned((dpc + KDPC_QUEUED_OFFSET) as *const u8) != 0
        {
            return 0;
        }
        let capacity = dpc_queue_capacity(FSD_SHARED_VADDR);
        if capacity == 0 {
            let drops = read_volatile((FSD_SHARED_VADDR + SH_DPC_QUEUE_DROPS) as *const u64);
            write_volatile(
                (FSD_SHARED_VADDR + SH_DPC_QUEUE_DROPS) as *mut u64,
                drops.saturating_add(1),
            );
            return 0;
        }
        let head = read_volatile((FSD_SHARED_VADDR + SH_DPC_QUEUE_HEAD) as *const u64);
        let tail = read_volatile((FSD_SHARED_VADDR + SH_DPC_QUEUE_TAIL) as *const u64);
        if tail.saturating_sub(head) >= capacity {
            let drops = read_volatile((FSD_SHARED_VADDR + SH_DPC_QUEUE_DROPS) as *const u64);
            write_volatile(
                (FSD_SHARED_VADDR + SH_DPC_QUEUE_DROPS) as *mut u64,
                drops.saturating_add(1),
            );
            return 0;
        }
        write_unaligned((dpc + KDPC_SYSTEM_ARGUMENT1_OFFSET) as *mut u64, arg1);
        write_unaligned((dpc + KDPC_SYSTEM_ARGUMENT2_OFFSET) as *mut u64, arg2);
        write_unaligned((dpc + KDPC_QUEUED_OFFSET) as *mut u8, 1);
        let slot = dpc_queue_slot(FSD_SHARED_VADDR, tail, capacity);
        write_volatile(slot as *mut u64, dpc);
        write_volatile(
            (FSD_SHARED_VADDR + SH_DPC_QUEUE_TAIL) as *mut u64,
            tail.saturating_add(1),
        );
    }
    1
}

