/// `NTSTATUS PsCreateSystemThread(...)`.
extern "win64" fn s_ps_create_system_thread(
    handle_out: u64,
    _desired_access: u32,
    object_attributes: u64,
    process_handle: u64,
    client_id: u64,
    start_routine: u64,
    start_context: u64,
) -> i32 {
    if handle_out == 0 {
        return STATUS_INVALID_PARAMETER;
    }
    let (_label, status, handle, _, _) = unsafe {
        call_on5(
            (FSD_SERVICE_PS_CREATE_SYSTEM_THREAD_LABEL << 12) | 5,
            start_routine,
            start_context,
            object_attributes,
            process_handle,
            client_id,
        )
    };
    unsafe {
        if status as i32 == STATUS_SUCCESS {
            write_unaligned(handle_out as *mut u64, handle);
        } else {
            write_unaligned(handle_out as *mut u64, 0);
        }
    }
    status as u32 as i32
}

/// `VOID PsTerminateSystemThread(NTSTATUS)`.
extern "win64" fn s_ps_terminate_system_thread(status: i32) {
    let (_label, reply_status, _, _, _) = unsafe {
        call_on4(
            (FSD_SERVICE_PS_TERMINATE_SYSTEM_THREAD_LABEL << 12) | 1,
            status as u32 as u64,
            0,
            0,
            0,
        )
    };
    print_str(b"[driver-thread] PsTerminateSystemThread unexpectedly returned status=0x");
    print_hex(reply_status as u32);
    print_str(b"\n");
    loop {
        crate::yield_now();
    }
}

