fn hosted_provider_leaf_from_path(path: &[u8]) -> Option<HostedAscii<HOSTED_DEP_PROVIDER_MAX>> {
    let mut start = 0usize;
    let mut i = 0usize;
    while i < path.len() {
        if path[i] == b'\\' || path[i] == b'/' {
            start = i + 1;
        }
        i += 1;
    }
    if start >= path.len() {
        return None;
    }
    let leaf = core::str::from_utf8(&path[start..]).ok()?;
    if !hosted_dependency_provider_dll(leaf) {
        return None;
    }
    let mut provider = HostedAscii::<HOSTED_DEP_PROVIDER_MAX>::empty();
    provider.set_str(leaf).then_some(provider)
}

unsafe fn record_hosted_provider_load(
    provider: HostedAscii<HOSTED_DEP_PROVIDER_MAX>,
    role: HostedProviderLoadRole,
    instance: usize,
    image_len: u32,
) {
    let summaries = hosted_provider_summaries_mut();
    for summary in summaries.iter_mut() {
        if summary.present() && hosted_ascii_eq_ignore_case(&summary.provider, &provider) {
            match role {
                HostedProviderLoadRole::PrimaryService => {
                    summary.primary_count = summary.primary_count.saturating_add(1);
                    summary.primary_image_bytes =
                        summary.primary_image_bytes.saturating_add(image_len as u64);
                }
                HostedProviderLoadRole::PrivateDependency => {
                    summary.private_count = summary.private_count.saturating_add(1);
                    summary.private_image_bytes =
                        summary.private_image_bytes.saturating_add(image_len as u64);
                    if summary.first_private_instance == 0 {
                        summary.first_private_instance = (instance as u64).saturating_add(1);
                    }
                }
            }
            return;
        }
    }

    let mut summary = HostedProviderSummary {
        provider,
        primary_count: 0,
        primary_image_bytes: 0,
        private_count: 0,
        private_image_bytes: 0,
        first_private_instance: 0,
    };
    match role {
        HostedProviderLoadRole::PrimaryService => {
            summary.primary_count = 1;
            summary.primary_image_bytes = image_len as u64;
        }
        HostedProviderLoadRole::PrivateDependency => {
            summary.private_count = 1;
            summary.private_image_bytes = image_len as u64;
            summary.first_private_instance = (instance as u64).saturating_add(1);
        }
    }
    summaries.push(summary);
}

unsafe fn find_hosted_provider_singleton(
    provider: &HostedAscii<HOSTED_DEP_PROVIDER_MAX>,
) -> Option<(usize, HostedProviderSingleton)> {
    let singletons = hosted_provider_singletons()?;
    for (index, singleton) in singletons.iter().copied().enumerate() {
        if singleton.present
            && hosted_ascii_eq_ignore_case(&singleton.provider, provider)
            && instance(singleton.instance).and_then(instance_domain_identity)
                == Some(singleton.owner_domain)
        {
            return Some((index, singleton));
        }
    }
    None
}

unsafe fn find_hosted_provider_singleton_by_cookie(
    provider_publication_cookie: u64,
) -> Option<(usize, HostedProviderSingleton)> {
    if provider_publication_cookie == 0 {
        return None;
    }
    let singletons = hosted_provider_singletons()?;
    for (index, singleton) in singletons.iter().copied().enumerate() {
        if singleton.present
            && singleton.provider_publication_cookie == provider_publication_cookie
            && instance(singleton.instance).and_then(instance_domain_identity)
                == Some(singleton.owner_domain)
        {
            return Some((index, singleton));
        }
    }
    None
}

unsafe fn clear_hosted_provider_singletons_for_instance(instance: usize) -> u64 {
    let singletons = hosted_provider_singletons_mut();
    let mut failures = 0u64;
    for singleton in singletons.iter_mut() {
        if singleton.present && singleton.instance == instance {
            let has_live_route = hosted_provider_dispatch_routes()
                .map(|routes| {
                    routes.iter().any(|route| {
                        route.used
                            && route.provider_domain == singleton.owner_domain
                            && route.provider_publication_cookie
                                == singleton.provider_publication_cookie
                    })
                })
                .unwrap_or(false);
            let has_live_dependency = hosted_provider_domain_dependencies()
                .map(|dependencies| {
                    dependencies.iter().any(|dependency| {
                        dependency.present
                            && dependency.provider_domain == singleton.owner_domain
                            && dependency.provider_publication_cookie
                                == singleton.provider_publication_cookie
                    })
                })
                .unwrap_or(false);
            if has_live_route || has_live_dependency {
                failures += 1;
            } else {
                clear_hosted_provider_internal_marshal_policies(
                    singleton.owner_domain,
                    singleton.provider_publication_cookie,
                );
                *singleton = HostedProviderSingleton::empty();
            }
        }
    }
    failures
}

unsafe fn register_hosted_provider_singleton(
    provider: HostedAscii<HOSTED_DEP_PROVIDER_MAX>,
    instance_index: usize,
    exec_va: u64,
    run_va: u64,
    image_offset: u64,
    image_len: u32,
    image_frames: u64,
    pool_base: u64,
    pool_frames: u64,
) -> bool {
    if image_offset & 0xfff != 0 || image_frames == 0 || image_frames > FSD_IMAGE_MAX_FRAMES {
        HOSTED_PROVIDER_SINGLETON_OVERFLOWS.fetch_add(1, Ordering::Relaxed);
        print_str(b"[driver-launch] provider singleton image capacity refused ");
        print_str(provider.as_bytes());
        print_str(b" frames=");
        print_u64(image_frames);
        print_str(b"\n");
        return false;
    }
    let Some(owner_domain) = instance(instance_index).and_then(instance_domain_identity) else {
        return false;
    };

    if let Some((_index, existing)) = find_hosted_provider_singleton(&provider) {
        if existing.image_offset == image_offset
            && existing.image_len == image_len
            && existing.image_frames == image_frames
            && existing.instance == instance_index
            && existing.owner_domain == owner_domain
            && existing.pool_base == pool_base
            && existing.pool_frames == pool_frames
        {
            return true;
        }
        HOSTED_PROVIDER_SINGLETON_CONFLICTS.fetch_add(1, Ordering::Relaxed);
        print_str(b"[driver-launch] provider singleton conflict ");
        print_str(provider.as_bytes());
        print_str(b"\n");
        return false;
    }

    let singletons = hosted_provider_singletons_mut();
    let Some(provider_publication_cookie) = (singletons.len() as u64).checked_add(1) else {
        HOSTED_PROVIDER_SINGLETON_OVERFLOWS.fetch_add(1, Ordering::Relaxed);
        print_str(b"[driver-launch] provider singleton cookie exhausted before ");
        print_str(provider.as_bytes());
        print_str(b"\n");
        return false;
    };
    let export_call_gate = if hosted_provider_has_export_marshal_policies(provider.as_str()) {
        hosted_provider_export_gate_va()
    } else {
        0
    };
    if singletons.try_reserve(1).is_err() {
        HOSTED_PROVIDER_SINGLETON_OVERFLOWS.fetch_add(1, Ordering::Relaxed);
        return false;
    }
    singletons.push(HostedProviderSingleton {
        present: true,
        provider,
        instance: instance_index,
        owner_domain,
        exec_va,
        run_va,
        image_offset,
        image_len,
        image_frames,
        pool_base,
        pool_frames,
        export_call_gate,
        provider_publication_cookie,
    });
    print_str(b"[driver-launch] provider singleton published ");
    print_str(provider.as_bytes());
    print_str(b" frames=");
    print_u64(image_frames);
    print_str(b" pool-frames=");
    print_u64(pool_frames);
    print_str(b" cookie=");
    print_u64(provider_publication_cookie);
    if export_call_gate != 0 {
        print_str(b" export-gate=0x");
        print_hex((export_call_gate >> 32) as u32);
        print_hex(export_call_gate as u32);
    }
    print_str(b"\n");
    true
}

pub(crate) fn hosted_provider_sharing_evidence() -> HostedProviderSharingEvidence {
    let mut evidence = HostedProviderSharingEvidence::default();
    unsafe {
        let summaries = hosted_provider_summaries();
        if let Some(summaries) = summaries {
            for summary in summaries {
                evidence.primary_services = evidence
                    .primary_services
                    .saturating_add(summary.primary_count);
                evidence.primary_service_image_bytes = evidence
                    .primary_service_image_bytes
                    .saturating_add(summary.primary_image_bytes);
                evidence.private_dependencies = evidence
                    .private_dependencies
                    .saturating_add(summary.private_count);
                evidence.private_dependency_image_bytes = evidence
                    .private_dependency_image_bytes
                    .saturating_add(summary.private_image_bytes);
                if summary.primary_count != 0 && summary.private_count != 0 {
                    evidence.private_dependencies_with_primary_provider = evidence
                        .private_dependencies_with_primary_provider
                        .saturating_add(summary.private_count);
                    evidence.unique_primary_provider_matches =
                        evidence.unique_primary_provider_matches.saturating_add(1);
                    if summary.first_private_instance != 0
                        && (evidence.first_private_dependency_with_primary_instance == 0
                            || summary.first_private_instance
                                < evidence.first_private_dependency_with_primary_instance)
                    {
                        evidence.first_private_dependency_with_primary_instance =
                            summary.first_private_instance;
                    }
                }
                if summary.private_count > 1 {
                    evidence.duplicate_private_dependencies = evidence
                        .duplicate_private_dependencies
                        .saturating_add(summary.private_count);
                }
            }
        }
        if let Some(singletons) = hosted_provider_singletons() {
            evidence.singleton_providers =
                singletons.iter().filter(|record| record.present).count() as u64;
        }
    }
    evidence.provider_domain_bindings = HOSTED_PROVIDER_DOMAIN_BINDINGS.load(Ordering::Relaxed);
    evidence.singleton_overflows = HOSTED_PROVIDER_SINGLETON_OVERFLOWS.load(Ordering::Relaxed);
    evidence.singleton_conflicts = HOSTED_PROVIDER_SINGLETON_CONFLICTS.load(Ordering::Relaxed);
    evidence.provider_export_requests = HOSTED_PROVIDER_EXPORT_REQUESTS.load(Ordering::Relaxed);
    evidence.provider_export_completions =
        HOSTED_PROVIDER_EXPORT_COMPLETIONS.load(Ordering::Relaxed);
    evidence.provider_export_rejections = HOSTED_PROVIDER_EXPORT_REJECTIONS.load(Ordering::Relaxed);
    evidence.provider_callback_requests = HOSTED_PROVIDER_CALLBACK_REQUESTS.load(Ordering::Relaxed);
    evidence.provider_callback_completions =
        HOSTED_PROVIDER_CALLBACK_COMPLETIONS.load(Ordering::Relaxed);
    evidence.provider_packet_array_export_requests =
        HOSTED_PROVIDER_PACKET_ARRAY_EXPORT_REQUESTS.load(Ordering::Relaxed);
    evidence.provider_packet_array_export_completions =
        HOSTED_PROVIDER_PACKET_ARRAY_EXPORT_COMPLETIONS.load(Ordering::Relaxed);
    evidence.provider_packet_array_protocol_receive_requests =
        HOSTED_PROVIDER_PACKET_ARRAY_PROTOCOL_RECEIVE_REQUESTS.load(Ordering::Relaxed);
    evidence.provider_packet_array_protocol_receive_completions =
        HOSTED_PROVIDER_PACKET_ARRAY_PROTOCOL_RECEIVE_COMPLETIONS.load(Ordering::Relaxed);
    evidence.provider_packet_array_protocol_receive_packet_requests =
        HOSTED_PROVIDER_PACKET_ARRAY_PROTOCOL_RECEIVE_PACKET_REQUESTS.load(Ordering::Relaxed);
    evidence.provider_packet_array_protocol_receive_packet_completions =
        HOSTED_PROVIDER_PACKET_ARRAY_PROTOCOL_RECEIVE_PACKET_COMPLETIONS.load(Ordering::Relaxed);
    evidence.provider_protocol_receive_requests =
        HOSTED_PROVIDER_PROTOCOL_RECEIVE_REQUESTS.load(Ordering::Relaxed);
    evidence.provider_protocol_receive_completions =
        HOSTED_PROVIDER_PROTOCOL_RECEIVE_COMPLETIONS.load(Ordering::Relaxed);
    evidence.provider_protocol_receive_complete_requests =
        HOSTED_PROVIDER_PROTOCOL_RECEIVE_COMPLETE_REQUESTS.load(Ordering::Relaxed);
    evidence.provider_protocol_receive_complete_completions =
        HOSTED_PROVIDER_PROTOCOL_RECEIVE_COMPLETE_COMPLETIONS.load(Ordering::Relaxed);
    evidence.provider_protocol_receive_packet_requests =
        HOSTED_PROVIDER_PROTOCOL_RECEIVE_PACKET_REQUESTS.load(Ordering::Relaxed);
    evidence.provider_protocol_receive_packet_completions =
        HOSTED_PROVIDER_PROTOCOL_RECEIVE_PACKET_COMPLETIONS.load(Ordering::Relaxed);
    evidence
}

unsafe fn clear_support_image_records(shared_va: u64) {
    write_volatile((shared_va + SH_SUPPORT_ENTRY_COUNT) as *mut u32, 0);
    write_volatile(
        (shared_va + SH_SUPPORT_ENTRY_CAPACITY) as *mut u32,
        SH_SUPPORT_RECORD_CAPACITY as u32,
    );
    write_volatile((shared_va + SH_SUPPORT_ENTRY_RVA) as *mut u64, 0);
    write_volatile((shared_va + SH_SUPPORT_DE_STATUS) as *mut i32, 0);
    write_volatile((shared_va + SH_SUPPORT_VERDICT) as *mut u32, 0);
    let mut index = 0u64;
    while index < SH_SUPPORT_RECORD_CAPACITY {
        let record = shared_va + SH_SUPPORT_RECORDS + index * SH_SUPPORT_RECORD_SIZE;
        write_volatile((record + SH_SUPPORT_RECORD_ENTRY_RVA) as *mut u64, 0);
        write_volatile((record + SH_SUPPORT_RECORD_STATUS) as *mut i32, 0);
        write_volatile((record + SH_SUPPORT_RECORD_VERDICT) as *mut u32, 0);
        index += 1;
    }
}

unsafe fn write_support_image_record(shared_va: u64, index: u32, entry_rva: u64) -> Option<()> {
    if index as u64 >= SH_SUPPORT_RECORD_CAPACITY {
        return None;
    }
    let record = shared_va + SH_SUPPORT_RECORDS + index as u64 * SH_SUPPORT_RECORD_SIZE;
    write_volatile(
        (record + SH_SUPPORT_RECORD_ENTRY_RVA) as *mut u64,
        entry_rva,
    );
    write_volatile((record + SH_SUPPORT_RECORD_STATUS) as *mut i32, 0);
    write_volatile((record + SH_SUPPORT_RECORD_VERDICT) as *mut u32, 0);
    Some(())
}

fn dependency_plan_contains(
    plan: &[PlannedDependencyImage],
    provider: &HostedAscii<HOSTED_DEP_PROVIDER_MAX>,
) -> bool {
    plan.iter()
        .any(|planned| hosted_ascii_eq_ignore_case(&planned.provider, provider))
}

fn provider_domain_plan_contains(
    plan: &[PlannedProviderDomain],
    provider: &HostedAscii<HOSTED_DEP_PROVIDER_MAX>,
) -> bool {
    plan.iter()
        .any(|planned| hosted_ascii_eq_ignore_case(&planned.provider, provider))
}

fn dependency_name_list_contains(
    names: &[HostedAscii<HOSTED_DEP_PROVIDER_MAX>],
    provider: &HostedAscii<HOSTED_DEP_PROVIDER_MAX>,
) -> bool {
    names
        .iter()
        .any(|existing| hosted_ascii_eq_ignore_case(existing, provider))
}

fn print_hosted_provider_domain_error(error: HostedProviderDomainError) {
    match error {
        HostedProviderDomainError::ImageOffsetUnaligned => print_str(b"image-offset-unaligned"),
        HostedProviderDomainError::EmptyImage => print_str(b"empty-image"),
        HostedProviderDomainError::EmptyImageFrames => print_str(b"empty-image-frames"),
        HostedProviderDomainError::ImageFrameCapacityOverflow => {
            print_str(b"image-frame-capacity-overflow")
        }
        HostedProviderDomainError::ImageExceedsFrames => print_str(b"image-exceeds-frames"),
        HostedProviderDomainError::EmptyPoolFrames => print_str(b"empty-pool-frames"),
        HostedProviderDomainError::EmptyProviderDomainCookie => {
            print_str(b"empty-provider-domain-cookie")
        }
    }
}

fn print_hosted_provider_import_binding_error(error: HostedProviderImportBindingError) {
    match error {
        HostedProviderImportBindingError::Domain(error) => {
            print_hosted_provider_domain_error(error)
        }
        HostedProviderImportBindingError::Export(error) => match error {
            nt_hosted_runtime::HostedProviderExportCallError::Overflow => {
                print_str(b"export-offset-overflow")
            }
            nt_hosted_runtime::HostedProviderExportCallError::ExportOutsideImage => {
                print_str(b"export-outside-image")
            }
        },
    }
}

fn print_hosted_provider_import_thunk_error(error: HostedProviderImportThunkError) {
    match error {
        HostedProviderImportThunkError::Overflow => print_str(b"thunk-overflow"),
        HostedProviderImportThunkError::ThunkOutsideTable => print_str(b"thunk-table-exhausted"),
        HostedProviderImportThunkError::OutputTooSmall => print_str(b"thunk-output-too-small"),
    }
}

fn hosted_provider_domain_descriptor(
    singleton: HostedProviderSingleton,
) -> HostedProviderDomainDescriptor {
    HostedProviderDomainDescriptor {
        image_offset: singleton.image_offset,
        image_len: singleton.image_len as u64,
        image_frames: singleton.image_frames,
        pool_base: singleton.pool_base,
        pool_frames: singleton.pool_frames,
        export_call_gate: singleton.export_call_gate,
        provider_publication_cookie: singleton.provider_publication_cookie,
    }
}

fn hosted_provider_export_failure(status: i32) -> u64 {
    HOSTED_PROVIDER_EXPORT_REJECTIONS.fetch_add(1, Ordering::Relaxed);
    status as u32 as u64
}

fn hosted_provider_callback_failure(status: i32) -> u64 {
    status as u32 as u64
}

