fn print_hosted_provider_callback_name(record: HostedProviderCallbackRecord) {
    match record.callback_kind {
        HOSTED_PROVIDER_CALLBACK_KIND_MINIPORT => {
            print_ndis_miniport_callback_name(record.callback_offset)
        }
        HOSTED_PROVIDER_CALLBACK_KIND_PROTOCOL => {
            print_ndis_protocol_callback_name(record.callback_offset)
        }
        HOSTED_PROVIDER_CALLBACK_KIND_MINIPORT_TIMER => match record.callback_offset {
            NDIS_MINIPORT_TIMER_FUNCTION_CALLBACK_OFFSET_X64 => print_str(b"TimerFunction"),
            _ => print_str(b"unknown"),
        },
        HOSTED_PROVIDER_CALLBACK_KIND_NDIS_WORK_ITEM => match record.callback_offset {
            NDIS_WORK_ITEM_ROUTINE_CALLBACK_OFFSET_X64 => print_str(b"WorkItemRoutine"),
            _ => print_str(b"unknown"),
        },
        _ => print_str(b"unknown"),
    }
}

unsafe fn trace_hosted_provider_export(
    phase: &[u8],
    provider: &HostedAscii<HOSTED_DEP_PROVIDER_MAX>,
    provider_publication_cookie: u64,
    provider_export_rva: u64,
    args: &[u64; HOSTED_PROVIDER_EXPORT_ARG_CAP],
    result: u64,
) {
    if HOSTED_PROVIDER_EXPORT_TRACE_COUNT.fetch_add(1, Ordering::Relaxed)
        >= HOSTED_PROVIDER_TRACE_CAP
    {
        return;
    }
    print_str(b"[provider-export] ");
    print_str(phase);
    print_str(b" provider=");
    print_str(provider.as_bytes());
    print_str(b" cookie=");
    print_u64(provider_publication_cookie);
    print_str(b" rva=0x");
    print_hex(provider_export_rva as u32);
    print_str(b" args=");
    print_hex64(args[0]);
    print_str(b",");
    print_hex64(args[1]);
    print_str(b",");
    print_hex64(args[2]);
    print_str(b",");
    print_hex64(args[3]);
    print_str(b" stack=");
    print_hex64(args[4]);
    print_str(b",");
    print_hex64(args[5]);
    if phase == b"done" {
        print_str(b" result=0x");
        print_hex((result >> 32) as u32);
        print_hex(result as u32);
    }
    print_str(b"\n");
}

unsafe fn trace_hosted_provider_export_rejection(
    provider: &HostedAscii<HOSTED_DEP_PROVIDER_MAX>,
    provider_publication_cookie: u64,
    provider_export_rva: u64,
    status: i32,
    stage: &[u8],
) {
    let trace = HOSTED_PROVIDER_EXPORT_REJECTION_TRACE_COUNT.fetch_add(1, Ordering::Relaxed);
    if trace >= HOSTED_PROVIDER_EXPORT_REJECTION_TRACE_CAP {
        return;
    }
    print_str(b"[provider-export-reject] provider=");
    print_str(provider.as_bytes());
    print_str(b" cookie=");
    print_u64(provider_publication_cookie);
    print_str(b" rva=0x");
    print_hex(provider_export_rva as u32);
    print_str(b" stage=");
    print_str(stage);
    print_str(b" status=0x");
    print_hex(status as u32);
    print_str(b"\n");
}

unsafe fn trace_hosted_provider_export_frame(
    phase: &[u8],
    provider_export_rva: u64,
    dependent_index: usize,
    dependent_inst: DriverInstance,
    caller_rsp: u64,
) {
    let trace = HOSTED_PROVIDER_EXPORT_FRAME_TRACE_COUNT.fetch_add(1, Ordering::Relaxed);
    if trace >= HOSTED_PROVIDER_EXPORT_FRAME_TRACE_CAP {
        return;
    }
    print_str(b"[provider-export-frame] ");
    print_str(phase);
    print_str(b" dependent-inst=");
    print_u64(dependent_index as u64);
    print_str(b" rva=0x");
    print_hex(provider_export_rva as u32);
    print_str(b" caller-rsp=");
    print_hex64(caller_rsp);
    if let Some(stack_exec) =
        component_to_exec_va_for_instance(dependent_index, dependent_inst, caller_rsp, 0x40)
    {
        print_str(b" ret=");
        print_hex64(read_unaligned(stack_exec as *const u64));
        print_str(b" home=");
        print_hex64(read_unaligned((stack_exec + 0x08) as *const u64));
        print_str(b",");
        print_hex64(read_unaligned((stack_exec + 0x10) as *const u64));
        print_str(b",");
        print_hex64(read_unaligned((stack_exec + 0x18) as *const u64));
        print_str(b",");
        print_hex64(read_unaligned((stack_exec + 0x20) as *const u64));
        print_str(b" tail=");
        print_hex64(read_unaligned((stack_exec + 0x28) as *const u64));
        print_str(b",");
        print_hex64(read_unaligned((stack_exec + 0x30) as *const u64));
        print_str(b",");
        print_hex64(read_unaligned((stack_exec + 0x38) as *const u64));
    } else {
        print_str(b" stack=no-map");
    }
    print_str(b"\n");
}

unsafe fn trace_hosted_provider_callback(
    phase: &[u8],
    record: HostedProviderCallbackRecord,
    args: [u64; 4],
    stack_args: &[u64; PROVIDER_CALLBACK_STACK_QWORDS],
    result: Result<u64, i32>,
) {
    if HOSTED_PROVIDER_CALLBACK_TRACE_COUNT.fetch_add(1, Ordering::Relaxed)
        >= HOSTED_PROVIDER_TRACE_CAP
    {
        return;
    }
    print_str(b"[provider-callback] ");
    print_str(phase);
    print_str(b" provider-inst=");
    print_u64(record.provider_instance as u64);
    print_str(b" dependent-inst=");
    print_u64(record.dependent_instance as u64);
    print_str(b" off=0x");
    print_hex(record.callback_offset as u32);
    print_str(b" kind=");
    print_hosted_provider_callback_kind_name(record.callback_kind);
    print_str(b" ");
    print_hosted_provider_callback_name(record);
    print_str(b" target=");
    print_hex64(record.target);
    print_str(b" args=");
    print_hex64(args[0]);
    print_str(b",");
    print_hex64(args[1]);
    print_str(b",");
    print_hex64(args[2]);
    print_str(b",");
    print_hex64(args[3]);
    print_str(b" stack=");
    print_hex64(stack_args[0]);
    print_str(b",");
    print_hex64(stack_args[1]);
    if phase == b"done" {
        match result {
            Ok(value) => {
                print_str(b" result=0x");
                print_hex((value >> 32) as u32);
                print_hex(value as u32);
            }
            Err(status) => {
                print_str(b" status=0x");
                print_hex(status as u32);
            }
        }
    }
    print_str(b"\n");
}

unsafe fn trace_hosted_provider_callback_wall(
    record: HostedProviderCallbackRecord,
    dependent_inst: DriverInstance,
    pr: crate::spawn_hosts::PumpResult,
) {
    let trace = HOSTED_PROVIDER_CALLBACK_WALL_TRACE_COUNT.fetch_add(1, Ordering::Relaxed);
    if trace >= HOSTED_PROVIDER_CALLBACK_WALL_TRACE_CAP {
        return;
    }
    let mut regs = [0u64; 20];
    crate::win32k_glue::tcb_read_regs20(dependent_inst.tcb, &mut regs);
    print_str(b"[provider-callback-wall] provider-inst=");
    print_u64(record.provider_instance as u64);
    print_str(b" dependent-inst=");
    print_u64(record.dependent_instance as u64);
    print_str(b" off=0x");
    print_hex(record.callback_offset as u32);
    print_str(b" kind=");
    print_hosted_provider_callback_kind_name(record.callback_kind);
    print_str(b" ");
    print_hosted_provider_callback_name(record);
    print_str(b" target=");
    print_hex64(record.target);
    print_str(b" status=0x");
    print_hex(pr.status as u32);
    print_str(b" wall-ip=");
    print_hex64(pr.wall_ip);
    print_str(b" wall-addr=");
    print_hex64(pr.wall_addr);
    print_str(b" regs rip/rsp/rax/rcx/rdx/r8/r9=");
    print_hex64(regs[0]);
    print_str(b"/");
    print_hex64(regs[1]);
    print_str(b"/");
    print_hex64(regs[3]);
    print_str(b"/");
    print_hex64(regs[5]);
    print_str(b"/");
    print_hex64(regs[6]);
    print_str(b"/");
    print_hex64(regs[10]);
    print_str(b"/");
    print_hex64(regs[11]);
    let rsp = regs[1];
    if let Some(stack_exec) =
        component_to_exec_va_for_instance(record.dependent_instance, dependent_inst, rsp, 64)
    {
        print_str(b" stack=");
        let mut index = 0u64;
        while index < 8 {
            if index != 0 {
                print_str(b",");
            }
            print_hex64(read_unaligned((stack_exec + index * 8) as *const u64));
            index += 1;
        }
    }
    print_str(b"\n");
}

fn record_provider_protocol_receive_request(record: HostedProviderCallbackRecord) {
    if record.callback_kind != HOSTED_PROVIDER_CALLBACK_KIND_PROTOCOL {
        return;
    }
    match record.callback_offset {
        NDIS_PROTOCOL_RECEIVE_CALLBACK_OFFSET_X64 => {
            HOSTED_PROVIDER_PROTOCOL_RECEIVE_REQUESTS.fetch_add(1, Ordering::Relaxed);
        }
        NDIS_PROTOCOL_RECEIVE_COMPLETE_CALLBACK_OFFSET_X64 => {
            HOSTED_PROVIDER_PROTOCOL_RECEIVE_COMPLETE_REQUESTS.fetch_add(1, Ordering::Relaxed);
        }
        NDIS_PROTOCOL_RECEIVE_PACKET_CALLBACK_OFFSET_X64 => {
            HOSTED_PROVIDER_PROTOCOL_RECEIVE_PACKET_REQUESTS.fetch_add(1, Ordering::Relaxed);
        }
        _ => {}
    }
}

fn record_provider_protocol_receive_completion(record: HostedProviderCallbackRecord) {
    if record.callback_kind != HOSTED_PROVIDER_CALLBACK_KIND_PROTOCOL {
        return;
    }
    match record.callback_offset {
        NDIS_PROTOCOL_RECEIVE_CALLBACK_OFFSET_X64 => {
            HOSTED_PROVIDER_PROTOCOL_RECEIVE_COMPLETIONS.fetch_add(1, Ordering::Relaxed);
        }
        NDIS_PROTOCOL_RECEIVE_COMPLETE_CALLBACK_OFFSET_X64 => {
            HOSTED_PROVIDER_PROTOCOL_RECEIVE_COMPLETE_COMPLETIONS.fetch_add(1, Ordering::Relaxed);
        }
        NDIS_PROTOCOL_RECEIVE_PACKET_CALLBACK_OFFSET_X64 => {
            HOSTED_PROVIDER_PROTOCOL_RECEIVE_PACKET_COMPLETIONS.fetch_add(1, Ordering::Relaxed);
        }
        _ => {}
    }
}

fn hosted_provider_domain_dependency_is_live(dependency: HostedProviderDomainDependency) -> bool {
    !dependency.retiring && hosted_provider_domain_dependency_is_current(dependency)
}

fn hosted_provider_domain_dependency_is_current(
    dependency: HostedProviderDomainDependency,
) -> bool {
    if !dependency.present
        || instance(dependency.dependent_instance).and_then(instance_domain_identity)
            != Some(dependency.dependent_domain)
        || instance(dependency.provider_instance).and_then(instance_domain_identity)
            != Some(dependency.provider_domain)
        || io_manager_mut().hosted_provider_identity(dependency.dependent_domain)
            != Some(dependency.provider_domain)
    {
        return false;
    }
    unsafe {
        matches!(
            find_hosted_provider_singleton_by_cookie(
                dependency.provider_publication_cookie,
            ),
            Some((_, singleton))
                if singleton.instance == dependency.provider_instance
                    && singleton.owner_domain == dependency.provider_domain
        )
    }
}

unsafe fn hosted_provider_domain_dependency_for_pair_current(
    provider_instance: usize,
    dependent_instance: usize,
) -> Option<HostedProviderDomainDependency> {
    hosted_provider_domain_dependencies()?
        .iter()
        .copied()
        .find(|dependency| {
            dependency.provider_instance == provider_instance
                && dependency.dependent_instance == dependent_instance
                && hosted_provider_domain_dependency_is_current(*dependency)
        })
}

unsafe fn hosted_provider_domain_dependency_for_pair(
    provider_instance: usize,
    dependent_instance: usize,
) -> Option<HostedProviderDomainDependency> {
    hosted_provider_domain_dependencies()?
        .iter()
        .copied()
        .find(|dependency| {
            dependency.provider_instance == provider_instance
                && dependency.dependent_instance == dependent_instance
                && hosted_provider_domain_dependency_is_live(*dependency)
        })
}

unsafe fn ensure_hosted_provider_domain_dependency(
    provider_instance: usize,
    provider_publication_cookie: u64,
    dependent_instance: usize,
) -> Result<HostedProviderDomainDependency, i32> {
    if provider_instance == dependent_instance || provider_publication_cookie == 0 {
        return Err(STATUS_INVALID_PARAMETER);
    }
    let provider_domain = instance(provider_instance)
        .and_then(instance_domain_identity)
        .ok_or(STATUS_DEVICE_NOT_READY)?;
    let dependent_domain = instance(dependent_instance)
        .and_then(instance_domain_identity)
        .ok_or(STATUS_DEVICE_NOT_READY)?;
    let Some((_, singleton)) =
        find_hosted_provider_singleton_by_cookie(provider_publication_cookie)
    else {
        return Err(STATUS_DEVICE_NOT_READY);
    };
    if singleton.instance != provider_instance || singleton.owner_domain != provider_domain {
        return Err(STATUS_INVALID_PARAMETER);
    }
    if let Some(dependencies) = hosted_provider_domain_dependencies() {
        if let Some(existing) = dependencies.iter().copied().find(|dependency| {
            dependency.present && dependency.dependent_domain == dependent_domain
        }) {
            return if existing.provider_instance == provider_instance
                && existing.dependent_instance == dependent_instance
                && existing.provider_domain == provider_domain
                && existing.provider_publication_cookie == provider_publication_cookie
            {
                if hosted_provider_domain_dependency_is_live(existing) {
                    Ok(existing)
                } else {
                    Err(STATUS_DEVICE_NOT_READY)
                }
            } else {
                Err(nt_status::NtStatus::OBJECT_NAME_COLLISION.raw())
            };
        }
    }
    let dependencies = hosted_provider_domain_dependencies_mut();
    let vacant_index = dependencies.iter().position(|slot| !slot.present);
    if vacant_index.is_none() {
        dependencies
            .try_reserve(1)
            .map_err(|_| STATUS_INSUFFICIENT_RESOURCES)?;
    }
    let created = io_manager_mut()
        .set_hosted_domain_provider(dependent_domain, provider_domain)
        .map_err(nt_status::NtStatus::raw)?;
    if !created {
        return Err(nt_status::NtStatus::OBJECT_NAME_COLLISION.raw());
    }
    let dependency = HostedProviderDomainDependency {
        present: true,
        retiring: false,
        in_flight: 0,
        dependent_instance,
        provider_instance,
        dependent_domain,
        provider_domain,
        provider_publication_cookie,
    };
    if let Some(index) = vacant_index {
        dependencies[index] = dependency;
    } else {
        dependencies.push(dependency);
    }
    Ok(dependency)
}

struct HostedProviderDependencyDispatchLease {
    provider_domain: HostedDomainIdentity,
    dependent_domain: HostedDomainIdentity,
    provider_publication_cookie: u64,
}

impl Drop for HostedProviderDependencyDispatchLease {
    fn drop(&mut self) {
        unsafe {
            let dependencies = hosted_provider_domain_dependencies_mut();
            let Some(dependency) = dependencies.iter_mut().find(|dependency| {
                dependency.present
                    && dependency.provider_domain == self.provider_domain
                    && dependency.dependent_domain == self.dependent_domain
                    && dependency.provider_publication_cookie == self.provider_publication_cookie
            }) else {
                panic!("hosted provider dependency disappeared with dispatch in flight");
            };
            assert!(
                dependency.in_flight != 0,
                "hosted provider dependency dispatch lease underflow"
            );
            dependency.in_flight -= 1;
        }
    }
}

unsafe fn acquire_hosted_provider_dependency_dispatch_lease(
    provider_instance: usize,
    dependent_instance: usize,
    provider_publication_cookie: u64,
) -> Option<HostedProviderDependencyDispatchLease> {
    let dependencies = hosted_provider_domain_dependencies_mut();
    let dependency = dependencies.iter_mut().find(|dependency| {
        dependency.provider_instance == provider_instance
            && dependency.dependent_instance == dependent_instance
            && dependency.provider_publication_cookie == provider_publication_cookie
            && hosted_provider_domain_dependency_is_live(**dependency)
    })?;
    dependency.in_flight = dependency.in_flight.checked_add(1)?;
    Some(HostedProviderDependencyDispatchLease {
        provider_domain: dependency.provider_domain,
        dependent_domain: dependency.dependent_domain,
        provider_publication_cookie,
    })
}

unsafe fn begin_hosted_provider_dependency_retirement_for_instance(
    instance_index: usize,
    domain: HostedDomainIdentity,
) -> u64 {
    let Some(dependencies) =
        (*core::ptr::addr_of_mut!(HOSTED_PROVIDER_DOMAIN_DEPENDENCIES)).as_mut()
    else {
        return 0;
    };
    let mut failures = 0u64;
    for dependency in dependencies
        .iter_mut()
        .filter(|dependency| dependency.present)
    {
        if dependency.provider_instance == instance_index {
            if dependency.provider_domain != domain {
                failures += 1;
            } else if dependency.dependent_instance != instance_index {
                // Provider domains cannot retire while a live dependent still owns the link.
                failures += 1;
            }
            continue;
        }
        if dependency.dependent_instance != instance_index {
            continue;
        }
        if dependency.dependent_domain != domain
            || !hosted_provider_domain_dependency_is_current(*dependency)
        {
            failures += 1;
            continue;
        }
        dependency.retiring = true;
        if dependency.in_flight != 0 {
            failures += 1;
        }
    }
    failures
}

unsafe fn register_hosted_provider_callback_record(
    provider_instance: usize,
    dependent_instance: usize,
    target: u64,
    callback_offset: u64,
    callback_kind: u8,
    thunk_token: HostedThunkSlotToken,
    thunk_key: HostedThunkSlotKey,
) -> Option<(usize, u64)> {
    let dependency =
        hosted_provider_domain_dependency_for_pair(provider_instance, dependent_instance)?;
    let dependent_inst = instance(dependent_instance)?;
    let image_frames = if dependent_inst.image_frames == 0 {
        FSD_IMAGE_FRAMES
    } else {
        dependent_inst.image_frames
    };
    let image_end = FSD_CODE_VA.checked_add(image_frames.checked_mul(0x1000)?)?;
    if target < FSD_CODE_VA || target >= image_end {
        return None;
    }
    let records = hosted_provider_callback_records_mut();
    let index = if let Some(index) = records.iter().position(|record| !record.present) {
        index
    } else {
        records.try_reserve(1).ok()?;
        records.len()
    };
    let cookie = HOSTED_PROVIDER_CALLBACK_NEXT_COOKIE
        .fetch_update(Ordering::Relaxed, Ordering::Relaxed, |cookie| {
            cookie.checked_add(1).filter(|next| *next != 0)
        })
        .ok()?;
    let record = HostedProviderCallbackRecord {
        present: true,
        construction_state: HostedProviderConstructionState::Constructing,
        callback_cookie: cookie,
        thunk_token,
        thunk_key,
        provider_instance,
        dependent_instance,
        provider_domain: dependency.provider_domain,
        dependent_domain: dependency.dependent_domain,
        provider_publication_cookie: dependency.provider_publication_cookie,
        target,
        callback_offset,
        callback_kind,
    };
    if index == records.len() {
        records.push(record);
    } else {
        records[index] = record;
    }
    Some((index, cookie))
}

unsafe fn finish_hosted_provider_callback_record(
    index: usize,
    callback_cookie: u64,
    thunk_token: HostedThunkSlotToken,
    thunk_key: HostedThunkSlotKey,
) -> bool {
    let Some(record) = hosted_provider_callback_records_mut().get_mut(index) else {
        return false;
    };
    if !record.present
        || record.construction_state != HostedProviderConstructionState::Constructing
        || record.callback_cookie != callback_cookie
        || record.thunk_token != thunk_token
        || record.thunk_key != thunk_key
    {
        return false;
    }
    record.construction_state = HostedProviderConstructionState::Published;
    true
}

unsafe fn abort_hosted_provider_callback_record(
    index: usize,
    callback_cookie: u64,
    thunk_token: HostedThunkSlotToken,
    thunk_key: HostedThunkSlotKey,
) {
    if let Some(record) = hosted_provider_callback_records_mut().get_mut(index) {
        if record.present
            && matches!(
                record.construction_state,
                HostedProviderConstructionState::Constructing
                    | HostedProviderConstructionState::Published
            )
            && record.callback_cookie == callback_cookie
            && record.thunk_token == thunk_token
            && record.thunk_key == thunk_key
        {
            record.present = false;
        }
    }
}

unsafe fn hosted_provider_callback_record_for_thunk(
    thunk_token: HostedThunkSlotToken,
    thunk_key: HostedThunkSlotKey,
) -> Option<HostedProviderCallbackRecord> {
    hosted_provider_callback_records()?
        .iter()
        .copied()
        .find(|record| {
            record.present
                && record.construction_state == HostedProviderConstructionState::Published
                && record.thunk_token == thunk_token
                && record.thunk_key == thunk_key
        })
}

unsafe fn retire_hosted_provider_callback_record_for_thunk(
    thunk_token: HostedThunkSlotToken,
    thunk_key: HostedThunkSlotKey,
) -> bool {
    let mut matched = false;
    for record in hosted_provider_callback_records_mut().iter_mut() {
        if record.present && record.thunk_token == thunk_token && record.thunk_key == thunk_key {
            record.construction_state = HostedProviderConstructionState::RollingBack;
            record.present = false;
            matched = true;
        }
    }
    matched
}

unsafe fn reserve_hosted_provider_callback_parent(
    provider_instance: usize,
    dependent_instance: usize,
    kind: u8,
) -> Result<usize, i32> {
    if !matches!(
        kind,
        HOSTED_PROVIDER_CALLBACK_PARENT_KIND_MINIPORT
            | HOSTED_PROVIDER_CALLBACK_PARENT_KIND_PROTOCOL
    ) {
        return Err(STATUS_INVALID_PARAMETER);
    }
    let owner = hosted_provider_object_owner_for_pair(provider_instance, dependent_instance)
        .ok_or(STATUS_DEVICE_NOT_READY)?;
    let parents = hosted_provider_callback_parents_mut();
    let index = if let Some(index) = parents.iter().position(|parent| !parent.present) {
        index
    } else {
        parents
            .try_reserve(1)
            .map_err(|_| STATUS_INSUFFICIENT_RESOURCES)?;
        parents.len()
    };
    let parent = HostedProviderCallbackParent {
        present: true,
        construction_state: HostedProviderConstructionState::Constructing,
        owner,
        provider_instance,
        dependent_instance,
        kind,
        provider_handle: 0,
        bindings: [None; NDIS_MINIPORT_CHARACTERISTICS_CALLBACK_CAP],
        binding_count: 0,
    };
    if index == parents.len() {
        parents.push(parent);
    } else {
        parents[index] = parent;
    }
    Ok(index)
}

unsafe fn retain_hosted_provider_callback_parent_binding(
    index: usize,
    binding: HostedExecutableThunkBinding,
) -> bool {
    let Some(parent) = hosted_provider_callback_parents_mut().get_mut(index) else {
        return false;
    };
    if !parent.present
        || parent.construction_state != HostedProviderConstructionState::Constructing
        || binding.instance_index != parent.provider_instance
        || parent.binding_count >= parent.bindings.len()
    {
        return false;
    }
    parent.bindings[parent.binding_count] = Some(binding);
    parent.binding_count += 1;
    true
}

unsafe fn rollback_hosted_provider_callback_parent(index: usize) {
    let Some(parent) = hosted_provider_callback_parents_mut().get_mut(index) else {
        return;
    };
    if !parent.present
        || !matches!(
            parent.construction_state,
            HostedProviderConstructionState::Constructing
                | HostedProviderConstructionState::RollingBack
        )
    {
        return;
    }
    parent.construction_state = HostedProviderConstructionState::RollingBack;
    let mut failed = false;
    let mut binding_index = 0usize;
    while binding_index < parent.binding_count {
        if let Some(binding) = parent.bindings[binding_index] {
            if release_instance_executable_thunk_binding(binding, true) {
                parent.bindings[binding_index] = None;
            } else {
                failed = true;
            }
        }
        binding_index += 1;
    }
    if !failed {
        *parent = HostedProviderCallbackParent::empty();
    }
}

unsafe fn retain_indeterminate_hosted_provider_callback_parent(index: usize) {
    if let Some(parent) = hosted_provider_callback_parents_mut().get_mut(index) {
        if parent.present
            && parent.construction_state == HostedProviderConstructionState::Constructing
        {
            parent.construction_state = HostedProviderConstructionState::CompensationRequired;
        }
    }
}

unsafe fn retain_hosted_provider_callback_parent_compensation(index: usize, provider_handle: u64) {
    if let Some(parent) = hosted_provider_callback_parents_mut().get_mut(index) {
        if parent.present
            && parent.construction_state == HostedProviderConstructionState::Constructing
        {
            parent.provider_handle = provider_handle;
            parent.construction_state = HostedProviderConstructionState::CompensationRequired;
        }
    }
}

unsafe fn finish_hosted_provider_callback_parent(index: usize, provider_handle: u64) -> bool {
    let parents = hosted_provider_callback_parents_mut();
    let Some(parent) = parents.get(index) else {
        return false;
    };
    if !parent.present
        || parent.construction_state != HostedProviderConstructionState::Constructing
        || provider_handle == 0
        || parent.binding_count == 0
        || parent.bindings[..parent.binding_count]
            .iter()
            .any(Option::is_none)
        || !hosted_provider_object_owner_is_live(
            parent.owner,
            parent.provider_instance,
            parent.dependent_instance,
        )
    {
        return false;
    }
    if parents.iter().enumerate().any(|(other_index, other)| {
        other_index != index
            && other.present
            && other.construction_state == HostedProviderConstructionState::Published
            && other.provider_instance == parent.provider_instance
            && other.dependent_instance == parent.dependent_instance
            && other.kind == parent.kind
            && other.provider_handle == provider_handle
    }) {
        return false;
    }
    let parent = &mut parents[index];
    parent.provider_handle = provider_handle;
    parent.construction_state = HostedProviderConstructionState::Published;
    true
}

unsafe fn retire_hosted_provider_callback_parent_by_handle(
    provider_instance: usize,
    dependent_instance: usize,
    kind: u8,
    provider_handle: u64,
) -> bool {
    let Some(parents) = (*core::ptr::addr_of_mut!(HOSTED_PROVIDER_CALLBACK_PARENTS)).as_mut()
    else {
        return true;
    };
    let Some(index) = parents.iter().position(|parent| {
        parent.present
            && matches!(
                parent.construction_state,
                HostedProviderConstructionState::Published
                    | HostedProviderConstructionState::CompensationRequired
            )
            && parent.provider_instance == provider_instance
            && parent.dependent_instance == dependent_instance
            && parent.kind == kind
            && parent.provider_handle == provider_handle
    }) else {
        return true;
    };
    parents[index].construction_state = HostedProviderConstructionState::RollingBack;
    rollback_hosted_provider_callback_parent(index);
    hosted_provider_callback_parents()
        .and_then(|parents| parents.get(index))
        .is_none_or(|parent| !parent.present)
}

unsafe fn clear_hosted_provider_callback_parents_for_instance(
    instance_index: usize,
    domain: HostedDomainIdentity,
) -> u64 {
    let parent_count = hosted_provider_callback_parents().map_or(0, Vec::len);
    let mut failures = 0u64;
    for index in 0..parent_count {
        let Some(parent) = hosted_provider_callback_parents().and_then(|rows| rows.get(index))
        else {
            continue;
        };
        if !parent.present
            || parent.provider_instance != instance_index
                && parent.dependent_instance != instance_index
        {
            continue;
        }
        if !hosted_provider_object_owner_matches_instance(
            parent.owner,
            parent.provider_instance,
            parent.dependent_instance,
            instance_index,
            domain,
        ) || !matches!(
            parent.construction_state,
            HostedProviderConstructionState::Constructing
                | HostedProviderConstructionState::RollingBack
        ) {
            failures += 1;
            continue;
        }
        rollback_hosted_provider_callback_parent(index);
        if hosted_provider_callback_parents()
            .and_then(|rows| rows.get(index))
            .is_some_and(|parent| parent.present)
        {
            failures += 1;
        }
    }
    failures
}

unsafe fn hosted_provider_callback_record(cookie: u64) -> Option<HostedProviderCallbackRecord> {
    if cookie == 0 {
        return None;
    }
    let record = hosted_provider_callback_records()?
        .iter()
        .copied()
        .find(|record| record.present && record.callback_cookie == cookie)?;
    if !record.present
        || record.construction_state != HostedProviderConstructionState::Published
        || instance(record.provider_instance).and_then(instance_domain_identity)
            != Some(record.provider_domain)
        || instance(record.dependent_instance).and_then(instance_domain_identity)
            != Some(record.dependent_domain)
    {
        return None;
    }
    if !driver_instance_thunk_slots()
        .and_then(|registries| registries.get(record.provider_instance))
        .is_some_and(|registry| registry.is_live(record.thunk_token, record.thunk_key))
    {
        return None;
    }
    let dependency = hosted_provider_domain_dependency_for_pair(
        record.provider_instance,
        record.dependent_instance,
    )?;
    (dependency.provider_domain == record.provider_domain
        && dependency.dependent_domain == record.dependent_domain
        && dependency.provider_publication_cookie == record.provider_publication_cookie)
        .then_some(record)
}

unsafe fn hosted_provider_callback_records_reference_route(
    route: HostedProviderDispatchRoute,
) -> bool {
    hosted_provider_callback_records().is_some_and(|records| {
        records.iter().any(|record| {
            record.present
                && record.provider_domain == route.provider_domain
                && record.dependent_domain == route.dependent_domain
                && record.provider_publication_cookie == route.provider_publication_cookie
        })
    })
}

unsafe fn hosted_provider_dispatch_routes_mut() -> &'static mut Vec<HostedProviderDispatchRoute> {
    let slot = &mut *core::ptr::addr_of_mut!(HOSTED_PROVIDER_DISPATCH_ROUTES);
    if slot.is_none() {
        *slot = Some(Vec::new());
    }
    slot.as_mut().unwrap()
}

unsafe fn hosted_provider_dispatch_routes() -> Option<&'static Vec<HostedProviderDispatchRoute>> {
    (*core::ptr::addr_of!(HOSTED_PROVIDER_DISPATCH_ROUTES)).as_ref()
}

fn hosted_provider_dispatch_route_is_live(route: HostedProviderDispatchRoute) -> bool {
    if !route.used
        || route.construction_state != HostedProviderConstructionState::Published
        || route.retiring
    {
        return false;
    }
    let dependent_live = instance(route.dependent_instance).and_then(instance_domain_identity);
    let provider_live = instance(route.provider_instance).and_then(instance_domain_identity);
    if dependent_live != Some(route.dependent_domain)
        || provider_live != Some(route.provider_domain)
    {
        return false;
    }
    unsafe {
        let Some(dependency) = hosted_provider_domain_dependency_for_pair(
            route.provider_instance,
            route.dependent_instance,
        ) else {
            return false;
        };
        if dependency.dependent_domain != route.dependent_domain
            || dependency.provider_domain != route.provider_domain
            || dependency.provider_publication_cookie != route.provider_publication_cookie
        {
            return false;
        }
        matches!(
            find_hosted_provider_singleton_by_cookie(route.provider_publication_cookie),
            Some((_, singleton))
                if singleton.instance == route.provider_instance
                    && singleton.owner_domain == route.provider_domain
        )
    }
}

unsafe fn hosted_provider_dispatch_route(index: usize) -> Option<HostedProviderDispatchRoute> {
    hosted_provider_dispatch_routes()?
        .get(index)
        .copied()
        .filter(|route| hosted_provider_dispatch_route_is_live(*route))
}

unsafe fn hosted_provider_dispatch_route_for_instance(
    dependent_instance: usize,
) -> Option<HostedProviderDispatchRoute> {
    hosted_provider_dispatch_routes()?
        .iter()
        .copied()
        .find(|route| {
            route.dependent_instance == dependent_instance
                && hosted_provider_dispatch_route_is_live(*route)
        })
}

unsafe fn hosted_provider_dispatch_route_for_pair(
    provider_instance: usize,
    dependent_instance: usize,
) -> Option<(usize, HostedProviderDispatchRoute)> {
    hosted_provider_dispatch_routes()?
        .iter()
        .copied()
        .enumerate()
        .find(|(_, route)| {
            route.provider_instance == provider_instance
                && route.dependent_instance == dependent_instance
                && hosted_provider_dispatch_route_is_live(*route)
        })
}

unsafe fn hosted_provider_dispatch_route_for_wrapper(
    provider_instance: usize,
    provider_wrapper_handle: u64,
) -> Option<(usize, HostedProviderDispatchRoute)> {
    if provider_wrapper_handle == 0 {
        return None;
    }
    hosted_provider_dispatch_routes()?
        .iter()
        .copied()
        .enumerate()
        .find(|(_, route)| {
            route.provider_instance == provider_instance
                && route.provider_wrapper_handle == provider_wrapper_handle
                && hosted_provider_dispatch_route_is_live(*route)
        })
}

fn clear_hosted_provider_domain_link(
    dependent: HostedDomainIdentity,
    provider: HostedDomainIdentity,
) -> Result<(), nt_status::NtStatus> {
    match io_manager_mut().hosted_provider_identity(dependent) {
        Some(link) if link == provider => {
            io_manager_mut().clear_hosted_domain_provider(dependent, provider)
        }
        None => Ok(()),
        Some(_) => Err(nt_status::NtStatus::INVALID_PARAMETER),
    }
}

unsafe fn hosted_provider_callback_records_reference_dependency(
    dependency: HostedProviderDomainDependency,
) -> bool {
    hosted_provider_callback_records().is_some_and(|records| {
        records.iter().any(|record| {
            record.present
                && record.provider_domain == dependency.provider_domain
                && record.dependent_domain == dependency.dependent_domain
                && record.provider_publication_cookie == dependency.provider_publication_cookie
        })
    })
}

unsafe fn teardown_hosted_provider_domain_dependency(
    dependency: HostedProviderDomainDependency,
) -> Result<(), nt_status::NtStatus> {
    if !dependency.present
        || !dependency.retiring
        || dependency.in_flight != 0
        || !hosted_provider_domain_dependency_is_current(dependency)
    {
        return Err(nt_status::NtStatus::INVALID_PARAMETER);
    }
    if hosted_provider_callback_records_reference_dependency(dependency) {
        return Err(nt_status::NtStatus::DEVICE_BUSY);
    }
    clear_hosted_provider_domain_link(dependency.dependent_domain, dependency.provider_domain)?;
    Ok(())
}

unsafe fn clear_hosted_provider_domain_dependencies_for_instance(instance_index: usize) -> u64 {
    let Some(dependencies) =
        (*core::ptr::addr_of_mut!(HOSTED_PROVIDER_DOMAIN_DEPENDENCIES)).as_mut()
    else {
        return 0;
    };
    let mut failures = 0u64;
    for index in 0..dependencies.len() {
        let dependency = dependencies[index];
        if !dependency.present {
            continue;
        }
        if dependency.dependent_instance == instance_index {
            if teardown_hosted_provider_domain_dependency(dependency).is_ok() {
                dependencies[index] = HostedProviderDomainDependency::empty();
            } else {
                failures += 1;
            }
        } else if dependency.provider_instance == instance_index {
            failures += 1;
        }
    }
    failures
}

unsafe fn release_hosted_provider_dispatch_route_allocations(
    route: &mut HostedProviderDispatchRoute,
) -> bool {
    if !route.used
        || !hosted_provider_object_owner_is_current(
            route.owner,
            route.provider_instance,
            route.dependent_instance,
        )
    {
        return false;
    }
    let owner = route.owner;
    let provider_instance = route.provider_instance;
    let dependent_instance = route.dependent_instance;
    let provider_driver_extension = route.provider_driver_extension;
    let provider_driver_object = route.provider_driver_object;
    route.release_progress.release_with(|bit| match bit {
        0 => release_hosted_provider_owned_pool_allocation(
            owner,
            provider_instance,
            dependent_instance,
            provider_instance,
            provider_driver_extension,
        ),
        1 => release_hosted_provider_owned_pool_allocation(
            owner,
            provider_instance,
            dependent_instance,
            provider_instance,
            provider_driver_object,
        ),
        _ => false,
    })
}

unsafe fn abort_hosted_provider_dispatch_route_construction(
    route: &mut HostedProviderDispatchRoute,
) -> bool {
    if !route.used
        || !matches!(
            route.construction_state,
            HostedProviderConstructionState::Constructing
                | HostedProviderConstructionState::RollingBack
        )
    {
        return false;
    }
    if route.provider_driver_object != 0 {
        let driver_binding = io_manager_mut()
            .hosted_driver_by_identity(route.provider_domain, route.provider_driver_object);
        match driver_binding {
            Some(driver) if driver == DriverId(route.dependent_driver_id) => {
                if !io_manager_mut().unbind_hosted_driver_identity(
                    route.provider_domain,
                    route.provider_driver_object,
                    driver,
                ) {
                    return false;
                }
            }
            None => {}
            Some(_) => return false,
        }
        clear_driver_object_extensions_for_driver_object(route.provider_driver_object);
    }
    release_hosted_provider_dispatch_route_allocations(route)
}

unsafe fn retain_or_clear_failed_hosted_provider_dispatch_route(
    route_index: usize,
    status: i32,
) -> i32 {
    let routes = hosted_provider_dispatch_routes_mut();
    if let Some(route) = routes.get_mut(route_index) {
        route.construction_state = HostedProviderConstructionState::RollingBack;
    }
    if routes
        .get_mut(route_index)
        .is_some_and(|route| abort_hosted_provider_dispatch_route_construction(route))
    {
        routes[route_index] = HostedProviderDispatchRoute::empty();
    }
    status
}

unsafe fn teardown_hosted_provider_dispatch_route(
    route: &mut HostedProviderDispatchRoute,
) -> Result<(), nt_status::NtStatus> {
    if !route.used
        || route.construction_state != HostedProviderConstructionState::Published
        || !route.retiring
        || !route.owner.pair_matches(
            route.provider_domain.domain_id.raw(),
            route.provider_domain.cookie,
            route.dependent_domain.domain_id.raw(),
            route.dependent_domain.cookie,
        )
        || !hosted_provider_object_owner_is_current(
            route.owner,
            route.provider_instance,
            route.dependent_instance,
        )
        || !hosted_provider_domain_dependency_for_pair_current(
            route.provider_instance,
            route.dependent_instance,
        )
        .is_some_and(|dependency| {
            dependency.retiring
                && dependency.in_flight == 0
                && dependency.provider_domain == route.provider_domain
                && dependency.dependent_domain == route.dependent_domain
                && dependency.provider_publication_cookie == route.provider_publication_cookie
        })
    {
        return Err(nt_status::NtStatus::INVALID_PARAMETER);
    }
    if hosted_provider_callback_records_reference_route(*route) {
        return Err(nt_status::NtStatus::DEVICE_BUSY);
    }
    let driver_binding = io_manager_mut()
        .hosted_driver_by_identity(route.provider_domain, route.provider_driver_object);
    match driver_binding {
        Some(driver) if driver == DriverId(route.dependent_driver_id) => {}
        None => {}
        Some(_) => return Err(nt_status::NtStatus::INVALID_PARAMETER),
    }
    if let Some(driver) = driver_binding {
        if !io_manager_mut().unbind_hosted_driver_identity(
            route.provider_domain,
            route.provider_driver_object,
            driver,
        ) {
            return Err(nt_status::NtStatus::INVALID_PARAMETER);
        }
    }
    if !release_hosted_provider_dispatch_route_allocations(route) {
        return Err(nt_status::NtStatus::INSUFFICIENT_RESOURCES);
    }
    clear_driver_object_extensions_for_driver_object(route.provider_driver_object);
    Ok(())
}

unsafe fn clear_hosted_provider_dispatch_routes_for_instance(
    instance_index: usize,
    domain: HostedDomainIdentity,
) -> u64 {
    let Some(routes) = (*core::ptr::addr_of_mut!(HOSTED_PROVIDER_DISPATCH_ROUTES)).as_mut() else {
        return 0;
    };
    let mut failures = 0u64;
    for index in 0..routes.len() {
        let route = routes[index];
        if route.used
            && (route.dependent_instance == instance_index
                || route.provider_instance == instance_index)
        {
            if route.construction_state != HostedProviderConstructionState::Published {
                if !hosted_provider_object_owner_matches_instance(
                    route.owner,
                    route.provider_instance,
                    route.dependent_instance,
                    instance_index,
                    domain,
                ) || !abort_hosted_provider_dispatch_route_construction(&mut routes[index])
                {
                    failures += 1;
                } else {
                    routes[index] = HostedProviderDispatchRoute::empty();
                }
                continue;
            }
            routes[index].retiring = true;
            if !hosted_provider_object_owner_matches_instance(
                routes[index].owner,
                routes[index].provider_instance,
                routes[index].dependent_instance,
                instance_index,
                domain,
            ) {
                failures += 1;
                continue;
            }
            if teardown_hosted_provider_dispatch_route(&mut routes[index]).is_ok() {
                routes[index] = HostedProviderDispatchRoute::empty();
            } else {
                failures += 1;
            }
        }
    }
    failures
}

unsafe fn initialize_provider_driver_object_shadow_for_instance(
    provider_instance: usize,
    provider_inst: DriverInstance,
    driver_object: u64,
    driver_extension: u64,
) -> Result<(), i32> {
    let Some(driver_exec) = component_to_exec_va_for_instance(
        provider_instance,
        provider_inst,
        driver_object,
        WDM_X64_DRIVER_OBJECT_SIZE as u64,
    ) else {
        return Err(STATUS_INVALID_PARAMETER);
    };
    let Some(extension_exec) = component_to_exec_va_for_instance(
        provider_instance,
        provider_inst,
        driver_extension,
        WDM_X64_DRIVER_EXTENSION_SIZE as u64,
    ) else {
        return Err(STATUS_INVALID_PARAMETER);
    };
    let mut offset = 0u64;
    while offset < WDM_X64_DRIVER_EXTENSION_SIZE as u64 {
        write_unaligned((extension_exec + offset) as *mut u64, 0);
        offset += 8;
    }
    let driver_bytes =
        core::slice::from_raw_parts_mut(driver_exec as *mut u8, WDM_X64_DRIVER_OBJECT_SIZE);
    write_wdm_driver_object(
        driver_bytes,
        WdmDriverObjectInit {
            size_field: WDM_X64_DRIVER_OBJECT_SIZE as u16,
            device_object: 0,
            driver_extension,
            driver_unload: 0,
        },
    )
    .map_err(|_| STATUS_INVALID_PARAMETER)?;
    offset = WDM_X64_DRIVER_MAJOR_FUNCTION_OFFSET as u64;
    while offset + 8 <= WDM_X64_DRIVER_OBJECT_SIZE as u64 {
        write_unaligned(
            (driver_exec + offset) as *mut u64,
            fsd_invalid_device_request as *const () as usize as u64,
        );
        offset += 8;
    }
    Ok(())
}

unsafe fn register_hosted_provider_driver_object_shadow(
    provider_instance: usize,
    provider_publication_cookie: u64,
    dependent_instance: usize,
    dependent_inst: DriverInstance,
    dependent_driver_object: u64,
) -> Result<usize, i32> {
    if dependent_driver_object == 0 || provider_publication_cookie == 0 {
        return Err(STATUS_INVALID_PARAMETER);
    }
    if component_to_exec_va_for_instance(
        dependent_instance,
        dependent_inst,
        dependent_driver_object,
        WDM_X64_DRIVER_OBJECT_SIZE as u64,
    )
    .is_none()
    {
        return Err(STATUS_INVALID_PARAMETER);
    }
    let Some(provider_inst) = instance(provider_instance) else {
        return Err(STATUS_DEVICE_NOT_READY);
    };
    let Some(dependent_domain) = instance_domain_identity(dependent_inst) else {
        return Err(STATUS_INVALID_PARAMETER);
    };
    let Some(provider_domain) = instance_domain_identity(provider_inst) else {
        return Err(STATUS_INVALID_PARAMETER);
    };
    let Some((_, singleton)) =
        find_hosted_provider_singleton_by_cookie(provider_publication_cookie)
    else {
        return Err(STATUS_INVALID_PARAMETER);
    };
    if singleton.instance != provider_instance || singleton.owner_domain != provider_domain {
        return Err(STATUS_INVALID_PARAMETER);
    }
    let Some(owner) = hosted_provider_object_owner_for_pair(provider_instance, dependent_instance)
    else {
        return Err(STATUS_DEVICE_NOT_READY);
    };
    if let Some((index, route)) = hosted_provider_dispatch_routes().and_then(|routes| {
        routes
            .iter()
            .copied()
            .enumerate()
            .find(|(_, route)| route.used && route.dependent_domain == dependent_domain)
    }) {
        let exact = route.owner == owner
            && route.provider_instance == provider_instance
            && route.dependent_instance == dependent_instance
            && route.provider_domain == provider_domain
            && route.provider_publication_cookie == provider_publication_cookie
            && route.dependent_driver_object == dependent_driver_object
            && route.dependent_driver_id == dependent_inst.driver_id;
        if route.construction_state != HostedProviderConstructionState::Published {
            if !exact {
                return Err(nt_status::NtStatus::OBJECT_NAME_COLLISION.raw());
            }
            if route.construction_state != HostedProviderConstructionState::RollingBack {
                return Err(nt_status::NtStatus::DEVICE_BUSY.raw());
            }
            let routes = hosted_provider_dispatch_routes_mut();
            if !abort_hosted_provider_dispatch_route_construction(&mut routes[index]) {
                return Err(nt_status::NtStatus::DEVICE_BUSY.raw());
            }
            routes[index] = HostedProviderDispatchRoute::empty();
        } else if exact
            && hosted_provider_dispatch_route_is_live(route)
            && route.provider_driver_object != 0
        {
            return io_manager_mut()
                .bind_hosted_driver_identity(
                    provider_domain,
                    route.provider_driver_object,
                    DriverId(dependent_inst.driver_id),
                )
                .map(|()| index)
                .map_err(nt_status::NtStatus::raw);
        } else {
            return Err(nt_status::NtStatus::OBJECT_NAME_COLLISION.raw());
        }
    }
    let route = HostedProviderDispatchRoute {
        used: true,
        construction_state: HostedProviderConstructionState::Constructing,
        retiring: false,
        owner,
        release_progress: HostedProviderReleaseProgress::new(0),
        dependent_instance,
        provider_instance,
        dependent_domain,
        provider_domain,
        provider_publication_cookie,
        dependent_driver_id: dependent_inst.driver_id,
        dependent_driver_object,
        provider_driver_object: 0,
        provider_driver_extension: 0,
        provider_wrapper_handle: 0,
        provider_add_device: 0,
    };
    let route_index = {
        let routes = hosted_provider_dispatch_routes_mut();
        if let Some(index) = routes.iter().position(|route| !route.used) {
            routes[index] = route;
            index
        } else {
            routes
                .try_reserve(1)
                .map_err(|_| STATUS_INSUFFICIENT_RESOURCES)?;
            routes.push(route);
            routes.len() - 1
        }
    };
    let Some(provider_driver_object) =
        hosted_instance_pool_alloc(provider_inst, WDM_X64_DRIVER_OBJECT_SIZE as u64)
    else {
        return Err(retain_or_clear_failed_hosted_provider_dispatch_route(
            route_index,
            STATUS_INSUFFICIENT_RESOURCES,
        ));
    };
    {
        let route = &mut hosted_provider_dispatch_routes_mut()[route_index];
        route.provider_driver_object = provider_driver_object;
        route.release_progress.add_pending(1 << 1);
    }
    let Some(provider_driver_extension) =
        hosted_instance_pool_alloc(provider_inst, WDM_X64_DRIVER_EXTENSION_SIZE as u64)
    else {
        return Err(retain_or_clear_failed_hosted_provider_dispatch_route(
            route_index,
            STATUS_INSUFFICIENT_RESOURCES,
        ));
    };
    {
        let route = &mut hosted_provider_dispatch_routes_mut()[route_index];
        route.provider_driver_extension = provider_driver_extension;
        route.release_progress.add_pending(1 << 0);
    }
    if let Err(status) = initialize_provider_driver_object_shadow_for_instance(
        provider_instance,
        provider_inst,
        provider_driver_object,
        provider_driver_extension,
    ) {
        return Err(retain_or_clear_failed_hosted_provider_dispatch_route(
            route_index,
            status,
        ));
    }
    if let Err(status) = io_manager_mut().bind_hosted_driver_identity(
        provider_domain,
        provider_driver_object,
        DriverId(dependent_inst.driver_id),
    ) {
        return Err(retain_or_clear_failed_hosted_provider_dispatch_route(
            route_index,
            status.raw(),
        ));
    }
    let published = {
        let route = &mut hosted_provider_dispatch_routes_mut()[route_index];
        if route.construction_state == HostedProviderConstructionState::Constructing
            && route.owner == owner
            && route.provider_driver_object == provider_driver_object
            && route.provider_driver_extension == provider_driver_extension
        {
            route.construction_state = HostedProviderConstructionState::Published;
            true
        } else {
            false
        }
    };
    if published {
        Ok(route_index)
    } else {
        Err(retain_or_clear_failed_hosted_provider_dispatch_route(
            route_index,
            STATUS_DEVICE_NOT_READY,
        ))
    }
}

unsafe fn set_hosted_provider_route_wrapper(
    route_index: usize,
    provider_wrapper_handle: u64,
) -> Result<(), i32> {
    if provider_wrapper_handle == 0 {
        return Err(STATUS_DEVICE_NOT_READY);
    }
    let routes = hosted_provider_dispatch_routes_mut();
    let Some(route) = routes.get_mut(route_index) else {
        return Err(STATUS_DEVICE_NOT_READY);
    };
    if !hosted_provider_dispatch_route_is_live(*route) {
        return Err(STATUS_DEVICE_NOT_READY);
    }
    route.provider_wrapper_handle = provider_wrapper_handle;
    Ok(())
}

unsafe fn complete_hosted_provider_miniport_registration(
    provider_instance: usize,
    provider_wrapper_handle: u64,
) -> Result<(), i32> {
    let Some((route_index, route)) =
        hosted_provider_dispatch_route_for_wrapper(provider_instance, provider_wrapper_handle)
    else {
        return Err(STATUS_DEVICE_NOT_READY);
    };
    let Some(provider_inst) = instance(provider_instance) else {
        return Err(STATUS_DEVICE_NOT_READY);
    };
    let Some(extension_exec) = component_to_exec_va_for_instance(
        provider_instance,
        provider_inst,
        route.provider_driver_extension,
        WDM_X64_DRIVER_EXTENSION_SIZE as u64,
    ) else {
        return Err(STATUS_INVALID_PARAMETER);
    };
    let add_device =
        read_unaligned((extension_exec + WDM_X64_DRIVER_EXTENSION_ADD_DEVICE_OFFSET) as *const u64);
    let Some(driver_exec) = component_to_exec_va_for_instance(
        provider_instance,
        provider_inst,
        route.provider_driver_object,
        WDM_X64_DRIVER_OBJECT_SIZE as u64,
    ) else {
        return Err(STATUS_INVALID_PARAMETER);
    };
    let pnp_dispatch = read_unaligned(
        (driver_exec + WDM_X64_DRIVER_MAJOR_FUNCTION_OFFSET as u64 + IRP_MJ_PNP * 8) as *const u64,
    );
    if add_device == 0 || pnp_dispatch == 0 {
        return Err(STATUS_INVALID_DEVICE_REQUEST);
    }
    let routes = hosted_provider_dispatch_routes_mut();
    let Some(slot) = routes.get_mut(route_index) else {
        return Err(STATUS_DEVICE_NOT_READY);
    };
    if !hosted_provider_dispatch_route_is_live(*slot) {
        return Err(STATUS_DEVICE_NOT_READY);
    }
    slot.provider_add_device = add_device;
    print_str(b"[driver-launch] provider miniport route published dependent-inst=");
    print_u64(slot.dependent_instance as u64);
    print_str(b" provider-inst=");
    print_u64(provider_instance as u64);
    print_str(b" drv=0x");
    print_hex64(slot.provider_driver_object);
    print_str(b" add=0x");
    print_hex64(add_device);
    print_str(b"\n");
    Ok(())
}

unsafe fn register_hosted_provider_pointer_allocation(
    owner: HostedProviderObjectOwner,
    dependent_instance: usize,
    dependent_component_va: u64,
    provider_instance: usize,
    bytes: u64,
) {
    assert!(dependent_component_va != 0 && bytes != 0);
    assert!(hosted_provider_object_owner_is_live(
        owner,
        provider_instance,
        dependent_instance,
    ));
    let records = hosted_provider_pointer_allocations_mut();
    for record in records.iter_mut() {
        if !record.present {
            *record = HostedProviderPointerAllocation {
                present: true,
                owner,
                release_progress: HostedProviderReleaseProgress::new(1),
                dependent_instance,
                dependent_component_va,
                provider_instance,
                provider_component_va: 0,
                bytes,
            };
            return;
        }
    }
    records.push(HostedProviderPointerAllocation {
        present: true,
        owner,
        release_progress: HostedProviderReleaseProgress::new(1),
        dependent_instance,
        dependent_component_va,
        provider_instance,
        provider_component_va: 0,
        bytes,
    });
}

unsafe fn hosted_provider_pointer_allocation(
    dependent_instance: usize,
    dependent_component_va: u64,
    bytes: u64,
) -> Option<HostedProviderPointerAllocation> {
    let Some(records) = hosted_provider_pointer_allocations() else {
        return None;
    };
    for record in records.iter().copied() {
        if record.present
            && record.dependent_instance == dependent_instance
            && record.dependent_component_va == dependent_component_va
            && hosted_provider_object_owner_is_live(
                record.owner,
                record.provider_instance,
                record.dependent_instance,
            )
            && (bytes == 0 || bytes <= record.bytes)
        {
            return Some(record);
        }
    }
    None
}

unsafe fn associate_hosted_provider_pointer_allocation(
    dependent_instance: usize,
    dependent_component_va: u64,
    provider_instance: usize,
    provider_component_va: u64,
) -> bool {
    if provider_component_va == 0 {
        return false;
    }
    let records = hosted_provider_pointer_allocations_mut();
    for record in records.iter_mut() {
        if record.present
            && record.dependent_instance == dependent_instance
            && record.dependent_component_va == dependent_component_va
            && record.provider_instance == provider_instance
            && hosted_provider_object_owner_is_live(
                record.owner,
                record.provider_instance,
                record.dependent_instance,
            )
            && record.provider_component_va == 0
        {
            record.provider_component_va = provider_component_va;
            record.release_progress.add_pending(1 << 1);
            return true;
        }
    }
    false
}

unsafe fn release_hosted_provider_pointer_allocation_record(
    record: &mut HostedProviderPointerAllocation,
    provider_component_override: u64,
) -> bool {
    if !record.present
        || !hosted_provider_object_owner_is_current(
            record.owner,
            record.provider_instance,
            record.dependent_instance,
        )
    {
        return false;
    }
    if provider_component_override != 0 {
        if record.provider_component_va != 0
            && record.provider_component_va != provider_component_override
        {
            return false;
        }
        if record.provider_component_va == 0 {
            record.provider_component_va = provider_component_override;
            record.release_progress.add_pending(1 << 1);
        }
    }
    let dependent_instance = record.dependent_instance;
    let dependent_component_va = record.dependent_component_va;
    let provider_instance = record.provider_instance;
    let provider_component_va = record.provider_component_va;
    record.release_progress.release_with(|bit| match bit {
        0 => instance(dependent_instance).is_some_and(|inst| {
            release_hosted_instance_pool_allocation_if_live(inst, dependent_component_va)
        }),
        1 => instance(provider_instance).is_some_and(|inst| {
            release_hosted_instance_pool_allocation_if_live(inst, provider_component_va)
        }),
        _ => false,
    })
}

unsafe fn release_hosted_provider_pointer_allocation_by_dependent(
    dependent_instance: usize,
    component_va: u64,
    provider_component_override: u64,
) -> bool {
    for record in hosted_provider_pointer_allocations_mut().iter_mut() {
        if record.present
            && record.dependent_instance == dependent_instance
            && record.dependent_component_va == component_va
            && hosted_provider_object_owner_is_live(
                record.owner,
                record.provider_instance,
                record.dependent_instance,
            )
        {
            if !release_hosted_provider_pointer_allocation_record(
                record,
                provider_component_override,
            ) {
                return false;
            }
            *record = HostedProviderPointerAllocation::empty();
            return true;
        }
    }
    HOSTED_PROVIDER_POINTER_ALLOCATION_REJECTIONS.fetch_add(1, Ordering::Relaxed);
    false
}

unsafe fn abort_provider_export_marshal_before_dispatch(state: &ProviderMarshalState) {
    if state.pointer_allocation_dependent_component_va != 0
        && !release_hosted_provider_pointer_allocation_by_dependent(
            state.pointer_allocation_dependent_instance,
            state.pointer_allocation_dependent_component_va,
            0,
        )
    {
        HOSTED_PROVIDER_POINTER_ALLOCATION_REJECTIONS.fetch_add(1, Ordering::Relaxed);
    }
    if state.miniport_interrupt_construction_index != usize::MAX {
        retain_or_clear_failed_hosted_provider_miniport_interrupt_construction(
            state.miniport_interrupt_construction_index,
            STATUS_DEVICE_NOT_READY,
        );
    }
    if state.miniport_timer_construction_index != usize::MAX {
        rollback_hosted_provider_miniport_timer_construction(
            state.miniport_timer_construction_index,
        );
    }
    if state.ndis_work_item_construction_index != usize::MAX {
        if let Some(token) = state.ndis_work_item_schedule_token {
            abort_hosted_provider_ndis_work_item_schedule(
                state.ndis_work_item_construction_index,
                token,
                state.ndis_work_item_parent_constructing,
            );
        }
    }
    if state.callback_parent_construction_index != usize::MAX {
        rollback_hosted_provider_callback_parent(state.callback_parent_construction_index);
    }
}

unsafe fn abort_provider_export_marshal_after_possible_dispatch(state: &ProviderMarshalState) {
    if state.pointer_allocation_dependent_component_va != 0 {
        let provider_component_va =
            read_unaligned(state.pointer_allocation_provider_output_exec_va as *const u64);
        if !release_hosted_provider_pointer_allocation_by_dependent(
            state.pointer_allocation_dependent_instance,
            state.pointer_allocation_dependent_component_va,
            provider_component_va,
        ) {
            HOSTED_PROVIDER_POINTER_ALLOCATION_REJECTIONS.fetch_add(1, Ordering::Relaxed);
        }
    }
    if state.pointer_free_dependent_component_va != 0 {
        let record_matches = hosted_provider_pointer_allocation(
            state.pointer_free_dependent_instance,
            state.pointer_free_dependent_component_va,
            0,
        )
        .is_some_and(|record| {
            record.provider_instance == state.pointer_free_provider_instance
                && record.provider_component_va == state.pointer_free_provider_component_va
        });
        if !record_matches
            || !release_hosted_provider_pointer_allocation_by_dependent(
                state.pointer_free_dependent_instance,
                state.pointer_free_dependent_component_va,
                0,
            )
        {
            HOSTED_PROVIDER_POINTER_ALLOCATION_REJECTIONS.fetch_add(1, Ordering::Relaxed);
        }
    }
    if state.miniport_interrupt_construction_index != usize::MAX {
        retain_indeterminate_hosted_provider_miniport_interrupt_construction(
            state.miniport_interrupt_construction_index,
        );
    }
    if state.miniport_timer_construction_index != usize::MAX {
        retain_indeterminate_hosted_provider_miniport_timer_construction(
            state.miniport_timer_construction_index,
        );
    }
    if state.ndis_work_item_construction_index != usize::MAX {
        if let Some(token) = state.ndis_work_item_schedule_token {
            retain_indeterminate_hosted_provider_ndis_work_item_schedule(
                state.ndis_work_item_construction_index,
                token,
            );
        }
    }
    if state.callback_parent_construction_index != usize::MAX {
        retain_indeterminate_hosted_provider_callback_parent(
            state.callback_parent_construction_index,
        );
    }
}

struct ProviderMarshalPreparationGuard {
    state: *const ProviderMarshalState,
    armed: bool,
}

impl ProviderMarshalPreparationGuard {
    fn new(state: &ProviderMarshalState) -> Self {
        Self {
            state: state as *const ProviderMarshalState,
            armed: true,
        }
    }

    fn disarm(&mut self) {
        self.armed = false;
    }
}

impl Drop for ProviderMarshalPreparationGuard {
    fn drop(&mut self) {
        if self.armed {
            unsafe {
                abort_provider_export_marshal_before_dispatch(&*self.state);
            }
        }
    }
}

unsafe fn clear_hosted_provider_pointer_allocations_for_instance(
    instance_index: usize,
    domain: HostedDomainIdentity,
) -> u64 {
    let records = hosted_provider_pointer_allocations_mut();
    let mut failures = 0u64;
    for record in records.iter_mut() {
        if !record.present {
            continue;
        }
        if record.dependent_instance != instance_index && record.provider_instance != instance_index
        {
            continue;
        }
        if !hosted_provider_object_owner_matches_instance(
            record.owner,
            record.provider_instance,
            record.dependent_instance,
            instance_index,
            domain,
        ) {
            failures += 1;
            continue;
        }
        if release_hosted_provider_pointer_allocation_record(record, 0) {
            *record = HostedProviderPointerAllocation::empty();
        } else {
            failures += 1;
        }
    }
    failures
}

fn provider_shared_component_to_exec(
    provider_shared: u64,
    component_va: u64,
    bytes: u64,
) -> Option<u64> {
    translate_component_range(
        component_va,
        bytes,
        FSD_SHARED_VADDR,
        FSD_SHARED_FRAMES * 0x1000,
        provider_shared,
    )
}

unsafe fn ndis_packet_shadow_len(packet_exec: u64) -> Option<u64> {
    let oob_offset =
        read_unaligned((packet_exec + NDIS_PACKET_PRIVATE_OOB_OFFSET_X64) as *const u16) as u64;
    if !(NDIS_PACKET_MIN_LEN_X64..=NDIS_PACKET_MAX_SHADOW_LEN_X64).contains(&oob_offset) {
        return None;
    }
    let bytes = oob_offset
        .checked_add(NDIS_PACKET_OOB_DATA_LEN_X64)?
        .checked_add(NDIS_PACKET_EXTENSION_LEN_X64)?;
    if !(NDIS_PACKET_MIN_LEN_X64..=NDIS_PACKET_MAX_SHADOW_LEN_X64).contains(&bytes) {
        return None;
    }
    Some(bytes)
}

unsafe fn ndis_packet_sg_info_cell_exec(packet_exec: u64, packet_bytes: u64) -> Option<u64> {
    let oob_offset =
        read_unaligned((packet_exec + NDIS_PACKET_PRIVATE_OOB_OFFSET_X64) as *const u16) as u64;
    let offset = oob_offset
        .checked_add(NDIS_PACKET_OOB_DATA_LEN_X64)?
        .checked_add(NDIS_PACKET_SCATTER_GATHER_INFO_INDEX_X64 * 8)?;
    if offset.checked_add(8)? > packet_bytes {
        return None;
    }
    packet_exec.checked_add(offset)
}

unsafe fn find_hosted_provider_ndis_packet_shadow_by_dependent(
    provider_instance: usize,
    dependent_instance: usize,
    dependent_component_va: u64,
) -> Option<(usize, HostedProviderNdisPacketShadow)> {
    if dependent_component_va == 0 {
        return None;
    }
    let Some(records) = hosted_provider_ndis_packet_shadows() else {
        return None;
    };
    for (index, record) in records.iter().copied().enumerate() {
        if record.present
            && record.construction_state == HostedProviderConstructionState::Published
            && record.provider_instance == provider_instance
            && record.dependent_instance == dependent_instance
            && hosted_provider_object_owner_is_live(
                record.owner,
                record.provider_instance,
                record.dependent_instance,
            )
            && record.dependent_component_va == dependent_component_va
        {
            return Some((index, record));
        }
    }
    None
}

