unsafe fn provider_marshal_output_network_address(
    state: &mut ProviderMarshalState,
    dependent_instance: usize,
    dependent_inst: DriverInstance,
    provider_shared: u64,
    arg_value: u64,
    length_arg_value: u64,
) -> Result<(u64, u64), i32> {
    let Some(dependent_ptr_exec_va) =
        component_to_exec_va_for_instance(dependent_instance, dependent_inst, arg_value, 8)
    else {
        return Err(STATUS_INVALID_PARAMETER);
    };
    let Some(dependent_len_exec_va) =
        component_to_exec_va_for_instance(dependent_instance, dependent_inst, length_arg_value, 4)
    else {
        return Err(STATUS_INVALID_PARAMETER);
    };
    let Some((provider_ptr_component_va, provider_ptr_exec_va)) =
        provider_marshal_alloc(state, provider_shared, 8)
    else {
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    };
    let Some((provider_len_component_va, provider_len_exec_va)) =
        provider_marshal_alloc(state, provider_shared, 4)
    else {
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    };
    state.ndis_network_address_dependent_ptr_exec_va = dependent_ptr_exec_va;
    state.ndis_network_address_provider_ptr_exec_va = provider_ptr_exec_va;
    state.ndis_network_address_dependent_len_exec_va = dependent_len_exec_va;
    state.ndis_network_address_provider_len_exec_va = provider_len_exec_va;
    write_unaligned(provider_ptr_exec_va as *mut u64, 0);
    write_unaligned(provider_len_exec_va as *mut u32, 0);
    Ok((provider_ptr_component_va, provider_len_component_va))
}

unsafe fn write_provider_ndis_status(state: &ProviderMarshalState, status: i32) {
    if state.ndis_status_provider_exec_va != 0 {
        write_unaligned(
            state.ndis_status_provider_exec_va as *mut u32,
            status as u32,
        );
    }
}

unsafe fn provider_ndis_status_success(state: &ProviderMarshalState) -> bool {
    state.ndis_status_provider_exec_va == 0
        || read_unaligned(state.ndis_status_provider_exec_va as *const u32) == STATUS_SUCCESS as u32
}

unsafe fn complete_provider_unicode_string_init(state: &ProviderMarshalState) {
    if state.ndis_unicode_init_dependent_desc_exec_va == 0
        || state.ndis_unicode_init_provider_desc_exec_va == 0
        || state.ndis_unicode_init_dependent_source_component_va == 0
    {
        return;
    }
    copy_bytes(
        state.ndis_unicode_init_dependent_desc_exec_va,
        state.ndis_unicode_init_provider_desc_exec_va,
        16,
    );
    write_unaligned(
        (state.ndis_unicode_init_dependent_desc_exec_va + 8) as *mut u64,
        state.ndis_unicode_init_dependent_source_component_va,
    );
}

unsafe fn complete_provider_ndis_device_properties(
    state: &ProviderMarshalState,
    binding: Option<HostedDeviceBinding>,
) {
    if state.ndis_device_property_output_count == 0 {
        return;
    }
    let mut index = 0usize;
    while index < state.ndis_device_property_output_count {
        let output = state.ndis_device_property_outputs[index];
        let provider_value = read_unaligned(output.provider_exec_va as *const u64);
        let value = match output.kind {
            NDIS_DEVICE_PROPERTY_PDO => binding.map(|slot| slot.pdo_object).unwrap_or(0),
            NDIS_DEVICE_PROPERTY_FDO => binding
                .map(|slot| slot.device_object)
                .filter(|value| *value != 0)
                .unwrap_or(0),
            NDIS_DEVICE_PROPERTY_NEXT => binding.map(|slot| slot.pdo_object).unwrap_or(0),
            NDIS_DEVICE_PROPERTY_ALLOCATED_RESOURCES
            | NDIS_DEVICE_PROPERTY_TRANSLATED_RESOURCES => 0,
            _ => 0,
        };
        write_unaligned(output.dependent_exec_va as *mut u64, value);
        let trace = PROVIDER_DEVICE_PROPERTY_TRACE_COUNT.fetch_add(1, Ordering::Relaxed);
        if trace < PROVIDER_DEVICE_PROPERTY_TRACE_CAP {
            print_str(b"[driver-import] provider device-property kind=");
            print_u64(output.kind as u64);
            print_str(b" provider=0x");
            print_hex64(provider_value);
            print_str(b" dependent=0x");
            print_hex64(value);
            print_str(b" binding=");
            print_u64(binding.is_some() as u64);
            print_str(b" device-id=");
            print_u64(binding.map(|binding| binding.device_id).unwrap_or(0));
            print_str(b"\n");
        }
        index += 1;
    }
}

unsafe fn complete_provider_ndis_configuration_parameter(
    state: &ProviderMarshalState,
    provider_instance: usize,
    provider_inst: DriverInstance,
    dependent_instance: usize,
    dependent_inst: DriverInstance,
) {
    if state.ndis_config_param_provider_exec_va == 0
        || state.ndis_config_param_dependent_exec_va == 0
    {
        return;
    }
    if !provider_ndis_status_success(state) {
        write_unaligned(state.ndis_config_param_dependent_exec_va as *mut u64, 0);
        return;
    }
    let provider_param = read_unaligned(state.ndis_config_param_provider_exec_va as *const u64);
    if provider_param == 0 {
        write_provider_ndis_status(state, STATUS_INVALID_PARAMETER);
        write_unaligned(state.ndis_config_param_dependent_exec_va as *mut u64, 0);
        return;
    }
    let Some(provider_param_exec) = component_to_exec_va_for_instance(
        provider_instance,
        provider_inst,
        provider_param,
        NDIS_CONFIGURATION_PARAMETER_LEN_X64,
    ) else {
        write_provider_ndis_status(state, STATUS_INVALID_PARAMETER);
        write_unaligned(state.ndis_config_param_dependent_exec_va as *mut u64, 0);
        return;
    };
    let parameter_type = read_unaligned(provider_param_exec as *const u32);
    if parameter_type != NDIS_CONFIGURATION_PARAMETER_INTEGER
        && parameter_type != NDIS_CONFIGURATION_PARAMETER_HEX_INTEGER
    {
        write_provider_ndis_status(state, STATUS_NOT_SUPPORTED);
        write_unaligned(state.ndis_config_param_dependent_exec_va as *mut u64, 0);
        return;
    }
    let Some(dependent_param) =
        hosted_instance_pool_alloc(dependent_inst, NDIS_CONFIGURATION_PARAMETER_LEN_X64)
    else {
        write_provider_ndis_status(state, STATUS_INSUFFICIENT_RESOURCES);
        write_unaligned(state.ndis_config_param_dependent_exec_va as *mut u64, 0);
        return;
    };
    let Some(dependent_param_exec) = component_to_exec_va_for_instance(
        dependent_instance,
        dependent_inst,
        dependent_param,
        NDIS_CONFIGURATION_PARAMETER_LEN_X64,
    ) else {
        hosted_instance_pool_free(dependent_inst, dependent_param);
        write_provider_ndis_status(state, STATUS_INVALID_PARAMETER);
        write_unaligned(state.ndis_config_param_dependent_exec_va as *mut u64, 0);
        return;
    };
    copy_bytes(
        dependent_param_exec,
        provider_param_exec,
        NDIS_CONFIGURATION_PARAMETER_LEN_X64,
    );
    write_unaligned(
        state.ndis_config_param_dependent_exec_va as *mut u64,
        dependent_param,
    );
}

unsafe fn complete_provider_network_address(
    state: &ProviderMarshalState,
    provider_instance: usize,
    provider_inst: DriverInstance,
    dependent_instance: usize,
    dependent_inst: DriverInstance,
) {
    if state.ndis_network_address_provider_ptr_exec_va == 0
        || state.ndis_network_address_provider_len_exec_va == 0
        || state.ndis_network_address_dependent_ptr_exec_va == 0
        || state.ndis_network_address_dependent_len_exec_va == 0
    {
        return;
    }
    if !provider_ndis_status_success(state) {
        write_unaligned(
            state.ndis_network_address_dependent_ptr_exec_va as *mut u64,
            0,
        );
        write_unaligned(
            state.ndis_network_address_dependent_len_exec_va as *mut u32,
            0,
        );
        return;
    }
    let provider_buffer =
        read_unaligned(state.ndis_network_address_provider_ptr_exec_va as *const u64);
    let bytes =
        read_unaligned(state.ndis_network_address_provider_len_exec_va as *const u32) as u64;
    if provider_buffer == 0 || bytes == 0 || bytes > NDIS_NETWORK_ADDRESS_MAX_LEN {
        write_provider_ndis_status(state, STATUS_INVALID_PARAMETER);
        write_unaligned(
            state.ndis_network_address_dependent_ptr_exec_va as *mut u64,
            0,
        );
        write_unaligned(
            state.ndis_network_address_dependent_len_exec_va as *mut u32,
            0,
        );
        return;
    }
    let Some(provider_buffer_exec) =
        component_to_exec_va_for_instance(provider_instance, provider_inst, provider_buffer, bytes)
    else {
        write_provider_ndis_status(state, STATUS_INVALID_PARAMETER);
        write_unaligned(
            state.ndis_network_address_dependent_ptr_exec_va as *mut u64,
            0,
        );
        write_unaligned(
            state.ndis_network_address_dependent_len_exec_va as *mut u32,
            0,
        );
        return;
    };
    let Some(dependent_buffer) = hosted_instance_pool_alloc(dependent_inst, bytes) else {
        write_provider_ndis_status(state, STATUS_INSUFFICIENT_RESOURCES);
        write_unaligned(
            state.ndis_network_address_dependent_ptr_exec_va as *mut u64,
            0,
        );
        write_unaligned(
            state.ndis_network_address_dependent_len_exec_va as *mut u32,
            0,
        );
        return;
    };
    let Some(dependent_buffer_exec) = component_to_exec_va_for_instance(
        dependent_instance,
        dependent_inst,
        dependent_buffer,
        bytes,
    ) else {
        hosted_instance_pool_free(dependent_inst, dependent_buffer);
        write_provider_ndis_status(state, STATUS_INVALID_PARAMETER);
        write_unaligned(
            state.ndis_network_address_dependent_ptr_exec_va as *mut u64,
            0,
        );
        write_unaligned(
            state.ndis_network_address_dependent_len_exec_va as *mut u32,
            0,
        );
        return;
    };
    copy_bytes(dependent_buffer_exec, provider_buffer_exec, bytes);
    write_unaligned(
        state.ndis_network_address_dependent_ptr_exec_va as *mut u64,
        dependent_buffer,
    );
    write_unaligned(
        state.ndis_network_address_dependent_len_exec_va as *mut u32,
        bytes as u32,
    );
}

unsafe fn complete_provider_ndis_packet_allocation(
    state: &ProviderMarshalState,
    provider_instance: usize,
    provider_inst: DriverInstance,
    dependent_instance: usize,
    dependent_inst: DriverInstance,
) {
    if state.ndis_packet_out_provider_exec_va == 0 || state.ndis_packet_out_dependent_exec_va == 0 {
        return;
    }
    if !provider_ndis_status_success(state) {
        write_unaligned(state.ndis_packet_out_dependent_exec_va as *mut u64, 0);
        return;
    }
    let Some(owner) = hosted_provider_object_owner_for_pair(provider_instance, dependent_instance)
    else {
        write_provider_ndis_status(state, STATUS_DEVICE_NOT_READY);
        write_unaligned(state.ndis_packet_out_dependent_exec_va as *mut u64, 0);
        return;
    };
    let provider_packet = read_unaligned(state.ndis_packet_out_provider_exec_va as *const u64);
    if provider_packet == 0 {
        write_provider_ndis_status(state, STATUS_INSUFFICIENT_RESOURCES);
        write_unaligned(state.ndis_packet_out_dependent_exec_va as *mut u64, 0);
        return;
    }
    let Some(provider_packet_exec) = component_to_exec_va_for_instance(
        provider_instance,
        provider_inst,
        provider_packet,
        NDIS_PACKET_MIN_LEN_X64,
    ) else {
        write_provider_ndis_status(state, STATUS_INVALID_PARAMETER);
        write_unaligned(state.ndis_packet_out_dependent_exec_va as *mut u64, 0);
        return;
    };
    let Some(packet_bytes) = ndis_packet_shadow_len(provider_packet_exec) else {
        write_provider_ndis_status(state, STATUS_INVALID_PARAMETER);
        write_unaligned(state.ndis_packet_out_dependent_exec_va as *mut u64, 0);
        return;
    };
    let Some(provider_packet_exec) = component_to_exec_va_for_instance(
        provider_instance,
        provider_inst,
        provider_packet,
        packet_bytes,
    ) else {
        write_provider_ndis_status(state, STATUS_INVALID_PARAMETER);
        write_unaligned(state.ndis_packet_out_dependent_exec_va as *mut u64, 0);
        return;
    };
    let Some(dependent_packet) = hosted_instance_pool_alloc(dependent_inst, packet_bytes) else {
        write_provider_ndis_status(state, STATUS_INSUFFICIENT_RESOURCES);
        write_unaligned(state.ndis_packet_out_dependent_exec_va as *mut u64, 0);
        return;
    };
    let Some(dependent_packet_exec) = component_to_exec_va_for_instance(
        dependent_instance,
        dependent_inst,
        dependent_packet,
        packet_bytes,
    ) else {
        hosted_instance_pool_free(dependent_inst, dependent_packet);
        write_provider_ndis_status(state, STATUS_INVALID_PARAMETER);
        write_unaligned(state.ndis_packet_out_dependent_exec_va as *mut u64, 0);
        return;
    };
    copy_bytes(dependent_packet_exec, provider_packet_exec, packet_bytes);
    if !register_hosted_provider_ndis_packet_shadow(HostedProviderNdisPacketShadow {
        present: true,
        construction_state: HostedProviderConstructionState::Published,
        owner,
        provider_instance,
        dependent_instance,
        dependent_component_va: dependent_packet,
        provider_component_va: provider_packet,
        bytes: packet_bytes,
        provider_component_owned_by_bridge: false,
        dependent_component_owned_by_bridge: true,
        dependent_sg_component_va: 0,
        provider_sg_component_va: 0,
        dependent_sg_component_owned_by_bridge: false,
        construction_buffer_component_vas: [0; NDIS_PACKET_BUFFER_CHAIN_MAX as usize],
        construction_buffer_count: 0,
    }) {
        hosted_instance_pool_free(dependent_inst, dependent_packet);
        write_provider_ndis_status(state, STATUS_INSUFFICIENT_RESOURCES);
        write_unaligned(state.ndis_packet_out_dependent_exec_va as *mut u64, 0);
        return;
    }
    write_unaligned(
        state.ndis_packet_out_dependent_exec_va as *mut u64,
        dependent_packet,
    );
}

unsafe fn complete_provider_ndis_buffer_allocation(
    state: &ProviderMarshalState,
    provider_instance: usize,
    provider_inst: DriverInstance,
    dependent_instance: usize,
    dependent_inst: DriverInstance,
) {
    if state.ndis_buffer_out_provider_exec_va == 0 || state.ndis_buffer_out_dependent_exec_va == 0 {
        return;
    }
    if !provider_ndis_status_success(state) {
        if state.ndis_buffer_out_provider_data_owned_by_bridge {
            hosted_instance_pool_free(
                provider_inst,
                state.ndis_buffer_out_provider_data_component_va,
            );
        }
        write_unaligned(state.ndis_buffer_out_dependent_exec_va as *mut u64, 0);
        return;
    }
    let Some(owner) = hosted_provider_object_owner_for_pair(provider_instance, dependent_instance)
    else {
        if state.ndis_buffer_out_provider_data_owned_by_bridge {
            hosted_instance_pool_free(
                provider_inst,
                state.ndis_buffer_out_provider_data_component_va,
            );
        }
        write_provider_ndis_status(state, STATUS_DEVICE_NOT_READY);
        write_unaligned(state.ndis_buffer_out_dependent_exec_va as *mut u64, 0);
        return;
    };
    let provider_buffer = read_unaligned(state.ndis_buffer_out_provider_exec_va as *const u64);
    if provider_buffer == 0 || state.ndis_buffer_out_bytes == 0 {
        if state.ndis_buffer_out_provider_data_owned_by_bridge {
            hosted_instance_pool_free(
                provider_inst,
                state.ndis_buffer_out_provider_data_component_va,
            );
        }
        write_provider_ndis_status(state, STATUS_INSUFFICIENT_RESOURCES);
        write_unaligned(state.ndis_buffer_out_dependent_exec_va as *mut u64, 0);
        return;
    }
    let Some(provider_buffer_exec) = component_to_exec_va_for_instance(
        provider_instance,
        provider_inst,
        provider_buffer,
        nt_mdl::MDL_SIZE as u64,
    ) else {
        if state.ndis_buffer_out_provider_data_owned_by_bridge {
            hosted_instance_pool_free(
                provider_inst,
                state.ndis_buffer_out_provider_data_component_va,
            );
        }
        write_provider_ndis_status(state, STATUS_INVALID_PARAMETER);
        write_unaligned(state.ndis_buffer_out_dependent_exec_va as *mut u64, 0);
        return;
    };
    let Some(dependent_buffer) =
        hosted_instance_pool_alloc(dependent_inst, nt_mdl::MDL_SIZE as u64)
    else {
        if state.ndis_buffer_out_provider_data_owned_by_bridge {
            hosted_instance_pool_free(
                provider_inst,
                state.ndis_buffer_out_provider_data_component_va,
            );
        }
        write_provider_ndis_status(state, STATUS_INSUFFICIENT_RESOURCES);
        write_unaligned(state.ndis_buffer_out_dependent_exec_va as *mut u64, 0);
        return;
    };
    let Some(dependent_buffer_exec) = component_to_exec_va_for_instance(
        dependent_instance,
        dependent_inst,
        dependent_buffer,
        nt_mdl::MDL_SIZE as u64,
    ) else {
        hosted_instance_pool_free(dependent_inst, dependent_buffer);
        if state.ndis_buffer_out_provider_data_owned_by_bridge {
            hosted_instance_pool_free(
                provider_inst,
                state.ndis_buffer_out_provider_data_component_va,
            );
        }
        write_provider_ndis_status(state, STATUS_INVALID_PARAMETER);
        write_unaligned(state.ndis_buffer_out_dependent_exec_va as *mut u64, 0);
        return;
    };
    write_ndis_mdl(
        dependent_buffer_exec,
        state.ndis_buffer_out_dependent_data_component_va,
        state.ndis_buffer_out_bytes,
        0,
    );
    write_ndis_mdl(
        provider_buffer_exec,
        state.ndis_buffer_out_provider_data_component_va,
        state.ndis_buffer_out_bytes,
        0,
    );
    if !register_hosted_provider_ndis_buffer_shadow(HostedProviderNdisBufferShadow {
        present: true,
        construction_state: HostedProviderConstructionState::Published,
        owner,
        provider_instance,
        dependent_instance,
        dependent_component_va: dependent_buffer,
        provider_component_va: provider_buffer,
        dependent_data_component_va: state.ndis_buffer_out_dependent_data_component_va,
        provider_data_component_va: state.ndis_buffer_out_provider_data_component_va,
        bytes: state.ndis_buffer_out_bytes,
        provider_component_owned_by_bridge: true,
        provider_data_component_owned_by_bridge: state
            .ndis_buffer_out_provider_data_owned_by_bridge,
        dependent_component_owned_by_bridge: true,
        dependent_data_component_owned_by_bridge: false,
    }) {
        hosted_instance_pool_free(dependent_inst, dependent_buffer);
        if state.ndis_buffer_out_provider_data_owned_by_bridge {
            hosted_instance_pool_free(
                provider_inst,
                state.ndis_buffer_out_provider_data_component_va,
            );
        }
        write_provider_ndis_status(state, STATUS_INSUFFICIENT_RESOURCES);
        write_unaligned(state.ndis_buffer_out_dependent_exec_va as *mut u64, 0);
        return;
    }
    write_unaligned(
        state.ndis_buffer_out_dependent_exec_va as *mut u64,
        dependent_buffer,
    );
}

unsafe fn complete_provider_ndis_first_buffer_outputs(
    state: &ProviderMarshalState,
    provider_instance: usize,
    dependent_instance: usize,
) {
    if state.ndis_first_buffer_provider_exec_va == 0
        && state.ndis_first_buffer_va_provider_exec_va == 0
    {
        return;
    }
    let provider_buffer = if state.ndis_first_buffer_provider_exec_va == 0 {
        0
    } else {
        read_unaligned(state.ndis_first_buffer_provider_exec_va as *const u64)
    };
    let mapped = if provider_buffer == 0 {
        None
    } else {
        find_hosted_provider_ndis_buffer_shadow_by_provider_for_dependent(
            provider_instance,
            dependent_instance,
            provider_buffer,
        )
        .map(|(_, shadow)| shadow)
    };
    let dependent_buffer = mapped
        .map(|shadow| shadow.dependent_component_va)
        .unwrap_or(0);
    if state.ndis_first_buffer_dependent_exec_va != 0 {
        write_unaligned(
            state.ndis_first_buffer_dependent_exec_va as *mut u64,
            dependent_buffer,
        );
    }
    if state.ndis_first_buffer_va_dependent_exec_va != 0 {
        let provider_va = if state.ndis_first_buffer_va_provider_exec_va == 0 {
            0
        } else {
            read_unaligned(state.ndis_first_buffer_va_provider_exec_va as *const u64)
        };
        let dependent_va = match mapped {
            Some(shadow) if provider_va != 0 => component_subrange_offset(
                shadow.provider_data_component_va,
                shadow.bytes,
                provider_va,
                1,
            )
            .and_then(|offset| shadow.dependent_data_component_va.checked_add(offset))
            .unwrap_or(0),
            _ => 0,
        };
        write_unaligned(
            state.ndis_first_buffer_va_dependent_exec_va as *mut u64,
            dependent_va,
        );
    }
}

unsafe fn complete_provider_ndis_packet_copyback(
    state: &ProviderMarshalState,
    provider_instance: usize,
    provider_inst: DriverInstance,
    dependent_instance: usize,
    dependent_inst: DriverInstance,
) {
    if state.ndis_packet_copyback_provider_component_va == 0
        || state.ndis_packet_copyback_dependent_component_va == 0
        || state.ndis_packet_copyback_bytes == 0
        || !provider_ndis_status_success(state)
    {
        return;
    }
    let Some((_index, shadow)) = find_hosted_provider_ndis_packet_shadow_by_dependent(
        provider_instance,
        dependent_instance,
        state.ndis_packet_copyback_dependent_component_va,
    ) else {
        return;
    };
    let _ = sync_ndis_packet_shadow_to_dependent(
        provider_instance,
        provider_inst,
        dependent_instance,
        dependent_inst,
        shadow,
    );
}

unsafe fn complete_provider_ndis_packet_array_copyback(
    state: &ProviderMarshalState,
    provider_instance: usize,
    provider_inst: DriverInstance,
    dependent_instance: usize,
    dependent_inst: DriverInstance,
) {
    if state.ndis_packet_array_copyback_provider_exec_va == 0
        || state.ndis_packet_array_copyback_count == 0
        || !provider_ndis_status_success(state)
    {
        return;
    }
    let mut index = 0u64;
    while index < state.ndis_packet_array_copyback_count {
        let provider_packet = read_unaligned(
            (state.ndis_packet_array_copyback_provider_exec_va + index * 8) as *const u64,
        );
        if provider_packet != 0 {
            if let Some((_shadow_index, shadow)) =
                find_hosted_provider_ndis_packet_shadow_by_provider_for_dependent(
                    provider_instance,
                    dependent_instance,
                    provider_packet,
                )
            {
                let _ = sync_ndis_packet_shadow_to_dependent(
                    provider_instance,
                    provider_inst,
                    dependent_instance,
                    dependent_inst,
                    shadow,
                );
            } else {
                HOSTED_PROVIDER_NDIS_PACKET_SHADOW_REJECTIONS.fetch_add(1, Ordering::Relaxed);
            }
        }
        index += 1;
    }
}

unsafe fn complete_provider_ndis_packet_free(
    state: &ProviderMarshalState,
    provider_instance: usize,
    dependent_instance: usize,
) {
    if !state.ndis_packet_free_on_success
        || state.ndis_packet_free_dependent_component_va == 0
        || !provider_ndis_status_success(state)
    {
        return;
    }
    if !release_hosted_provider_ndis_packet_shadow_by_dependent(
        provider_instance,
        dependent_instance,
        state.ndis_packet_free_dependent_component_va,
    ) {
        HOSTED_PROVIDER_NDIS_PACKET_SHADOW_REJECTIONS.fetch_add(1, Ordering::Relaxed);
    }
}

unsafe fn complete_provider_ndis_object_shadows(
    state: &ProviderMarshalState,
    provider_instance: usize,
    provider_inst: DriverInstance,
    dependent_instance: usize,
    dependent_inst: DriverInstance,
    dependent_binding: Option<HostedDeviceBinding>,
) {
    complete_provider_unicode_string_init(state);
    complete_provider_ndis_device_properties(state, dependent_binding);
    complete_provider_ndis_configuration_parameter(
        state,
        provider_instance,
        provider_inst,
        dependent_instance,
        dependent_inst,
    );
    complete_provider_network_address(
        state,
        provider_instance,
        provider_inst,
        dependent_instance,
        dependent_inst,
    );
    complete_provider_ndis_packet_allocation(
        state,
        provider_instance,
        provider_inst,
        dependent_instance,
        dependent_inst,
    );
    complete_provider_ndis_buffer_allocation(
        state,
        provider_instance,
        provider_inst,
        dependent_instance,
        dependent_inst,
    );
    complete_provider_ndis_first_buffer_outputs(state, provider_instance, dependent_instance);
    complete_provider_ndis_packet_copyback(
        state,
        provider_instance,
        provider_inst,
        dependent_instance,
        dependent_inst,
    );
    complete_provider_ndis_packet_array_copyback(
        state,
        provider_instance,
        provider_inst,
        dependent_instance,
        dependent_inst,
    );
    complete_provider_ndis_packet_free(state, provider_instance, dependent_instance);
}

unsafe fn find_hosted_provider_miniport_interrupt_shadow(
    provider_instance: usize,
    dependent_instance: usize,
    dependent_component_va: u64,
) -> Option<(usize, HostedProviderMiniportInterruptShadow)> {
    if dependent_component_va == 0 {
        return None;
    }
    let Some(records) = hosted_provider_miniport_interrupt_shadows() else {
        return None;
    };
    for (index, record) in records.iter().copied().enumerate() {
        if record.present
            && record.construction_state == HostedProviderConstructionState::Published
            && record.provider_instance == provider_instance
            && record.dependent_instance == dependent_instance
            && hosted_provider_device_binding(
                record.provider_instance,
                record.dependent_instance,
                record.device_id,
            )
            .is_some()
            && hosted_provider_object_owner_is_live(
                record.owner,
                record.provider_instance,
                record.dependent_instance,
            )
            && record.dependent_component_va == dependent_component_va
        {
            return Some((index, record));
        }
    }
    None
}

unsafe fn allocate_hosted_provider_miniport_interrupt_shadow(
    provider_instance: usize,
    provider_inst: DriverInstance,
    dependent_instance: usize,
    dependent_component_va: u64,
) -> Result<(usize, HostedProviderMiniportInterruptShadow), i32> {
    let owner = hosted_provider_object_owner_for_pair(provider_instance, dependent_instance)
        .ok_or(STATUS_DEVICE_NOT_READY)?;
    let binding = current_hosted_device_dispatch_binding(dependent_instance)
        .filter(|binding| binding.projection_instance == provider_instance)
        .ok_or(STATUS_INVALID_DEVICE_REQUEST)?;
    if dependent_component_va == 0 {
        return Err(STATUS_INVALID_PARAMETER);
    }
    let skeleton = HostedProviderMiniportInterruptShadow {
        present: true,
        construction_state: HostedProviderConstructionState::Constructing,
        owner,
        provider_instance,
        dependent_instance,
        device_id: binding.device_id,
        dependent_component_va,
        provider_component_va: 0,
        provider_component_owned_by_bridge: false,
        bytes: NDIS_MINIPORT_INTERRUPT_LEN_X64,
    };
    let construction_index = {
        let records = hosted_provider_miniport_interrupt_shadows_mut();
        if let Some((index, record)) = records.iter().copied().enumerate().find(|(_, record)| {
            record.present
                && record.provider_instance == provider_instance
                && record.dependent_instance == dependent_instance
                && record.device_id == binding.device_id
                && record.dependent_component_va == dependent_component_va
        }) {
            if record.owner != owner
                || record.construction_state == HostedProviderConstructionState::Published
            {
                return Err(nt_status::NtStatus::OBJECT_NAME_COLLISION.raw());
            }
            if record.construction_state != HostedProviderConstructionState::RollingBack {
                return Err(nt_status::NtStatus::DEVICE_BUSY.raw());
            }
            if !release_hosted_provider_miniport_interrupt_shadow_record(&mut records[index]) {
                return Err(nt_status::NtStatus::DEVICE_BUSY.raw());
            }
            records[index] = skeleton;
            index
        } else if let Some(index) = records.iter().position(|record| !record.present) {
            records[index] = skeleton;
            index
        } else {
            records
                .try_reserve(1)
                .map_err(|_| STATUS_INSUFFICIENT_RESOURCES)?;
            records.push(skeleton);
            records.len() - 1
        }
    };
    let Some(provider_component_va) =
        hosted_instance_pool_alloc(provider_inst, NDIS_MINIPORT_INTERRUPT_LEN_X64)
    else {
        return Err(
            retain_or_clear_failed_hosted_provider_miniport_interrupt_construction(
                construction_index,
                STATUS_INSUFFICIENT_RESOURCES,
            ),
        );
    };
    {
        let record = &mut hosted_provider_miniport_interrupt_shadows_mut()[construction_index];
        record.provider_component_va = provider_component_va;
        record.provider_component_owned_by_bridge = true;
    }
    if component_to_exec_va_for_instance(
        provider_instance,
        provider_inst,
        provider_component_va,
        NDIS_MINIPORT_INTERRUPT_LEN_X64,
    )
    .is_none()
    {
        return Err(
            retain_or_clear_failed_hosted_provider_miniport_interrupt_construction(
                construction_index,
                STATUS_INVALID_PARAMETER,
            ),
        );
    }
    Ok((
        construction_index,
        hosted_provider_miniport_interrupt_shadows_mut()[construction_index],
    ))
}

unsafe fn release_hosted_provider_miniport_interrupt_shadow_record(
    record: &mut HostedProviderMiniportInterruptShadow,
) -> bool {
    if !record.present
        || record.construction_state == HostedProviderConstructionState::CompensationRequired
        || !hosted_provider_object_owner_is_current(
            record.owner,
            record.provider_instance,
            record.dependent_instance,
        )
    {
        return false;
    }
    if record.provider_component_owned_by_bridge {
        if !release_hosted_provider_owned_pool_allocation(
            record.owner,
            record.provider_instance,
            record.dependent_instance,
            record.provider_instance,
            record.provider_component_va,
        ) {
            return false;
        }
        record.provider_component_owned_by_bridge = false;
    }
    true
}

unsafe fn retain_or_clear_failed_hosted_provider_miniport_interrupt_construction(
    index: usize,
    status: i32,
) -> i32 {
    let records = hosted_provider_miniport_interrupt_shadows_mut();
    if let Some(record) = records.get_mut(index) {
        record.construction_state = HostedProviderConstructionState::RollingBack;
    }
    if records
        .get_mut(index)
        .is_some_and(|record| release_hosted_provider_miniport_interrupt_shadow_record(record))
    {
        records[index] = HostedProviderMiniportInterruptShadow::empty();
    }
    status
}

unsafe fn retain_indeterminate_hosted_provider_miniport_interrupt_construction(index: usize) {
    if let Some(record) = hosted_provider_miniport_interrupt_shadows_mut().get_mut(index) {
        if record.present
            && record.construction_state == HostedProviderConstructionState::Constructing
        {
            record.construction_state = HostedProviderConstructionState::CompensationRequired;
        }
    }
}

unsafe fn finish_hosted_provider_miniport_interrupt_construction(index: usize) -> bool {
    let Some(record) = hosted_provider_miniport_interrupt_shadows_mut().get_mut(index) else {
        return false;
    };
    if !record.present
        || record.construction_state != HostedProviderConstructionState::Constructing
        || record.provider_component_va == 0
        || !record.provider_component_owned_by_bridge
        || !hosted_provider_object_owner_is_live(
            record.owner,
            record.provider_instance,
            record.dependent_instance,
        )
    {
        return false;
    }
    record.construction_state = HostedProviderConstructionState::Published;
    true
}

unsafe fn hosted_provider_miniport_interrupt_shadow(
    provider_instance: usize,
    provider_inst: DriverInstance,
    dependent_instance: usize,
    dependent_inst: DriverInstance,
    dependent_component_va: u64,
    allow_create: bool,
) -> Result<(u64, u64, u64, Option<usize>), i32> {
    let Some(dependent_exec_va) = component_to_exec_va_for_instance(
        dependent_instance,
        dependent_inst,
        dependent_component_va,
        NDIS_MINIPORT_INTERRUPT_LEN_X64,
    ) else {
        return Err(STATUS_INVALID_PARAMETER);
    };
    let (shadow, construction_index) = match find_hosted_provider_miniport_interrupt_shadow(
        provider_instance,
        dependent_instance,
        dependent_component_va,
    ) {
        Some((_index, shadow)) => (shadow, None),
        None if allow_create => {
            let (index, shadow) = allocate_hosted_provider_miniport_interrupt_shadow(
                provider_instance,
                provider_inst,
                dependent_instance,
                dependent_component_va,
            )?;
            (shadow, Some(index))
        }
        None => {
            HOSTED_PROVIDER_MINIPORT_INTERRUPT_SHADOW_REJECTIONS.fetch_add(1, Ordering::Relaxed);
            return Err(STATUS_INVALID_PARAMETER);
        }
    };
    if shadow.bytes < NDIS_MINIPORT_INTERRUPT_LEN_X64 {
        HOSTED_PROVIDER_MINIPORT_INTERRUPT_SHADOW_REJECTIONS.fetch_add(1, Ordering::Relaxed);
        return Err(STATUS_INVALID_PARAMETER);
    }
    let Some(provider_exec_va) = component_to_exec_va_for_instance(
        provider_instance,
        provider_inst,
        shadow.provider_component_va,
        NDIS_MINIPORT_INTERRUPT_LEN_X64,
    ) else {
        HOSTED_PROVIDER_MINIPORT_INTERRUPT_SHADOW_REJECTIONS.fetch_add(1, Ordering::Relaxed);
        return Err(STATUS_INVALID_PARAMETER);
    };
    copy_bytes(
        provider_exec_va,
        dependent_exec_va,
        NDIS_MINIPORT_INTERRUPT_LEN_X64,
    );
    Ok((
        shadow.provider_component_va,
        dependent_exec_va,
        provider_exec_va,
        construction_index,
    ))
}

unsafe fn free_hosted_provider_miniport_interrupt_shadow(
    provider_instance: usize,
    provider_component_va: u64,
) -> bool {
    for record in hosted_provider_miniport_interrupt_shadows_mut().iter_mut() {
        if record.present
            && record.construction_state == HostedProviderConstructionState::Published
            && record.provider_instance == provider_instance
            && record.provider_component_va == provider_component_va
            && hosted_provider_object_owner_is_live(
                record.owner,
                record.provider_instance,
                record.dependent_instance,
            )
        {
            if !release_hosted_provider_miniport_interrupt_shadow_record(record) {
                return false;
            }
            *record = HostedProviderMiniportInterruptShadow::empty();
            return true;
        }
    }
    HOSTED_PROVIDER_MINIPORT_INTERRUPT_SHADOW_REJECTIONS.fetch_add(1, Ordering::Relaxed);
    false
}

unsafe fn clear_hosted_provider_miniport_interrupt_shadows_for_instance(
    instance_index: usize,
    domain: HostedDomainIdentity,
) -> u64 {
    let mut failures = 0u64;
    for record in hosted_provider_miniport_interrupt_shadows_mut().iter_mut() {
        if !record.present
            || record.provider_instance != instance_index
                && record.dependent_instance != instance_index
        {
            continue;
        }
        if !hosted_provider_object_owner_matches_instance(
            record.owner,
            record.provider_instance,
            record.dependent_instance,
            instance_index,
            domain,
        ) || !release_hosted_provider_miniport_interrupt_shadow_record(record)
        {
            failures += 1;
        } else {
            *record = HostedProviderMiniportInterruptShadow::empty();
        }
    }
    failures
}

