fn hosted_provider_device_binding(
    provider_instance: usize,
    dependent_instance: usize,
    device_id: u64,
) -> Option<HostedDeviceBinding> {
    hosted_resource_binding_by_device_id(device_id).filter(|binding| {
        binding.instance == dependent_instance
            && binding.projection_instance == provider_instance
            && hosted_driver_device_route_by_device_id(device_id).is_some_and(
                |(route_instance, route_inst, route_object)| {
                    route_instance == dependent_instance
                        && route_inst.driver_id == binding.driver_id
                        && route_object == binding.device_object
                },
            )
    })
}

fn hosted_provider_ndis_miniport_block_binding(
    mirror: HostedProviderNdisMiniportBlockMirror,
) -> Option<HostedDeviceBinding> {
    hosted_provider_device_binding(
        mirror.provider_instance,
        mirror.dependent_instance,
        mirror.device_id,
    )
}

unsafe fn provider_marshal_provider_handle(
    provider_instance: usize,
    dependent_instance: usize,
    handle: u64,
) -> Result<u64, i32> {
    if handle == 0 {
        return Err(STATUS_INVALID_PARAMETER);
    }
    let Some(mirror) = hosted_provider_ndis_miniport_block_mirror_by_dependent(
        provider_instance,
        dependent_instance,
        handle,
    ) else {
        let Some(provider_inst) = instance(provider_instance) else {
            return Err(STATUS_DEVICE_NOT_READY);
        };
        if component_to_exec_va_for_instance(provider_instance, provider_inst, handle, 1).is_none()
        {
            HOSTED_PROVIDER_NDIS_MINIPORT_BLOCK_MIRROR_REJECTIONS.fetch_add(1, Ordering::Relaxed);
            return Err(STATUS_INVALID_PARAMETER);
        }
        return Ok(handle);
    };
    let Some(provider_inst) = instance(provider_instance) else {
        return Err(STATUS_DEVICE_NOT_READY);
    };
    let Some(dependent_inst) = instance(dependent_instance) else {
        return Err(STATUS_DEVICE_NOT_READY);
    };
    refresh_hosted_provider_ndis_miniport_block_mirror(provider_inst, dependent_inst, mirror)?;
    Ok(mirror.provider_component_va)
}

unsafe fn reserve_hosted_provider_ndis_miniport_block_mirror(
    mirror: HostedProviderNdisMiniportBlockMirror,
) -> Option<usize> {
    if mirror.provider_component_va == 0
        || mirror.dependent_component_va == 0
        || mirror.device_id == 0
        || mirror.provider_instance == mirror.dependent_instance
        || mirror.construction_state != HostedProviderConstructionState::Constructing
        || mirror.thunk_binding_count != 0
        || !hosted_provider_object_owner_is_live(
            mirror.owner,
            mirror.provider_instance,
            mirror.dependent_instance,
        )
        || hosted_provider_ndis_miniport_block_binding(mirror).is_none()
    {
        return None;
    }
    let records = hosted_provider_ndis_miniport_block_mirrors_mut();
    for (index, record) in records.iter_mut().enumerate() {
        if !record.present {
            *record = mirror;
            return Some(index);
        }
    }
    records.try_reserve(1).ok()?;
    records.push(mirror);
    Some(records.len() - 1)
}

unsafe fn store_hosted_provider_ndis_miniport_block_mirror_construction(
    index: usize,
    mirror: HostedProviderNdisMiniportBlockMirror,
) -> bool {
    let Some(record) = hosted_provider_ndis_miniport_block_mirrors_mut().get_mut(index) else {
        return false;
    };
    if !record.present
        || record.construction_state != HostedProviderConstructionState::Constructing
        || mirror.construction_state != HostedProviderConstructionState::Constructing
        || record.owner != mirror.owner
        || record.provider_instance != mirror.provider_instance
        || record.dependent_instance != mirror.dependent_instance
        || record.device_id != mirror.device_id
        || record.provider_component_va != mirror.provider_component_va
        || record.dependent_component_va != mirror.dependent_component_va
    {
        return false;
    }
    *record = mirror;
    true
}

unsafe fn finish_hosted_provider_ndis_miniport_block_mirror_construction(index: usize) -> bool {
    let Some(record) = hosted_provider_ndis_miniport_block_mirrors_mut().get_mut(index) else {
        return false;
    };
    if !record.present
        || record.construction_state != HostedProviderConstructionState::Constructing
        || record.thunk_binding_count != HOSTED_PROVIDER_NDIS_MINIPORT_BLOCK_THUNK_COUNT
        || record.thunk_bindings[..record.thunk_binding_count]
            .iter()
            .any(Option::is_none)
        || record.packet_indicate_thunk == 0
        || record.send_complete_thunk == 0
        || record.send_resources_thunk == 0
        || record.reset_complete_thunk == 0
        || record.eth_rx_indicate_thunk == 0
        || record.eth_rx_complete_thunk == 0
        || record.status_thunk == 0
        || record.status_complete_thunk == 0
        || record.td_complete_thunk == 0
        || record.query_complete_thunk == 0
        || record.set_complete_thunk == 0
    {
        return false;
    }
    record.construction_state = HostedProviderConstructionState::Published;
    true
}

unsafe fn rollback_hosted_provider_ndis_miniport_block_mirror_construction(index: usize) {
    let Some(record) = hosted_provider_ndis_miniport_block_mirrors_mut().get_mut(index) else {
        return;
    };
    if !record.present
        || !matches!(
            record.construction_state,
            HostedProviderConstructionState::Constructing
                | HostedProviderConstructionState::RollingBack
        )
    {
        return;
    }
    record.construction_state = HostedProviderConstructionState::RollingBack;
    let mut release_failed = false;
    let mut index = 0usize;
    while index < record.thunk_binding_count {
        if let Some(binding) = record.thunk_bindings[index] {
            if release_instance_executable_thunk_binding(binding, true) {
                record.thunk_bindings[index] = None;
            } else {
                release_failed = true;
            }
        }
        index += 1;
    }
    if record.dependent_component_va != 0 {
        if release_hosted_provider_owned_pool_allocation(
            record.owner,
            record.provider_instance,
            record.dependent_instance,
            record.dependent_instance,
            record.dependent_component_va,
        ) {
            record.dependent_component_va = 0;
        } else {
            release_failed = true;
        }
    }
    if release_failed {
        record.construction_state = HostedProviderConstructionState::RollingBack;
    } else {
        *record = HostedProviderNdisMiniportBlockMirror::empty();
    }
}

unsafe fn write_hosted_provider_ndis_miniport_block_mirror_cell(
    provider_exec: u64,
    dependent_exec: u64,
    offset: u64,
    value: u64,
) -> Result<(), i32> {
    if offset > NDIS_MINIPORT_BLOCK_CALLBACK_PROJECTION_LEN_X64.saturating_sub(8) {
        return Err(STATUS_INVALID_PARAMETER);
    }
    let provider_value = read_unaligned((provider_exec + offset) as *const u64);
    write_unaligned(
        (dependent_exec + offset) as *mut u64,
        if provider_value == 0 { 0 } else { value },
    );
    Ok(())
}

unsafe fn refresh_hosted_provider_ndis_miniport_block_mirror(
    provider_inst: DriverInstance,
    dependent_inst: DriverInstance,
    mirror: HostedProviderNdisMiniportBlockMirror,
) -> Result<(), i32> {
    let Some(provider_exec) = component_to_exec_va_for_instance(
        mirror.provider_instance,
        provider_inst,
        mirror.provider_component_va,
        NDIS_MINIPORT_BLOCK_CALLBACK_PROJECTION_LEN_X64,
    ) else {
        HOSTED_PROVIDER_NDIS_MINIPORT_BLOCK_MIRROR_REJECTIONS.fetch_add(1, Ordering::Relaxed);
        return Err(STATUS_INVALID_PARAMETER);
    };
    let Some(dependent_exec) = component_to_exec_va_for_instance(
        mirror.dependent_instance,
        dependent_inst,
        mirror.dependent_component_va,
        NDIS_MINIPORT_BLOCK_CALLBACK_PROJECTION_LEN_X64,
    ) else {
        HOSTED_PROVIDER_NDIS_MINIPORT_BLOCK_MIRROR_REJECTIONS.fetch_add(1, Ordering::Relaxed);
        return Err(STATUS_INVALID_PARAMETER);
    };

    provider_marshal_zero(
        dependent_exec,
        NDIS_MINIPORT_BLOCK_CALLBACK_PROJECTION_LEN_X64,
    );
    let miniport_adapter_context = read_unaligned(
        (provider_exec + NDIS_MINIPORT_BLOCK_MINIPORT_ADAPTER_CONTEXT_OFFSET_X64) as *const u64,
    );
    write_unaligned(
        (dependent_exec + NDIS_MINIPORT_BLOCK_MINIPORT_ADAPTER_CONTEXT_OFFSET_X64) as *mut u64,
        miniport_adapter_context,
    );
    let eth_db =
        read_unaligned((provider_exec + NDIS_MINIPORT_BLOCK_ETH_DB_OFFSET_X64) as *const u64);
    write_unaligned(
        (dependent_exec + NDIS_MINIPORT_BLOCK_ETH_DB_OFFSET_X64) as *mut u64,
        eth_db,
    );
    write_hosted_provider_ndis_miniport_block_mirror_cell(
        provider_exec,
        dependent_exec,
        NDIS_MINIPORT_BLOCK_PACKET_INDICATE_HANDLER_OFFSET_X64,
        mirror.packet_indicate_thunk,
    )?;
    write_hosted_provider_ndis_miniport_block_mirror_cell(
        provider_exec,
        dependent_exec,
        NDIS_MINIPORT_BLOCK_SEND_COMPLETE_HANDLER_OFFSET_X64,
        mirror.send_complete_thunk,
    )?;
    write_hosted_provider_ndis_miniport_block_mirror_cell(
        provider_exec,
        dependent_exec,
        NDIS_MINIPORT_BLOCK_SEND_RESOURCES_HANDLER_OFFSET_X64,
        mirror.send_resources_thunk,
    )?;
    write_hosted_provider_ndis_miniport_block_mirror_cell(
        provider_exec,
        dependent_exec,
        NDIS_MINIPORT_BLOCK_RESET_COMPLETE_HANDLER_OFFSET_X64,
        mirror.reset_complete_thunk,
    )?;
    write_hosted_provider_ndis_miniport_block_mirror_cell(
        provider_exec,
        dependent_exec,
        NDIS_MINIPORT_BLOCK_ETH_RX_INDICATE_HANDLER_OFFSET_X64,
        mirror.eth_rx_indicate_thunk,
    )?;
    write_hosted_provider_ndis_miniport_block_mirror_cell(
        provider_exec,
        dependent_exec,
        NDIS_MINIPORT_BLOCK_ETH_RX_COMPLETE_HANDLER_OFFSET_X64,
        mirror.eth_rx_complete_thunk,
    )?;
    write_hosted_provider_ndis_miniport_block_mirror_cell(
        provider_exec,
        dependent_exec,
        NDIS_MINIPORT_BLOCK_STATUS_HANDLER_OFFSET_X64,
        mirror.status_thunk,
    )?;
    write_hosted_provider_ndis_miniport_block_mirror_cell(
        provider_exec,
        dependent_exec,
        NDIS_MINIPORT_BLOCK_STATUS_COMPLETE_HANDLER_OFFSET_X64,
        mirror.status_complete_thunk,
    )?;
    write_hosted_provider_ndis_miniport_block_mirror_cell(
        provider_exec,
        dependent_exec,
        NDIS_MINIPORT_BLOCK_TD_COMPLETE_HANDLER_OFFSET_X64,
        mirror.td_complete_thunk,
    )?;
    write_hosted_provider_ndis_miniport_block_mirror_cell(
        provider_exec,
        dependent_exec,
        NDIS_MINIPORT_BLOCK_QUERY_COMPLETE_HANDLER_OFFSET_X64,
        mirror.query_complete_thunk,
    )?;
    write_hosted_provider_ndis_miniport_block_mirror_cell(
        provider_exec,
        dependent_exec,
        NDIS_MINIPORT_BLOCK_SET_COMPLETE_HANDLER_OFFSET_X64,
        mirror.set_complete_thunk,
    )
}

unsafe fn refresh_hosted_provider_ndis_miniport_block_mirrors_for_pair(
    provider_instance: usize,
    provider_inst: DriverInstance,
    dependent_instance: usize,
    dependent_inst: DriverInstance,
) -> Result<(), i32> {
    let mut matched = false;
    let Some(records) = hosted_provider_ndis_miniport_block_mirrors() else {
        HOSTED_PROVIDER_NDIS_MINIPORT_BLOCK_MIRROR_REJECTIONS.fetch_add(1, Ordering::Relaxed);
        return Err(STATUS_DEVICE_NOT_READY);
    };
    for mirror in records.iter().copied() {
        if mirror.present
            && mirror.construction_state == HostedProviderConstructionState::Published
            && mirror.provider_instance == provider_instance
            && mirror.dependent_instance == dependent_instance
            && hosted_provider_ndis_miniport_block_binding(mirror).is_some()
            && hosted_provider_object_owner_is_live(
                mirror.owner,
                mirror.provider_instance,
                mirror.dependent_instance,
            )
        {
            matched = true;
            refresh_hosted_provider_ndis_miniport_block_mirror(
                provider_inst,
                dependent_inst,
                mirror,
            )?;
        }
    }
    if !matched {
        HOSTED_PROVIDER_NDIS_MINIPORT_BLOCK_MIRROR_REJECTIONS.fetch_add(1, Ordering::Relaxed);
        return Err(STATUS_DEVICE_NOT_READY);
    }
    Ok(())
}

unsafe fn allocate_hosted_provider_ndis_miniport_block_mirror(
    provider_instance: usize,
    provider_inst: DriverInstance,
    provider_publication_cookie: u64,
    dependent_instance: usize,
    dependent_inst: DriverInstance,
    provider_component_va: u64,
) -> Result<HostedProviderNdisMiniportBlockMirror, i32> {
    let owner = hosted_provider_object_owner_for_pair(provider_instance, dependent_instance)
        .ok_or(STATUS_DEVICE_NOT_READY)?;
    let binding = current_hosted_device_dispatch_binding(dependent_instance)
        .filter(|binding| binding.projection_instance == provider_instance)
        .ok_or(STATUS_INVALID_DEVICE_REQUEST)?;
    let mirror_records = hosted_provider_ndis_miniport_block_mirrors_mut();
    if mirror_records.iter().all(|record| record.present) && mirror_records.try_reserve(1).is_err()
    {
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    }
    let Some(provider_exec) = component_to_exec_va_for_instance(
        provider_instance,
        provider_inst,
        provider_component_va,
        NDIS_MINIPORT_BLOCK_CALLBACK_PROJECTION_LEN_X64,
    ) else {
        HOSTED_PROVIDER_NDIS_MINIPORT_BLOCK_MIRROR_REJECTIONS.fetch_add(1, Ordering::Relaxed);
        return Err(STATUS_INVALID_PARAMETER);
    };
    let packet_indicate_target = read_unaligned(
        (provider_exec + NDIS_MINIPORT_BLOCK_PACKET_INDICATE_HANDLER_OFFSET_X64) as *const u64,
    );
    if packet_indicate_target == 0 {
        HOSTED_PROVIDER_NDIS_MINIPORT_BLOCK_MIRROR_REJECTIONS.fetch_add(1, Ordering::Relaxed);
        return Err(STATUS_INVALID_PARAMETER);
    }
    let Some(dependent_component_va) = hosted_instance_pool_alloc(
        dependent_inst,
        NDIS_MINIPORT_BLOCK_CALLBACK_PROJECTION_LEN_X64,
    ) else {
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    };
    if component_to_exec_va_for_instance(
        dependent_instance,
        dependent_inst,
        dependent_component_va,
        NDIS_MINIPORT_BLOCK_CALLBACK_PROJECTION_LEN_X64,
    )
    .is_none()
    {
        hosted_instance_pool_free(dependent_inst, dependent_component_va);
        HOSTED_PROVIDER_NDIS_MINIPORT_BLOCK_MIRROR_REJECTIONS.fetch_add(1, Ordering::Relaxed);
        return Err(STATUS_INVALID_PARAMETER);
    }

    let mut mirror = HostedProviderNdisMiniportBlockMirror {
        present: true,
        construction_state: HostedProviderConstructionState::Constructing,
        owner,
        provider_instance,
        dependent_instance,
        device_id: binding.device_id,
        provider_component_va,
        dependent_component_va,
        ..HostedProviderNdisMiniportBlockMirror::empty()
    };
    let Some(construction_index) = reserve_hosted_provider_ndis_miniport_block_mirror(mirror)
    else {
        hosted_instance_pool_free(dependent_inst, dependent_component_va);
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    };

    macro_rules! retain_or_rollback {
        ($field:ident, $emit:expr) => {
            match $emit {
                Ok(thunk) => {
                    let binding = thunk.binding;
                    let Some(run_va) = mirror.retain_thunk(thunk) else {
                        let _ = release_instance_executable_thunk_binding(binding, true);
                        rollback_hosted_provider_ndis_miniport_block_mirror_construction(
                            construction_index,
                        );
                        return Err(STATUS_INSUFFICIENT_RESOURCES);
                    };
                    mirror.$field = run_va;
                    if !store_hosted_provider_ndis_miniport_block_mirror_construction(
                        construction_index,
                        mirror,
                    ) {
                        let _ = release_instance_executable_thunk_binding(binding, true);
                        rollback_hosted_provider_ndis_miniport_block_mirror_construction(
                            construction_index,
                        );
                        return Err(STATUS_DEVICE_NOT_READY);
                    }
                }
                Err(status) => {
                    rollback_hosted_provider_ndis_miniport_block_mirror_construction(
                        construction_index,
                    );
                    return Err(status);
                }
            }
        };
    }

    retain_or_rollback!(
        packet_indicate_thunk,
        provider_marshal_emit_internal_import_thunk_for_instance(
            dependent_instance,
            "ndis.sys",
            "MiniIndicateReceivePacket",
            packet_indicate_target,
            provider_publication_cookie,
        )
    );
    retain_or_rollback!(
        send_complete_thunk,
        provider_marshal_emit_import_thunk_for_instance(
            dependent_instance,
            "ndis.sys",
            "NdisMSendComplete",
            provider_publication_cookie,
        )
    );
    retain_or_rollback!(
        send_resources_thunk,
        provider_marshal_emit_import_thunk_for_instance(
            dependent_instance,
            "ndis.sys",
            "NdisMSendResourcesAvailable",
            provider_publication_cookie,
        )
    );
    retain_or_rollback!(
        reset_complete_thunk,
        provider_marshal_emit_import_thunk_for_instance(
            dependent_instance,
            "ndis.sys",
            "NdisMResetComplete",
            provider_publication_cookie,
        )
    );
    retain_or_rollback!(
        eth_rx_indicate_thunk,
        provider_marshal_emit_import_thunk_for_instance(
            dependent_instance,
            "ndis.sys",
            "EthFilterDprIndicateReceive",
            provider_publication_cookie,
        )
    );
    retain_or_rollback!(
        eth_rx_complete_thunk,
        provider_marshal_emit_import_thunk_for_instance(
            dependent_instance,
            "ndis.sys",
            "EthFilterDprIndicateReceiveComplete",
            provider_publication_cookie,
        )
    );
    retain_or_rollback!(
        status_thunk,
        provider_marshal_emit_import_thunk_for_instance(
            dependent_instance,
            "ndis.sys",
            "NdisMIndicateStatus",
            provider_publication_cookie,
        )
    );
    retain_or_rollback!(
        status_complete_thunk,
        provider_marshal_emit_import_thunk_for_instance(
            dependent_instance,
            "ndis.sys",
            "NdisMIndicateStatusComplete",
            provider_publication_cookie,
        )
    );
    retain_or_rollback!(
        td_complete_thunk,
        provider_marshal_emit_import_thunk_for_instance(
            dependent_instance,
            "ndis.sys",
            "NdisMTransferDataComplete",
            provider_publication_cookie,
        )
    );
    retain_or_rollback!(
        query_complete_thunk,
        provider_marshal_emit_import_thunk_for_instance(
            dependent_instance,
            "ndis.sys",
            "NdisMQueryInformationComplete",
            provider_publication_cookie,
        )
    );
    retain_or_rollback!(
        set_complete_thunk,
        provider_marshal_emit_import_thunk_for_instance(
            dependent_instance,
            "ndis.sys",
            "NdisMSetInformationComplete",
            provider_publication_cookie,
        )
    );

    if let Err(status) =
        refresh_hosted_provider_ndis_miniport_block_mirror(provider_inst, dependent_inst, mirror)
    {
        rollback_hosted_provider_ndis_miniport_block_mirror_construction(construction_index);
        return Err(status);
    }
    if !finish_hosted_provider_ndis_miniport_block_mirror_construction(construction_index) {
        rollback_hosted_provider_ndis_miniport_block_mirror_construction(construction_index);
        return Err(STATUS_DEVICE_NOT_READY);
    }
    mirror.construction_state = HostedProviderConstructionState::Published;
    print_str(b"[provider-ndis] miniport block mirror provider-inst=");
    print_u64(provider_instance as u64);
    print_str(b" dependent-inst=");
    print_u64(dependent_instance as u64);
    print_str(b" provider=0x");
    print_hex64(provider_component_va);
    print_str(b" dependent=0x");
    print_hex64(dependent_component_va);
    print_str(b"\n");
    Ok(mirror)
}

unsafe fn ensure_hosted_provider_ndis_miniport_block_mirror(
    provider_instance: usize,
    provider_inst: DriverInstance,
    provider_publication_cookie: u64,
    dependent_instance: usize,
    dependent_inst: DriverInstance,
    provider_component_va: u64,
) -> Result<HostedProviderNdisMiniportBlockMirror, i32> {
    if let Some((_index, mirror)) = hosted_provider_ndis_miniport_block_mirror_by_provider(
        provider_instance,
        dependent_instance,
        provider_component_va,
    ) {
        refresh_hosted_provider_ndis_miniport_block_mirror(provider_inst, dependent_inst, mirror)?;
        return Ok(mirror);
    }
    allocate_hosted_provider_ndis_miniport_block_mirror(
        provider_instance,
        provider_inst,
        provider_publication_cookie,
        dependent_instance,
        dependent_inst,
        provider_component_va,
    )
}

unsafe fn clear_hosted_provider_ndis_miniport_block_mirrors_for_instance(
    instance_index: usize,
    domain: HostedDomainIdentity,
) -> u64 {
    let record_count = hosted_provider_ndis_miniport_block_mirrors_mut().len();
    for index in 0..record_count {
        if hosted_provider_ndis_miniport_block_mirrors()
            .and_then(|records| records.get(index))
            .is_some_and(|record| {
                record.present
                    && matches!(
                        record.construction_state,
                        HostedProviderConstructionState::Constructing
                            | HostedProviderConstructionState::RollingBack
                    )
            })
        {
            rollback_hosted_provider_ndis_miniport_block_mirror_construction(index);
        }
    }
    let mut failures = 0u64;
    for record in hosted_provider_ndis_miniport_block_mirrors_mut().iter_mut() {
        if !record.present
            || record.provider_instance != instance_index
                && record.dependent_instance != instance_index
        {
            continue;
        }
        if record.thunk_bindings[..record.thunk_binding_count]
            .iter()
            .any(Option::is_some)
            || !hosted_provider_object_owner_matches_instance(
                record.owner,
                record.provider_instance,
                record.dependent_instance,
                instance_index,
                domain,
            )
            || !release_hosted_provider_owned_pool_allocation(
                record.owner,
                record.provider_instance,
                record.dependent_instance,
                record.dependent_instance,
                record.dependent_component_va,
            )
        {
            failures += 1;
        } else {
            *record = HostedProviderNdisMiniportBlockMirror::empty();
        }
    }
    failures
}

unsafe fn clear_hosted_provider_state_for_device(binding: HostedDeviceBinding) -> u64 {
    if hosted_device_binding_by_device_id(binding.device_id) != Some(binding) {
        return 1;
    }
    let mut failures = 0u64;

    for record in hosted_provider_miniport_interrupt_shadows_mut().iter_mut() {
        if !record.present || record.device_id != binding.device_id {
            continue;
        }
        if !hosted_provider_object_owner_is_live(
            record.owner,
            record.provider_instance,
            record.dependent_instance,
        ) || !release_hosted_provider_miniport_interrupt_shadow_record(record)
        {
            failures = failures.saturating_add(1);
        } else {
            *record = HostedProviderMiniportInterruptShadow::empty();
        }
    }

    for record in hosted_provider_miniport_timer_shadows_mut().iter_mut() {
        if !record.present || record.device_id != binding.device_id {
            continue;
        }
        if !hosted_provider_object_owner_is_live(
            record.owner,
            record.provider_instance,
            record.dependent_instance,
        ) {
            failures = failures.saturating_add(1);
            continue;
        }
        if let Some(thunk) = record.callback_binding {
            if !release_instance_executable_thunk_binding(thunk, true) {
                failures = failures.saturating_add(1);
                continue;
            }
            record.callback_binding = None;
        }
        if record.provider_component_va != 0
            && !release_hosted_provider_owned_pool_allocation(
                record.owner,
                record.provider_instance,
                record.dependent_instance,
                record.provider_instance,
                record.provider_component_va,
            )
        {
            failures = failures.saturating_add(1);
            continue;
        }
        *record = HostedProviderMiniportTimerShadow::empty();
    }

    for record in hosted_provider_ndis_work_item_shadows_mut().iter() {
        if !record.present {
            continue;
        }
        if [record.preparing, record.queued, record.active]
            .iter()
            .any(|invocation| invocation.device_id == binding.device_id)
        {
            failures = failures.saturating_add(1);
        }
    }

    for record in hosted_provider_ndis_miniport_block_mirrors_mut().iter_mut() {
        if !record.present || record.device_id != binding.device_id {
            continue;
        }
        if !hosted_provider_object_owner_is_live(
            record.owner,
            record.provider_instance,
            record.dependent_instance,
        ) {
            failures = failures.saturating_add(1);
            continue;
        }
        let mut binding_index = 0usize;
        let mut binding_failure = false;
        while binding_index < record.thunk_binding_count {
            if let Some(thunk) = record.thunk_bindings[binding_index] {
                if release_instance_executable_thunk_binding(thunk, true) {
                    record.thunk_bindings[binding_index] = None;
                } else {
                    binding_failure = true;
                }
            }
            binding_index += 1;
        }
        if binding_failure
            || record.dependent_component_va != 0
                && !release_hosted_provider_owned_pool_allocation(
                    record.owner,
                    record.provider_instance,
                    record.dependent_instance,
                    record.dependent_instance,
                    record.dependent_component_va,
                )
        {
            failures = failures.saturating_add(1);
            continue;
        }
        *record = HostedProviderNdisMiniportBlockMirror::empty();
    }

    failures
}

unsafe fn hosted_provider_lifetime_records_reference_instance(instance_index: usize) -> bool {
    let references = |provider_instance: usize, dependent_instance: usize| {
        provider_instance == instance_index || dependent_instance == instance_index
    };
    hosted_provider_domain_dependencies().is_some_and(|records| {
        records.iter().any(|record| {
            record.present && references(record.provider_instance, record.dependent_instance)
        })
    }) || hosted_provider_callback_parents().is_some_and(|records| {
        records.iter().any(|record| {
            record.present && references(record.provider_instance, record.dependent_instance)
        })
    }) || hosted_provider_dispatch_routes().is_some_and(|records| {
        records.iter().any(|record| {
            record.used && references(record.provider_instance, record.dependent_instance)
        })
    }) || hosted_provider_pointer_allocations().is_some_and(|records| {
        records.iter().any(|record| {
            record.present && references(record.provider_instance, record.dependent_instance)
        })
    }) || hosted_provider_ndis_packet_shadows().is_some_and(|records| {
        records.iter().any(|record| {
            record.present && references(record.provider_instance, record.dependent_instance)
        })
    }) || hosted_provider_ndis_buffer_shadows().is_some_and(|records| {
        records.iter().any(|record| {
            record.present && references(record.provider_instance, record.dependent_instance)
        })
    }) || hosted_provider_miniport_interrupt_shadows().is_some_and(|records| {
        records.iter().any(|record| {
            record.present && references(record.provider_instance, record.dependent_instance)
        })
    }) || hosted_provider_miniport_timer_shadows().is_some_and(|records| {
        records.iter().any(|record| {
            record.present && references(record.provider_instance, record.dependent_instance)
        })
    }) || hosted_provider_ndis_work_item_shadows().is_some_and(|records| {
        records.iter().any(|record| {
            record.present && references(record.provider_instance, record.dependent_instance)
        })
    }) || hosted_provider_ndis_miniport_block_mirrors().is_some_and(|records| {
        records.iter().any(|record| {
            record.present && references(record.provider_instance, record.dependent_instance)
        })
    })
}

unsafe fn provider_marshal_emit_callback_thunk(
    provider_instance: usize,
    dependent_instance: usize,
    target: u64,
    callback_offset: u64,
    callback_kind: u8,
) -> Result<HostedExecutableThunkAddress, i32> {
    let owner = hosted_provider_object_owner_for_pair(provider_instance, dependent_instance)
        .ok_or(STATUS_DEVICE_NOT_READY)?;
    let discriminator = callback_offset ^ ((callback_kind as u64) << 56);
    let key = HostedThunkSlotKey::new(
        owner,
        HOSTED_THUNK_PURPOSE_PROVIDER_CALLBACK,
        target,
        discriminator,
    )
    .ok_or(STATUS_INVALID_PARAMETER)?;
    let reservation = reserve_instance_executable_thunk(provider_instance, key)?;
    if reservation.existing {
        let Some(record) = hosted_provider_callback_record_for_thunk(reservation.token, key) else {
            abort_instance_executable_thunk(provider_instance, reservation);
            return Err(STATUS_DEVICE_NOT_READY);
        };
        return if record.target == target
            && record.callback_offset == callback_offset
            && record.callback_kind == callback_kind
            && hosted_provider_callback_record(record.callback_cookie).is_some()
        {
            Ok(reservation.address(provider_instance))
        } else {
            abort_instance_executable_thunk(provider_instance, reservation);
            Err(STATUS_DEVICE_NOT_READY)
        };
    }
    let Some((record_index, callback_cookie)) = register_hosted_provider_callback_record(
        provider_instance,
        dependent_instance,
        target,
        callback_offset,
        callback_kind,
        reservation.token,
        key,
    ) else {
        abort_instance_executable_thunk(provider_instance, reservation);
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    };
    let thunk = HostedProviderCallbackThunkPlan {
        thunk_va: reservation.run_va,
        thunk_offset: reservation
            .thunk_index
            .saturating_mul(HOSTED_PROVIDER_IMPORT_THUNK_SLOT_LEN),
        callback_gate: hosted_provider_callback_gate_va(),
        callback_cookie,
    };
    let slot = core::slice::from_raw_parts_mut(
        reservation.exec_va as *mut u8,
        HOSTED_PROVIDER_IMPORT_THUNK_SLOT_LEN as usize,
    );
    if encode_hosted_provider_callback_thunk(thunk, slot).is_err()
        || !finish_hosted_provider_callback_record(
            record_index,
            callback_cookie,
            reservation.token,
            key,
        )
        || !commit_instance_executable_thunk(provider_instance, reservation)
    {
        abort_hosted_provider_callback_record(
            record_index,
            callback_cookie,
            reservation.token,
            key,
        );
        abort_instance_executable_thunk(provider_instance, reservation);
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    }
    Ok(reservation.address(provider_instance))
}

fn provider_marshal_align8(value: u64) -> Option<u64> {
    value.checked_add(7).map(|value| value & !7)
}

unsafe fn provider_marshal_zero(exec_va: u64, bytes: u64) {
    let mut offset = 0u64;
    while offset < bytes {
        write_unaligned((exec_va + offset) as *mut u8, 0);
        offset += 1;
    }
}

unsafe fn provider_marshal_alloc(
    state: &mut ProviderMarshalState,
    provider_shared: u64,
    bytes: u64,
) -> Option<(u64, u64)> {
    if bytes == 0 {
        return None;
    }
    let start = provider_marshal_align8(state.cursor)?;
    let end = start.checked_add(bytes)?;
    if end > SH_PROVIDER_EXPORT_MARSHAL_BYTES {
        return None;
    }
    state.cursor = end;
    let component_va = FSD_SHARED_VADDR
        .checked_add(SH_PROVIDER_EXPORT_MARSHAL_BASE)?
        .checked_add(start)?;
    let exec_va = provider_shared
        .checked_add(SH_PROVIDER_EXPORT_MARSHAL_BASE)?
        .checked_add(start)?;
    provider_marshal_zero(exec_va, bytes);
    Some((component_va, exec_va))
}

fn provider_marshal_add_copyout(
    state: &mut ProviderMarshalState,
    dependent_exec_va: u64,
    provider_exec_va: u64,
    bytes: u64,
) -> Option<()> {
    provider_marshal_add_copyout_with_fixed(
        state,
        dependent_exec_va,
        provider_exec_va,
        bytes,
        0,
        0,
        0,
    )
}

fn provider_marshal_add_copyout_with_fixed(
    state: &mut ProviderMarshalState,
    dependent_exec_va: u64,
    provider_exec_va: u64,
    bytes: u64,
    fixed_success_value: u64,
    fixed_failure_value: u64,
    fixed_bytes: u8,
) -> Option<()> {
    if state.copyout_count >= state.copyouts.len() {
        return None;
    }
    state.copyouts[state.copyout_count] = ProviderMarshalCopyout {
        dependent_exec_va,
        provider_exec_va,
        bytes,
        fixed_success_value,
        fixed_failure_value,
        fixed_bytes,
    };
    state.copyout_count += 1;
    Some(())
}

fn provider_marshal_add_deferred_free(
    state: &mut ProviderMarshalState,
    dependent_instance: usize,
    component_va: u64,
    condition: u8,
) -> Option<()> {
    if state.deferred_free_count >= state.deferred_frees.len() || condition == 0 {
        return None;
    }
    state.deferred_frees[state.deferred_free_count] = ProviderMarshalDeferredFree {
        dependent_instance,
        component_va,
        condition,
    };
    state.deferred_free_count += 1;
    Some(())
}

fn provider_marshal_add_ndis_device_property_output(
    state: &mut ProviderMarshalState,
    dependent_exec_va: u64,
    provider_exec_va: u64,
    kind: u8,
) -> Option<()> {
    if state.ndis_device_property_output_count >= state.ndis_device_property_outputs.len() {
        return None;
    }
    state.ndis_device_property_outputs[state.ndis_device_property_output_count] =
        ProviderMarshalNdisDevicePropertyOutput {
            dependent_exec_va,
            provider_exec_va,
            kind,
        };
    state.ndis_device_property_output_count += 1;
    Some(())
}

unsafe fn provider_marshal_output_cell(
    state: &mut ProviderMarshalState,
    dependent_index: usize,
    dependent_inst: DriverInstance,
    provider_shared: u64,
    arg_value: u64,
    bytes: u64,
) -> Result<u64, i32> {
    let Some(dependent_exec_va) =
        component_to_exec_va_for_instance(dependent_index, dependent_inst, arg_value, bytes)
    else {
        return Err(STATUS_INVALID_PARAMETER);
    };
    let Some((provider_component_va, provider_exec_va)) =
        provider_marshal_alloc(state, provider_shared, bytes)
    else {
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    };
    provider_marshal_add_copyout(state, dependent_exec_va, provider_exec_va, bytes)
        .ok_or(STATUS_INSUFFICIENT_RESOURCES)?;
    Ok(provider_component_va)
}

unsafe fn provider_marshal_ndis_device_property_output(
    state: &mut ProviderMarshalState,
    dependent_index: usize,
    dependent_inst: DriverInstance,
    provider_shared: u64,
    arg_value: u64,
    kind: u8,
) -> Result<u64, i32> {
    if arg_value == 0 {
        return Ok(0);
    }
    if kind == 0 || kind > NDIS_DEVICE_PROPERTY_TRANSLATED_RESOURCES {
        return Err(STATUS_INVALID_PARAMETER);
    }
    let Some(dependent_exec_va) =
        component_to_exec_va_for_instance(dependent_index, dependent_inst, arg_value, 8)
    else {
        return Err(STATUS_INVALID_PARAMETER);
    };
    let Some((provider_component_va, provider_exec_va)) =
        provider_marshal_alloc(state, provider_shared, 8)
    else {
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    };
    write_unaligned(provider_exec_va as *mut u64, 0);
    provider_marshal_add_ndis_device_property_output(
        state,
        dependent_exec_va,
        provider_exec_va,
        kind,
    )
    .ok_or(STATUS_INSUFFICIENT_RESOURCES)?;
    Ok(provider_component_va)
}

