unsafe fn dma_common_pointer_in_grant(
    sh: u64,
    component_va: u64,
    logical: u64,
    length: u64,
) -> bool {
    let grant_va = read_volatile((sh + SH_DMA_COMMON_VA) as *const u64);
    let grant_len = read_volatile((sh + SH_DMA_COMMON_LEN) as *const u64);
    let grant_logical = read_volatile((sh + SH_DMA_COMMON_LOGICAL) as *const u64);
    if grant_va == 0
        || grant_len == 0
        || grant_logical == 0
        || component_va == 0
        || logical == 0
        || length == 0
    {
        return false;
    }
    let Some(va_offset) = component_va.checked_sub(grant_va) else {
        return false;
    };
    let Some(logical_offset) = logical.checked_sub(grant_logical) else {
        return false;
    };
    va_offset == logical_offset && va_offset <= grant_len && length <= grant_len - va_offset
}

unsafe fn dma_common_allocation_record_matches(
    sh: u64,
    component_va: u64,
    logical: u64,
    length: u64,
) -> bool {
    if !dma_common_pointer_in_grant(sh, component_va, logical, length) {
        return false;
    }
    let capacity = dma_allocation_record_capacity(sh);
    let count = read_volatile((sh + SH_DMA_ALLOC_RECORD_COUNT) as *const u64);
    if capacity == 0 || count > capacity {
        return false;
    }
    let mut index = 0u64;
    while index < count {
        let Some(record) = dma_allocation_record(sh, index) else {
            return false;
        };
        let record_logical = read_volatile((record + SH_DMA_ALLOC_RECORD_LOGICAL) as *const u64);
        let record_len = read_volatile((record + SH_DMA_ALLOC_RECORD_LEN) as *const u64);
        let record_va = read_volatile((record + SH_DMA_ALLOC_RECORD_VA) as *const u64);
        let record_kind = read_volatile((record + SH_DMA_ALLOC_RECORD_KIND) as *const u64);
        if record_kind == HOSTED_DMA_RECORD_KIND_COMMON
            && record_logical == logical
            && record_len == length
            && record_va == component_va
        {
            return true;
        }
        index += 1;
    }
    false
}

unsafe fn dma_common_allocation_record_covers(
    sh: u64,
    component_va: u64,
    length: u64,
) -> Option<u64> {
    if component_va == 0 || length == 0 {
        return None;
    }
    let grant_va = read_volatile((sh + SH_DMA_COMMON_VA) as *const u64);
    let grant_logical = read_volatile((sh + SH_DMA_COMMON_LOGICAL) as *const u64);
    if grant_va == 0 || grant_logical == 0 {
        return None;
    }
    let capacity = dma_allocation_record_capacity(sh);
    let count = read_volatile((sh + SH_DMA_ALLOC_RECORD_COUNT) as *const u64);
    if capacity == 0 || count > capacity {
        return None;
    }
    let mut index = 0u64;
    while index < count {
        let record = dma_allocation_record(sh, index)?;
        let record_logical = read_volatile((record + SH_DMA_ALLOC_RECORD_LOGICAL) as *const u64);
        let record_len = read_volatile((record + SH_DMA_ALLOC_RECORD_LEN) as *const u64);
        let record_va = read_volatile((record + SH_DMA_ALLOC_RECORD_VA) as *const u64);
        let record_kind = read_volatile((record + SH_DMA_ALLOC_RECORD_KIND) as *const u64);
        if record_kind == HOSTED_DMA_RECORD_KIND_COMMON && record_logical != 0 && record_va != 0 {
            let logical_offset = record_logical.checked_sub(grant_logical)?;
            let va_offset = record_va.checked_sub(grant_va)?;
            if logical_offset == va_offset {
                if let Some(offset) =
                    component_subrange_offset(record_va, record_len, component_va, length)
                {
                    let logical = record_logical.checked_add(offset)?;
                    if dma_common_pointer_in_grant(sh, component_va, logical, length) {
                        return Some(logical);
                    }
                }
            }
        }
        index += 1;
    }
    None
}

unsafe fn dma_common_subrange_exec_va(
    inst: DriverInstance,
    component_va: u64,
    bytes: u64,
) -> Option<u64> {
    let (instance, _) = instance_by_driver_id(inst.driver_id)?;
    let binding = current_hosted_device_dispatch_binding(instance)?;
    let state = hosted_device_resource_state_by_device_id(binding.device_id)?;
    dma_common_allocation_record_covers(inst.exec_shared_va, component_va, bytes)?;
    hosted_dma_alias_for_component_va(state, component_va, bytes)
}

unsafe fn component_or_dma_common_to_exec_va(
    instance: usize,
    inst: DriverInstance,
    dma_owner_inst: DriverInstance,
    component_va: u64,
    bytes: u64,
) -> Option<u64> {
    component_to_exec_va_for_instance(instance, inst, component_va, bytes)
        .or_else(|| dma_common_subrange_exec_va(dma_owner_inst, component_va, bytes))
}

unsafe fn provider_marshal_output_dma_common_buffer(
    state: &mut ProviderMarshalState,
    dependent_index: usize,
    dependent_inst: DriverInstance,
    provider_shared: u64,
    arg_value: u64,
    length: u64,
) -> Result<u64, i32> {
    state.resource_projection_required = true;
    let sh = dependent_inst.exec_shared_va;
    let grant_va = read_volatile((sh + SH_DMA_COMMON_VA) as *const u64);
    let grant_len = read_volatile((sh + SH_DMA_COMMON_LEN) as *const u64);
    let grant_logical = read_volatile((sh + SH_DMA_COMMON_LOGICAL) as *const u64);
    let adapter_id = read_volatile((sh + SH_DMA_ADAPTER_ID) as *const u64);
    if grant_va == 0
        || grant_len == 0
        || grant_logical == 0
        || adapter_id == 0
        || length == 0
        || length > u32::MAX as u64
        || length > grant_len
    {
        return Err(STATUS_INVALID_PARAMETER);
    }
    let cell = provider_marshal_output_cell(
        state,
        dependent_index,
        dependent_inst,
        provider_shared,
        arg_value,
        8,
    )?;
    state.dma_state_copyback = true;
    Ok(cell)
}

unsafe fn provider_marshal_input_dma_common_buffer(
    state: &mut ProviderMarshalState,
    dependent_inst: DriverInstance,
    arg_value: u64,
    length: u64,
    physical_address: u64,
) -> Result<u64, i32> {
    state.resource_projection_required = true;
    if length > u32::MAX as u64 {
        return Err(STATUS_INVALID_PARAMETER);
    }
    if !dma_common_allocation_record_matches(
        dependent_inst.exec_shared_va,
        arg_value,
        physical_address,
        length,
    ) {
        return Err(STATUS_INVALID_PARAMETER);
    }
    state.dma_state_copyback = true;
    state.dma_free_logical = physical_address;
    state.dma_free_len = length;
    Ok(arg_value)
}

unsafe fn provider_marshal_output_pointer_from_length(
    state: &mut ProviderMarshalState,
    provider_instance: usize,
    dependent_index: usize,
    dependent_inst: DriverInstance,
    provider_shared: u64,
    arg_value: u64,
    length: u64,
) -> Result<u64, i32> {
    if length == 0 {
        return Err(STATUS_INVALID_PARAMETER);
    }
    let Some(owner) = hosted_provider_object_owner_for_pair(provider_instance, dependent_index)
    else {
        return Err(STATUS_DEVICE_NOT_READY);
    };
    let Some(dependent_exec_va) =
        component_to_exec_va_for_instance(dependent_index, dependent_inst, arg_value, 8)
    else {
        return Err(STATUS_INVALID_PARAMETER);
    };
    let Some(allocated_component_va) = hosted_instance_pool_alloc(dependent_inst, length) else {
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    };
    register_hosted_provider_pointer_allocation(
        owner,
        dependent_index,
        allocated_component_va,
        provider_instance,
        length,
    );
    let Some((provider_component_va, provider_exec_va)) =
        provider_marshal_alloc(state, provider_shared, 8)
    else {
        if !release_hosted_provider_pointer_allocation_by_dependent(
            dependent_index,
            allocated_component_va,
            0,
        ) {
            HOSTED_PROVIDER_POINTER_ALLOCATION_REJECTIONS.fetch_add(1, Ordering::Relaxed);
        }
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    };
    if provider_marshal_add_copyout_with_fixed(
        state,
        dependent_exec_va,
        provider_exec_va,
        8,
        allocated_component_va,
        0,
        8,
    )
    .is_none()
    {
        if !release_hosted_provider_pointer_allocation_by_dependent(
            dependent_index,
            allocated_component_va,
            0,
        ) {
            HOSTED_PROVIDER_POINTER_ALLOCATION_REJECTIONS.fetch_add(1, Ordering::Relaxed);
        }
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    }
    if provider_marshal_add_deferred_free(
        state,
        dependent_index,
        allocated_component_va,
        PROVIDER_MARSHAL_FREE_ON_FAILURE,
    )
    .is_none()
    {
        if !release_hosted_provider_pointer_allocation_by_dependent(
            dependent_index,
            allocated_component_va,
            0,
        ) {
            HOSTED_PROVIDER_POINTER_ALLOCATION_REJECTIONS.fetch_add(1, Ordering::Relaxed);
        }
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    }
    state.pointer_allocation_dependent_instance = dependent_index;
    state.pointer_allocation_dependent_component_va = allocated_component_va;
    state.pointer_allocation_provider_output_exec_va = provider_exec_va;
    state.pointer_allocation_bytes = length;
    Ok(provider_component_va)
}

unsafe fn provider_marshal_owned_allocation(
    state: &mut ProviderMarshalState,
    provider_instance: usize,
    dependent_index: usize,
    arg_value: u64,
    length: u64,
) -> Result<u64, i32> {
    if arg_value == 0 {
        return Err(STATUS_INVALID_PARAMETER);
    }
    let Some(record) = hosted_provider_pointer_allocation(dependent_index, arg_value, length)
    else {
        return Err(STATUS_INVALID_PARAMETER);
    };
    if record.provider_instance != provider_instance || record.provider_component_va == 0 {
        return Err(STATUS_INVALID_PARAMETER);
    }
    state.pointer_free_dependent_instance = dependent_index;
    state.pointer_free_dependent_component_va = arg_value;
    state.pointer_free_provider_instance = provider_instance;
    state.pointer_free_provider_component_va = record.provider_component_va;
    provider_marshal_add_deferred_free(
        state,
        dependent_index,
        arg_value,
        PROVIDER_MARSHAL_FREE_ALWAYS,
    )
    .ok_or(STATUS_INSUFFICIENT_RESOURCES)?;
    Ok(record.provider_component_va)
}

unsafe fn provider_marshal_ndis_request(
    state: &mut ProviderMarshalState,
    dependent_index: usize,
    dependent_inst: DriverInstance,
    provider_shared: u64,
    arg_value: u64,
) -> Result<u64, i32> {
    if arg_value == 0 {
        return Err(STATUS_INVALID_PARAMETER);
    }
    let Some(dependent_request_exec) = component_to_exec_va_for_instance(
        dependent_index,
        dependent_inst,
        arg_value,
        NDIS_REQUEST_LEN_X64,
    ) else {
        return Err(STATUS_INVALID_PARAMETER);
    };
    let request_type =
        read_unaligned((dependent_request_exec + NDIS_REQUEST_TYPE_OFFSET_X64) as *const u32);
    if request_type != NDIS_REQUEST_QUERY_INFORMATION
        && request_type != NDIS_REQUEST_SET_INFORMATION
    {
        return Err(STATUS_NOT_SUPPORTED);
    }
    let info_buffer = read_unaligned(
        (dependent_request_exec + NDIS_REQUEST_INFORMATION_BUFFER_OFFSET_X64) as *const u64,
    );
    let info_len = read_unaligned(
        (dependent_request_exec + NDIS_REQUEST_INFORMATION_BUFFER_LEN_OFFSET_X64) as *const u32,
    ) as u64;

    let Some((provider_request_component, provider_request_exec)) =
        provider_marshal_alloc(state, provider_shared, NDIS_REQUEST_LEN_X64)
    else {
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    };
    copy_bytes(
        provider_request_exec,
        dependent_request_exec,
        NDIS_REQUEST_LEN_X64,
    );
    provider_marshal_add_copyout(
        state,
        dependent_request_exec + NDIS_REQUEST_BYTES_DONE_OFFSET_X64,
        provider_request_exec + NDIS_REQUEST_BYTES_DONE_OFFSET_X64,
        NDIS_REQUEST_BYTE_COUNTERS_LEN_X64,
    )
    .ok_or(STATUS_INSUFFICIENT_RESOURCES)?;

    if info_len == 0 {
        write_unaligned(
            (provider_request_exec + NDIS_REQUEST_INFORMATION_BUFFER_OFFSET_X64) as *mut u64,
            0,
        );
        return Ok(provider_request_component);
    }
    if info_buffer == 0 {
        return Err(STATUS_INVALID_PARAMETER);
    }
    let Some(dependent_info_exec) =
        component_to_exec_va_for_instance(dependent_index, dependent_inst, info_buffer, info_len)
    else {
        return Err(STATUS_INVALID_PARAMETER);
    };
    let Some((provider_info_component, provider_info_exec)) =
        provider_marshal_alloc(state, provider_shared, info_len)
    else {
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    };
    if request_type == NDIS_REQUEST_SET_INFORMATION {
        copy_bytes(provider_info_exec, dependent_info_exec, info_len);
    }
    if request_type == NDIS_REQUEST_QUERY_INFORMATION {
        provider_marshal_add_copyout(state, dependent_info_exec, provider_info_exec, info_len)
            .ok_or(STATUS_INSUFFICIENT_RESOURCES)?;
    }
    write_unaligned(
        (provider_request_exec + NDIS_REQUEST_INFORMATION_BUFFER_OFFSET_X64) as *mut u64,
        provider_info_component,
    );
    Ok(provider_request_component)
}

unsafe fn provider_marshal_ndis_buffer(
    state: &mut ProviderMarshalState,
    provider_instance: usize,
    dependent_index: usize,
    dependent_inst: DriverInstance,
    provider_shared: u64,
    arg_value: u64,
) -> Result<u64, i32> {
    if arg_value == 0 {
        return Err(STATUS_INVALID_PARAMETER);
    }
    let mdl_bytes = nt_mdl::MDL_SIZE as u64;
    if let Some(dependent_exec_va) =
        component_to_exec_va_for_instance(dependent_index, dependent_inst, arg_value, mdl_bytes)
    {
        let Some((provider_component_va, provider_exec_va)) =
            provider_marshal_alloc(state, provider_shared, mdl_bytes)
        else {
            return Err(STATUS_INSUFFICIENT_RESOURCES);
        };
        copy_bytes(provider_exec_va, dependent_exec_va, mdl_bytes);
        return Ok(provider_component_va);
    }
    let Some(provider_inst) = instance(provider_instance) else {
        return Err(STATUS_DEVICE_NOT_READY);
    };
    if component_to_exec_va_for_instance(provider_instance, provider_inst, arg_value, mdl_bytes)
        .is_none()
    {
        return Err(STATUS_INVALID_PARAMETER);
    }
    Ok(arg_value)
}

unsafe fn provider_marshal_driver_object_shadow(
    state: &mut ProviderMarshalState,
    provider_instance: usize,
    provider_publication_cookie: u64,
    dependent_index: usize,
    dependent_inst: DriverInstance,
    arg_value: u64,
) -> Result<u64, i32> {
    let route_index = register_hosted_provider_driver_object_shadow(
        provider_instance,
        provider_publication_cookie,
        dependent_index,
        dependent_inst,
        arg_value,
    )?;
    let Some(route) = hosted_provider_dispatch_route(route_index) else {
        return Err(STATUS_DEVICE_NOT_READY);
    };
    state.ndis_route_index = route_index;
    Ok(route.provider_driver_object)
}

unsafe fn provider_marshal_unicode_string(
    state: &mut ProviderMarshalState,
    dependent_index: usize,
    dependent_inst: DriverInstance,
    provider_shared: u64,
    arg_value: u64,
) -> Result<u64, i32> {
    let Some(desc_exec) =
        component_to_exec_va_for_instance(dependent_index, dependent_inst, arg_value, 16)
    else {
        return Err(STATUS_INVALID_PARAMETER);
    };
    let length = read_unaligned(desc_exec as *const u16) as u64;
    let maximum = read_unaligned((desc_exec + 2) as *const u16) as u64;
    let buffer = read_unaligned((desc_exec + 8) as *const u64);
    if length > maximum || length > SH_PROVIDER_EXPORT_MARSHAL_BYTES / 2 {
        return Err(STATUS_INVALID_PARAMETER);
    }
    let Some((provider_desc_va, provider_desc_exec)) =
        provider_marshal_alloc(state, provider_shared, 16)
    else {
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    };
    let provider_buffer_va = if length == 0 {
        0
    } else {
        let Some(buffer_exec) =
            component_to_exec_va_for_instance(dependent_index, dependent_inst, buffer, length)
        else {
            return Err(STATUS_INVALID_PARAMETER);
        };
        let buffer_bytes = length.checked_add(2).ok_or(STATUS_INVALID_PARAMETER)?;
        let Some((provider_buffer_va, provider_buffer_exec)) =
            provider_marshal_alloc(state, provider_shared, buffer_bytes)
        else {
            return Err(STATUS_INSUFFICIENT_RESOURCES);
        };
        copy_bytes(provider_buffer_exec, buffer_exec, length);
        provider_buffer_va
    };
    write_unaligned(provider_desc_exec as *mut u16, length as u16);
    write_unaligned(
        (provider_desc_exec + 2) as *mut u16,
        length.saturating_add(2) as u16,
    );
    write_unaligned((provider_desc_exec + 8) as *mut u64, provider_buffer_va);
    Ok(provider_desc_va)
}

unsafe fn provider_marshal_unicode_string_from_source(
    state: &mut ProviderMarshalState,
    dependent_index: usize,
    dependent_inst: DriverInstance,
    provider_shared: u64,
    desc_arg_value: u64,
    source_arg_value: u64,
) -> Result<(u64, u64), i32> {
    if source_arg_value == 0 {
        return Err(STATUS_INVALID_PARAMETER);
    }
    let Some(dependent_desc_exec) =
        component_to_exec_va_for_instance(dependent_index, dependent_inst, desc_arg_value, 16)
    else {
        return Err(STATUS_INVALID_PARAMETER);
    };

    let mut source_bytes = 0u64;
    loop {
        if source_bytes >= NDIS_INIT_UNICODE_STRING_MAX_BYTES {
            return Err(STATUS_INVALID_PARAMETER);
        }
        let Some(ch_exec) = component_to_exec_va_for_instance(
            dependent_index,
            dependent_inst,
            source_arg_value
                .checked_add(source_bytes)
                .ok_or(STATUS_INVALID_PARAMETER)?,
            2,
        ) else {
            return Err(STATUS_INVALID_PARAMETER);
        };
        let ch = read_unaligned(ch_exec as *const u16);
        if ch == 0 {
            break;
        }
        source_bytes = source_bytes
            .checked_add(2)
            .ok_or(STATUS_INVALID_PARAMETER)?;
    }

    let source_total = source_bytes
        .checked_add(2)
        .ok_or(STATUS_INVALID_PARAMETER)?;
    let Some(source_exec) = component_to_exec_va_for_instance(
        dependent_index,
        dependent_inst,
        source_arg_value,
        source_total,
    ) else {
        return Err(STATUS_INVALID_PARAMETER);
    };
    let Some((provider_desc_va, provider_desc_exec)) =
        provider_marshal_alloc(state, provider_shared, 16)
    else {
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    };
    let Some((provider_source_va, provider_source_exec)) =
        provider_marshal_alloc(state, provider_shared, source_total)
    else {
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    };
    provider_marshal_zero(provider_desc_exec, 16);
    copy_bytes(provider_source_exec, source_exec, source_total);
    state.ndis_unicode_init_dependent_desc_exec_va = dependent_desc_exec;
    state.ndis_unicode_init_provider_desc_exec_va = provider_desc_exec;
    state.ndis_unicode_init_dependent_source_component_va = source_arg_value;
    Ok((provider_desc_va, provider_source_va))
}

unsafe fn provider_marshal_embedded_unicode_string_buffer(
    state: &mut ProviderMarshalState,
    dependent_index: usize,
    dependent_inst: DriverInstance,
    provider_shared: u64,
    provider_desc_exec: u64,
    dependent_desc_exec: u64,
) -> Result<(), i32> {
    let length = read_unaligned(dependent_desc_exec as *const u16) as u64;
    let maximum = read_unaligned((dependent_desc_exec + 2) as *const u16) as u64;
    let buffer = read_unaligned((dependent_desc_exec + 8) as *const u64);
    if length > maximum || length > SH_PROVIDER_EXPORT_MARSHAL_BYTES / 2 {
        return Err(STATUS_INVALID_PARAMETER);
    }
    let provider_buffer_va = if length == 0 {
        0
    } else {
        let Some(buffer_exec) =
            component_to_exec_va_for_instance(dependent_index, dependent_inst, buffer, length)
        else {
            return Err(STATUS_INVALID_PARAMETER);
        };
        let buffer_bytes = length.checked_add(2).ok_or(STATUS_INVALID_PARAMETER)?;
        let Some((provider_buffer_va, provider_buffer_exec)) =
            provider_marshal_alloc(state, provider_shared, buffer_bytes)
        else {
            return Err(STATUS_INSUFFICIENT_RESOURCES);
        };
        copy_bytes(provider_buffer_exec, buffer_exec, length);
        provider_buffer_va
    };
    write_unaligned(provider_desc_exec as *mut u16, length as u16);
    write_unaligned(
        (provider_desc_exec + 2) as *mut u16,
        length.saturating_add(2) as u16,
    );
    write_unaligned((provider_desc_exec + 8) as *mut u64, provider_buffer_va);
    Ok(())
}

unsafe fn provider_marshal_miniport_characteristics(
    state: &mut ProviderMarshalState,
    provider_instance: usize,
    dependent_index: usize,
    dependent_inst: DriverInstance,
    provider_shared: u64,
    arg_value: u64,
    supplied_len: u64,
) -> Result<u64, i32> {
    let Some(header_exec) =
        component_to_exec_va_for_instance(dependent_index, dependent_inst, arg_value, 8)
    else {
        return Err(STATUS_INVALID_PARAMETER);
    };
    let major = read_unaligned(header_exec as *const u8);
    let minor = read_unaligned((header_exec + 1) as *const u8);
    let layout = match ndis_miniport_characteristics_layout(major, minor, supplied_len) {
        Ok(layout) => layout,
        Err(NdisMiniportCharacteristicsLayoutError::BadVersion) => {
            return Err(STATUS_INVALID_PARAMETER)
        }
        Err(NdisMiniportCharacteristicsLayoutError::BufferTooSmall) => {
            return Err(STATUS_INVALID_PARAMETER)
        }
    };
    if layout.required_len > SH_PROVIDER_EXPORT_MARSHAL_BYTES {
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    }
    let Some(dependent_exec_va) = component_to_exec_va_for_instance(
        dependent_index,
        dependent_inst,
        arg_value,
        layout.required_len,
    ) else {
        return Err(STATUS_INVALID_PARAMETER);
    };

    let mut callback_count = 0u64;
    let mut callback_index = 0usize;
    while callback_index < layout.callback_count as usize {
        let Some(offset) = layout.callback_offset(callback_index) else {
            return Err(STATUS_INVALID_PARAMETER);
        };
        if read_unaligned((dependent_exec_va + offset) as *const u64) != 0 {
            callback_count = callback_count.saturating_add(1);
        }
        callback_index += 1;
    }
    let Some((provider_component_va, provider_exec_va)) =
        provider_marshal_alloc(state, provider_shared, layout.required_len)
    else {
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    };
    copy_bytes(provider_exec_va, dependent_exec_va, layout.required_len);
    if callback_count != 0 {
        state.callback_parent_construction_index = reserve_hosted_provider_callback_parent(
            provider_instance,
            dependent_index,
            HOSTED_PROVIDER_CALLBACK_PARENT_KIND_MINIPORT,
        )?;
    }

    callback_index = 0;
    while callback_index < layout.callback_count as usize {
        let Some(offset) = layout.callback_offset(callback_index) else {
            return Err(STATUS_INVALID_PARAMETER);
        };
        let target = read_unaligned((dependent_exec_va + offset) as *const u64);
        if target != 0 {
            let thunk = provider_marshal_emit_callback_thunk(
                provider_instance,
                dependent_index,
                target,
                offset,
                HOSTED_PROVIDER_CALLBACK_KIND_MINIPORT,
            )?;
            if !retain_hosted_provider_callback_parent_binding(
                state.callback_parent_construction_index,
                thunk.binding,
            ) {
                let _ = release_instance_executable_thunk_binding(thunk.binding, true);
                return Err(STATUS_INSUFFICIENT_RESOURCES);
            }
            write_unaligned((provider_exec_va + offset) as *mut u64, thunk.run_va);
        }
        callback_index += 1;
    }
    Ok(provider_component_va)
}

unsafe fn provider_marshal_protocol_characteristics(
    state: &mut ProviderMarshalState,
    provider_instance: usize,
    dependent_index: usize,
    dependent_inst: DriverInstance,
    provider_shared: u64,
    arg_value: u64,
    supplied_len: u64,
) -> Result<u64, i32> {
    let Some(header_exec) =
        component_to_exec_va_for_instance(dependent_index, dependent_inst, arg_value, 8)
    else {
        return Err(STATUS_INVALID_PARAMETER);
    };
    let major = read_unaligned(header_exec as *const u8);
    let minor = read_unaligned((header_exec + 1) as *const u8);
    let layout = match ndis_protocol_characteristics_layout(major, minor, supplied_len) {
        Ok(layout) => layout,
        Err(NdisProtocolCharacteristicsLayoutError::BadVersion) => {
            return Err(STATUS_INVALID_PARAMETER)
        }
        Err(NdisProtocolCharacteristicsLayoutError::BufferTooSmall) => {
            return Err(STATUS_INVALID_PARAMETER)
        }
    };
    if layout.required_len > SH_PROVIDER_EXPORT_MARSHAL_BYTES {
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    }
    let Some(dependent_exec_va) = component_to_exec_va_for_instance(
        dependent_index,
        dependent_inst,
        arg_value,
        layout.required_len,
    ) else {
        return Err(STATUS_INVALID_PARAMETER);
    };

    let mut callback_count = 0u64;
    let mut callback_index = 0usize;
    while callback_index < layout.callback_count as usize {
        let Some(offset) = layout.callback_offset(callback_index) else {
            return Err(STATUS_INVALID_PARAMETER);
        };
        if read_unaligned((dependent_exec_va + offset) as *const u64) != 0 {
            callback_count = callback_count.saturating_add(1);
        }
        callback_index += 1;
    }
    let Some((provider_component_va, provider_exec_va)) =
        provider_marshal_alloc(state, provider_shared, layout.required_len)
    else {
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    };
    copy_bytes(provider_exec_va, dependent_exec_va, layout.required_len);

    provider_marshal_embedded_unicode_string_buffer(
        state,
        dependent_index,
        dependent_inst,
        provider_shared,
        provider_exec_va + NDIS_PROTOCOL_CHARACTERISTICS_NAME_OFFSET_X64,
        dependent_exec_va + NDIS_PROTOCOL_CHARACTERISTICS_NAME_OFFSET_X64,
    )?;
    if callback_count != 0 {
        state.callback_parent_construction_index = reserve_hosted_provider_callback_parent(
            provider_instance,
            dependent_index,
            HOSTED_PROVIDER_CALLBACK_PARENT_KIND_PROTOCOL,
        )?;
    }

    callback_index = 0;
    while callback_index < layout.callback_count as usize {
        let Some(offset) = layout.callback_offset(callback_index) else {
            return Err(STATUS_INVALID_PARAMETER);
        };
        let target = read_unaligned((dependent_exec_va + offset) as *const u64);
        if target != 0 {
            let thunk = provider_marshal_emit_callback_thunk(
                provider_instance,
                dependent_index,
                target,
                offset,
                HOSTED_PROVIDER_CALLBACK_KIND_PROTOCOL,
            )?;
            if !retain_hosted_provider_callback_parent_binding(
                state.callback_parent_construction_index,
                thunk.binding,
            ) {
                let _ = release_instance_executable_thunk_binding(thunk.binding, true);
                return Err(STATUS_INSUFFICIENT_RESOURCES);
            }
            write_unaligned((provider_exec_va + offset) as *mut u64, thunk.run_va);
        }
        callback_index += 1;
    }
    Ok(provider_component_va)
}

unsafe fn prepare_provider_export_marshal(
    policy: HostedProviderExportMarshalPolicy,
    provider_instance: usize,
    provider_publication_cookie: u64,
    dependent_index: usize,
    dependent_inst: DriverInstance,
    provider_shared: u64,
    args: &mut [u64; HOSTED_PROVIDER_EXPORT_ARG_CAP],
) -> Result<ProviderMarshalState, i32> {
    if policy.argument_count as usize > args.len() {
        return Err(STATUS_INVALID_PARAMETER);
    }
    if policy.stack_qwords as u64 > SH_PROVIDER_EXPORT_STACK_QWORDS {
        return Err(STATUS_INVALID_PARAMETER);
    }
    let mut state = ProviderMarshalState::empty();
    let mut preparation_guard = ProviderMarshalPreparationGuard::new(&state);
    let mut index = 0usize;
    while index < policy.argument_count as usize {
        let arg = args[index];
        args[index] = match policy.args[index] {
            HostedProviderArgumentMarshal::Scalar
            | HostedProviderArgumentMarshal::CallerContext => arg,
            HostedProviderArgumentMarshal::ProviderHandle => {
                let provider_handle =
                    provider_marshal_provider_handle(provider_instance, dependent_index, arg)?;
                if matches!(
                    policy.side_effect,
                    HostedProviderExportSideEffect::NdisMiniportRegistration
                        | HostedProviderExportSideEffect::NdisTerminateWrapper
                        | HostedProviderExportSideEffect::NdisProtocolDeregistration
                ) {
                    state.callback_parent_input_provider_handle = provider_handle;
                }
                provider_handle
            }
            HostedProviderArgumentMarshal::CallerInDriverObject => {
                if policy.side_effect == HostedProviderExportSideEffect::NdisInitializeWrapper {
                    provider_marshal_driver_object_shadow(
                        &mut state,
                        provider_instance,
                        provider_publication_cookie,
                        dependent_index,
                        dependent_inst,
                        arg,
                    )?
                } else {
                    arg
                }
            }
            HostedProviderArgumentMarshal::CallerInOwnedAllocation { length_arg } => {
                let length_index = length_arg as usize;
                provider_marshal_owned_allocation(
                    &mut state,
                    provider_instance,
                    dependent_index,
                    arg,
                    provider_marshal_u32_arg(policy, args, length_index)?,
                )?
            }
            HostedProviderArgumentMarshal::CallerOutStatus => {
                let provider_arg = provider_marshal_output_cell(
                    &mut state,
                    dependent_index,
                    dependent_inst,
                    provider_shared,
                    arg,
                    4,
                )?;
                state.ndis_status_provider_exec_va =
                    provider_shared_component_to_exec(provider_shared, provider_arg, 4)
                        .unwrap_or(0);
                provider_arg
            }
            HostedProviderArgumentMarshal::CallerOutHandle
            | HostedProviderArgumentMarshal::CallerOutU8
            | HostedProviderArgumentMarshal::CallerOutU32
            | HostedProviderArgumentMarshal::CallerOutPhysicalAddress => {
                let bytes = match policy.args[index] {
                    HostedProviderArgumentMarshal::CallerOutU8 => 1,
                    HostedProviderArgumentMarshal::CallerOutU32 => 4,
                    _ => 8,
                };
                let provider_arg = provider_marshal_output_cell(
                    &mut state,
                    dependent_index,
                    dependent_inst,
                    provider_shared,
                    arg,
                    bytes,
                )?;
                if policy.side_effect == HostedProviderExportSideEffect::NdisInitializeWrapper
                    && matches!(
                        policy.args[index],
                        HostedProviderArgumentMarshal::CallerOutHandle
                    )
                {
                    state.ndis_initialize_wrapper_handle_exec_va =
                        provider_shared + (provider_arg - FSD_SHARED_VADDR);
                }
                if policy.side_effect == HostedProviderExportSideEffect::NdisProtocolRegistration
                    && matches!(
                        policy.args[index],
                        HostedProviderArgumentMarshal::CallerOutHandle
                    )
                {
                    state.callback_parent_handle_exec_va =
                        provider_shared + (provider_arg - FSD_SHARED_VADDR);
                }
                provider_arg
            }
            HostedProviderArgumentMarshal::CallerInOutU32 => provider_marshal_inout_cell(
                &mut state,
                dependent_index,
                dependent_inst,
                provider_shared,
                arg,
                4,
            )?,
            HostedProviderArgumentMarshal::CallerInUnicodeString => {
                provider_marshal_unicode_string(
                    &mut state,
                    dependent_index,
                    dependent_inst,
                    provider_shared,
                    arg,
                )?
            }
            HostedProviderArgumentMarshal::CallerOutUnicodeStringFromSource { source_arg } => {
                let source_index = source_arg as usize;
                if source_index >= policy.argument_count as usize {
                    return Err(STATUS_INVALID_PARAMETER);
                }
                let (provider_desc_va, provider_source_va) =
                    provider_marshal_unicode_string_from_source(
                        &mut state,
                        dependent_index,
                        dependent_inst,
                        provider_shared,
                        arg,
                        args[source_index],
                    )?;
                args[source_index] = provider_source_va;
                provider_desc_va
            }
            HostedProviderArgumentMarshal::CallerInAnsiString => provider_marshal_ansi_string(
                &mut state,
                dependent_index,
                dependent_inst,
                provider_shared,
                arg,
            )?,
            HostedProviderArgumentMarshal::CallerInBuffer { length_arg } => {
                let length_index = length_arg as usize;
                provider_marshal_input_buffer(
                    &mut state,
                    dependent_index,
                    dependent_inst,
                    provider_shared,
                    arg,
                    provider_marshal_u32_arg(policy, args, length_index)?,
                )?
            }
            HostedProviderArgumentMarshal::CallerInArray {
                count_arg,
                element_size,
                count_width,
            } => {
                let count_index = count_arg as usize;
                if count_index >= policy.argument_count as usize || element_size == 0 {
                    return Err(STATUS_INVALID_PARAMETER);
                }
                let count = match count_width {
                    4 => args[count_index] & u32::MAX as u64,
                    8 => args[count_index],
                    _ => return Err(STATUS_INVALID_PARAMETER),
                };
                let bytes = count
                    .checked_mul(element_size as u64)
                    .ok_or(STATUS_INVALID_PARAMETER)?;
                provider_marshal_input_buffer(
                    &mut state,
                    dependent_index,
                    dependent_inst,
                    provider_shared,
                    arg,
                    bytes,
                )?
            }
            HostedProviderArgumentMarshal::CallerInNdisBuffer => provider_marshal_ndis_buffer(
                &mut state,
                provider_instance,
                dependent_index,
                dependent_inst,
                provider_shared,
                arg,
            )?,
            HostedProviderArgumentMarshal::CallerInPacket => {
                let Some(provider_inst) = instance(provider_instance) else {
                    return Err(STATUS_DEVICE_NOT_READY);
                };
                provider_marshal_ndis_packet(
                    &mut state,
                    provider_instance,
                    provider_inst,
                    dependent_index,
                    dependent_inst,
                    arg,
                    false,
                    true,
                    true,
                )?
            }
            HostedProviderArgumentMarshal::CallerInOutPacket => {
                let Some(provider_inst) = instance(provider_instance) else {
                    return Err(STATUS_DEVICE_NOT_READY);
                };
                let free_on_success =
                    policy.side_effect == HostedProviderExportSideEffect::NdisPacketFree;
                state.ndis_packet_free_on_success = free_on_success;
                if !free_on_success
                    && current_hosted_device_dispatch_binding(dependent_index).is_some()
                {
                    state.dma_state_copyback = true;
                }
                let provider_packet = provider_marshal_ndis_packet(
                    &mut state,
                    provider_instance,
                    provider_inst,
                    dependent_index,
                    dependent_inst,
                    arg,
                    !free_on_success,
                    !free_on_success,
                    !free_on_success,
                )?;
                if free_on_success {
                    state.ndis_packet_free_dependent_component_va = arg;
                }
                provider_packet
            }
            HostedProviderArgumentMarshal::CallerOutNdisPacket => {
                provider_marshal_output_ndis_packet(
                    &mut state,
                    dependent_index,
                    dependent_inst,
                    provider_shared,
                    arg,
                )?
            }
            HostedProviderArgumentMarshal::CallerOutNdisBuffer {
                virtual_address_arg,
                length_arg,
            } => {
                let virtual_address_index = virtual_address_arg as usize;
                let length_index = length_arg as usize;
                if virtual_address_index >= policy.argument_count as usize {
                    return Err(STATUS_INVALID_PARAMETER);
                }
                let length = provider_marshal_u32_arg(policy, args, length_index)?;
                let Some(provider_inst) = instance(provider_instance) else {
                    return Err(STATUS_DEVICE_NOT_READY);
                };
                let provider_arg = provider_marshal_output_ndis_buffer(
                    &mut state,
                    dependent_index,
                    dependent_inst,
                    provider_instance,
                    provider_inst,
                    provider_shared,
                    arg,
                    args[virtual_address_index],
                    length,
                )?;
                args[virtual_address_index] = state.ndis_buffer_out_provider_data_component_va;
                provider_arg
            }
            HostedProviderArgumentMarshal::CallerOutNdisBufferFromPacket => {
                provider_marshal_output_ndis_first_buffer(
                    &mut state,
                    dependent_index,
                    dependent_inst,
                    provider_shared,
                    arg,
                )?
            }
            HostedProviderArgumentMarshal::CallerOutNdisBufferVirtualAddress => {
                provider_marshal_output_ndis_first_buffer_va(
                    &mut state,
                    dependent_index,
                    dependent_inst,
                    provider_shared,
                    arg,
                )?
            }
            HostedProviderArgumentMarshal::CallerOutNdisConfigurationParameter => {
                provider_marshal_output_ndis_configuration_parameter(
                    &mut state,
                    dependent_index,
                    dependent_inst,
                    provider_shared,
                    arg,
                )?
            }
            HostedProviderArgumentMarshal::CallerOutNetworkAddress { length_arg } => {
                let length_index = length_arg as usize;
                if length_index >= policy.argument_count as usize {
                    return Err(STATUS_INVALID_PARAMETER);
                }
                let (provider_ptr_component_va, provider_len_component_va) =
                    provider_marshal_output_network_address(
                        &mut state,
                        dependent_index,
                        dependent_inst,
                        provider_shared,
                        arg,
                        args[length_index],
                    )?;
                args[length_index] = provider_len_component_va;
                provider_ptr_component_va
            }
            HostedProviderArgumentMarshal::CallerInOutRequest => provider_marshal_ndis_request(
                &mut state,
                dependent_index,
                dependent_inst,
                provider_shared,
                arg,
            )?,
            HostedProviderArgumentMarshal::CallerOutBuffer { length_arg } => {
                let length_index = length_arg as usize;
                provider_marshal_output_buffer(
                    &mut state,
                    dependent_index,
                    dependent_inst,
                    provider_shared,
                    arg,
                    provider_marshal_u32_arg(policy, args, length_index)?,
                )?
            }
            HostedProviderArgumentMarshal::CallerInMiniportCharacteristics { length_arg } => {
                let length_index = length_arg as usize;
                provider_marshal_miniport_characteristics(
                    &mut state,
                    provider_instance,
                    dependent_index,
                    dependent_inst,
                    provider_shared,
                    arg,
                    provider_marshal_u32_arg(policy, args, length_index)?,
                )?
            }
            HostedProviderArgumentMarshal::CallerInProtocolCharacteristics { length_arg } => {
                let length_index = length_arg as usize;
                provider_marshal_protocol_characteristics(
                    &mut state,
                    provider_instance,
                    dependent_index,
                    dependent_inst,
                    provider_shared,
                    arg,
                    provider_marshal_u32_arg(policy, args, length_index)?,
                )?
            }
            HostedProviderArgumentMarshal::CallerInOutResourceList { length_pointer_arg } => {
                let length_index = length_pointer_arg as usize;
                if length_index >= policy.argument_count as usize {
                    return Err(STATUS_INVALID_PARAMETER);
                }
                provider_marshal_resource_list(
                    &mut state,
                    dependent_index,
                    dependent_inst,
                    provider_shared,
                    arg,
                    args[length_index],
                )?
            }
            HostedProviderArgumentMarshal::CallerOutNdisDeviceProperty { kind } => {
                provider_marshal_ndis_device_property_output(
                    &mut state,
                    dependent_index,
                    dependent_inst,
                    provider_shared,
                    arg,
                    kind,
                )?
            }
            HostedProviderArgumentMarshal::CallerInOutMiniportInterrupt => {
                let Some(provider_inst) = instance(provider_instance) else {
                    return Err(STATUS_DEVICE_NOT_READY);
                };
                provider_marshal_miniport_interrupt(
                    &mut state,
                    provider_instance,
                    provider_inst,
                    dependent_index,
                    dependent_inst,
                    arg,
                    policy.side_effect
                        == HostedProviderExportSideEffect::NdisMiniportInterruptDeregistration,
                )?
            }
            HostedProviderArgumentMarshal::CallerInOutMiniportTimer { allow_create } => {
                let Some(provider_inst) = instance(provider_instance) else {
                    return Err(STATUS_DEVICE_NOT_READY);
                };
                provider_marshal_miniport_timer(
                    &mut state,
                    provider_instance,
                    provider_inst,
                    dependent_index,
                    dependent_inst,
                    arg,
                    allow_create,
                )?
            }
            HostedProviderArgumentMarshal::CallerInMiniportTimerFunction => {
                provider_marshal_miniport_timer_function(
                    &mut state,
                    provider_instance,
                    dependent_index,
                    arg,
                )?
            }
            HostedProviderArgumentMarshal::CallerInOutNdisWorkItem => {
                let Some(provider_inst) = instance(provider_instance) else {
                    return Err(STATUS_DEVICE_NOT_READY);
                };
                provider_marshal_ndis_work_item(
                    &mut state,
                    provider_instance,
                    provider_inst,
                    dependent_index,
                    dependent_inst,
                    arg,
                )?
            }
            HostedProviderArgumentMarshal::CallerOutIoPortRange {
                initial_port_arg,
                length_arg,
            } => {
                let initial_port_index = initial_port_arg as usize;
                let length_index = length_arg as usize;
                if initial_port_index >= policy.argument_count as usize
                    || length_index >= policy.argument_count as usize
                {
                    return Err(STATUS_INVALID_PARAMETER);
                }
                provider_marshal_io_port_range(
                    &mut state,
                    dependent_index,
                    dependent_inst,
                    provider_shared,
                    arg,
                    args[initial_port_index],
                    provider_marshal_u32_arg(policy, args, length_index)?,
                )?
            }
            HostedProviderArgumentMarshal::CallerOutMmioMapping {
                physical_address_arg,
                length_arg,
            } => {
                let physical_address_index = physical_address_arg as usize;
                let length_index = length_arg as usize;
                if physical_address_index >= policy.argument_count as usize
                    || length_index >= policy.argument_count as usize
                {
                    return Err(STATUS_INVALID_PARAMETER);
                }
                provider_marshal_mmio_mapping(
                    &mut state,
                    dependent_index,
                    dependent_inst,
                    provider_shared,
                    arg,
                    args[physical_address_index],
                    provider_marshal_u32_arg(policy, args, length_index)?,
                )?
            }
            HostedProviderArgumentMarshal::CallerOutDmaCommonBuffer { length_arg } => {
                let length_index = length_arg as usize;
                provider_marshal_output_dma_common_buffer(
                    &mut state,
                    dependent_index,
                    dependent_inst,
                    provider_shared,
                    arg,
                    provider_marshal_u32_arg(policy, args, length_index)?,
                )?
            }
            HostedProviderArgumentMarshal::CallerInDmaCommonBuffer {
                length_arg,
                physical_address_arg,
            } => {
                let length_index = length_arg as usize;
                let physical_address_index = physical_address_arg as usize;
                if length_index >= policy.argument_count as usize
                    || physical_address_index >= policy.argument_count as usize
                {
                    return Err(STATUS_INVALID_PARAMETER);
                }
                provider_marshal_input_dma_common_buffer(
                    &mut state,
                    dependent_inst,
                    arg,
                    provider_marshal_u32_arg(policy, args, length_index)?,
                    args[physical_address_index],
                )?
            }
            HostedProviderArgumentMarshal::CallerOutPointerFromLength { length_arg } => {
                let length_index = length_arg as usize;
                provider_marshal_output_pointer_from_length(
                    &mut state,
                    provider_instance,
                    dependent_index,
                    dependent_inst,
                    provider_shared,
                    arg,
                    provider_marshal_u32_arg(policy, args, length_index)?,
                )?
            }
            HostedProviderArgumentMarshal::CallerInPointerArray { count_arg } => {
                let count_index = count_arg as usize;
                let Some(provider_inst) = instance(provider_instance) else {
                    return Err(STATUS_DEVICE_NOT_READY);
                };
                provider_marshal_ndis_packet_array(
                    &mut state,
                    provider_instance,
                    provider_inst,
                    dependent_index,
                    dependent_inst,
                    provider_shared,
                    arg,
                    provider_marshal_u32_arg(policy, args, count_index)?,
                    false,
                )?
            }
            HostedProviderArgumentMarshal::CallerInOutPacketArray { count_arg } => {
                let count_index = count_arg as usize;
                let Some(provider_inst) = instance(provider_instance) else {
                    return Err(STATUS_DEVICE_NOT_READY);
                };
                if current_hosted_device_dispatch_binding(dependent_index).is_some() {
                    state.dma_state_copyback = true;
                }
                provider_marshal_ndis_packet_array(
                    &mut state,
                    provider_instance,
                    provider_inst,
                    dependent_index,
                    dependent_inst,
                    provider_shared,
                    arg,
                    provider_marshal_u32_arg(policy, args, count_index)?,
                    true,
                )?
            }
            _ => return Err(STATUS_NOT_SUPPORTED),
        };
        index += 1;
    }
    if policy.side_effect == HostedProviderExportSideEffect::NdisScatterGatherDmaInitialization {
        state.resource_projection_required = true;
        state.dma_state_copyback = true;
    }
    preparation_guard.disarm();
    Ok(state)
}

unsafe fn complete_provider_export_marshal(
    policy: HostedProviderExportMarshalPolicy,
    state: &ProviderMarshalState,
    provider_instance: usize,
    provider_inst: DriverInstance,
    result: &mut u64,
) {
    let mut success = provider_export_result_success(policy, *result);
    if state.pointer_allocation_dependent_component_va != 0 {
        let provider_component_va =
            read_unaligned(state.pointer_allocation_provider_output_exec_va as *const u64);
        let provider_pointer_valid = provider_component_va != 0
            && hosted_pool_allocation_exec_va(
                provider_inst.exec_pool_va,
                provider_component_va,
                state.pointer_allocation_bytes,
            )
            .is_some();
        if success
            && provider_pointer_valid
            && associate_hosted_provider_pointer_allocation(
                state.pointer_allocation_dependent_instance,
                state.pointer_allocation_dependent_component_va,
                provider_instance,
                provider_component_va,
            )
        {
            // The paired provider allocation is retained until the dependent calls
            // NdisFreeMemory. The fixed copyout below publishes only the dependent address.
        } else {
            if !release_hosted_provider_pointer_allocation_by_dependent(
                state.pointer_allocation_dependent_instance,
                state.pointer_allocation_dependent_component_va,
                if provider_pointer_valid {
                    provider_component_va
                } else {
                    0
                },
            ) {
                HOSTED_PROVIDER_POINTER_ALLOCATION_REJECTIONS.fetch_add(1, Ordering::Relaxed);
            }
            if success {
                *result = STATUS_INVALID_PARAMETER as u32 as u64;
                success = false;
            }
        }
    }
    if state.miniport_interrupt_construction_index != usize::MAX {
        if success {
            if !finish_hosted_provider_miniport_interrupt_construction(
                state.miniport_interrupt_construction_index,
            ) {
                retain_indeterminate_hosted_provider_miniport_interrupt_construction(
                    state.miniport_interrupt_construction_index,
                );
                *result = STATUS_DEVICE_NOT_READY as u32 as u64;
                success = false;
            }
        } else {
            retain_or_clear_failed_hosted_provider_miniport_interrupt_construction(
                state.miniport_interrupt_construction_index,
                *result as i32,
            );
        }
    }
    if state.miniport_timer_construction_index != usize::MAX {
        if success {
            if !finish_hosted_provider_miniport_timer_construction(
                state.miniport_timer_construction_index,
            ) {
                retain_indeterminate_hosted_provider_miniport_timer_construction(
                    state.miniport_timer_construction_index,
                );
                *result = STATUS_DEVICE_NOT_READY as u32 as u64;
                success = false;
            }
        } else {
            // A returned failure proves the provider call is no longer executing and cannot retain
            // an unpublished timer callback from a failed initialization.
            rollback_hosted_provider_miniport_timer_construction(
                state.miniport_timer_construction_index,
            );
        }
    }
    if state.ndis_work_item_construction_index != usize::MAX {
        if let Some(token) = state.ndis_work_item_schedule_token {
            if success {
                if !commit_hosted_provider_ndis_work_item_schedule(
                    state.ndis_work_item_construction_index,
                    token,
                    state.ndis_work_item_parent_constructing,
                ) {
                    retain_indeterminate_hosted_provider_ndis_work_item_schedule(
                        state.ndis_work_item_construction_index,
                        token,
                    );
                    *result = STATUS_DEVICE_NOT_READY as u32 as u64;
                    success = false;
                }
            } else {
                abort_hosted_provider_ndis_work_item_schedule(
                    state.ndis_work_item_construction_index,
                    token,
                    state.ndis_work_item_parent_constructing,
                );
            }
        } else {
            *result = STATUS_DEVICE_NOT_READY as u32 as u64;
            success = false;
        }
    }
    if state.callback_parent_construction_index != usize::MAX {
        let (registration_succeeded, provider_handle) = match policy.side_effect {
            HostedProviderExportSideEffect::NdisMiniportRegistration => (
                success && state.callback_parent_input_provider_handle != 0,
                state.callback_parent_input_provider_handle,
            ),
            HostedProviderExportSideEffect::NdisProtocolRegistration => {
                let status = if state.ndis_status_provider_exec_va == 0 {
                    STATUS_DEVICE_NOT_READY
                } else {
                    read_unaligned(state.ndis_status_provider_exec_va as *const i32)
                };
                let handle = if state.callback_parent_handle_exec_va == 0 {
                    0
                } else {
                    read_unaligned(state.callback_parent_handle_exec_va as *const u64)
                };
                (status == STATUS_SUCCESS && handle != 0, handle)
            }
            _ => (false, 0),
        };
        if registration_succeeded {
            if !finish_hosted_provider_callback_parent(
                state.callback_parent_construction_index,
                provider_handle,
            ) {
                retain_hosted_provider_callback_parent_compensation(
                    state.callback_parent_construction_index,
                    provider_handle,
                );
                if policy.side_effect == HostedProviderExportSideEffect::NdisProtocolRegistration
                    && state.ndis_status_provider_exec_va != 0
                {
                    write_unaligned(
                        state.ndis_status_provider_exec_va as *mut i32,
                        STATUS_DEVICE_NOT_READY,
                    );
                }
                *result = STATUS_DEVICE_NOT_READY as u32 as u64;
                success = false;
            }
        } else {
            rollback_hosted_provider_callback_parent(state.callback_parent_construction_index);
        }
    }
    let mut index = 0usize;
    while index < state.copyout_count {
        let copyout = state.copyouts[index];
        if copyout.fixed_bytes != 0 {
            let value = if success {
                copyout.fixed_success_value
            } else {
                copyout.fixed_failure_value
            };
            match copyout.fixed_bytes {
                4 => write_unaligned(copyout.provider_exec_va as *mut u32, value as u32),
                8 => write_unaligned(copyout.provider_exec_va as *mut u64, value),
                _ => {}
            }
        }
        copy_bytes(
            copyout.dependent_exec_va,
            copyout.provider_exec_va,
            copyout.bytes,
        );
        index += 1;
    }
    let mut free_index = 0usize;
    while free_index < state.deferred_free_count {
        let deferred = state.deferred_frees[free_index];
        let should_free = match deferred.condition {
            PROVIDER_MARSHAL_FREE_ALWAYS => true,
            PROVIDER_MARSHAL_FREE_ON_FAILURE => !success,
            _ => false,
        };
        let pointer_allocation_already_released = state.pointer_allocation_dependent_component_va
            != 0
            && deferred.dependent_instance == state.pointer_allocation_dependent_instance
            && deferred.component_va == state.pointer_allocation_dependent_component_va;
        if should_free && !pointer_allocation_already_released {
            if !release_hosted_provider_pointer_allocation_by_dependent(
                deferred.dependent_instance,
                deferred.component_va,
                0,
            ) {
                HOSTED_PROVIDER_POINTER_ALLOCATION_REJECTIONS.fetch_add(1, Ordering::Relaxed);
            }
        }
        free_index += 1;
    }
    if success
        && state.miniport_interrupt_free_on_success
        && state.miniport_interrupt_provider_component_va != 0
        && state.miniport_interrupt_provider_instance != usize::MAX
    {
        free_hosted_provider_miniport_interrupt_shadow(
            state.miniport_interrupt_provider_instance,
            state.miniport_interrupt_provider_component_va,
        );
    }
}

unsafe fn complete_hosted_provider_miniport_attributes(
    provider_instance: usize,
    provider_component_va: u64,
) -> Result<(), i32> {
    let Some(mirror) = hosted_provider_ndis_miniport_block_mirror_by_provider_component(
        provider_instance,
        provider_component_va,
    ) else {
        HOSTED_PROVIDER_NDIS_MINIPORT_BLOCK_MIRROR_REJECTIONS.fetch_add(1, Ordering::Relaxed);
        return Err(STATUS_INVALID_PARAMETER);
    };
    let Some(provider_inst) = instance(provider_instance) else {
        return Err(STATUS_DEVICE_NOT_READY);
    };
    let Some(dependent_inst) = instance(mirror.dependent_instance) else {
        return Err(STATUS_DEVICE_NOT_READY);
    };
    refresh_hosted_provider_ndis_miniport_block_mirror(provider_inst, dependent_inst, mirror)
}

unsafe fn complete_provider_export_side_effects(
    policy: HostedProviderExportMarshalPolicy,
    state: &ProviderMarshalState,
    provider_instance: usize,
    dependent_instance: usize,
    args: &[u64; HOSTED_PROVIDER_EXPORT_ARG_CAP],
    result: u64,
) -> Result<(), i32> {
    match policy.side_effect {
        HostedProviderExportSideEffect::None => Ok(()),
        HostedProviderExportSideEffect::NdisInitializeWrapper => {
            if state.ndis_route_index == usize::MAX {
                return Err(STATUS_INVALID_PARAMETER);
            }
            let provider_handle_exec = state.ndis_initialize_wrapper_handle_exec_va;
            if provider_handle_exec == 0 {
                return Err(STATUS_INVALID_PARAMETER);
            }
            let provider_wrapper_handle = read_unaligned(provider_handle_exec as *const u64);
            if provider_wrapper_handle == 0 {
                return Ok(());
            }
            set_hosted_provider_route_wrapper(state.ndis_route_index, provider_wrapper_handle)
        }
        HostedProviderExportSideEffect::NdisTerminateWrapper => {
            if retire_hosted_provider_callback_parent_by_handle(
                provider_instance,
                dependent_instance,
                HOSTED_PROVIDER_CALLBACK_PARENT_KIND_MINIPORT,
                state.callback_parent_input_provider_handle,
            ) {
                Ok(())
            } else {
                Err(STATUS_DEVICE_NOT_READY)
            }
        }
        HostedProviderExportSideEffect::NdisMiniportRegistration => {
            if result != STATUS_SUCCESS as u64 {
                return Ok(());
            }
            complete_hosted_provider_miniport_registration(provider_instance, args[0])
        }
        HostedProviderExportSideEffect::NdisMiniportAttributes => {
            complete_hosted_provider_miniport_attributes(provider_instance, args[0])
        }
        HostedProviderExportSideEffect::NdisProtocolRegistration => Ok(()),
        HostedProviderExportSideEffect::NdisProtocolDeregistration => {
            if state.ndis_status_provider_exec_va == 0
                || read_unaligned(state.ndis_status_provider_exec_va as *const i32)
                    != STATUS_SUCCESS
            {
                return Ok(());
            }
            if retire_hosted_provider_callback_parent_by_handle(
                provider_instance,
                dependent_instance,
                HOSTED_PROVIDER_CALLBACK_PARENT_KIND_PROTOCOL,
                state.callback_parent_input_provider_handle,
            ) {
                Ok(())
            } else {
                Err(STATUS_DEVICE_NOT_READY)
            }
        }
        HostedProviderExportSideEffect::NdisScatterGatherDmaInitialization => Ok(()),
        HostedProviderExportSideEffect::NdisMiniportInterruptDeregistration => Ok(()),
        HostedProviderExportSideEffect::NdisPacketFree => Ok(()),
    }
}

const PROVIDER_MMIO_MAPPING_STATE_OFFSETS: [u64; 2] =
    [SH_RESOURCE_MMIO_MAPPED_PHYS, SH_RESOURCE_MMIO_MAPPED_LEN];

const PROVIDER_DMA_PROJECTION_OFFSETS: [u64; 11] = [
    SH_DMA_COMMON_VA,
    SH_DMA_COMMON_LEN,
    SH_DMA_COMMON_LOGICAL,
    SH_DMA_ADAPTER_ID,
    SH_DMA_REQUESTED_LEN,
    SH_DMA_ALLOCATED_VA,
    SH_DMA_ALLOCATED_LOGICAL,
    SH_DMA_FREED_LOGICAL,
    SH_DMA_ALLOC_CURSOR,
    SH_DMA_ALLOC_RECORD_COUNT,
    SH_DMA_ALLOC_RECORD_CAPACITY,
];

const PROVIDER_INTERRUPT_STATE_OFFSETS: [u64; 7] = [
    SH_RESOURCE_INTERRUPT_OBJECT,
    SH_RESOURCE_INTERRUPT_ROUTINE,
    SH_RESOURCE_INTERRUPT_CONTEXT,
    SH_RESOURCE_INTERRUPT_ID,
    SH_RESOURCE_INTERRUPT_DELIVERED_VECTOR,
    SH_RESOURCE_INTERRUPT_ISR_CLAIMED,
    SH_RESOURCE_INTERRUPT_DELIVERIES,
];

unsafe fn copy_provider_interrupt_state(dst_shared: u64, src_shared: u64) {
    let mut index = 0usize;
    while index < PROVIDER_INTERRUPT_STATE_OFFSETS.len() {
        let offset = PROVIDER_INTERRUPT_STATE_OFFSETS[index];
        write_volatile(
            (dst_shared + offset) as *mut u64,
            read_volatile((src_shared + offset) as *const u64),
        );
        index += 1;
    }
}

unsafe fn copy_provider_dma_projection_fields(dst_shared: u64, src_shared: u64) {
    let mut index = 0usize;
    while index < PROVIDER_DMA_PROJECTION_OFFSETS.len() {
        let offset = PROVIDER_DMA_PROJECTION_OFFSETS[index];
        write_volatile(
            (dst_shared + offset) as *mut u64,
            read_volatile((src_shared + offset) as *const u64),
        );
        index += 1;
    }
}

unsafe fn copy_provider_mmio_mapping_state(dst_shared: u64, src_shared: u64) {
    let mut index = 0usize;
    while index < PROVIDER_MMIO_MAPPING_STATE_OFFSETS.len() {
        let offset = PROVIDER_MMIO_MAPPING_STATE_OFFSETS[index];
        write_volatile(
            (dst_shared + offset) as *mut u64,
            read_volatile((src_shared + offset) as *const u64),
        );
        index += 1;
    }
}

unsafe fn copy_provider_dma_allocation_records(dst_shared: u64, src_shared: u64) {
    copy_bytes(
        dst_shared + SH_DMA_ALLOC_RECORDS,
        src_shared + SH_DMA_ALLOC_RECORDS,
        SH_DMA_ALLOC_RECORD_LIMIT - SH_DMA_ALLOC_RECORDS,
    );
}

unsafe fn provider_dma_allocation_records_valid(sh: u64) -> bool {
    let record_capacity = dma_allocation_record_capacity(sh);
    let record_count = read_volatile((sh + SH_DMA_ALLOC_RECORD_COUNT) as *const u64);
    if record_capacity != dma_allocation_record_arena_capacity() || record_count > record_capacity {
        return false;
    }
    let grant_va = read_volatile((sh + SH_DMA_COMMON_VA) as *const u64);
    let grant_len = read_volatile((sh + SH_DMA_COMMON_LEN) as *const u64);
    let grant_logical = read_volatile((sh + SH_DMA_COMMON_LOGICAL) as *const u64);
    let adapter_id = read_volatile((sh + SH_DMA_ADAPTER_ID) as *const u64);
    let mut index = 0u64;
    while index < record_count {
        let Some(record) = dma_allocation_record(sh, index) else {
            return false;
        };
        let logical = read_volatile((record + SH_DMA_ALLOC_RECORD_LOGICAL) as *const u64);
        let len = read_volatile((record + SH_DMA_ALLOC_RECORD_LEN) as *const u64);
        let va = read_volatile((record + SH_DMA_ALLOC_RECORD_VA) as *const u64);
        let kind = read_volatile((record + SH_DMA_ALLOC_RECORD_KIND) as *const u64);
        if logical != 0 || len != 0 || va != 0 || kind != 0 {
            if adapter_id == 0
                || grant_va == 0
                || grant_len == 0
                || grant_logical == 0
                || len == 0
                || (kind != HOSTED_DMA_RECORD_KIND_COMMON
                    && kind != HOSTED_DMA_RECORD_KIND_MAP_TRANSFER)
            {
                return false;
            }
            if !dma_common_pointer_in_grant(sh, va, logical, len) {
                return false;
            }
            if kind == HOSTED_DMA_RECORD_KIND_MAP_TRANSFER {
                let source_va =
                    read_volatile((record + SH_DMA_ALLOC_RECORD_SOURCE_VA) as *const u64);
                let map_register =
                    read_volatile((record + SH_DMA_ALLOC_RECORD_MAP_REGISTER) as *const u64);
                if source_va == 0 || map_register == 0 {
                    return false;
                }
            }
        }
        index += 1;
    }
    true
}

unsafe fn project_provider_dma_state(
    dependent_shared: u64,
    provider_shared: u64,
) -> Result<(), i32> {
    if !provider_dma_allocation_records_valid(dependent_shared) {
        return Err(STATUS_INVALID_DEVICE_REQUEST);
    }
    copy_provider_dma_projection_fields(provider_shared, dependent_shared);
    copy_provider_dma_allocation_records(provider_shared, dependent_shared);
    write_volatile((provider_shared + SH_DMA_REQUESTED_LEN) as *mut u64, 0);
    write_volatile((provider_shared + SH_DMA_ALLOCATED_VA) as *mut u64, 0);
    write_volatile((provider_shared + SH_DMA_ALLOCATED_LOGICAL) as *mut u64, 0);
    write_volatile((provider_shared + SH_DMA_FREED_LOGICAL) as *mut u64, 0);
    Ok(())
}

unsafe fn project_provider_resource_state(
    binding: HostedDeviceBinding,
    dependent_shared: u64,
    provider_inst: DriverInstance,
    provider_shared: u64,
) -> Result<(), i32> {
    let state = hosted_device_resource_state_by_device_id(binding.device_id).unwrap_or_else(|| {
        read_hosted_device_resource_state_from_shared(binding, dependent_shared)
    });
    if state.driver_id != binding.driver_id || state.instance != binding.instance {
        return Err(STATUS_INVALID_DEVICE_REQUEST);
    }
    copy_hosted_io_port_caps_to_instance(provider_inst, state).map_err(|status| status.raw())?;
    write_hosted_resource_state_projection(provider_shared, state, false);
    copy_provider_mmio_mapping_state(provider_shared, dependent_shared);
    copy_provider_interrupt_state(provider_shared, dependent_shared);
    project_provider_dma_state(dependent_shared, provider_shared)?;
    Ok(())
}

fn provider_export_result_success(policy: HostedProviderExportMarshalPolicy, result: u64) -> bool {
    policy.result_semantics == HostedProviderExportResultSemantics::Void
        || result == STATUS_SUCCESS as u64
}

fn provider_policy_uses_packet_array(policy: HostedProviderExportMarshalPolicy) -> bool {
    let mut index = 0usize;
    while index < policy.argument_count as usize {
        if matches!(
            policy.args[index],
            HostedProviderArgumentMarshal::CallerInOutPacketArray { .. }
        ) {
            return true;
        }
        index += 1;
    }
    false
}

unsafe fn complete_provider_resource_mapping(
    policy: HostedProviderExportMarshalPolicy,
    state: &ProviderMarshalState,
    binding: Option<HostedDeviceBinding>,
    dependent_shared: u64,
    provider_shared: u64,
    result: u64,
) {
    if !provider_export_result_success(policy, result) {
        return;
    }
    if state.resource_mapping_copyback {
        copy_provider_mmio_mapping_state(dependent_shared, provider_shared);
    }
    if state.resource_state_copyback {
        copy_provider_interrupt_state(dependent_shared, provider_shared);
    }
    if state.resource_mapping_copyback || state.resource_state_copyback {
        if let Some(binding) = binding {
            refresh_hosted_device_resource_state(binding, dependent_shared);
        }
    }
}

unsafe fn complete_provider_dma_state(
    state: &ProviderMarshalState,
    binding: Option<HostedDeviceBinding>,
    dependent_shared: u64,
    provider_shared: u64,
) {
    if !state.dma_state_copyback {
        return;
    }
    if !provider_dma_allocation_records_valid(provider_shared) {
        print_str(b"[driver-import] provider DMA state rejected\n");
        return;
    }
    copy_provider_dma_projection_fields(dependent_shared, provider_shared);
    copy_provider_dma_allocation_records(dependent_shared, provider_shared);
    let Some(binding) = binding else {
        print_str(b"[driver-import] provider DMA state has no dependent binding\n");
        return;
    };
    if state.dma_free_logical != 0 {
        let freed = read_volatile((dependent_shared + SH_DMA_FREED_LOGICAL) as *const u64);
        if freed == state.dma_free_logical {
            match hosted_dma_manager_mut().free_common_buffer(
                hosted_dma_owner(binding),
                state.dma_free_logical,
                state.dma_free_len,
            ) {
                Ok(()) | Err(DmaError::StaleId) => {}
                Err(_) => {
                    print_str(b"[driver-import] provider DMA free rejected by manager\n");
                }
            }
        }
    }
    match replay_hosted_dma_allocation_records(binding, dependent_shared) {
        Ok(()) => refresh_hosted_device_resource_state(binding, dependent_shared),
        Err(status) => {
            print_str(b"[driver-import] provider DMA replay rejected status=0x");
            print_hex(status.0 as u32);
            print_str(b"\n");
        }
    }
}

unsafe fn copy_provider_dma_state_to_bound_dependent(
    binding: HostedDeviceBinding,
    dependent_shared: u64,
    provider_shared: u64,
) -> Result<(), i32> {
    if !provider_dma_allocation_records_valid(provider_shared) {
        return Err(STATUS_INVALID_DEVICE_REQUEST);
    }
    copy_provider_dma_projection_fields(dependent_shared, provider_shared);
    copy_provider_dma_allocation_records(dependent_shared, provider_shared);
    replay_hosted_dma_allocation_records(binding, dependent_shared)
        .map_err(|status| status.raw())?;
    refresh_hosted_device_resource_state(binding, dependent_shared);
    Ok(())
}

fn provider_policy_resource_list_args(
    policy: HostedProviderExportMarshalPolicy,
) -> Option<(usize, usize)> {
    let mut index = 0usize;
    while index < policy.argument_count as usize {
        if let HostedProviderArgumentMarshal::CallerInOutResourceList { length_pointer_arg } =
            policy.args[index]
        {
            return Some((index, length_pointer_arg as usize));
        }
        index += 1;
    }
    None
}

fn provider_policy_io_port_range_args(
    policy: HostedProviderExportMarshalPolicy,
) -> Option<(usize, usize, usize)> {
    let mut index = 0usize;
    while index < policy.argument_count as usize {
        if let HostedProviderArgumentMarshal::CallerOutIoPortRange {
            initial_port_arg,
            length_arg,
        } = policy.args[index]
        {
            return Some((index, initial_port_arg as usize, length_arg as usize));
        }
        index += 1;
    }
    None
}

fn provider_policy_status_arg(policy: HostedProviderExportMarshalPolicy) -> Option<usize> {
    let mut index = 0usize;
    while index < policy.argument_count as usize {
        if policy.args[index] == HostedProviderArgumentMarshal::CallerOutStatus {
            return Some(index);
        }
        index += 1;
    }
    None
}

unsafe fn read_provider_arg_u32(
    instance_index: usize,
    inst: DriverInstance,
    component_va: u64,
) -> Option<u32> {
    component_to_exec_va_for_instance(instance_index, inst, component_va, 4)
        .map(|exec_va| read_unaligned(exec_va as *const u32))
}

unsafe fn read_provider_arg_u64(
    instance_index: usize,
    inst: DriverInstance,
    component_va: u64,
) -> Option<u64> {
    component_to_exec_va_for_instance(instance_index, inst, component_va, 8)
        .map(|exec_va| read_unaligned(exec_va as *const u64))
}

#[derive(Clone, Copy)]
struct ProviderResourceDescriptorTrace {
    kind: u8,
    share: u8,
    flags: u16,
    field0: u64,
    field1: u32,
    field2: u64,
}

unsafe fn read_provider_resource_descriptor_trace(
    instance_index: usize,
    inst: DriverInstance,
    list_component_va: u64,
    descriptor_index: u32,
) -> Option<ProviderResourceDescriptorTrace> {
    let offset = 8u64.checked_add((descriptor_index as u64).checked_mul(20)?)?;
    let exec_va =
        component_to_exec_va_for_instance(instance_index, inst, list_component_va + offset, 20)?;
    let kind = read_unaligned(exec_va as *const u8);
    let share = read_unaligned((exec_va + 1) as *const u8);
    let flags = read_unaligned((exec_va + 2) as *const u16);
    let (field0, field1, field2) = match kind {
        2 => (
            read_unaligned((exec_va + 4) as *const u32) as u64,
            read_unaligned((exec_va + 8) as *const u32),
            read_unaligned((exec_va + 12) as *const u64),
        ),
        _ => (
            read_unaligned((exec_va + 4) as *const u64),
            read_unaligned((exec_va + 12) as *const u32),
            0,
        ),
    };
    Some(ProviderResourceDescriptorTrace {
        kind,
        share,
        flags,
        field0,
        field1,
        field2,
    })
}

fn print_provider_resource_descriptor_trace(desc: Option<ProviderResourceDescriptorTrace>) {
    if let Some(desc) = desc {
        print_u64(desc.kind as u64);
        print_str(b"/");
        print_u64(desc.share as u64);
        print_str(b"/0x");
        print_hex(desc.flags as u32);
        print_str(b"/0x");
        print_hex((desc.field0 >> 32) as u32);
        print_hex(desc.field0 as u32);
        print_str(b"/");
        print_u64(desc.field1 as u64);
        print_str(b"/0x");
        print_hex((desc.field2 >> 32) as u32);
        print_hex(desc.field2 as u32);
    } else {
        print_str(b"none");
    }
}

#[allow(clippy::too_many_arguments)]
unsafe fn trace_provider_resource_list_export(
    policy: HostedProviderExportMarshalPolicy,
    provider_export_rva: u64,
    provider_index: usize,
    provider_inst: DriverInstance,
    dependent_index: usize,
    dependent_inst: DriverInstance,
    original_args: &[u64; HOSTED_PROVIDER_EXPORT_ARG_CAP],
    marshalled_args: &[u64; HOSTED_PROVIDER_EXPORT_ARG_CAP],
    result: u64,
) {
    let Some((list_index, length_index)) = provider_policy_resource_list_args(policy) else {
        return;
    };
    if length_index >= policy.argument_count as usize
        || list_index >= policy.argument_count as usize
    {
        return;
    }
    let trace = PROVIDER_RESOURCE_LIST_TRACE_COUNT.fetch_add(1, Ordering::Relaxed);
    if trace >= PROVIDER_RESOURCE_LIST_TRACE_CAP {
        return;
    }

    let status_index = provider_policy_status_arg(policy);
    let dependent_status = status_index
        .and_then(|index| {
            read_provider_arg_u32(dependent_index, dependent_inst, original_args[index])
        })
        .unwrap_or(u32::MAX);
    let provider_status = status_index
        .and_then(|index| {
            read_provider_arg_u32(provider_index, provider_inst, marshalled_args[index])
        })
        .unwrap_or(u32::MAX);
    let dependent_len =
        read_provider_arg_u32(dependent_index, dependent_inst, original_args[length_index])
            .unwrap_or(u32::MAX);
    let provider_len =
        read_provider_arg_u32(provider_index, provider_inst, marshalled_args[length_index])
            .unwrap_or(u32::MAX);
    let list_component_va = original_args[list_index];
    let (version, revision, count) = if list_component_va == 0 {
        (0xffffu16, 0xffffu16, u32::MAX)
    } else if let Some(list_exec) =
        component_to_exec_va_for_instance(dependent_index, dependent_inst, list_component_va, 8)
    {
        (
            read_unaligned(list_exec as *const u16),
            read_unaligned((list_exec + 2) as *const u16),
            read_unaligned((list_exec + 4) as *const u32),
        )
    } else {
        (0xffffu16, 0xffffu16, u32::MAX)
    };
    let desc0 = if count > 0 && count != u32::MAX {
        read_provider_resource_descriptor_trace(
            dependent_index,
            dependent_inst,
            list_component_va,
            0,
        )
    } else {
        None
    };
    let desc1 = if count > 1 && count != u32::MAX {
        read_provider_resource_descriptor_trace(
            dependent_index,
            dependent_inst,
            list_component_va,
            1,
        )
    } else {
        None
    };
    let desc2 = if count > 2 && count != u32::MAX {
        read_provider_resource_descriptor_trace(
            dependent_index,
            dependent_inst,
            list_component_va,
            2,
        )
    } else {
        None
    };

    print_str(b"[driver-import] provider resource-list export rva=0x");
    print_hex(provider_export_rva as u32);
    print_str(b" result=0x");
    print_hex((result >> 32) as u32);
    print_hex(result as u32);
    print_str(b" status dep/prov=0x");
    print_hex(dependent_status);
    print_str(b"/0x");
    print_hex(provider_status);
    print_str(b" len dep/prov=");
    print_u64(dependent_len as u64);
    print_str(b"/");
    print_u64(provider_len as u64);
    print_str(b" list=0x");
    print_hex((list_component_va >> 32) as u32);
    print_hex(list_component_va as u32);
    print_str(b" v/r/count=");
    print_u64(version as u64);
    print_str(b"/");
    print_u64(revision as u64);
    print_str(b"/");
    print_u64(count as u64);
    print_str(b" desc0=");
    print_provider_resource_descriptor_trace(desc0);
    print_str(b" desc1=");
    print_provider_resource_descriptor_trace(desc1);
    print_str(b" desc2=");
    print_provider_resource_descriptor_trace(desc2);
    print_str(b"\n");
}

#[allow(clippy::too_many_arguments)]
unsafe fn trace_provider_io_port_range_export(
    policy: HostedProviderExportMarshalPolicy,
    provider_export_rva: u64,
    provider_index: usize,
    provider_inst: DriverInstance,
    dependent_index: usize,
    dependent_inst: DriverInstance,
    original_args: &[u64; HOSTED_PROVIDER_EXPORT_ARG_CAP],
    marshalled_args: &[u64; HOSTED_PROVIDER_EXPORT_ARG_CAP],
    result: u64,
) {
    let Some((out_index, initial_index, length_index)) = provider_policy_io_port_range_args(policy)
    else {
        return;
    };
    if out_index >= policy.argument_count as usize
        || initial_index >= policy.argument_count as usize
        || length_index >= policy.argument_count as usize
    {
        return;
    }
    let trace = PROVIDER_IO_PORT_RANGE_TRACE_COUNT.fetch_add(1, Ordering::Relaxed);
    if trace >= PROVIDER_IO_PORT_RANGE_TRACE_CAP {
        return;
    }

    let requested_start = original_args[initial_index] & u32::MAX as u64;
    let requested_len = original_args[length_index] & u32::MAX as u64;
    let dependent_out =
        read_provider_arg_u64(dependent_index, dependent_inst, original_args[out_index])
            .unwrap_or(u64::MAX);
    let provider_out =
        read_provider_arg_u64(provider_index, provider_inst, marshalled_args[out_index])
            .unwrap_or(u64::MAX);
    let dependent_sh = dependent_inst.exec_shared_va;
    let provider_sh = provider_inst.exec_shared_va;
    let dependent_resource =
        first_shared_address_resource(dependent_sh, SH_RESOURCE_ADDRESS_KIND_PORT)
            .unwrap_or_default();
    let provider_resource =
        first_shared_address_resource(provider_sh, SH_RESOURCE_ADDRESS_KIND_PORT)
            .unwrap_or_default();

    print_str(b"[driver-import] provider io-port export rva=0x");
    print_hex(provider_export_rva as u32);
    print_str(b" result=0x");
    print_hex((result >> 32) as u32);
    print_hex(result as u32);
    print_str(b" success=");
    print_u64(provider_export_result_success(policy, result) as u64);
    print_str(b" request=0x");
    print_hex64(requested_start);
    print_str(b"/");
    print_u64(requested_len);
    print_str(b" out dep/prov=0x");
    print_hex64(dependent_out);
    print_str(b"/0x");
    print_hex64(provider_out);
    print_str(b" grant dep=0x");
    print_hex64(dependent_resource.translated_start);
    print_str(b"/");
    print_u64(dependent_resource.len);
    print_str(b" prov=0x");
    print_hex64(provider_resource.translated_start);
    print_str(b"/");
    print_u64(provider_resource.len);
    print_str(b" prov-cap=");
    print_u64(provider_resource.component_cap);
    print_str(b"\n");
}

struct HostedComponentPumpDepthGuard;

impl HostedComponentPumpDepthGuard {
    fn enter() -> Self {
        HOSTED_COMPONENT_PUMP_DEPTH.fetch_add(1, Ordering::AcqRel);
        Self
    }
}

impl Drop for HostedComponentPumpDepthGuard {
    fn drop(&mut self) {
        let previous = HOSTED_COMPONENT_PUMP_DEPTH.fetch_sub(1, Ordering::Release);
        assert!(previous != 0, "hosted component pump depth underflow");
    }
}

unsafe fn hosted_component_pump(
    ch: &crate::spawn_hosts::PumpChannel,
) -> crate::spawn_hosts::PumpResult {
    let _depth = HostedComponentPumpDepthGuard::enter();
    crate::spawn_hosts::component_pump(ch)
}

pub(crate) unsafe fn service_hosted_provider_export(
    dependent_channel: &crate::spawn_hosts::PumpChannel,
    provider_export_rva: u64,
    provider_publication_cookie: u64,
    arg0: u64,
    arg1: u64,
) -> u64 {
    HOSTED_PROVIDER_EXPORT_REQUESTS.fetch_add(1, Ordering::Relaxed);
    let arg2 = read_volatile((dependent_channel.shared_va + SH_PROVIDER_EXPORT_ARG2) as *const u64);
    let arg3 = read_volatile((dependent_channel.shared_va + SH_PROVIDER_EXPORT_ARG3) as *const u64);
    let caller_rsp =
        read_volatile((dependent_channel.shared_va + SH_PROVIDER_EXPORT_CALLER_RSP) as *const u64);
    let Some((_singleton_index, singleton)) =
        find_hosted_provider_singleton_by_cookie(provider_publication_cookie)
    else {
        return hosted_provider_export_failure(STATUS_DEVICE_NOT_READY);
    };
    let descriptor = hosted_provider_domain_descriptor(singleton);
    let Some(policy) = loaded_pe_export_rva_marshal_policy(
        singleton.provider.as_str(),
        singleton.exec_va,
        singleton.image_len,
        provider_export_rva,
    )
    .or_else(|| hosted_provider_internal_rva_marshal_policy(singleton, provider_export_rva)) else {
        return hosted_provider_export_failure(STATUS_NOT_SUPPORTED);
    };
    let packet_array_export = provider_policy_uses_packet_array(policy);
    if packet_array_export {
        HOSTED_PROVIDER_PACKET_ARRAY_EXPORT_REQUESTS.fetch_add(1, Ordering::Relaxed);
    }
    let (
        packet_array_protocol_receive_requests_before,
        packet_array_protocol_receive_completions_before,
        packet_array_protocol_receive_packet_requests_before,
        packet_array_protocol_receive_packet_completions_before,
    ) = if packet_array_export {
        (
            HOSTED_PROVIDER_PROTOCOL_RECEIVE_REQUESTS.load(Ordering::Relaxed),
            HOSTED_PROVIDER_PROTOCOL_RECEIVE_COMPLETIONS.load(Ordering::Relaxed),
            HOSTED_PROVIDER_PROTOCOL_RECEIVE_PACKET_REQUESTS.load(Ordering::Relaxed),
            HOSTED_PROVIDER_PROTOCOL_RECEIVE_PACKET_COMPLETIONS.load(Ordering::Relaxed),
        )
    } else {
        (0, 0, 0, 0)
    };
    match plan_hosted_provider_import_binding(Some(descriptor), provider_export_rva) {
        Ok(HostedProviderImportBinding::ProviderDomainCall(_plan)) => {}
        Ok(HostedProviderImportBinding::PrivateDependencyRequired) => {
            return hosted_provider_export_failure(STATUS_DEVICE_NOT_READY)
        }
        Err(_) => return hosted_provider_export_failure(STATUS_INVALID_PARAMETER),
    }
    let Some((dependent_index, dependent_inst)) =
        instance_by_shared_va(dependent_channel.shared_va)
    else {
        return hosted_provider_export_failure(STATUS_DEVICE_NOT_READY);
    };
    if dependent_index == singleton.instance {
        return hosted_provider_export_failure(STATUS_INVALID_PARAMETER);
    }
    let Some(provider_inst) = instance(singleton.instance) else {
        return hosted_provider_export_failure(STATUS_DEVICE_NOT_READY);
    };
    if provider_inst.fault_ep == 0
        || provider_inst.pml4 == 0
        || provider_inst.reply_cap == 0
        || provider_inst.driver_object == 0
    {
        return hosted_provider_export_failure(STATUS_DEVICE_NOT_READY);
    }
    if let Err(status) = ensure_hosted_provider_domain_dependency(
        singleton.instance,
        singleton.provider_publication_cookie,
        dependent_index,
    ) {
        trace_hosted_provider_export_rejection(
            &singleton.provider,
            provider_publication_cookie,
            provider_export_rva,
            status,
            b"dependency",
        );
        return hosted_provider_export_failure(status);
    }
    let Some(_dependency_lease) = acquire_hosted_provider_dependency_dispatch_lease(
        singleton.instance,
        dependent_index,
        singleton.provider_publication_cookie,
    ) else {
        return hosted_provider_export_failure(STATUS_DEVICE_NOT_READY);
    };
    let Some(exec_code_va) =
        ExecVaWindow::try_for_instance(singleton.instance).map(|win| win.code_va)
    else {
        return hosted_provider_export_failure(STATUS_DEVICE_NOT_READY);
    };
    let provider_shared = provider_inst.exec_shared_va;

    let mut args = [0u64; HOSTED_PROVIDER_EXPORT_ARG_CAP];
    args[0] = arg0;
    args[1] = arg1;
    args[2] = arg2;
    args[3] = arg3;
    let mut stack_index = 0u64;
    while stack_index < SH_PROVIDER_EXPORT_STACK_QWORDS {
        args[4 + stack_index as usize] = read_volatile(
            (dependent_channel.shared_va + SH_PROVIDER_EXPORT_STACK_BASE + stack_index * 8)
                as *const u64,
        );
        stack_index += 1;
    }
    let original_args = args;
    trace_hosted_provider_export_frame(
        b"enter",
        provider_export_rva,
        dependent_index,
        dependent_inst,
        caller_rsp,
    );
    trace_hosted_provider_export(
        b"enter",
        &singleton.provider,
        provider_publication_cookie,
        provider_export_rva,
        &args,
        0,
    );
    let dependent_binding = current_hosted_device_dispatch_binding(dependent_index)
        .and_then(|binding| hosted_resource_binding_by_device_id(binding.device_id));
    let marshal_state = match prepare_provider_export_marshal(
        policy,
        singleton.instance,
        singleton.provider_publication_cookie,
        dependent_index,
        dependent_inst,
        provider_shared,
        &mut args,
    ) {
        Ok(state) => state,
        Err(status) => {
            trace_hosted_provider_export_rejection(
                &singleton.provider,
                provider_publication_cookie,
                provider_export_rva,
                status,
                b"marshal",
            );
            return hosted_provider_export_failure(status);
        }
    };

    if let Some(binding) = dependent_binding {
        if let Err(status) = project_provider_resource_state(
            binding,
            dependent_channel.shared_va,
            provider_inst,
            provider_shared,
        ) {
            trace_hosted_provider_export_rejection(
                &singleton.provider,
                provider_publication_cookie,
                provider_export_rva,
                status,
                b"resource",
            );
            abort_provider_export_marshal_before_dispatch(&marshal_state);
            return hosted_provider_export_failure(status);
        }
    } else if marshal_state.resource_projection_required {
        trace_hosted_provider_export_rejection(
            &singleton.provider,
            provider_publication_cookie,
            provider_export_rva,
            STATUS_INVALID_DEVICE_REQUEST,
            b"resource-required",
        );
        abort_provider_export_marshal_before_dispatch(&marshal_state);
        return hosted_provider_export_failure(STATUS_INVALID_DEVICE_REQUEST);
    }
    write_volatile(
        (provider_shared + SH_REQ_MAJOR) as *mut u64,
        FSD_DISPATCH_PROVIDER_EXPORT,
    );
    write_volatile(
        (provider_shared + SH_REQ_MINOR) as *mut u64,
        provider_export_rva,
    );
    write_volatile((provider_shared + SH_REQ_FSCTL) as *mut u64, args[0]);
    write_volatile((provider_shared + SH_REQ_INLEN) as *mut u64, args[1]);
    write_volatile((provider_shared + SH_REQ_OUTLEN) as *mut u64, args[2]);
    write_volatile((provider_shared + SH_REQ_FILEID) as *mut u64, args[3]);
    write_volatile(
        (provider_shared + SH_PROVIDER_EXPORT_CALLER_RSP) as *mut u64,
        caller_rsp,
    );
    stack_index = 0;
    while stack_index < SH_PROVIDER_EXPORT_STACK_QWORDS {
        write_volatile(
            (provider_shared + SH_PROVIDER_EXPORT_STACK_BASE + stack_index * 8) as *mut u64,
            args[4 + stack_index as usize],
        );
        stack_index += 1;
    }
    write_volatile((provider_shared + SH_REQ_STATUS) as *mut i32, 0);
    write_volatile((provider_shared + SH_REQ_INFO) as *mut u64, 0);
    write_volatile((provider_shared + SH_ACTIVE_IRP) as *mut u64, 0);
    write_volatile((provider_shared + SH_ACTIVE_IOSL) as *mut u64, 0);
    write_volatile((provider_shared + SH_ACTIVE_DATA) as *mut u64, 0);
    write_volatile((provider_shared + SH_ACTIVE_DATA_CAP) as *mut u64, 0);
    write_volatile((provider_shared + SH_ACTIVE_FILE_OBJECT) as *mut u64, 0);

    let image_frames = if provider_inst.image_frames == 0 {
        singleton.image_frames
    } else {
        provider_inst.image_frames
    };
    let ch = crate::spawn_hosts::PumpChannel {
        fault_ep: provider_inst.fault_ep,
        pml4: provider_inst.pml4,
        code_va: 0,
        image_frames: 0,
        exec_code_va,
        root_image_rights: 3,
        root_image_map_owner: provider_inst.map_cap_bank.owner,
        shared_va: provider_shared,
        dispatch_label: FSD_DISPATCH_LABEL,
        demand_cap: 256,
        trace_faults: false,
        initial: crate::spawn_hosts::InitialAction::ReplyRequest,
        tcb: provider_inst.tcb,
        reply_cap: provider_inst.reply_cap,
        client_pi: 0,
        caps: crate::spawn_hosts::HostCaps {
            dispatch_server: true,
            kind: crate::spawn_hosts::ReqKind::Irp,
            io_port_faults: shared_has_port_resources(provider_shared),
            ..crate::spawn_hosts::HostCaps::default()
        },
    };
    let pr = hosted_component_pump(&ch);
    if !pr.completed {
        let trace = HOSTED_PROVIDER_EXPORT_INCOMPLETE_TRACE_COUNT.fetch_add(1, Ordering::Relaxed);
        if trace < HOSTED_PROVIDER_EXPORT_INCOMPLETE_TRACE_CAP {
            print_str(b"[provider-export] incomplete provider=");
            print_str(singleton.provider.as_bytes());
            print_str(b" cookie=");
            print_u64(provider_publication_cookie);
            print_str(b" rva=0x");
            print_hex(provider_export_rva as u32);
            print_str(b" status=0x");
            print_hex(pr.status as u32);
            print_str(b" result=");
            print_hex64(pr.result);
            print_str(b" wall-ip=");
            print_hex64(pr.wall_ip);
            print_str(b" wall-addr=");
            print_hex64(pr.wall_addr);
            print_str(b" wall-label=");
            print_hex64(pr.wall_label);
            print_str(b" wall-flags=");
            print_hex64(pr.wall_flags);
            print_str(b" tcb=");
            print_hex64(provider_inst.tcb);
            print_str(b"\n");
        }
        register_instance_ready(singleton.instance, false);
        trace_hosted_provider_export_rejection(
            &singleton.provider,
            provider_publication_cookie,
            provider_export_rva,
            STATUS_UNSUCCESSFUL,
            b"pump",
        );
        abort_provider_export_marshal_after_possible_dispatch(&marshal_state);
        return hosted_provider_export_failure(STATUS_UNSUCCESSFUL);
    }
    let provider_inst = instance(singleton.instance).unwrap_or(provider_inst);
    let mut result = read_volatile((provider_shared + SH_REQ_INFO) as *const u64);
    if let Err(status) = complete_provider_export_side_effects(
        policy,
        &marshal_state,
        singleton.instance,
        dependent_index,
        &args,
        result,
    ) {
        print_str(b"[driver-import] provider side effect failed cookie=");
        print_u64(provider_publication_cookie);
        print_str(b" status=0x");
        print_hex(status as u32);
        print_str(b"\n");
        if policy.side_effect == HostedProviderExportSideEffect::NdisMiniportRegistration
            && result == STATUS_SUCCESS as u64
        {
            result = status as u32 as u64;
        }
        if policy.side_effect == HostedProviderExportSideEffect::NdisProtocolDeregistration
            && marshal_state.ndis_status_provider_exec_va != 0
        {
            write_unaligned(
                marshal_state.ndis_status_provider_exec_va as *mut i32,
                status,
            );
        }
    }
    complete_provider_dma_state(
        &marshal_state,
        dependent_binding,
        dependent_channel.shared_va,
        provider_shared,
    );
    complete_provider_ndis_object_shadows(
        &marshal_state,
        singleton.instance,
        provider_inst,
        dependent_index,
        dependent_inst,
        dependent_binding,
    );
    complete_provider_export_marshal(
        policy,
        &marshal_state,
        singleton.instance,
        provider_inst,
        &mut result,
    );
    trace_provider_resource_list_export(
        policy,
        provider_export_rva,
        singleton.instance,
        provider_inst,
        dependent_index,
        dependent_inst,
        &original_args,
        &args,
        result,
    );
    trace_provider_io_port_range_export(
        policy,
        provider_export_rva,
        singleton.instance,
        provider_inst,
        dependent_index,
        dependent_inst,
        &original_args,
        &args,
        result,
    );
    complete_provider_resource_mapping(
        policy,
        &marshal_state,
        dependent_binding,
        dependent_channel.shared_va,
        provider_shared,
        result,
    );
    HOSTED_PROVIDER_EXPORT_COMPLETIONS.fetch_add(1, Ordering::Relaxed);
    if packet_array_export {
        HOSTED_PROVIDER_PACKET_ARRAY_EXPORT_COMPLETIONS.fetch_add(1, Ordering::Relaxed);
        HOSTED_PROVIDER_PACKET_ARRAY_PROTOCOL_RECEIVE_REQUESTS.fetch_add(
            HOSTED_PROVIDER_PROTOCOL_RECEIVE_REQUESTS
                .load(Ordering::Relaxed)
                .saturating_sub(packet_array_protocol_receive_requests_before),
            Ordering::Relaxed,
        );
        HOSTED_PROVIDER_PACKET_ARRAY_PROTOCOL_RECEIVE_COMPLETIONS.fetch_add(
            HOSTED_PROVIDER_PROTOCOL_RECEIVE_COMPLETIONS
                .load(Ordering::Relaxed)
                .saturating_sub(packet_array_protocol_receive_completions_before),
            Ordering::Relaxed,
        );
        HOSTED_PROVIDER_PACKET_ARRAY_PROTOCOL_RECEIVE_PACKET_REQUESTS.fetch_add(
            HOSTED_PROVIDER_PROTOCOL_RECEIVE_PACKET_REQUESTS
                .load(Ordering::Relaxed)
                .saturating_sub(packet_array_protocol_receive_packet_requests_before),
            Ordering::Relaxed,
        );
        HOSTED_PROVIDER_PACKET_ARRAY_PROTOCOL_RECEIVE_PACKET_COMPLETIONS.fetch_add(
            HOSTED_PROVIDER_PROTOCOL_RECEIVE_PACKET_COMPLETIONS
                .load(Ordering::Relaxed)
                .saturating_sub(packet_array_protocol_receive_packet_completions_before),
            Ordering::Relaxed,
        );
    }
    trace_hosted_provider_export(
        b"done",
        &singleton.provider,
        provider_publication_cookie,
        provider_export_rva,
        &args,
        result,
    );
    trace_hosted_provider_export_frame(
        b"done",
        provider_export_rva,
        dependent_index,
        dependent_inst,
        caller_rsp,
    );
    if DEBUG_TRACE && HOSTED_PROVIDER_EXPORT_COMPLETIONS.load(Ordering::Relaxed) <= 8 {
        print_str(b"[driver-import] provider-domain export dispatched cookie=");
        print_u64(provider_publication_cookie);
        print_str(b" rva=0x");
        print_hex(provider_export_rva as u32);
        print_str(b" result=0x");
        print_hex((result >> 32) as u32);
        print_hex(result as u32);
        print_str(b" frames=");
        print_u64(image_frames);
        print_str(b"\n");
    }
    result
}

#[derive(Clone, Copy)]
enum HostedComponentDispatchError {
    Status(i32),
    Wall(crate::spawn_hosts::PumpResult),
}

unsafe fn dispatch_hosted_component_target(
    instance_index: usize,
    inst: DriverInstance,
    exec_code_va: u64,
    target: u64,
    args: [u64; 4],
    stack_args: [u64; PROVIDER_CALLBACK_STACK_QWORDS],
) -> Result<u64, HostedComponentDispatchError> {
    let inst = instance(instance_index).unwrap_or(inst);
    let shared = inst.exec_shared_va;
    write_volatile(
        (shared + SH_REQ_MAJOR) as *mut u64,
        FSD_DISPATCH_PROVIDER_CALLBACK,
    );
    write_volatile((shared + SH_REQ_MINOR) as *mut u64, target);
    write_volatile((shared + SH_REQ_FSCTL) as *mut u64, args[0]);
    write_volatile((shared + SH_REQ_INLEN) as *mut u64, args[1]);
    write_volatile((shared + SH_REQ_OUTLEN) as *mut u64, args[2]);
    write_volatile((shared + SH_REQ_FILEID) as *mut u64, args[3]);
    let mut stack_index = 0usize;
    while stack_index < PROVIDER_CALLBACK_STACK_QWORDS {
        write_volatile(
            (shared + SH_PROVIDER_EXPORT_STACK_BASE + stack_index as u64 * 8) as *mut u64,
            stack_args[stack_index],
        );
        stack_index += 1;
    }
    write_volatile((shared + SH_PROVIDER_EXPORT_CALLER_RSP) as *mut u64, 0);
    write_volatile((shared + SH_REQ_STATUS) as *mut i32, 0);
    write_volatile((shared + SH_REQ_INFO) as *mut u64, 0);
    write_volatile((shared + SH_ACTIVE_IRP) as *mut u64, 0);
    write_volatile((shared + SH_ACTIVE_IOSL) as *mut u64, 0);
    write_volatile((shared + SH_ACTIVE_DATA) as *mut u64, 0);
    write_volatile((shared + SH_ACTIVE_DATA_CAP) as *mut u64, 0);
    write_volatile((shared + SH_ACTIVE_FILE_OBJECT) as *mut u64, 0);

    let ch = crate::spawn_hosts::PumpChannel {
        fault_ep: inst.fault_ep,
        pml4: inst.pml4,
        code_va: 0,
        image_frames: 0,
        exec_code_va,
        root_image_rights: 3,
        root_image_map_owner: inst.map_cap_bank.owner,
        shared_va: shared,
        dispatch_label: FSD_DISPATCH_LABEL,
        demand_cap: 256,
        trace_faults: false,
        initial: crate::spawn_hosts::InitialAction::ReplyRequest,
        tcb: inst.tcb,
        reply_cap: inst.reply_cap,
        client_pi: 0,
        caps: crate::spawn_hosts::HostCaps {
            dispatch_server: true,
            kind: crate::spawn_hosts::ReqKind::Irp,
            io_port_faults: shared_has_port_resources(shared),
            ..crate::spawn_hosts::HostCaps::default()
        },
    };
    let pr = hosted_component_pump(&ch);
    if !pr.completed {
        register_instance_ready(instance_index, false);
        return Err(HostedComponentDispatchError::Wall(pr));
    }
    let dispatch_status = read_volatile((shared + SH_REQ_STATUS) as *const i32);
    if dispatch_status != STATUS_SUCCESS {
        return Err(HostedComponentDispatchError::Status(dispatch_status));
    }
    Ok(read_volatile((shared + SH_REQ_INFO) as *const u64))
}

unsafe fn dispatch_dependent_provider_callback(
    record: HostedProviderCallbackRecord,
    dependent_inst: DriverInstance,
    exec_code_va: u64,
    args: [u64; 4],
    stack_args: [u64; PROVIDER_CALLBACK_STACK_QWORDS],
) -> Result<u64, i32> {
    let dependent_shared = dependent_inst.exec_shared_va;
    let dependent_binding = current_hosted_device_dispatch_binding(record.dependent_instance)
        .and_then(|binding| hosted_resource_binding_by_device_id(binding.device_id));
    if let Some(binding) = dependent_binding {
        restore_hosted_device_resource_state(binding, dependent_shared, false)
            .map_err(|status| status.raw())?;
    }
    match dispatch_hosted_component_target(
        record.dependent_instance,
        dependent_inst,
        exec_code_va,
        record.target,
        args,
        stack_args,
    ) {
        Ok(result) => {
            if let Some(binding) = dependent_binding {
                refresh_hosted_device_resource_state(binding, dependent_shared);
            }
            Ok(result)
        }
        Err(HostedComponentDispatchError::Status(status)) => {
            if let Some(binding) = dependent_binding {
                refresh_hosted_device_resource_state(binding, dependent_shared);
            }
            Err(status)
        }
        Err(HostedComponentDispatchError::Wall(pr)) => {
            trace_hosted_provider_callback_wall(record, dependent_inst, pr);
            Err(STATUS_UNSUCCESSFUL)
        }
    }
}

unsafe fn trace_hosted_work_queue_wall(
    instance_index: usize,
    kind: u64,
    work_item: u64,
    routine: u64,
    arg0: u64,
    arg1: u64,
    pr: crate::spawn_hosts::PumpResult,
) {
    let trace = HOSTED_WORK_QUEUE_WALL_TRACE_COUNT.fetch_add(1, Ordering::Relaxed);
    if trace >= HOSTED_WORK_QUEUE_WALL_TRACE_CAP {
        return;
    }
    print_str(b"[hosted-work-wall] inst=");
    print_u64(instance_index as u64);
    print_str(b" kind=");
    print_u64(kind);
    print_str(b" work-item=");
    print_hex64(work_item);
    print_str(b" routine=");
    print_hex64(routine);
    print_str(b" args=");
    print_hex64(arg0);
    print_str(b",");
    print_hex64(arg1);
    print_str(b" status=0x");
    print_hex(pr.status as u32);
    print_str(b" wall-ip=");
    print_hex64(pr.wall_ip);
    print_str(b" wall-addr=");
    print_hex64(pr.wall_addr);
    print_str(b"\n");
}

unsafe fn trace_hosted_work_queue_capacity(
    instance_index: usize,
    head: u64,
    tail: u64,
    drops: u64,
    drained: u64,
) {
    let trace = HOSTED_WORK_QUEUE_CAPACITY_TRACE_COUNT.fetch_add(1, Ordering::Relaxed);
    if trace >= HOSTED_WORK_QUEUE_CAPACITY_TRACE_CAP {
        return;
    }
    print_str(b"[hosted-work-capacity] inst=");
    print_u64(instance_index as u64);
    print_str(b" head=");
    print_u64(head);
    print_str(b" tail=");
    print_u64(tail);
    print_str(b" drops=");
    print_u64(drops);
    print_str(b" drained=");
    print_u64(drained);
    print_str(b" cap=");
    print_u64(SH_WORK_QUEUE_CAPACITY);
    print_str(b"\n");
}

unsafe fn drain_hosted_work_queue_for_instance(
    instance_index: usize,
    inst: DriverInstance,
) -> Result<u64, i32> {
    let shared = inst.exec_shared_va;
    let Some(exec_code_va) = ExecVaWindow::try_for_instance(instance_index).map(|win| win.code_va)
    else {
        return Err(STATUS_DEVICE_NOT_READY);
    };
    let saved_irql = read_volatile((shared + SH_HOSTED_CURRENT_IRQL) as *const u8);
    let mut drained = 0u64;
    let budget = SH_WORK_QUEUE_CAPACITY.saturating_mul(4);
    while drained < budget {
        let head = read_volatile((shared + SH_WORK_QUEUE_HEAD) as *const u64);
        let tail = read_volatile((shared + SH_WORK_QUEUE_TAIL) as *const u64);
        if head == tail {
            break;
        }
        let slot = hosted_work_queue_slot(shared, head);
        let kind = read_volatile((slot + SH_WORK_QUEUE_ENTRY_KIND) as *const u64);
        let work_item = read_volatile((slot + SH_WORK_QUEUE_ENTRY_WORK_ITEM) as *const u64);
        let routine = read_volatile((slot + SH_WORK_QUEUE_ENTRY_ROUTINE) as *const u64);
        let arg0 = read_volatile((slot + SH_WORK_QUEUE_ENTRY_ARG0) as *const u64);
        let arg1 = read_volatile((slot + SH_WORK_QUEUE_ENTRY_ARG1) as *const u64);
        write_volatile((slot + SH_WORK_QUEUE_ENTRY_KIND) as *mut u64, 0);
        write_volatile((slot + SH_WORK_QUEUE_ENTRY_WORK_ITEM) as *mut u64, 0);
        write_volatile((slot + SH_WORK_QUEUE_ENTRY_ROUTINE) as *mut u64, 0);
        write_volatile((slot + SH_WORK_QUEUE_ENTRY_ARG0) as *mut u64, 0);
        write_volatile((slot + SH_WORK_QUEUE_ENTRY_ARG1) as *mut u64, 0);
        write_volatile(
            (shared + SH_WORK_QUEUE_HEAD) as *mut u64,
            head.wrapping_add(1),
        );
        if routine == 0 {
            continue;
        }
        let args = match kind {
            HOSTED_WORK_QUEUE_KIND_EX => [arg0, 0, 0, 0],
            HOSTED_WORK_QUEUE_KIND_IO => [arg0, arg1, 0, 0],
            _ => continue,
        };
        let ndis_work_dispatch = if kind == HOSTED_WORK_QUEUE_KIND_EX {
            match begin_hosted_provider_ndis_work_item_dispatch(instance_index, work_item, arg0) {
                Ok(dispatch) => dispatch,
                Err(status) => {
                    register_instance_ready(instance_index, false);
                    write_volatile((shared + SH_HOSTED_CURRENT_IRQL) as *mut u8, saved_irql);
                    return Err(status);
                }
            }
        } else {
            None
        };
        write_volatile((shared + SH_HOSTED_CURRENT_IRQL) as *mut u8, PASSIVE_LEVEL);
        match dispatch_hosted_component_target(
            instance_index,
            inst,
            exec_code_va,
            routine,
            args,
            [0u64; PROVIDER_CALLBACK_STACK_QWORDS],
        ) {
            Ok(_) => {
                if ndis_work_dispatch.is_some_and(|dispatch| {
                    !complete_hosted_provider_ndis_work_item_dispatch(dispatch)
                }) {
                    register_instance_ready(instance_index, false);
                    write_volatile((shared + SH_HOSTED_CURRENT_IRQL) as *mut u8, saved_irql);
                    return Err(STATUS_DEVICE_NOT_READY);
                }
                drained = drained.saturating_add(1);
                let total = read_volatile((shared + SH_WORK_QUEUE_DRAINED) as *const u64);
                write_volatile(
                    (shared + SH_WORK_QUEUE_DRAINED) as *mut u64,
                    total.saturating_add(1),
                );
            }
            Err(HostedComponentDispatchError::Status(status)) => {
                if let Some(dispatch) = ndis_work_dispatch {
                    mark_hosted_provider_ndis_work_item_dispatch_indeterminate(dispatch);
                }
                register_instance_ready(instance_index, false);
                write_volatile((shared + SH_HOSTED_CURRENT_IRQL) as *mut u8, saved_irql);
                return Err(status);
            }
            Err(HostedComponentDispatchError::Wall(pr)) => {
                if let Some(dispatch) = ndis_work_dispatch {
                    mark_hosted_provider_ndis_work_item_dispatch_indeterminate(dispatch);
                }
                trace_hosted_work_queue_wall(
                    instance_index,
                    kind,
                    work_item,
                    routine,
                    arg0,
                    arg1,
                    pr,
                );
                write_volatile((shared + SH_HOSTED_CURRENT_IRQL) as *mut u8, saved_irql);
                return Err(STATUS_UNSUCCESSFUL);
            }
        }
    }
    let head = read_volatile((shared + SH_WORK_QUEUE_HEAD) as *const u64);
    let tail = read_volatile((shared + SH_WORK_QUEUE_TAIL) as *const u64);
    let drops = read_volatile((shared + SH_WORK_QUEUE_DROPS) as *const u64);
    if drops != 0 || head != tail {
        trace_hosted_work_queue_capacity(instance_index, head, tail, drops, drained);
        register_instance_ready(instance_index, false);
        write_volatile((shared + SH_HOSTED_CURRENT_IRQL) as *mut u8, saved_irql);
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    }
    write_volatile((shared + SH_HOSTED_CURRENT_IRQL) as *mut u8, saved_irql);
    Ok(drained)
}

struct HostedWorkQueueDrainGuard;

impl HostedWorkQueueDrainGuard {
    fn enter() -> Option<Self> {
        HOSTED_WORK_QUEUE_DRAIN_ACTIVE
            .compare_exchange(0, 1, Ordering::AcqRel, Ordering::Acquire)
            .ok()
            .map(|_| Self)
    }
}

impl Drop for HostedWorkQueueDrainGuard {
    fn drop(&mut self) {
        HOSTED_WORK_QUEUE_DRAIN_ACTIVE.store(0, Ordering::Release);
    }
}

/// Run queued PASSIVE_LEVEL work only after the outermost hosted component call has returned.
///
/// Provider callbacks can cross several isolated driver domains while the original provider still
/// owns DISPATCH_LEVEL state such as an NDIS miniport lock. Scanning every live instance here keeps
/// work ownership dynamic (no NIC/driver bitset or identity list) and prevents a nested callback
/// from running a passive worker before that outer state is released.
unsafe fn drain_hosted_work_queues_at_passive_level() -> Result<u64, i32> {
    if HOSTED_COMPONENT_PUMP_DEPTH.load(Ordering::Acquire) != 0 {
        return Ok(0);
    }
    let Some(_drain) = HostedWorkQueueDrainGuard::enter() else {
        return Ok(0);
    };
    let instance_count = driver_instances().map(Vec::len).unwrap_or(0);
    if instance_count == 0 {
        return Ok(0);
    }
    let sweep_budget = instance_count.saturating_mul(4).max(1);
    let mut total = 0u64;
    let mut sweeps = 0usize;
    while sweeps < sweep_budget {
        let mut sweep_drained = 0u64;
        for instance_index in 0..instance_count {
            let Some(inst) = instance(instance_index) else {
                continue;
            };
            if !inst.ready || inst.exec_shared_va == 0 {
                continue;
            }
            let head = read_volatile((inst.exec_shared_va + SH_WORK_QUEUE_HEAD) as *const u64);
            let tail = read_volatile((inst.exec_shared_va + SH_WORK_QUEUE_TAIL) as *const u64);
            let drops = read_volatile((inst.exec_shared_va + SH_WORK_QUEUE_DROPS) as *const u64);
            if head == tail && drops == 0 {
                continue;
            }
            let drained = drain_hosted_work_queue_for_instance(instance_index, inst)?;
            sweep_drained = sweep_drained.saturating_add(drained);
            total = total.saturating_add(drained);
        }
        if sweep_drained == 0 {
            return Ok(total);
        }
        sweeps += 1;
    }
    Err(STATUS_INSUFFICIENT_RESOURCES)
}

unsafe fn provider_callback_marshal_window(
    payload_bytes: u64,
    trailing_cells: u64,
) -> Result<(u64, u64), i32> {
    let cell_base = provider_marshal_align8(payload_bytes).ok_or(STATUS_INVALID_PARAMETER)?;
    let used = cell_base
        .checked_add(
            trailing_cells
                .checked_mul(8)
                .ok_or(STATUS_INVALID_PARAMETER)?,
        )
        .ok_or(STATUS_INVALID_PARAMETER)?;
    if used > SH_PROVIDER_EXPORT_MARSHAL_BYTES {
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    }
    Ok((cell_base, used))
}

unsafe fn service_ndis_initialize_callback(
    provider_instance: usize,
    provider_inst: DriverInstance,
    record: HostedProviderCallbackRecord,
    dependent_inst: DriverInstance,
    exec_code_va: u64,
    arg0: u64,
    arg1: u64,
    arg2: u64,
    arg3: u64,
    provider_stack: [u64; PROVIDER_CALLBACK_STACK_QWORDS],
) -> Result<u64, i32> {
    if arg3 == 0 || arg3 > NDIS_MINIPORT_INITIALIZE_MEDIUM_CAP {
        return Err(STATUS_INVALID_PARAMETER);
    }
    let medium_bytes = arg3
        .checked_mul(NDIS_MEDIUM_ENTRY_BYTES_X64)
        .ok_or(STATUS_INVALID_PARAMETER)?;
    provider_callback_marshal_window(0x10 + medium_bytes, 0)?;

    let provider_open_status_exec =
        component_to_exec_va_for_instance(provider_instance, provider_inst, arg0, 4)
            .ok_or(STATUS_INVALID_PARAMETER)?;
    let provider_selected_exec =
        component_to_exec_va_for_instance(provider_instance, provider_inst, arg1, 4)
            .ok_or(STATUS_INVALID_PARAMETER)?;
    let provider_medium_exec =
        component_to_exec_va_for_instance(provider_instance, provider_inst, arg2, medium_bytes)
            .ok_or(STATUS_INVALID_PARAMETER)?;

    let dependent_shared = dependent_inst.exec_shared_va;
    let dependent_open_status_component = FSD_SHARED_VADDR + SH_PROVIDER_EXPORT_MARSHAL_BASE;
    let dependent_selected_component = dependent_open_status_component + 8;
    let dependent_medium_component = dependent_open_status_component + 0x10;
    let dependent_open_status_exec = dependent_shared + SH_PROVIDER_EXPORT_MARSHAL_BASE;
    let dependent_selected_exec = dependent_open_status_exec + 8;
    let dependent_medium_exec = dependent_open_status_exec + 0x10;
    provider_marshal_zero(dependent_open_status_exec, 0x10 + medium_bytes);
    copy_bytes(dependent_medium_exec, provider_medium_exec, medium_bytes);
    let Some((_route_index, route)) =
        hosted_provider_dispatch_route_for_pair(provider_instance, record.dependent_instance)
    else {
        return Err(STATUS_DEVICE_NOT_READY);
    };
    let miniport_block_mirror = ensure_hosted_provider_ndis_miniport_block_mirror(
        provider_instance,
        provider_inst,
        route.provider_publication_cookie,
        record.dependent_instance,
        dependent_inst,
        provider_stack[0],
    )?;

    let mut stack_args = [0u64; PROVIDER_CALLBACK_STACK_QWORDS];
    stack_args[0] = miniport_block_mirror.dependent_component_va;
    stack_args[1] = provider_stack[1];
    let result = dispatch_dependent_provider_callback(
        record,
        dependent_inst,
        exec_code_va,
        [
            dependent_open_status_component,
            dependent_selected_component,
            dependent_medium_component,
            arg3,
        ],
        stack_args,
    )?;
    copy_bytes(provider_open_status_exec, dependent_open_status_exec, 4);
    copy_bytes(provider_selected_exec, dependent_selected_exec, 4);
    if result == STATUS_SUCCESS as u64 {
        refresh_hosted_provider_ndis_miniport_block_mirror(
            provider_inst,
            dependent_inst,
            miniport_block_mirror,
        )?;
    }
    Ok(result)
}

unsafe fn service_ndis_query_set_callback(
    provider_instance: usize,
    provider_inst: DriverInstance,
    record: HostedProviderCallbackRecord,
    dependent_inst: DriverInstance,
    exec_code_va: u64,
    arg0: u64,
    arg1: u64,
    arg2: u64,
    arg3: u64,
    provider_stack: [u64; PROVIDER_CALLBACK_STACK_QWORDS],
    input_buffer: bool,
    output_buffer: bool,
) -> Result<u64, i32> {
    let bytes0_provider = provider_stack[0];
    let bytes1_provider = provider_stack[1];
    if bytes0_provider == 0 || bytes1_provider == 0 {
        return Err(STATUS_INVALID_PARAMETER);
    }
    if arg3 > SH_PROVIDER_EXPORT_MARSHAL_BYTES {
        return Err(STATUS_INSUFFICIENT_RESOURCES);
    }
    let (cell_base, used) = provider_callback_marshal_window(arg3, 2)?;
    let provider_bytes0_exec =
        component_to_exec_va_for_instance(provider_instance, provider_inst, bytes0_provider, 4)
            .ok_or(STATUS_INVALID_PARAMETER)?;
    let provider_bytes1_exec =
        component_to_exec_va_for_instance(provider_instance, provider_inst, bytes1_provider, 4)
            .ok_or(STATUS_INVALID_PARAMETER)?;
    let provider_info_exec = if arg3 == 0 {
        0
    } else {
        component_to_exec_va_for_instance(provider_instance, provider_inst, arg2, arg3)
            .ok_or(STATUS_INVALID_PARAMETER)?
    };

    let dependent_shared = dependent_inst.exec_shared_va;
    let dependent_info_component = if arg3 == 0 {
        0
    } else {
        FSD_SHARED_VADDR + SH_PROVIDER_EXPORT_MARSHAL_BASE
    };
    let dependent_info_exec = dependent_shared + SH_PROVIDER_EXPORT_MARSHAL_BASE;
    let dependent_bytes0_component = FSD_SHARED_VADDR + SH_PROVIDER_EXPORT_MARSHAL_BASE + cell_base;
    let dependent_bytes1_component = dependent_bytes0_component + 8;
    let dependent_bytes0_exec = dependent_shared + SH_PROVIDER_EXPORT_MARSHAL_BASE + cell_base;
    let dependent_bytes1_exec = dependent_bytes0_exec + 8;
    provider_marshal_zero(dependent_info_exec, used);
    if input_buffer && arg3 != 0 {
        copy_bytes(dependent_info_exec, provider_info_exec, arg3);
    }

    let mut stack_args = [0u64; PROVIDER_CALLBACK_STACK_QWORDS];
    stack_args[0] = dependent_bytes0_component;
    stack_args[1] = dependent_bytes1_component;
    let result = dispatch_dependent_provider_callback(
        record,
        dependent_inst,
        exec_code_va,
        [arg0, arg1, dependent_info_component, arg3],
        stack_args,
    )?;
    copy_bytes(provider_bytes0_exec, dependent_bytes0_exec, 4);
    copy_bytes(provider_bytes1_exec, dependent_bytes1_exec, 4);
    if output_buffer && result == STATUS_SUCCESS as u64 && arg3 != 0 {
        copy_bytes(provider_info_exec, dependent_info_exec, arg3);
    }
    Ok(result)
}

