const HOSTED_MMIO_RESOURCE_KIND_BASE: u64 = 0x10;
const HOSTED_IO_PORT_RESOURCE_KIND_BASE: u64 = 0x20;
const HOSTED_INTERRUPT_RESOURCE_KIND: u64 = 0x30;
const HOSTED_SUPPLEMENTAL_IO_PORT_RESOURCE_KIND: u64 = 0x31;
const PLATFORM_RESOURCE_OWNER: ResourceOwner = ResourceOwner {
    driver_host_id: u64::MAX,
    driver_host_cookie: u64::MAX,
    device_object_id: u64::MAX,
};
const PLATFORM_PCI_CONFIG_PORT_RESOURCE_ID: u64 = u64::MAX;
const PLATFORM_PCI_CONFIG_PORT_BASE: u64 = 0xCF8;
const PLATFORM_PCI_CONFIG_PORT_LEN: u64 = 8;

fn hosted_resource_id(device_id: u64, kind: u64) -> Option<u64> {
    device_id.checked_mul(0x100)?.checked_add(kind)
}

fn hosted_mmio_resource_id(device_id: u64, resource_index: u8) -> Option<u64> {
    (resource_index < SH_RESOURCE_KIND_CAPACITY).then_some(())?;
    hosted_resource_id(
        device_id,
        HOSTED_MMIO_RESOURCE_KIND_BASE + resource_index as u64,
    )
}

fn hosted_interrupt_resource_id(device_id: u64) -> Option<u64> {
    hosted_resource_id(device_id, HOSTED_INTERRUPT_RESOURCE_KIND)
}

fn hosted_io_port_resource_id(device_id: u64, resource_index: u8) -> Option<u64> {
    (resource_index < SH_RESOURCE_KIND_CAPACITY).then_some(())?;
    hosted_resource_id(
        device_id,
        HOSTED_IO_PORT_RESOURCE_KIND_BASE + resource_index as u64,
    )
}

fn hosted_supplemental_io_port_resource_id(device_id: u64) -> Option<u64> {
    hosted_resource_id(device_id, HOSTED_SUPPLEMENTAL_IO_PORT_RESOURCE_KIND)
}

fn hosted_resource_owner(binding: HostedDeviceBinding) -> ResourceOwner {
    ResourceOwner::new(
        binding.projection_domain.domain_id.raw(),
        binding.projection_domain.cookie,
        binding.device_id,
    )
}

fn hosted_dma_owner(binding: HostedDeviceBinding) -> DmaOwner {
    DmaOwner::new(
        binding.projection_domain.domain_id.raw(),
        binding.projection_domain.cookie,
        binding.device_id,
    )
}

unsafe fn hosted_device_bindings_mut() -> &'static mut Vec<HostedDeviceBinding> {
    let slot = &mut *core::ptr::addr_of_mut!(HOSTED_DEVICE_BINDINGS);
    if slot.is_none() {
        *slot = Some(Vec::new());
    }
    slot.as_mut().unwrap()
}

unsafe fn hosted_device_bindings() -> Option<&'static Vec<HostedDeviceBinding>> {
    (*core::ptr::addr_of!(HOSTED_DEVICE_BINDINGS)).as_ref()
}

unsafe fn hosted_device_retirements_mut() -> &'static mut Vec<HostedDeviceRetirement> {
    let slot = &mut *core::ptr::addr_of_mut!(HOSTED_DEVICE_RETIREMENTS);
    if slot.is_none() {
        *slot = Some(Vec::new());
    }
    slot.as_mut().unwrap()
}

fn hosted_device_retirement_matches_binding(
    retirement: HostedDeviceRetirement,
    binding: HostedDeviceBinding,
) -> bool {
    hosted_device_retirement_matches(
        retirement,
        binding.projection_instance,
        binding.projection_domain,
        binding.device_object,
        nt_io_manager::DeviceId(binding.device_id),
    )
}

fn hosted_device_retirement_matches(
    retirement: HostedDeviceRetirement,
    instance: usize,
    domain: HostedDomainIdentity,
    device_object: u64,
    device_id: nt_io_manager::DeviceId,
) -> bool {
    retirement.instance == instance
        && retirement.domain == domain
        && retirement.device_object == device_object
        && retirement.device_id == device_id
}

unsafe fn hosted_pnp_transaction_owns_stack_device(
    irp_id: IrpId,
    device_id: nt_io_manager::DeviceId,
) -> bool {
    (*core::ptr::addr_of!(HOSTED_PNP_TRANSACTIONS))
        .as_ref()
        .is_some_and(|transactions| {
            transactions.iter().any(|transaction| {
                transaction.irp_id == irp_id && transaction.stack_device_ids.contains(&device_id)
            })
        })
}

unsafe fn guard_hosted_device_retirements_for_pnp(
    irp_id: IrpId,
) -> Result<(), nt_status::NtStatus> {
    if !(*core::ptr::addr_of!(HOSTED_PNP_TRANSACTIONS))
        .as_ref()
        .is_some_and(|transactions| transactions.iter().any(|entry| entry.irp_id == irp_id))
    {
        return Err(nt_status::NtStatus::OBJECT_NAME_COLLISION);
    }
    for retirement in hosted_device_retirements_mut().iter_mut() {
        if !hosted_pnp_transaction_owns_stack_device(irp_id, retirement.device_id) {
            continue;
        }
        match retirement.authority {
            HostedDeviceRetirementAuthority::Driver => {
                retirement.authority = HostedDeviceRetirementAuthority::PnpGuarded;
            }
            HostedDeviceRetirementAuthority::PnpGuarded => {}
            HostedDeviceRetirementAuthority::PnpRemove(_) => {
                return Err(nt_status::NtStatus::INVALID_DEVICE_REQUEST);
            }
        }
    }
    Ok(())
}

unsafe fn authorize_hosted_device_retirements(
    binding: HostedDeviceBinding,
    irp_id: IrpId,
) -> Result<(), nt_status::NtStatus> {
    let valid_transaction = (*core::ptr::addr_of!(HOSTED_PNP_TRANSACTIONS))
        .as_ref()
        .is_some_and(|transactions| {
            transactions.iter().any(|transaction| {
                transaction.irp_id == irp_id
                    && transaction.minor == nt_pnp_manager::PnpMinor::RemoveDevice
                    && transaction.binding == binding
                    && transaction
                        .stack_device_ids
                        .contains(&nt_io_manager::DeviceId(binding.device_id))
            })
        });
    if irp_id.raw() == 0
        || !valid_transaction
        || hosted_device_binding_by_device_id(binding.device_id) != Some(binding)
    {
        return Err(nt_status::NtStatus::INVALID_DEVICE_REQUEST);
    }
    let pdo_device_id = nt_io_manager::DeviceId(binding.pdo_device_id);
    let retirements = hosted_device_retirements_mut();
    if retirements.iter().any(|retirement| {
        retirement.domain == binding.projection_domain
            && ((retirement.device_object == binding.device_object
                && retirement.device_id != nt_io_manager::DeviceId(binding.device_id))
                || (retirement.device_object == binding.pdo_object
                    && retirement.device_id != pdo_device_id))
    }) {
        return Err(nt_status::NtStatus::OBJECT_NAME_COLLISION);
    }
    let mut function_retirement_present = false;
    let mut pdo_retirement_present = false;
    for retirement in retirements.iter_mut() {
        if !hosted_pnp_transaction_owns_stack_device(irp_id, retirement.device_id) {
            continue;
        }
        if retirement.device_id == nt_io_manager::DeviceId(binding.device_id) {
            if !hosted_device_retirement_matches_binding(*retirement, binding) {
                return Err(nt_status::NtStatus::OBJECT_NAME_COLLISION);
            }
            function_retirement_present = true;
        }
        if retirement.device_id == pdo_device_id {
            if !hosted_device_retirement_matches(
                *retirement,
                binding.projection_instance,
                binding.projection_domain,
                binding.pdo_object,
                pdo_device_id,
            ) {
                return Err(nt_status::NtStatus::OBJECT_NAME_COLLISION);
            }
            pdo_retirement_present = true;
        }
        if let Some(status) = retirement.barrier_status {
            return Err(status);
        }
        match retirement.authority {
            HostedDeviceRetirementAuthority::Driver
            | HostedDeviceRetirementAuthority::PnpGuarded => {
                retirement.authority = HostedDeviceRetirementAuthority::PnpRemove(irp_id);
            }
            HostedDeviceRetirementAuthority::PnpRemove(owner) if owner == irp_id => {}
            HostedDeviceRetirementAuthority::PnpRemove(_) => {
                return Err(nt_status::NtStatus::INVALID_DEVICE_REQUEST);
            }
        }
    }
    if function_retirement_present && pdo_retirement_present {
        return Ok(());
    }
    let missing = usize::from(!function_retirement_present) + usize::from(!pdo_retirement_present);
    retirements
        .try_reserve(missing)
        .map_err(|_| nt_status::NtStatus::INSUFFICIENT_RESOURCES)?;
    if !function_retirement_present {
        retirements.push(HostedDeviceRetirement {
            instance: binding.projection_instance,
            domain: binding.projection_domain,
            device_object: binding.device_object,
            device_id: nt_io_manager::DeviceId(binding.device_id),
            authority: HostedDeviceRetirementAuthority::PnpRemove(irp_id),
            barrier_status: None,
        });
    }
    if !pdo_retirement_present {
        retirements.push(HostedDeviceRetirement {
            instance: binding.projection_instance,
            domain: binding.projection_domain,
            device_object: binding.pdo_object,
            device_id: pdo_device_id,
            authority: HostedDeviceRetirementAuthority::PnpRemove(irp_id),
            barrier_status: None,
        });
    }
    Ok(())
}

