/// Dispatch a CREATE whose input buffer contains the UTF-16 FILE_OBJECT name followed by the
/// validated EA chain. The typed parameters keep those extents distinct across the driver-domain
/// transport even though they share one canonical transfer owner.
pub(crate) unsafe fn dispatch_hosted_file_create_irp_result_exact(
    file_id: u64,
    major: u8,
    requestor_tid: u64,
    parameters: CreateParameters,
    in_data: &[u8],
    out: &mut [u8],
) -> Result<(i32, u64, Option<IrpId>, Option<u64>), u32> {
    if !matches!(
        major,
        major::IRP_MJ_CREATE | major::IRP_MJ_CREATE_NAMED_PIPE | major::IRP_MJ_CREATE_MAILSLOT
    ) || parameters.ea_length as usize > in_data.len()
    {
        return Err(STATUS_INVALID_PARAMETER as u32);
    }
    let canonical_file_id = FileId(file_id);
    let device_id = io_manager_mut()
        .file(canonical_file_id)
        .filter(|file| file.client_id == ClientId(IO_MANAGER_COMPONENT_ID))
        .map(|file| file.device_id.raw())
        .ok_or(STATUS_INVALID_HANDLE as u32)?;
    require_hosted_device_ready_for_dispatch(device_id)?;
    dispatch_external_irp_to_device_record_result_exact(
        device_id,
        Some(canonical_file_id),
        major as u64,
        0,
        0,
        requestor_tid,
        in_data,
        out,
        Some(parameters),
        None,
        None,
        None,
        None,
        None,
        None,
        StackFlags::empty(),
    )
}

/// Open the parent of a provider-backed rename/link target. The temporary canonical File is never
/// inserted into a process handle table; `SL_OPEN_TARGET_DIRECTORY` is the only target-parent
/// directive crossing the driver boundary.
pub(crate) unsafe fn dispatch_hosted_target_directory_create_irp_result_exact(
    file_id: u64,
    requestor_tid: u64,
    parameters: CreateParameters,
    in_data: &[u8],
) -> Result<(i32, u64, Option<IrpId>, Option<u64>), u32> {
    if parameters.ea_length != 0 || parameters.related_file.is_some() {
        return Err(STATUS_INVALID_PARAMETER as u32);
    }
    let canonical_file_id = FileId(file_id);
    let device_id = io_manager_mut()
        .file(canonical_file_id)
        .filter(|file| file.client_id == ClientId(IO_MANAGER_COMPONENT_ID))
        .map(|file| file.device_id.raw())
        .ok_or(STATUS_INVALID_HANDLE as u32)?;
    require_hosted_device_ready_for_dispatch(device_id)?;
    let mut output = [];
    dispatch_external_irp_to_device_record_result_exact(
        device_id,
        Some(canonical_file_id),
        major::IRP_MJ_CREATE as u64,
        0,
        0,
        requestor_tid,
        in_data,
        &mut output,
        Some(parameters),
        None,
        None,
        None,
        None,
        None,
        None,
        StackFlags::FORCE_ACCESS_CHECK | StackFlags::OPEN_TARGET_DIRECTORY,
    )
}

/// Begin canonical CLEANUP/CLOSE after the executive's final process handle
/// reference is gone. Retry and pending completion remain manager-owned.
pub(crate) fn release_hosted_file(file_id: u64) -> Result<(), u32> {
    release_hosted_file_with_provenance(file_id, b"final-handle")
}

/// Abandon a canonical File whose process-handle publication never committed.
/// This shares the manager state machine with final-handle release, but remains
/// a distinct integration boundary so a rollback cannot masquerade as CLEANUP.
pub(crate) fn abandon_unpublished_hosted_file(file_id: u64) -> Result<(), u32> {
    release_hosted_file_with_provenance(file_id, b"unpublished")
}

fn release_hosted_file_with_provenance(file_id: u64, provenance: &[u8]) -> Result<(), u32> {
    let io = io_manager_mut();
    let before = io.file(FileId(file_id)).map(|file| {
        (
            hosted_file_state_code(file.state),
            file.outstanding_irp_refs as u64,
            file.close_deferred,
        )
    });
    print_str(b"[hosted-file-release] owner=");
    print_str(provenance);
    print_str(b" file=0x");
    print_hex64(file_id);
    if let Some((state, refs, deferred)) = before {
        print_str(b" state=");
        print_hex64(state);
        print_str(b" irp-refs=");
        print_hex64(refs);
        print_str(b" deferred=");
        print_hex64(deferred as u64);
    } else {
        print_str(b" state=missing");
    }
    let result = io
        .release_external_file(ClientId(IO_MANAGER_COMPONENT_ID), FileId(file_id))
        .map_err(|status| status.raw() as u32);
    print_str(b" status=0x");
    print_hex64(result.as_ref().err().copied().unwrap_or(0) as u64);
    print_str(b"\n");
    result
}

fn hosted_device_ready_for_dispatch(device_id: u64) -> bool {
    require_hosted_device_ready_for_dispatch(device_id).is_ok()
}

fn hosted_dispatch_instance_for_device_id(
    device_id: u64,
) -> Result<(usize, DriverInstance, u64), u32> {
    hosted_driver_device_route_by_device_id(device_id).ok_or(STATUS_DEVICE_NOT_READY as u32)
}

fn require_hosted_device_ready_for_dispatch(device_id: u64) -> Result<(), u32> {
    let (_, inst, device_object) = hosted_dispatch_instance_for_device_id(device_id)?;
    if !inst.ready || inst.driver_id == 0 || device_object == 0 {
        return Err(STATUS_DEVICE_NOT_READY as u32);
    }
    if io_manager_mut()
        .device(nt_io_manager::DeviceId(device_id))
        .is_none()
    {
        return Err(STATUS_DEVICE_NOT_READY as u32);
    }
    Ok(())
}

/// Route one IRP to the driver-declared `\Device\NamedPipe` route. Kept as a semantic npfs wrapper
/// for existing named-pipe call sites; it no longer assumes instance 0.
pub(crate) unsafe fn npfs_dispatch_irp(
    major: u64,
    fsctl: u64,
    file_id: u64,
    in_data: &[u8],
    out: &mut [u8],
) -> Option<(i32, u64)> {
    dispatch_hosted_file_irp_result_exact(file_id, major, fsctl, 0, in_data, out)
        .ok()
        .map(|(status, information, _, _)| (status, information))
}

pub(crate) unsafe fn npfs_dispatch_irp_exact(
    major: u64,
    fsctl: u64,
    file_id: u64,
    in_data: &[u8],
    out: &mut [u8],
) -> Option<(i32, u64, u64)> {
    dispatch_hosted_file_irp_result_exact(file_id, major, fsctl, 0, in_data, out)
        .ok()
        .map(|(status, information, irp_id, _)| {
            (
                status,
                information,
                irp_id.map(|irp_id| irp_id.raw()).unwrap_or(0),
            )
        })
}
